INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/warden-lint-judge', 'official', 'getsentry', 'skills', 'getsentry/skills', 'warden-lint-judge', 285, 7, 95, '2026-02-22T20:43:50Z', '2026-03-06T02:30:16.714Z', '61b2372abd530a633682fc60757c4601198be3d7d9ee28d8479ef17daeb3e7ce', '{"id":"getsentry/skills/warden-lint-judge","name":"warden-lint-judge","description":{"zh":"Warden-lint-judge 技能是一种第二步代码检查，负责将 AI 检测结果转化为确定性的 lint 规则","ja":"Warden-lint-judge スキルは 2 番目のコード検証で、AI の検出結果を確定的 lint ルールに変換します","ko":"Warden-lint-judge 스킬은 두번째 패스의 코드 검증으로 AI 검출 결과를 결정적인 lint 규칙으로 변환합니다","es":"Warden Lint Judge es una habilidad de Warden que evalúa los hallazgos de primera pasada y propone reglas de lint deterministas","fr":"Warden Lint Judge est une compétence Warden qui évalue les résultats de la première passe et propose des règles de lint déterministes","de":"Warden Lint Judge ist eine Warden-Fähigkeit, die die Ergebnisse der ersten Durchlauf auswertet und deterministische Lint-Regeln vorschlägt","pt":"O Warden Lint Judge é uma habilidade que cria regras de lint determinísticas a partir de achados de IA, garantindo a precisão e a eficiência.","ru":"Warden Lint Judge - это навык, который создает определенные правила линта из результатов ИИ, гарантируя точность и эффективность.","ar":"WARDEN LINT JUDGE هو مهارة يُنشئ قواعد لينت محددة من النتائج الإلكترونية، مما يضمن الدقة والكفاءة","en":"Warden skill: evaluates first-pass findings and proposes deterministic lint rules that could permanently catch the same patterns. Requires Wardens multi-pass pipeline (phase 2)."},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":285,"forks":7,"updatedAt":"2026-02-22T20:43:50Z","topics":["tag-production"],"skillMd":{"name":"warden-lint-judge","description":"Warden skill: evaluates first-pass findings and proposes deterministic lint rules that could permanently catch the same patterns. Requires Wardens multi-pass pipeline (phase 2).","bodyPreview":"# Lint Judge\n\nYou are a second-pass Warden skill. Your job: turn AI findings into deterministic lint rules.\n\nThe bar is high. Only propose a rule when you can guarantee it catches the exact pattern through AST structure, not heuristics. A rule that fires on `eval(anything)` is deterministic. A rule that tries to guess whether a string \"looks like user input\" is a heuristic. Only the first kind belongs here.\n\n## Step 1: Detect the linter\n\nBefore evaluating any findings, determine what linter syst","body":"# Lint Judge\n\nYou are a second-pass Warden skill. Your job: turn AI findings into deterministic lint rules.\n\nThe bar is high. Only propose a rule when you can guarantee it catches the exact pattern through AST structure, not heuristics. A rule that fires on `eval(anything)` is deterministic. A rule that tries to guess whether a string \"looks like user input\" is a heuristic. Only the first kind belongs here.\n\n## Step 1: Detect the linter\n\nBefore evaluating any findings, determine what linter system the project uses. Use `Glob` and `Read` to check for:\n\n- `.oxlintrc.json` / `oxlint.json` (oxlint)\n- `.eslintrc.*` / `eslint.config.*` / `\"eslintConfig\"` in package.json (eslint)\n- `clippy.toml` / `.clippy.toml` (Rust clippy)\n- `.pylintrc` / `pyproject.toml` with `[tool.pylint]` (pylint)\n- `.flake8` / `setup.cfg` with `[flake8]` (flake8)\n- `biome.json` / `biome.jsonc` (biome)\n\nAlso check whether the linter supports custom/plugin rules:\n- oxlint: check for `jsPlugins` in config and an existing plugins directory\n- eslint: check for local plugins or `eslint-plugin-*` deps\n- biome: no custom rule support, existing rules only\n\nIf custom rules exist, read them. Before proposing a new custom rule in Step 2, verify no existing rule already covers the same pattern. If one does, skip it silently.\n\nIf the project has no linter, return an empty findings array. You cannot propose rules for a tool that doesn''t exist.\n\n## Step 2: Evaluate prior findings\n\nFor each prior finding that has a `suggestedFix`, ask: can this exact pattern be caught by a deterministic AST check in the linter we found?\n\n**Deterministic means:**\n- The rule matches a specific syntactic pattern in the AST (node type, property name, call signature)\n- Zero or near-zero false positives -- if the AST matches, the code is wrong\n- No guessing about intent, data flow, variable contents, or runtime behavior\n- Examples: banning `eval()`, requiring `===` over `==`, disallowing `execSync` with template literal arguments, flagging `new Function()` calls\n\n**Not deterministic (skip these):**\n- \"This variable might contain user input\" (data flow analysis)\n- \"This function name suggests it handles sensitive data\" (naming heuristic)\n- \"This pattern is usually a bug\" (probabilistic)\n- Anything that requires understanding what a variable contains at runtime\n\n**Only report if ALL of these are true:**\n1. You can identify a specific existing rule by name, OR you can write a complete working custom rule\n2. The rule is deterministic: it matches AST structure, not heuristics\n3. The project''s linter actually supports this\n\n## What to skip silently\n\n- Findings without `suggestedFix`\n- Patterns that need type information the linter can''t access, cross-file context, or runtime knowledge\n- Patterns where the rule would need to guess or use heuristics\n- Cases where you''re not confident the rule is correct and complete\n\nReturn an empty findings array when nothing qualifies. That''s the expected common case.\n\n## Output format\n\n**Do NOT set a `location` field.** These findings target linter config and plugin files, not the source code where the original issue was found. Omitting location ensures they appear as top-level review comments, not inline on unrelated source lines.\n\n**The `description` is the primary output.** Write each finding''s description as a prompt you could copy-paste directly into a local coding agent. It should be a clear, complete instruction that an agent can act on without additional context. Example: \"Add `\\\"no-eval\\\": \\\"error\\\"` to the `rules` object in `.oxlintrc.json` to ban all `eval()` calls.\"\n\nThe `suggestedFix` carries the machine-readable diff for local application via `warden --fix`. It is not shown in PR comments.\n\nFor existing rules:\n- **title**: The rule name (e.g., `no-eval`)\n- **severity**: `low`\n- **description**: A copy-pasteable prompt: which config file to edit, what to add, and why.\n- **suggestedFix**: A diff enabling the rule in the project''s linter config file\n\nFor custom rules:\n- **title**: `custom: <rule-name>` (e.g., `custom: no-execsync-interpolation`)\n- **severity**: `low`\n- **description**: A copy-pasteable prompt: what plugin file to create, what AST pattern it matches, and how to wire it into the linter config.\n- **suggestedFix**: The complete rule implementation file AND the config diff to wire it up. Match the conventions of existing custom rules in the project.\n"},"category":"official","lastSynced":"2026-03-06T02:30:16.714Z","seo":{"title":{"zh":"Warden-lint-judge 技能：第二步代码检查","ja":"Warden-lint-judge スキル：2nd パスのコード検証","ko":"Warden-lint-judge 스킬: 두번째 패스의 코드 검증","es":"Warden Lint Judge: Reglas de Lint Deterministas","fr":"Warden Lint Judge : Règles de Lint Déterministes","de":"Warden Lint Judge: Deterministische Lint-Regeln","pt":"Warden Lint Judge: Regras de Lint Determinísticas","ru":"Warden Lint Judge: Определенные правила линта","ar":"WARDEN LINT JUDGE: قواعد لينت محددة","en":"warden-lint-judge"},"description":{"zh":"Warden-lint-judge 技能是一种第二步代码检查，负责将 AI 检测结果转化为确定性的 lint 规则","ja":"Warden-lint-judge スキルは 2 番目のコード検証で、AI の検出結果を確定的 lint ルールに変換します","ko":"Warden-lint-judge 스킬은 두번째 패스의 코드 검증으로 AI 검출 결과를 결정적인 lint 규칙으로 변환합니다","es":"Warden Lint Judge es una habilidad de Warden que evalúa los hallazgos de primera pasada y propone reglas de lint deterministas","fr":"Warden Lint Judge est une compétence Warden qui évalue les résultats de la première passe et propose des règles de lint déterministes","de":"Warden Lint Judge ist eine Warden-Fähigkeit, die die Ergebnisse der ersten Durchlauf auswertet und deterministische Lint-Regeln vorschlägt","pt":"O Warden Lint Judge é uma habilidade que cria regras de lint determinísticas a partir de achados de IA, garantindo a precisão e a eficiência.","ru":"Warden Lint Judge - это навык, который создает определенные правила линта из результатов ИИ, гарантируя точность и эффективность.","ar":"WARDEN LINT JUDGE هو مهارة يُنشئ قواعد لينت محددة من النتائج الإلكترونية، مما يضمن الدقة والكفاءة","en":"Warden skill: evaluates first-pass findings and proposes deterministic lint rules that could permanently catch the same patterns. Requires Wardens multi-pass..."},"definition":{"en":"Warden skill: evaluates first-pass findings and proposes deterministic lint rules that could permanently catch the same patterns. Requires Wardens multi-pass pipeline (phase 2)."},"features":{"zh":["第二步代码检查","将 AI 检测结果转化为确定性的 lint 规则","提高代码质量","支持多种代码语言","集成到 Warden 多步骤管道中"],"ja":["2 番目のコード検証","AI の検出結果を確定的 lint ルールに変換","コード品質の向上","複数のコード言語をサポート","Warden のマルチステップパイプラインに統合"],"ko":["두번째 패스의 코드 검증","AI 검출 결과를 결정적인 lint 규칙으로 변환","코드 품질 향상","여러 코드 언어 지원","Warden의 멀티스텝 파이프라인에 통합"],"es":["Evalúa hallazgos de primera pasada","Propone reglas de lint deterministas","Requiere el pipeline de múltiples pasos de Warden","Permite la creación de reglas de lint personalizadas","Mejora la calidad del código"],"fr":["Évalue les résultats de la première passe","Propose des règles de lint déterministes","Nécessite le pipeline à plusieurs passes de Warden","Permet la création de règles de lint personnalisées","Améliore la qualité du code"],"de":["Bewertet die Ergebnisse der ersten Durchlauf","Schlägt deterministische Lint-Regeln vor","Benötigt die Mehrfachdurchlauf-Pipeline von Warden","Ermöglicht die Erstellung benutzerdefinierter Lint-Regeln","Verbessert die Code-Qualität"],"pt":["Cria regras de lint determinísticas","Garante a precisão e a eficiência","Funciona com o pipeline de várias etapas do Warden","Propõe regras de lint com base em estruturas de AST","Não utiliza heurísticas"],"ru":["Создает определенные правила линта","Гарантирует точность и эффективность","Работает с многопроходным конвейером Warden","Предлагает правила линта на основе структур AST","Не использует эвристику"],"ar":["ينشئ قواعد لينت محددة","يضمن الدقة والكفاءة","يعمل مع خط أنابيب متعدد المراحل من WARDEN","يقترح قواعد لينت بناءً على هياكل AST","لا يستخدم الإستدلال"]},"keywords":{"zh":["Warden-lint-judge","代码检查","AI 检测","lint 规则","代码质量","Warden 多步骤管道"],"ja":["Warden-lint-judge","コード検証","AI 検出","lint ルール","コード品質","Warden マルチステップパイプライン"],"ko":["Warden-lint-judge","코드 검증","AI 검출","lint 규칙","코드 품질","Warden 멀티스텝 파이프라인"],"es":["Warden Lint Judge","reglas de lint deterministas","evaluación de hallazgos","pipeline de múltiples pasos","calidad del código","desarrollo de software"],"fr":["Warden Lint Judge","règles de lint déterministes","évaluation des résultats","pipeline à plusieurs passes","qualité du code","développement de logiciels"],"de":["Warden Lint Judge","deterministische Lint-Regeln","Ergebnisbewertung","Mehrfachdurchlauf-Pipeline","Code-Qualität","Software-Entwicklung"],"pt":["Warden Lint Judge","regras de lint determinísticas","achados de IA","pipeline de várias etapas","estruturas de AST","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Warden Lint Judge","определенные правила линта","результаты ИИ","многопроходный конвейер","структуры AST","разработка программного обеспечения","инструменты разработки"],"ar":["WARDEN LINT JUDGE","قواعد لينت محددة","نتائج إلكترونية","خط أنابيب متعدد المراحل","هياكل AST","تطوير البرمجيات","أدوات التطوير"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring advanced linting capabilities to evaluate and propose deterministic rules.","zh":"适用于需要高级linting功能的代码审查代理，以评估和提出确定性规则。","ja":"高度なlinting機能を必要とするコードレビューエージェントに最適で、決定的なルールを評価して提案する。","ko":"고급 linting 기능이 필요한 코드 리뷰 에이전트에게 적합하며, 결정적 규칙을 평가 및 제안합니다.","es":"Ideal para agentes de revisión de código que requieren capacidades avanzadas de linting para evaluar y proponer reglas deterministas.","fr":"Idéal pour les agents de revue de code nécessitant des capacités de linting avancées pour évaluer et proposer des règles déterministes.","de":"Ideal für Code-Review-Agenten, die erweiterte Linting-Fähigkeiten benötigen, um deterministische Regeln zu bewerten und vorzuschlagen.","pt":"Ideal para Agentes de Revisão de Código que exigem capacidades avançadas de linting para avaliar e propor regras determinísticas.","ru":"Идеально для агентов кодового обзора, требующих продвинутых возможностей линтинга для оценки и предложения детерминированных правил.","ar":"مثالي للوكلاء المراجعة الكودية الذين يتطلبون قدرات متقدمة لlinting لتقييم وطرح قواعد محددة."},"recommendation":{"en":"Empowers agents to turn AI findings into deterministic lint rules through AST structure analysis, guaranteeing precise pattern matching without relying on heuristics, and integrates with Warden''s multi-pass pipeline for enhanced code evaluation.","zh":"通过AST结构分析使代理能够将AI发现转化为确定性的lint规则，保证精确的模式匹配，而不依赖于启发式方法，并与Warden的多通道管道集成以增强代码评估。","ja":"AST構造分析を通じてエージェントがAIの発見を決定的なlintルールに変換することを可能にし、ヒューリスティックに頼ることなく正確なパターンマッチングを保証し、ウォーデンのマルチパスパイプラインと統合してコード評価を強化する。","ko":"AST 구조 분석을 통해 에이전트가 AI 발견을 결정적 린트 규칙으로 변환 할 수 있도록하여, 유추에 의존하지 않고 정확한 패턴 일치를 보장하며, 코드 평가를 강화하기 위해 Warden의 멀티 패스 파이프라인과 통합합니다.","es":"Permite a los agentes convertir los hallazgos de la IA en reglas de lint deterministas mediante el análisis de la estructura AST, garantizando una coincidencia de patrones precisa sin depender de heurísticas, y se integra con la canalización de múltiples pasos de Warden para una evaluación de código mejorada.","fr":"Permet aux agents de transformer les résultats de l''IA en règles de lint déterministes grâce à l''analyse de la structure AST, garantissant une correspondance de motifs précise sans recourir à des heuristiques, et s''intègre au pipeline multi-étapes de Warden pour une évaluation de code améliorée.","de":"Ermöglicht es Agenten, KI-Erkenntnisse durch AST-Strukturanalyse in deterministische Linting-Regeln umzuwandeln, garantiert exakte Mustererkennung ohne Heuristiken und integriert sich in die Multi-Pass-Pipeline von Warden für eine verbesserte Codebewertung.","pt":"Habilita os agentes a transformar descobertas de IA em regras de lint determinísticas por meio da análise da estrutura AST, garantindo a correspondência de padrões precisos sem depender de heurísticas, e integra-se com o pipeline multi-passo do Warden para uma avaliação de código aprimorada.","ru":"Наделяет агентов возможностью превратить нахождения ИИ в детерминированные правила линтинга посредством анализа структуры AST, гарантируя точное совпадение шаблонов без использования эвристик, и интегрируется с многополосным конвейером Warden для расширенной оценки кода.","ar":"تمكن الوكلاء من تحويل اكتشافات الذكاء الاصطناعي إلى قواعد لينت محددة من خلال تحليل هيكل AST ، مما يضمن مطابقة الأنماط الدقيقة دون الاعتماد على الإستدلالات ، ويتكامل مع خط أنابيب واردين متعدد المراحل لتقديم تقييم شاملة للكود."},"useCases":{"en":["Evaluating first-pass findings for lint rule proposals","Generating deterministic lint rules based on AST structure","Integrating with Warden''s multi-pass pipeline for comprehensive code review"],"zh":["评估首次传递的发现以提出lint规则","根据AST结构生成确定性的lint规则","与Warden的多通道管道集成进行全面代码审查"],"ja":["最初のパスでの発見をlintルールの提案のために評価する","AST構造に基づいて決定的なlintルールを生成する","ウォーデンのマルチパスパイプラインと統合して包括的なコードレビューを行う"],"ko":["린트 규칙 제안을 위해 첫 번째 전달의 발견을 평가합니다","AST 구조에 따라 결정적 린트 규칙을 생성합니다","전체 코드 리뷰를 위해 Warden의 멀티 패스 파이프라인과 통합"],"es":["Evaluación de hallazgos de primera pasada para propuestas de reglas de lint","Generación de reglas de lint deterministas basadas en la estructura AST","Integración con la canalización de múltiples pasos de Warden para una revisión de código exhaustiva"],"fr":["Évaluation des résultats de première passe pour les propositions de règles de lint","Génération de règles de lint déterministes basées sur la structure AST","Intégration au pipeline multi-étapes de Warden pour une revue de code complète"],"de":["Bewertung von First-Pass-Ergebnissen für Linting-Regelvorschläge","Generierung deterministischer Linting-Regeln basierend auf der AST-Struktur","Integration in die Multi-Pass-Pipeline von Warden für umfassendes Code-Review"],"pt":["Avaliando as descobertas de primeira passagem para propostas de regras de lint","Gerando regras de lint determinísticas com base na estrutura AST","Integrando-se com o pipeline multi-passo do Warden para revisão de código abrangente"],"ru":["Оценка результатов первого прохода для предложений правил линтинга","Генерация детерминированных правил линтинга на основе структуры AST","Интеграция с многополосным конвейером Warden для комплексного обзора кода"],"ar":["تقييم النتائج المبدئية للخطوة الأولى لطرح اقتراحات لقواعد لينت","إنتاج قواعد لينت محددة بناءً على هيكل AST","التكامل مع خط أنابيب واردين متعدد المراحل لمراجعة شاملة للكود"]},"limitations":{"en":["Requires Warden''s multi-pass pipeline (phase 2)","Must guarantee deterministic pattern matching through AST structure, not heuristics"],"zh":["需要Warden的多通道管道（第2阶段）","必须通过AST结构保证确定性的模式匹配，而不是启发式方法"],"ja":["ウォーデンのマルチパスパイプライン（フェーズ2）が必要","AST構造を通じて決定的なパターンマッチングを保証する必要があり、ヒューリスティックではない"],"ko":["Warden의 멀티 패스 파이프라인 (2차)이 필요합니다","AST 구조를 통해 결정적 패턴 일치를 보장해야하며, 유추가 아님"],"es":["Requiere la canalización de múltiples pasos de Warden (fase 2)","Debe garantizar una coincidencia de patrones determinista mediante la estructura AST, no heurísticas"],"fr":["Nécessite le pipeline multi-étapes de Warden (phase 2)","Doit garantir une correspondance de motifs déterministe via la structure AST, et non des heuristiques"],"de":["Erfordert die Multi-Pass-Pipeline von Warden (Phase 2)","Muss deterministische Mustererkennung durch AST-Struktur garantieren, nicht durch Heuristiken"],"pt":["Exige o pipeline multi-passo do Warden (fase 2)","Deve garantir a correspondência de padrões determinística por meio da estrutura AST, não heurísticas"],"ru":["Требует многополосного конвейера Warden (фаза 2)","Должен гарантировать детерминированное совпадение шаблонов посредством структуры AST, а не эвристик"],"ar":["يتطلب خط أنابيب واردين متعدد المراحل (المرحلة 2)","يجب أن يضمن مطابقة الأنماط المحددة من خلال هيكل AST ، وليس الإستدلالات"]},"version":3},"contentHash":"61b2372abd530a633682fc60757c4601198be3d7d9ee28d8479ef17daeb3e7ce","repoEtag":"W/\"11e1429ea6d94516e413e5c49466d9c3e6e2072d9f4ee50929a8f9d897fff491\"","qualityScore":95}');
