INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/warden-lint-judge', 'warden-lint-judge', 'getsentry', 'skills', 'official', 'warden-lint-judge getsentry skills official tag-production Warden-lint-judge 技能是一种第二步代码检查，负责将 AI 检测结果转化为确定性的 lint 规则 Warden-lint-judge スキルは 2 番目のコード検証で、AI の検出結果を確定的 lint ルールに変換します Warden-lint-judge 스킬은 두번째 패스의 코드 검증으로 AI 검출 결과를 결정적인 lint 규칙으로 변환합니다 Warden Lint Judge es una habilidad de Warden que evalúa los hallazgos de primera pasada y propone reglas de lint deterministas Warden Lint Judge est une compétence Warden qui évalue les résultats de la première passe et propose des règles de lint déterministes Warden Lint Judge ist eine Warden-Fähigkeit, die die Ergebnisse der ersten Durchlauf auswertet und deterministische Lint-Regeln vorschlägt O Warden Lint Judge é uma habilidade que cria regras de lint determinísticas a partir de achados de IA, garantindo a precisão e a eficiência. Warden Lint Judge - это навык, который создает определенные правила линта из результатов ИИ, гарантируя точность и эффективность. WARDEN LINT JUDGE هو مهارة يُنشئ قواعد لينت محددة من النتائج الإلكترونية، مما يضمن الدقة والكفاءة Warden skill: evaluates first-pass findings and proposes deterministic lint rules that could permanently catch the same patterns. Requires Wardens multi-pass pipeline (phase 2). Warden-lint-judge 代码检查 AI 检测 lint 规则 代码质量 Warden 多步骤管道 Warden skill: evaluates first-pass findings and proposes deterministic lint rules that could permanently catch the same patterns. Requires Wardens multi-pass pipeline (phase 2).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/project-guidelines-example', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'project-guidelines-example', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T04:26:11.931Z', '68a3764074ab8b9448049010b368c2be75295b9d1e1de8bec6ccacf35fd52c08', '{"id":"affaan-m/everything-claude-code/project-guidelines-example","name":"project-guidelines-example","description":{"en":"The project-guidelines-example skill provides project-specific technical documentation and guidelines for AI agent development. It serves as a template containing architecture overviews, file structure patterns, code standards, testing requirements, and deployment workflows for developers working...","zh":"这是一个基于真实生产项目Zenith的AI代理技能示例模板。提供项目特定的架构概览、文件结构、代码模式、测试要求和部署工作流，帮助开发者快速构建Claude Code项目。","ja":"実際のプロダクションアプリケーションZenithに基づくAIエージェントスキルの例テンプレート。プロジェクト固有のアーキテクチャ概要、ファイル構造、コードパターン、テスト要件、デプロイワークフローを提供し、Claude Code開発を効率化します。","ko":"실제 프로덕션 애플리케이션 Zenith를 기반으로 한 AI 에이전트 스킬 예제 템플릿. 프로젝트별 아키텍처 개요, 파일 구조, 코드 패턴, 테스트 요구사항, 배포 워크플로를 제공하여 Claude Code 개발을 가속화합니다.","es":"El skill de pautas de proyecto es un ejemplo de plantilla de skill específico del proyecto basado en la aplicación de producción Zenith","fr":"Le skill d''exemple de projet est un exemple de modèle de skill spécifique au projet basé sur l''application de production Zenith","de":"Das Projekt-Richtlinien-Beispiel-Skill ist ein Beispiel für eine projektspezifische Skill-Vorlage basierend auf der Produktionsanwendung Zenith","pt":"Um exemplo de skill específica para projetos baseada na aplicação real Zenith. Fornece diretrizes técnicas completas incluindo visão de arquitetura, estrutura de arquivos, padrões de código, requisitos de teste e workflow de deployment para desenvolvimento com Claude.","ru":"Пример специфичного для проекта навыка, основанный на реальном приложении Zenith. Предоставляет полные технические руководства, включая обзор архитектуры, структуру файлов, паттерны кода, требования к тестированию и рабочий процесс развертывания для разработки с Claude.","ar":"مثال لمهارة مخصصة للمشروع بناءً على التطبيق الفعلي Zenith. يقدم إرشادات تقنية شاملة تشمل نظرة عامة على البنية، هيكل الملفات، أنماط الكود، متطلبات الاختبار، وسير عمل النشر للتطوير باستخدام Claude."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"project-guidelines-example","description":"Example project-specific skill template based on a real production application.","bodyPreview":"# Project Guidelines Skill (Example)\n\nThis is an example of a project-specific skill. Use this as a template for your own projects.\n\nBased on a real production application: [Zenith](https://zenith.chat) - AI-powered customer discovery platform.\n\n## When to Use\n\nReference this skill when working on the specific project it''s designed for. Project skills contain:\n- Architecture overview\n- File structure\n- Code patterns\n- Testing requirements\n- Deployment workflow\n\n---\n\n## Architecture Overview\n\n**T","body":"# Project Guidelines Skill (Example)\n\nThis is an example of a project-specific skill. Use this as a template for your own projects.\n\nBased on a real production application: [Zenith](https://zenith.chat) - AI-powered customer discovery platform.\n\n## When to Use\n\nReference this skill when working on the specific project it''s designed for. Project skills contain:\n- Architecture overview\n- File structure\n- Code patterns\n- Testing requirements\n- Deployment workflow\n\n---\n\n## Architecture Overview\n\n**Tech Stack:**\n- **Frontend**: Next.js 15 (App Router), TypeScript, React\n- **Backend**: FastAPI (Python), Pydantic models\n- **Database**: Supabase (PostgreSQL)\n- **AI**: Claude API with tool calling and structured output\n- **Deployment**: Google Cloud Run\n- **Testing**: Playwright (E2E), pytest (backend), React Testing Library\n\n**Services:**\n```\n┌─────────────────────────────────────────────────────────────┐\n│                         Frontend                            │\n│  Next.js 15 + TypeScript + TailwindCSS                     │\n│  Deployed: Vercel / Cloud Run                              │\n└─────────────────────────────────────────────────────────────┘\n                              │\n                              ▼\n┌─────────────────────────────────────────────────────────────┐\n│                         Backend                             │\n│  FastAPI + Python 3.11 + Pydantic                          │\n│  Deployed: Cloud Run                                       │\n└─────────────────────────────────────────────────────────────┘\n                              │\n              ┌───────────────┼───────────────┐\n              ▼               ▼               ▼\n        ┌──────────┐   ┌──────────┐   ┌──────────┐\n        │ Supabase │   │  Claude  │   │  Redis   │\n        │ Database │   │   API    │   │  Cache   │\n        └──────────┘   └──────────┘   └──────────┘\n```\n\n---\n\n## File Structure\n\n```\nproject/\n├── frontend/\n│   └── src/\n│       ├── app/              # Next.js app router pages\n│       │   ├── api/          # API routes\n│       │   ├── (auth)/       # Auth-protected routes\n│       │   └── workspace/    # Main app workspace\n│       ├── components/       # React components\n│       │   ├── ui/           # Base UI components\n│       │   ├── forms/        # Form components\n│       │   └── layouts/      # Layout components\n│       ├── hooks/            # Custom React hooks\n│       ├── lib/              # Utilities\n│       ├── types/            # TypeScript definitions\n│       └── config/           # Configuration\n│\n├── backend/\n│   ├── routers/              # FastAPI route handlers\n│   ├── models.py             # Pydantic models\n│   ├── main.py               # FastAPI app entry\n│   ├── auth_system.py        # Authentication\n│   ├── database.py           # Database operations\n│   ├── services/             # Business logic\n│   └── tests/                # pytest tests\n│\n├── deploy/                   # Deployment configs\n├── docs/                     # Documentation\n└── scripts/                  # Utility scripts\n```\n\n---\n\n## Code Patterns\n\n### API Response Format (FastAPI)\n\n```python\nfrom pydantic import BaseModel\nfrom typing import Generic, TypeVar, Optional\n\nT = TypeVar(''T'')\n\nclass ApiResponse(BaseModel, Generic[T]):\n    success: bool\n    data: Optional[T] = None\n    error: Optional[str] = None\n\n    @classmethod\n    def ok(cls, data: T) -> \"ApiResponse[T]\":\n        return cls(success=True, data=data)\n\n    @classmethod\n    def fail(cls, error: str) -> \"ApiResponse[T]\":\n        return cls(success=False, error=error)\n```\n\n### Frontend API Calls (TypeScript)\n\n```typescript\ninterface ApiResponse<T> {\n  success: boolean\n  data?: T\n  error?: string\n}\n\nasync function fetchApi<T>(\n  endpoint: string,\n  options?: RequestInit\n): Promise<ApiResponse<T>> {\n  try {\n    const response = await fetch(`/api${endpoint}`, {\n      ...options,\n      headers: {\n        ''Content-Type'': ''application/json'',\n        ...options?.headers,\n      },\n    })\n\n    if (!response.ok) {\n      return { success: false, error: `HTTP ${response.status}` }\n    }\n\n    return await response.json()\n  } catch (error) {\n    return { success: false, error: String(error) }\n  }\n}\n```\n\n### Claude AI Integration (Structured Output)\n\n```python\nfrom anthropic import Anthropic\nfrom pydantic import BaseModel\n\nclass AnalysisResult(BaseModel):\n    summary: str\n    key_points: list[str]\n    confidence: float\n\nasync def analyze_with_claude(content: str) -> AnalysisResult:\n    client = Anthropic()\n\n    response = client.messages.create(\n        model=\"claude-sonnet-4-5-20250514\",\n        max_tokens=1024,\n        messages=[{\"role\": \"user\", \"content\": content}],\n        tools=[{\n            \"name\": \"provide_analysis\",\n            \"description\": \"Provide structured analysis\",\n            \"input_schema\": AnalysisResult.model_json_schema()\n        }],\n        tool_choice={\"type\": \"tool\", \"name\": \"provide_analysis\"}\n    )\n\n    # Extract tool use result\n    tool_use = next(\n        block for block in response.content\n        if block.type == \"tool_use\"\n    )\n\n    return AnalysisResult(**tool_use.input)\n```\n\n### Custom Hooks (React)\n\n```typescript\nimport { useState, useCallback } from ''react''\n\ninterface UseApiState<T> {\n  data: T | null\n  loading: boolean\n  error: string | null\n}\n\nexport function useApi<T>(\n  fetchFn: () => Promise<ApiResponse<T>>\n) {\n  const [state, setState] = useState<UseApiState<T>>({\n    data: null,\n    loading: false,\n    error: null,\n  })\n\n  const execute = useCallback(async () => {\n    setState(prev => ({ ...prev, loading: true, error: null }))\n\n    const result = await fetchFn()\n\n    if (result.success) {\n      setState({ data: result.data!, loading: false, error: null })\n    } else {\n      setState({ data: null, loading: false, error: result.error! })\n    }\n  }, [fetchFn])\n\n  return { ...state, execute }\n}\n```\n\n---\n\n## Testing Requirements\n\n### Backend (pytest)\n\n```bash\n# Run all tests\npoetry run pytest tests/\n\n# Run with coverage\npoetry run pytest tests/ --cov=. --cov-report=html\n\n# Run specific test file\npoetry run pytest tests/test_auth.py -v\n```\n\n**Test structure:**\n```python\nimport pytest\nfrom httpx import AsyncClient\nfrom main import app\n\n@pytest.fixture\nasync def client():\n    async with AsyncClient(app=app, base_url=\"http://test\") as ac:\n        yield ac\n\n@pytest.mark.asyncio\nasync def test_health_check(client: AsyncClient):\n    response = await client.get(\"/health\")\n    assert response.status_code == 200\n    assert response.json()[\"status\"] == \"healthy\"\n```\n\n### Frontend (React Testing Library)\n\n```bash\n# Run tests\nnpm run test\n\n# Run with coverage\nnpm run test -- --coverage\n\n# Run E2E tests\nnpm run test:e2e\n```\n\n**Test structure:**\n```typescript\nimport { render, screen, fireEvent } from ''@testing-library/react''\nimport { WorkspacePanel } from ''./WorkspacePanel''\n\ndescribe(''WorkspacePanel'', () => {\n  it(''renders workspace correctly'', () => {\n    render(<WorkspacePanel />)\n    expect(screen.getByRole(''main'')).toBeInTheDocument()\n  })\n\n  it(''handles session creation'', async () => {\n    render(<WorkspacePanel />)\n    fireEvent.click(screen.getByText(''New Session''))\n    expect(await screen.findByText(''Session created'')).toBeInTheDocument()\n  })\n})\n```\n\n---\n\n## Deployment Workflow\n\n### Pre-Deployment Checklist\n\n- [ ] All tests passing locally\n- [ ] `npm run build` succeeds (frontend)\n- [ ] `poetry run pytest` passes (backend)\n- [ ] No hardcoded secrets\n- [ ] Environment variables documented\n- [ ] Database migrations ready\n\n### Deployment Commands\n\n```bash\n# Build and deploy frontend\ncd frontend && npm run build\ngcloud run deploy frontend --source .\n\n# Build and deploy backend\ncd backend\ngcloud run deploy backend --source .\n```\n\n### Environment Variables\n\n```bash\n# Frontend (.env.local)\nNEXT_PUBLIC_API_URL=https://api.example.com\nNEXT_PUBLIC_SUPABASE_URL=https://xxx.supabase.co\nNEXT_PUBLIC_SUPABASE_ANON_KEY=eyJ...\n\n# Backend (.env)\nDATABASE_URL=postgresql://...\nANTHROPIC_API_KEY=sk-ant-...\nSUPABASE_URL=https://xxx.supabase.co\nSUPABASE_KEY=eyJ...\n```\n\n---\n\n## Critical Rules\n\n1. **No emojis** in code, comments, or documentation\n2. **Immutability** - never mutate objects or arrays\n3. **TDD** - write tests before implementation\n4. **80% coverage** minimum\n5. **Many small files** - 200-400 lines typical, 800 max\n6. **No console.log** in production code\n7. **Proper error handling** with try/catch\n8. **Input validation** with Pydantic/Zod\n\n---\n\n## Related Skills\n\n- `coding-standards.md` - General coding best practices\n- `backend-patterns.md` - API and database patterns\n- `frontend-patterns.md` - React and Next.js patterns\n- `tdd-workflow/` - Test-driven development methodology\n"},"category":"official","lastSynced":"2026-03-06T04:26:11.931Z","seo":{"title":{"en":"project-guidelines-example: Architecture & Deployment Set...","zh":"project-guidelines-example：AI代理项目模板设置指南","ja":"project-guidelines-example：AIエージェント開発テンプレート実践ガイド","ko":"project-guidelines-example: AI 에이전트 프로젝트 템플릿 설정 가이드","es":"Guía de configuración del skill de pautas de proyecto","fr":"Guide de configuration du skill d''exemple de projet","de":"Einrichtungsleitfaden für das Projekt-Richtlinien-Beispie...","pt":"project-guidelines-example: Template para Skills de IA em...","ru":"project-guidelines-example: Шаблон для ИИ Агентов в проектах","ar":"project-guidelines-example: قالب أدوات الذكاء الاصطناعي ل..."},"description":{"en":"Developer guide for project-guidelines-example AI skill. Learn architecture overview, file structure patterns, testing requirements, and deployment workflows...","zh":"基于Zenith生产项目的AI代理技能模板。包含架构概览、文件结构、代码模式、测试要求和部署工作流，适用于Claude Code开发。","ja":"Zenith本番アプリケーションを基にしたAIエージェントスキルテンプレート。アーキテクチャ概要、ファイル構造、コードパターン、テスト要件、デプロイワークフローを含むClaude Code開発向け。","ko":"Zenith 프로덕션 애플리케이션 기반 AI 에이전트 스킬 템플릿. 아키텍처 개요, 파일 구조, 코드 패턴, 테스트 요구사항, 배포 워크플로를 포함한 Claude Code 개발용.","es":"Aprende a configurar el skill de pautas de proyecto basado en la aplicación de producción Zenith","fr":"Découvrez comment configurer le skill d''exemple de projet basé sur l''application de production Zenith","de":"Erfahren Sie, wie Sie das Projekt-Richtlinien-Beispiel-Skill basierend auf der Produktionsanwendung Zenith konfigurieren","pt":"Template técnico baseado na Zenith para criar skills de MCP/Claude específicas de projeto. Inclui visão de arquitetura, padrões de código e fluxo de deploy.","ru":"Технический шаблон на основе Zenith для создания специфичных ИИ Агентов MCP/Claude. Включает обзор архитектуры, паттерны кода и рабочий процесс развертывания.","ar":"قالب تقني مبني على منصة Zenith لإنشاء أدوات ذكاء اصطناعي MCP/Claude مخصصة للمشاريع. يتضمن نظرة عامة على البنية، أنماط الكود، وسير عمل النشر."},"definition":{"en":"project-guidelines-example is an AI agent skill template based on Zenith''s production AI-powered customer discovery platform. It provides developers with project-specific guidelines including architecture overview, file structure, code patterns, testing requirements, and deployment workflows.","zh":"project-guidelines-example是基于Zenith AI客户发现平台的MCP技能模板。它为特定项目提供架构概览、文件结构指导、代码模式规范、测试要求和部署工作流程，帮助开发者标准化AI代理开发。","ja":"project-guidelines-exampleはZenith AIカスタマーディスカバリプラットフォームに基づくMCPスキルテンプレートです。特定プロジェクト向けにアーキテクチャ概要、ファイル構造ガイド、コードパターン規範、テスト要件、デプロイワークフローを提供し、AIエージェント開発を標準化します。","ko":"project-guidelines-example는 Zenith AI 고객 발견 플랫폼 기반 MCP 스킬 템플릿입니다. 특정 프로젝트를 위한 아키텍처 개요, 파일 구조 가이드, 코드 패턴 규범, 테스트 요구사항, 배포 워크플로를 제공하여 AI 에이전트 개발을 표준화합니다.","es":"Un skill de pautas de proyecto es una plantilla de código que proporciona una guía para la arquitectura y el desarrollo de proyectos","fr":"Un skill d''exemple de projet est un modèle de code qui fournit une guide pour l''architecture et le développement de projets","de":"Ein Projekt-Richtlinien-Beispiel-Skill ist eine Code-Vorlage, die eine Richtlinie für die Architektur und Entwicklung von Projekten bietet","pt":"project-guidelines-example é um template de skill para Model Context Protocol (MCP) que serve como exemplo baseado na plataforma Zenith. Fornece diretrizes técnicas específicas de projeto para desenvolvimento com agentes de IA como Claude.","ru":"project-guidelines-example — это шаблон навыка для Model Context Protocol (MCP), который служит примером на основе платформы Zenith. Предоставляет специфичные для проекта технические руководства для разработки с ИИ агентами, такими как Claude.","ar":"project-guidelines-example هو قالب مهارة لـ Model Context Protocol (MCP) يعمل كمثال بناءً على منصة Zenith. يقدم إرشادات تقنية مخصصة للمشروع للتطوير باستخدام أدوات الذكاء الاصطناعي مثل Claude."},"features":{"en":["Provides architecture overview documentation for AI projects","Includes file structure patterns and organization standards","Documents code patterns and development conventions","Specifies testing requirements and validation procedures","Outlines deployment workflow and release processes","Based on Zenith''s production AI customer discovery platform"],"zh":["基于Zenith生产项目的真实架构概览","详细的项目文件结构指导","标准化代码模式和实践规范","完整的测试要求和质量标准","自动化部署工作流程配置","Claude Code开发最佳实践集成"],"ja":["Zenith本番プロジェクトに基づく実践的アーキテクチャ概要","詳細なプロジェクトファイル構造ガイド","標準化されたコードパターンとプラクティス規範","包括的なテスト要件と品質基準","自動化デプロイワークフロー設定","Claude Code開発ベストプラクティス統合"],"ko":["Zenith 프로덕션 프로젝트 기반 실전 아키텍처 개요","상세한 프로젝트 파일 구조 가이드","표준화된 코드 패턴과 실무 규범","포괄적인 테스트 요구사항과 품질 기준","자동화 배포 워크플로 설정","Claude Code 개발 베스트 프랙티스 통합"],"es":["Arquitectura de ejemplo basada en la aplicación de producción Zenith","Estructura de archivos y patrones de código","Requisitos de testing y flujo de trabajo de implementación","Integración con herramientas de desarrollo como Claude y MCP","Compatibilidad con tecnologías como AI Agents y LLM"],"fr":["Exemple d''architecture basé sur l''application de production Zenith","Structure de fichiers et modèles de code","Exigences de testing et flux de travail de déploiement","Intégration avec des outils de développement tels que Claude et MCP","Compatibilité avec des technologies telles que les agents IA et LLM"],"de":["Beispiel-Architektur basierend auf der Produktionsanwendung Zenith","Dateistruktur und Code-Muster","Testanforderungen und Bereitstellungs-Workflow","Integration mit Entwicklungstools wie Claude und MCP","Kompatibilität mit Technologien wie AI-Agents und LLM"],"pt":["Template baseado na aplicação real Zenith - plataforma de descoberta de clientes com IA","Visão completa da arquitetura do projeto para referência técnica","Estrutura de arquivos otimizada para desenvolvimento com Claude","Padrões de código específicos para implementação consistente","Requisitos de teste para garantir qualidade do código","Workflow de deployment para ambientes de produção"],"ru":["Шаблон на основе реального приложения Zenith — AI-платформы для обнаружения клиентов","Полный обзор архитектуры проекта для технического reference","Оптимизированная структура файлов для разработки с Claude","Специфичные паттерны кода для последовательной реализации","Требования к тестированию для обеспечения качества кода","Рабочий процесс развертывания для production-сред"],"ar":["قالب مبني على التطبيق الفعلي Zenith - منصة اكتشاف العملاء بالذكاء الاصطناعي","نظرة شاملة على بنية المشروع للمرجعية التقنية","هيكل ملفات مُحسّن للتطوير باستخدام Claude","أنماط كود مخصصة للتنفيذ المتسق","متطلبات الاختبار لضمان جودة الكود","سير عمل النشر لبيئات الإنتاج"]},"keywords":{"en":["project-guidelines-example skill setup","AI agent architecture overview","project file structure patterns","testing requirements for AI agents","deployment workflow guide","Zenith AI platform template","how to use project-guidelines-example","project-guidelines-example vs custom development","install project-guidelines-example skill","MCP agent development guidelines"],"zh":["AI代理模板","Claude Code开发指南","MCP技能示例","Zenith项目架构","代码模式规范","部署工作流配置","AI工具开发模板","项目文件结构"],"ja":["AIエージェントテンプレート","Claude Code開発ガイド","MCPスキル例","Zenithプロジェクトアーキテクチャ","コードパターン規範","デプロイワークフロー設定","AIツール開発テンプレート","プロジェクトファイル構造"],"ko":["AI 에이전트 템플릿","Claude Code 개발 가이드","MCP 스킬 예제","Zenith 프로젝트 아키텍처","코드 패턴 규범","배포 워크플로 설정","AI 도구 개발 템플릿","프로젝트 파일 구조"],"es":["skill de pautas de proyecto","desarrollo de proyectos","arquitectura de ejemplo","herramientas de desarrollo","AI Agents","LLM","Claude","MCP","Zenith"],"fr":