INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/skill-scanner', 'skill-scanner', 'getsentry', 'skills', 'official', 'skill-scanner getsentry skills official tag-production The skill-scanner skill scans agent skills for security issues, benefiting developers by detecting prompt injection, malicious code, and supply chain risks. It provides a static analysis scanner that outputs structured JSON. skill-scanner是一种AI工具安全扫描器，用于检测安全问题，如命令注入和恶意代码。它还可以检测过度权限和秘密暴露等问题 skill-scannerはAIエージェントのセキュリティスキャナーです。プロンプトインジェクションや悪意のあるコードを検出し、過度の権限やシークレットの暴露を防ぎます skill-scanner는 AI 에이전트의 보안 스キャ너로 프롬프트 인젝션, 악성 코드, 과도한 권한 및 비밀 노출 등 보안 문제를 감지합니다 El escáner de seguridad de habilidades es una herramienta para detectar problemas de seguridad en habilidades de agentes. Utiliza análisis estático para detectar patrones deterministas Le scanneur de sécurité des compétences est un outil pour détecter les problèmes de sécurité dans les compétences des agents. Il utilise l''analyse statique pour détecter les modèles déterministes Der Sicherheits-Scanner von Fähigkeiten ist ein Tool zum Erkennen von Sicherheitsproblemen in Fähigkeiten von Agenten. Er verwendet statische Analyse, um deterministische Muster zu erkennen O Skill-Scanner é uma ferramenta de análise de segurança que detecta padrões determinísticos em agentes de IA. Execute a análise de segurança com o script scan_skill.py Skill-Scanner - это инструмент аналитики безопасности, обнаруживающий детерминированные закономерности в ИИ агентах. Запустите анализ безопасности с помощью скрипта scan_skill.py Skill-Scanner هو أداة تحليل أمان تكشف عن أنماط محددة في أدوات الذكاء الاصطناعي. قم بتشغيل تحليل الأمان باستخدام سكريبت scan_skill.py how to use skill-scanner what is skill-scanner skill-scanner alternative skill-scanner vs security tools skill-scanner install skill-scanner setup guide static analysis security tools agent skill security scanning prompt injection detection AI工具安全扫描 skill-scanner 命令注入检测 恶意代码检测 过度权限检测 秘密暴露检测 静态分析扫描 Detects prompt injection using static analysis Identifies malicious code and excessive permissions Scans for secret exposure and supply chain risks Outputs structured JSON for easy analysis Runs using the `scripts/scan_skill.py` script from the repository root Utilizes the `${CLAUDE_SKILL_ROOT}` path for execution skill-scanner is a security tool that scans agent skills for security issues, including prompt injection, malicious code, and supply chain risks, using static analysis techniques.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/claude-api', 'official', 'anthropics', 'skills', 'anthropics/skills', 'claude-api', 85097, 8974, 95, '2026-03-06T03:11:21Z', '2026-03-06T03:15:00.224Z', '1ec3d558d3364ac7f768471055ded521f95bdb0f3e7239be9e4c8e0b219c587e', '{"id":"anthropics/skills/claude-api","name":"claude-api","description":{"en":"This AI agent skill enables developers to build LLM-powered applications using Claude API and Anthropic SDKs. It automatically triggers when code imports anthropic, @anthropic-ai/sdk, or claude_agent_sdk, providing Claude Opus 4.6 integration with adaptive thinking capabilities.","zh":"Claude API是一种用于构建LLM应用的API，支持adaptive thinking和默认模型版本Claude Opus 4.6","ja":"Claude APIは、LLMアプリケーションを構築するためのAPIであり、adaptive thinkingとデフォルトモデルバージョンClaude Opus 4.6をサポートしています","ko":"Claude API는 LLM 애플리케이션을 구축하기 위한 API로, adaptive thinking 및 기본 모델 버전 Claude Opus 4.6를 지원합니다","pt":"Skill técnico para desenvolvedores construírem aplicações com Claude API e Anthropic SDK. Detecta automaticamente imports de `anthropic`, `@anthropic-ai/sdk` e `claude_agent_sdk` para oferecer documentação específica por linguagem.","ru":"Технический навык для разработчиков по созданию приложений с Claude API и Anthropic SDK. Автоматически обнаруживает импорты `anthropic`, `@anthropic-ai/sdk` и `claude_agent_sdk` для предоставления языковой документации.","ar":"مهارة تقنية للمطورين لبناء تطبيقات باستخدام Claude API وAnthropic SDK. تكتشف تلقائيًا استيراد `anthropic` و`@anthropic-ai/sdk` و`claude_agent_sdk` لتقديم وثائق محددة حسب اللغة."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"claude-api","description":"Build apps with the Claude API or Anthropic SDK. TRIGGER when: code imports `anthropic`/`@anthropic-ai/sdk`/`claude_agent_sdk`, or user asks to use Claude API, Anthropic SDKs, or Agent SDK. DO NOT TRIGGER when: code imports `openai`/other AI SDK, general programming, or ML/data-science tasks.","bodyPreview":"# Building LLM-Powered Applications with Claude\n\nThis skill helps you build LLM-powered applications with Claude. Choose the right surface based on your needs, detect the project language, then read the relevant language-specific documentation.\n\n## Defaults\n\nUnless the user requests otherwise:\n\nFor the Claude model version, please use Claude Opus 4.6, which you can access via the exact model string `claude-opus-4-6`. Please default to using adaptive thinking (`thinking: {type: \"adaptive\"}`) for","body":"# Building LLM-Powered Applications with Claude\n\nThis skill helps you build LLM-powered applications with Claude. Choose the right surface based on your needs, detect the project language, then read the relevant language-specific documentation.\n\n## Defaults\n\nUnless the user requests otherwise:\n\nFor the Claude model version, please use Claude Opus 4.6, which you can access via the exact model string `claude-opus-4-6`. Please default to using adaptive thinking (`thinking: {type: \"adaptive\"}`) for anything remotely complicated. And finally, please default to streaming for any request that may involve long input, long output, or high `max_tokens` — it prevents hitting request timeouts. Use the SDK''s `.get_final_message()` / `.finalMessage()` helper to get the complete response if you don''t need to handle individual stream events\n\n---\n\n## Language Detection\n\nBefore reading code examples, determine which language the user is working in:\n\n1. **Look at project files** to infer the language:\n\n   - `*.py`, `requirements.txt`, `pyproject.toml`, `setup.py`, `Pipfile` → **Python** — read from `python/`\n   - `*.ts`, `*.tsx`, `package.json`, `tsconfig.json` → **TypeScript** — read from `typescript/`\n   - `*.js`, `*.jsx` (no `.ts` files present) → **TypeScript** — JS uses the same SDK, read from `typescript/`\n   - `*.java`, `pom.xml`, `build.gradle` → **Java** — read from `java/`\n   - `*.kt`, `*.kts`, `build.gradle.kts` → **Java** — Kotlin uses the Java SDK, read from `java/`\n   - `*.scala`, `build.sbt` → **Java** — Scala uses the Java SDK, read from `java/`\n   - `*.go`, `go.mod` → **Go** — read from `go/`\n   - `*.rb`, `Gemfile` → **Ruby** — read from `ruby/`\n   - `*.cs`, `*.csproj` → **C#** — read from `csharp/`\n   - `*.php`, `composer.json` → **PHP** — read from `php/`\n\n2. **If multiple languages detected** (e.g., both Python and TypeScript files):\n\n   - Check which language the user''s current file or question relates to\n   - If still ambiguous, ask: \"I detected both Python and TypeScript files. Which language are you using for the Claude API integration?\"\n\n3. **If language can''t be inferred** (empty project, no source files, or unsupported language):\n\n   - Use AskUserQuestion with options: Python, TypeScript, Java, Go, Ruby, cURL/raw HTTP, C#, PHP\n   - If AskUserQuestion is unavailable, default to Python examples and note: \"Showing Python examples. Let me know if you need a different language.\"\n\n4. **If unsupported language detected** (Rust, Swift, C++, Elixir, etc.):\n\n   - Suggest cURL/raw HTTP examples from `curl/` and note that community SDKs may exist\n   - Offer to show Python or TypeScript examples as reference implementations\n\n5. **If user needs cURL/raw HTTP examples**, read from `curl/`.\n\n### Language-Specific Feature Support\n\n| Language   | Tool Runner | Agent SDK | Notes                                 |\n| ---------- | ----------- | --------- | ------------------------------------- |\n| Python     | Yes (beta)  | Yes       | Full support — `@beta_tool` decorator |\n| TypeScript | Yes (beta)  | Yes       | Full support — `betaZodTool` + Zod    |\n| Java       | Yes (beta)  | No        | Beta tool use with annotated classes  |\n| Go         | Yes (beta)  | No        | `BetaToolRunner` in `toolrunner` pkg  |\n| Ruby       | Yes (beta)  | No        | `BaseTool` + `tool_runner` in beta    |\n| cURL       | N/A         | N/A       | Raw HTTP, no SDK features             |\n| C#         | No          | No        | Official SDK                          |\n| PHP        | No          | No        | Official SDK                          |\n\n---\n\n## Which Surface Should I Use?\n\n> **Start simple.** Default to the simplest tier that meets your needs. Single API calls and workflows handle most use cases — only reach for agents when the task genuinely requires open-ended, model-driven exploration.\n\n| Use Case                                        | Tier            | Recommended Surface       | Why                                     |\n| ----------------------------------------------- | --------------- | ------------------------- | --------------------------------------- |\n| Classification, summarization, extraction, Q&A  | Single LLM call | **Claude API**            | One request, one response               |\n| Batch processing or embeddings                  | Single LLM call | **Claude API**            | Specialized endpoints                   |\n| Multi-step pipelines with code-controlled logic | Workflow        | **Claude API + tool use** | You orchestrate the loop                |\n| Custom agent with your own tools                | Agent           | **Claude API + tool use** | Maximum flexibility                     |\n| AI agent with file/web/terminal access          | Agent           | **Agent SDK**             | Built-in tools, safety, and MCP support |\n| Agentic coding assistant                        | Agent           | **Agent SDK**             | Designed for this use case              |\n| Want built-in permissions and guardrails        | Agent           | **Agent SDK**             | Safety features included                |\n\n> **Note:** The Agent SDK is for when you want built-in file/web/terminal tools, permissions, and MCP out of the box. If you want to build an agent with your own tools, Claude API is the right choice — use the tool runner for automatic loop handling, or the manual loop for fine-grained control (approval gates, custom logging, conditional execution).\n\n### Decision Tree\n\n```\nWhat does your application need?\n\n1. Single LLM call (classification, summarization, extraction, Q&A)\n   └── Claude API — one request, one response\n\n2. Does Claude need to read/write files, browse the web, or run shell commands\n   as part of its work? (Not: does your app read a file and hand it to Claude —\n   does Claude itself need to discover and access files/web/shell?)\n   └── Yes → Agent SDK — built-in tools, don''t reimplement them\n       Examples: \"scan a codebase for bugs\", \"summarize every file in a directory\",\n                 \"find bugs using subagents\", \"research a topic via web search\"\n\n3. Workflow (multi-step, code-orchestrated, with your own tools)\n   └── Claude API with tool use — you control the loop\n\n4. Open-ended agent (model decides its own trajectory, your own tools)\n   └── Claude API agentic loop (maximum flexibility)\n```\n\n### Should I Build an Agent?\n\nBefore choosing the agent tier, check all four criteria:\n\n- **Complexity** — Is the task multi-step and hard to fully specify in advance? (e.g., \"turn this design doc into a PR\" vs. \"extract the title from this PDF\")\n- **Value** — Does the outcome justify higher cost and latency?\n- **Viability** — Is Claude capable at this task type?\n- **Cost of error** — Can errors be caught and recovered from? (tests, review, rollback)\n\nIf the answer is \"no\" to any of these, stay at a simpler tier (single call or workflow).\n\n---\n\n## Architecture\n\nEverything goes through `POST /v1/messages`. Tools and output constraints are features of this single endpoint — not separate APIs.\n\n**User-defined tools** — You define tools (via decorators, Zod schemas, or raw JSON), and the SDK''s tool runner handles calling the API, executing your functions, and looping until Claude is done. For full control, you can write the loop manually.\n\n**Server-side tools** — Anthropic-hosted tools that run on Anthropic''s infrastructure. Code execution is fully server-side (declare it in `tools`, Claude runs code automatically). Computer use can be server-hosted or self-hosted.\n\n**Structured outputs** — Constrains the Messages API response format (`output_config.format`) and/or tool parameter validation (`strict: true`). The recommended approach is `client.messages.parse()` which validates responses against your schema automatically. Note: the old `output_format` parameter is deprecated; use `output_config: {format: {...}}` on `messages.create()`.\n\n**Supporting endpoints** — Batches (`POST /v1/messages/batches`), Files (`POST /v1/files`), and Token Counting feed into or support Messages API requests.\n\n---\n\n## Current Models (cached: 2026-02-17)\n\n| Model             | Model ID            | Context        | Input $/1M | Output $/1M |\n| ----------------- | ------------------- | -------------- | ---------- | ----------- |\n| Claude Opus 4.6   | `claude-opus-4-6`   | 200K (1M beta) | $5.00      | $25.00      |\n| Claude Sonnet 4.6 | `claude-sonnet-4-6` | 200K (1M beta) | $3.00      | $15.00      |\n| Claude Haiku 4.5  | `claude-haiku-4-5`  | 200K           | $1.00      | $5.00       |\n\n**ALWAYS use `claude-opus-4-6` unless the user explicitly names a different model.** This is non-negotiable. Do not use `claude-sonnet-4-6`, `claude-sonnet-4-5`, or any other model unless the user literally says \"use sonnet\" or \"use haiku\". Never downgrade for cost — that''s the user''s decision, not yours.\n\n**CRITICAL: Use only the exact model ID strings from the table above — they are complete as-is. Do not append date suffixes.** For example, use `claude-sonnet-4-5`, never `claude-sonnet-4-5-20250514` or any other date-suffixed variant you might recall from training data. If the user requests an older model not in the table (e.g., \"opus 4.5\", \"sonnet 3.7\"), read `shared/models.md` for the exact ID — do not construct one yourself.\n\nA note: if any of the model strings above look unfamiliar to you, that''s to be expected — that just means they were released after your training data cutoff. Rest assured they are real models; we wouldn''t mess with you like that.\n\n---\n\n## Thinking & Effort (Quick Reference)\n\n**Opus 4.6 — Adaptive thinking (recommended):** Use `thinking: {type: \"adaptive\"}`. Claude dynamically decides when and how much to think. No `budget_tokens` needed — `budget_tokens` is deprecated on Opus 4.6 and Sonnet 4.6 and must not be used. Adaptive thinking also automatically enables interleaved thinking (no beta header needed). **When the user asks for \"extended thinking\", a \"thinking budget\", or `budget_tokens`: always use Opus 4.6 with `thinking: {type: \"adaptive\"}`. The concept of a fixed token budget for thinking is deprecated — adaptive thinking replaces it. Do NOT use `budget_tokens` and do NOT switch to an older model.**\n\n**Effort parameter (GA, no beta header):** Controls thinking depth and overall token spend via `output_config: {effort: \"low\"|\"medium\"|\"high\"|\"max\"}` (inside `output_config`, not top-level). Default is `high` (equivalent to omitting it). `max` is Opus 4.6 only. Works on Opus 4.5, Opus 4.6, and Sonnet 4.6. Will error on Sonnet 4.5 / Haiku 4.5. Combine with adaptive thinking for the best cost-quality tradeoffs. Use `low` for subagents or simple tasks; `max` for the deepest reasoning.\n\n**Sonnet 4.6:** Supports adaptive thinking (`thinking: {type: \"adaptive\"}`). `budget_tokens` is deprecated on Sonnet 4.6 — use adaptive thinking instead.\n\n**Older models (only if explicitly requested):** If the user specifically asks for Sonnet 4.5 or another older model, use `thinking: {type: \"enabled\", budget_tokens: N}`. `budget_tokens` must be less than `max_tokens` (minimum 1024). Never choose an older model just because the user mentions `budget_tokens` — use Opus 4.6 with adaptive thinking instead.\n\n---\n\n## Compaction (Quick Reference)\n\n**Beta, Opus 4.6 only.** For long-running conversations that may exceed the 200K context window, enable server-side compaction. The API automatically summarizes earlier context when it approaches the trigger threshold (default: 150K tokens). Requires beta header `compact-2026-01-12`.\n\n**Critical:** Append `response.content` (not just the text) back to your messages on every turn. Compaction blocks in the response must be preserved — the API uses them to replace the compacted history on the next request. Extracting only the text string and appending that will silently lose the compaction state.\n\nSee `{lang}/claude-api/README.md` (Compaction section) for code examples. Full docs via WebFetch in `shared/live-sources.md`.\n\n---\n\n## Reading Guide\n\nAfter detecting the language, read the relevant files based on what the user needs:\n\n### Quick Task Reference\n\n**Single text classification/summarization/extraction/Q&A:**\n→ Read only `{lang}/claude-api/README.md`\n\n**Chat UI or real-time response display:**\n→ Read `{lang}/claude-api/README.md` + `{lang}/claude-api/streaming.md`\n\n**Long-running conversations (may exceed context window):**\n→ Read `{lang}/claude-api/README.md` — see Compaction section\n\n**Function calling / tool use / agents:**\n→ Read `{lang}/claude-api/README.md` + `shared/tool-use-concepts.md` + `{lang}/claude-api/tool-use.md`\n\n**Batch processing (non-latency-sensitive):**\n→ Read `{lang}/claude-api/README.md` + `{lang}/claude-api/batches.md`\n\n**File uploads across multiple requests:**\n→ Read `{lang}/claude-api/README.md` + `{lang}/claude-api/files-api.md`\n\n**Agent with built-in tools (file/web/terminal):**\n→ Read `{lang}/agent-sdk/README.md` + `{lang}/agent-sdk/patterns.md`\n\n### Claude API (Full File Reference)\n\nRead the **language-specific Claude API folder** (`{language}/claude-api/`):\n\n1. **`{language}/claude-api/README.md`** — **Read this first.** Installation, quick start, common patterns, error handling.\n2. **`shared/tool-use-concepts.md`** — Read when the user needs function calling, code execution, memory, or structured outputs. Covers conceptual foundations.\n3. **`{language}/claude-api/tool-use.md`** — Read for language-specific tool use code examples (tool runner, manual loop, code execution, memory, structured outputs).\n4. **`{language}/claude-api/streaming.md`** — Read when building chat UIs or interfaces that display responses incrementally.\n5. **`{language}/claude-api/batches.md`** — Read when processing many requests offline (not latency-sensitive). Runs asynchronously at 50% cost.\n6. **`{language}/claude-api/files-api.md`** — Read when sending the same file across multiple requests without re-uploading.\n7. **`shared/error-codes.md`** — Read when debugging HTTP errors or implementing error handling.\n8. **`shared/live-sources.md`** — WebFetch URLs for fetching the latest official documentation.\n\n> **Note:** For Java, Go, Ruby, C#, PHP, and cURL — these have a single file each covering all basics. Read that file plus `shared/tool-use-concepts.md` and `shared/error-codes.md` as needed.\n\n### Agent SDK\n\nRead the **language-specific Agent SDK folder** (`{language}/agent-sdk/`). Agent SDK is available for **Python and TypeScript only**.\n\n1. **`{language}/agent-sdk/README.md`** — Installation, quick start, built-in tools, permissions, MCP, hooks.\n2. **`{language}/agent-sdk/patterns.md`** — Custom tools, hooks, subagents, MCP integration, session resumption.\n3. **`shared/live-sources.md`** — WebFetch URLs for current Agent SDK docs.\n\n---\n\n## When to Use WebFetch\n\nUse WebFetch to get the latest documentation when:\n\n- User asks for \"latest\" or \"current\" information\n- Cached data seems incorrect\n- User asks about features not covered here\n\nLive documentation URLs are in `shared/live-sources.md`.\n\n## Common Pitfalls\n\n- Don''t truncate inputs when passing files or content to the API. If the content is too long to fit in the context window, notify the user and discuss options (chunking, summarization, etc.) rather than silently truncating.\n- **Opus 4.6 / Sonnet 4.6 thinking:** Use `thinking: {type: \"adaptive\"}` — do NOT use `budget_tokens` (deprecated on both Opus 4.6 and Sonnet 4.6). For older models, `budget_tokens` must be less than `max_tokens` (minimum 1024). This will throw an error if you get it wrong.\n- **Opus 4.6 prefill removed:** Assistant message prefills (last-assistant-turn prefills) return a 400 error on Opus 4.6. Use structured outputs (`output_config.format`) or system prompt instructions to control response format instead.\n- **128K output tokens:** Opus 4.6 supports up to 128K `max_tokens`, but the SDKs require streaming for large `max_tokens` to avoid HTTP timeouts. Use `.stream()` with `.get_final_message()` / `.finalMessage()`.\n- **Tool call JSON parsing (Opus 4.6):** Opus 4.6 may produce different JSON string escaping in tool call `input` fields (e.g., Unicode or forward-slash escaping). Always parse tool inputs with `json.loads()` / `JSON.parse()` — never do raw string matching on the serialized input.\n- **Structured outputs (all models):** Use `output_config: {format: {...}}` instead of the deprecated `output_format` parameter on `messages.create()`. This is a general API change, not 4.6-specific.\n- **Don''t reimplement SDK functionality:** The SDK provides high-level helpers — use them instead of building from scratch. Specifically: use `stream.finalMessage()` instead of wrapping `.on()` events in `new Promise()`; use typed exception classes (`Anthropic.RateLimitError`, etc.) instead of string-matching error messages; use SDK types (`Anthropic.MessageParam`, `Anthropic.Tool`, `Anthropic.Message`, etc.) instead of redefining equivalent interfaces.\n- **Don''t define custom types for SDK data structures:** The SDK exports types for all API objects. Use `Anthropic.MessageParam` for messages, `Anthropic.Tool` for tool definitions, `Anthropic.ToolUseBlock` / `Anthropic.ToolResultBlockParam` for tool results, `Anthropic.Message` for responses. Defining your own `interface ChatMessage { role: string; content: unknown }` duplicates what the SDK already provides and loses type safety.\n- **Report and document output:** For tasks that produce reports, documents, or visualizations, the code execution sandbox has `python-docx`, `python-pptx`, `matplotlib`, `pillow`, and `pypdf` pre-installed. Claude can generate formatted files (DOCX, PDF, charts) and return them via the Files API — consider this for \"report\" or \"document\" type requests instead of plain stdout text.\n"},"category":"official","lastSynced":"2026-03-06T03:15:00.224Z","seo":{"title":{"en":"claude-api: Build LLM Apps with Claude Opus & Adaptive Th...","zh":"Claude API Setup Guide - AIエージェント开发","ja":"Claude API Setup Guide - AIエージェント開発","ko":"Claude API Setup Guide - AI 에이전트 개발","pt":"Claude API Setup Guide: Integração com Anthropic SDK","ru":"Claude API Руководство: Интеграция ИИ Агентов с Anthropic...","ar":"دليل إعداد Claude API: تكامل أدوات الذكاء الاصطناعي مع An..."},"description":{"en":"Learn how to integrate Claude API with automatic Anthropic SDK detection. Build LLM applications using Claude Opus 4.6 model with adaptive thinking capabilit...","zh":"使用Claude API和Anthropic SDK构建LLM应用，了解默认模型版本和adaptive thinking","ja":"Claude APIとAnthropic SDKを使用してLLMアプリケーションを構築する方法、デフォルトモデルバージョンとadaptive thinkingについて","ko":"Claude API와 Anthropic SDK를 사용하여 LLM 애플리케이션을 구축하는 방법, 기본 모델 버전 및 적응형 사고에 대해 알아보기","pt":"Guia técnico para desenvolvedores integrar Claude API via Anthropic SDK. Configure Claude Opus 4.6, adaptive thinking e SDKs oficiais. Tutorial prático para ...","ru":"Техническое руководство по интеграции Claude API через Anthropic SDK. Настройка Claude Opus 4.6, адаптивного мышления и официальных SDK. Практический tutoria...","ar":"دليل تقني للمطورين لدمج Claude API عبر Anthropic SDK. إعداد Claude Opus 4.6، التفكير التكيفي وSDKs الرسمية. برنامج تعليمي عملي لتطبيقات LLM بلغة Python/JavaS..."},"definition":{"en":"claude-api is an AI agent skill that helps developers build applications with Claude API and Anthropic SDKs. It automatically detects when code imports anthropic libraries and provides Claude Opus 4.6 integration with adaptive thinking capabilities for LLM-powered applications.","zh":"Claude API是用于构建大型语言模型应用的API","ja":"Claude APIは、大規模な言語モデルアプリケーションを構築するためのAPIです","ko":"Claude API는 대형 언어 모델 애플리케이션을 구축하기 위한 API입니다","pt":"Claude API é uma skill técnica especializada que auxilia desenvolvedores na integração da API da Anthropic. Detecta automaticamente imports dos SDKs oficiais e fornece documentação específica por linguagem para construção de aplicações LLM com Claude Opus 4.6 e adaptive thinking.","ru":"Claude API — это технический навык, помогающий разработчикам интегрировать API Anthropic. Автоматически обнаруживает импорты официальных SDK и предоставляет языковую документацию для создания LLM-приложений с Claude Opus 4.6 и адаптивным мышлением.","ar":"Claude API هي مهارة تقنية متخصصة تساعد المطورين على دمج واجهة برمجة تطبيقات Anthropic. تكتشف تلقائيًا استيراد SDKs الرسمية وتوفر وثائق بلغة محددة لبناء تطبيقات LLM باستخدام Claude Opus 4.6 والتفكير التكيفي."},"features":{"en":["Automatic detection of anthropic SDK imports (@anthropic-ai/sdk, claude_agent_sdk)","Integration with Claude Opus 4.6 model via exact model string claude-opus-4-6","Default adaptive thinking implementation using thinking: {type: \"adaptive\"}","Project language detection for appropriate documentation routing","Trigger activation on Claude API usage requests or SDK imports","Exclusion filtering for OpenAI and other AI SDK imports"],"zh":["支持adaptive thinking","默认模型版本Claude Opus 4.6","使用Anthropic SDK构建LLM应用","支持多种编程语言","提供详细的文档和示例"],"ja":["adaptive thinkingをサポート","デフォルトモデルバージョンClaude Opus 4.6","Anthropic SDKを使用してLLMアプリケーションを構築","複数のプログラミング言語をサポート","詳細なドキュメントとサンプルを提供"],"ko":["적응형 사고 지원","기본 모델 버전 Claude Opus 4.6","Anthropic SDK를 사용하여 LLM 애플리케이션 구축","다중 프로그래밍 언어 지원","詳細한 문서 및 샘플 제공"],"pt":["Detecção automática de imports: `anthropic`, `@anthropic-ai/sdk`, `claude_agent_sdk`","Configuração padrão com Claude Opus 4.6 (model string: `claude-opus-4-6`)","Suporte integrado para adaptive thinking: `thinking: {type: \"adaptive\"}`","Documentação específica por linguagem de programação detectada","Exclusão inteligente em casos de imports concorrentes (OpenAI, outros SDKs AI)","Otimizado para desenvolvimento de aplicações LLM em múltiplas plataformas"],"ru":["Автоматическое обнаружение импортов: `anthropic`, `@anthropic-ai/sdk`, `claude_agent_sdk`","Конфигурация по умолчанию с Claude Opus 4.6 (model string: `claude-opus-4-6`)","Встроенная поддержка адаптивного мышления: `thinking: {type: \"adaptive\"}`","Языковая документация на основе обнаруженного языка программирования","Интеллектуальное исключение при конкурентных импортах (OpenAI, другие AI SDK)","Оптимизировано для разработки LLM-приложений на multiple платформах"],"ar":["الكشف التلقائي عن الاستيراد: `anthropic`, `@anthropic-ai/sdk`, `claude_agent_sdk`","التكوين الافتراضي مع Claude Opus 4.6 (model string: `claude-opus-4-6`)","دعم مدمج للتفكير التكيفي: `thinking: {type: \"adaptive\"}`","وثائق بلغة محددة بناءً على لغة البرمجة المكتشفة","استبعاد ذكي في حالات الاستيراد التنافسية (OpenAI, أخرى AI SDKs)","محسّن لتطوير تطبيقات LLM على منصات متعددة"]},"keywords":{"en":["how to use claude-api with anthropic sdk","claude-opus-4-6 integration guide","claude-api vs openai api comparison","anthropic sdk automatic detection setup","adaptive thinking implementation claude api","claude_agent_sdk installation tutorial","build llm apps with claude api","claude-api agent skill configuration"],"zh":["Claude API","Anthropic SDK","LLM应用","adaptive thinking","Claude Opus 4.6","AIエージェント开发","大型语言模型"],"ja":["Claude API","Anthropic SDK","LLMアプリケーション","adaptive thinking","Claude Opus 4.6","AIエージェント開発","大規模な言語モデル"],"ko":["Claude API","Anthropic SDK","LLM 애플리케이션","적응형 사고","Claude Opus 4.6","AI 에이전트 개발","대형 언어 모델"],"pt":["claude api tutorial","anthropic sdk integration","claude opus 4.6 setup","adaptive thinking implementation","claude agent sdk documentation","llm applications development","python anthropic integration","javascript claude api"],"ru":["claude api tutorial","anthropic sdk интеграция","claude opus 4.6 настройка","адаптивное мышление реализация","claude agent sdk документация","llm приложения разработка","python anthropic интеграция","javascript claude api"],"ar":["برنامج تعليمي claude api","دمج anthropic sdk","إعداد claude opus 4.6","تنفيذ التفكير التكيفي","وثائق claude agent sdk","تطوير تطبيقات llm","دمج python anthropic","javascript claude api"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Development Agents building LLM-powered applications with Claude''s advanced capabilities.","zh":"非常适合利用 Claude 高级功能构建 LLM 驱动应用程序的 AI 开发智能体。","ja":"Claude の高度な機能を活用して LLM 駆動型アプリケーションを構築する AI 開発エージェントに最適です。","ko":"Claude의 고급 기능을 활용하여 LLM 기반 애플리케이션을 구축하는 AI 개발 에이전트에 완벽합니다.","es":"Ideal para Agentes de Desarrollo de IA que construyen aplicaciones impulsadas por LLM con las capacidades avanzadas de Claude.","fr":"Parfait pour les Agents de Développement d''IA construisant des applications alimentées par des LLM avec les capacités avancées de Claude.","de":"Perfekt für KI-Entwicklungsagenten, die LLM-betriebene Anwendungen mit den fortschrittlichen Fähigkeiten von Claude erstellen.","pt":"Perfeito para Agentes de Desenvolvimento de IA que constroem aplicações alimentadas por LLM com as capacidades avançadas do Claude.","ru":"Идеально подходит для Агентов ИИ-разработки, создающих приложения на базе LLM с использованием расширенных возможностей Claude.","ar":"مثالي لوكلاء تطوير الذكاء الاصطناعي الذين يبنون تطبيقات تعمل بنماذج اللغة الكبيرة (LLM) باستخدام قدرات Claude المتقدمة."},"recommendation":{"en":"Enables direct integration with Claude API and Anthropic SDKs using the exact model string ''claude-opus-4-6'' and adaptive thinking configuration. Provides automatic detection of project language and surfaces appropriate SDK documentation for implementation.","zh":"支持使用确切的模型字符串 ''claude-opus-4-6'' 和自适应思维配置，实现与 Claude API 和 Anthropic SDK 的直接集成。自动检测项目语言并提供相应的 SDK 文档以供实现。","ja":"正確なモデル文字列 ''claude-opus-4-6'' と適応的思考設定を使用して、Claude API および Anthropic SDK との直接統合を可能にします。プロジェクトの言語を自動検出し、実装に適した SDK ドキュメントを表示します。","ko":"정확한 모델 문자열 ''claude-opus-4-6'' 및 적응형 사고 구성을 사용하여 Claude API 및 Anthropic SDK와의 직접 통합을 가능하게 합니다. 프로젝트 언어를 자동으로 감지하고 구현에 적합한 SDK 문서를 제공합니다.","es":"Permite la integración directa con la API de Claude y los SDK de Anthropic utilizando el string de modelo exacto ''claude-opus-4-6'' y la configuración de pensamiento adaptativo. Proporciona detección automática del lenguaje del proyecto y muestra la documentación apropiada del SDK para su implementación.","fr":"Permet une intégration directe avec l''API Claude et les SDK Anthropic en utilisant le string de modèle exact ''claude-opus-4-6'' et la configuration de pensée adaptive. Fournit une détection automatique du langage du projet et affiche la documentation SDK appropriée pour la mise en œuvre.","de":"Ermöglicht die direkte Integration mit der Claude API und den Anthropic SDKs unter Verwendung der exakten Modellzeichenkette ''claude-opus-4-6'' und der adaptiven Denkkonfiguration. Bietet automatische Erkennung der Projektsprache und zeigt die entsprechende SDK-Dokumentation für die Implementierung an.","pt":"Permite a integração direta com a API do Claude e os SDKs da Anthropic usando a string de modelo exata ''claude-opus-4-6'' e a configuração de pensamento adaptativo. Fornece deteção automática do idioma do projeto e disponibiliza a documentação SDK apropriada para implementação.","ru":"Обеспечивает прямую интеграцию с Claude API и SDK Anthropic с использованием точной строки модели ''claude-opus-4-6'' и конфигурации адаптивного мышления. Обеспечивает автоматическое определение языка проекта и предоставляет соответствующую документацию SDK для реализации.","ar":"يتيح التكامل المباشر مع Claude API وأدوات تطوير البرمجيات (SDK) من Anthropic باستخدام سلسلة النموذج الدقيقة ''claude-opus-4-6'' وتكوين التفكير التكيفي. يوفر الكشف التلقائي عن لغة المشروع ويعرض وثائق SDK المناسبة للتنفيذ."},"useCases":{"en":["Building Claude API-powered applications","Integrating Anthropic SDKs into projects","Implementing adaptive thinking configurations","Developing LLM-powered agents with Claude Opus"],"zh":["构建由 Claude API 驱动的应用程序","将 Anthropic SDK 集成到项目中","实施自适应思维配置","利用 Claude Opus 开发 LLM 驱动的智能体"],"ja":["Claude API 駆動のアプリケーション構築","プロジェクトへの Anthropic SDK の統合","適応的思考設定の実装","Claude Opus を使用した LLM 駆動型エージェントの開発"],"ko":["Claude API 기반 애플리케이션 구축","프로젝트에 Anthropic SDK 통합","적응형 사고 구성 구현","Claude Opus를 사용한 LLM 기반 에이전트 개발"],"es":["Construcción de aplicaciones impulsadas por la API de Claude","Integración de los SDK de Anthropic en proyectos","Implementación de configuraciones de pensamiento adaptativo","Desarrollo de agentes impulsados por LLM con Claude Opus"],"fr":["Construction d''applications alimentées par l''API Claude","Intégration des SDK Anthropic dans des projets","Mise en œuvre de configurations de pensée adaptive","Développement d''agents alimentés par des LLM avec Claude Opus"],"de":["Entwicklung von Claude API-betriebenen Anwendungen","Integration von Anthropic SDKs in Projekte","Implementierung von adaptiven Denkkonfigurationen","Entwicklung von LLM-betriebenen Agenten mit Claude Opus"],"pt":["Construção de aplicações alimentadas pela API do Claude","Integração dos SDKs da Anthropic em projetos","Implementação de configurações de pensamento adaptativo","Desenvolvimento de agentes alimentados por LLM com o Claude Opus"],"ru":["Создание приложений на базе Claude API","Интеграция SDK Anthropic в проекты","Реализация конфигураций адаптивного мышления","Разработка агентов на базе LLM с использованием Claude Opus"],"ar":["بناء تطبيقات تعمل بـ Claude API","دمج أدوات تطوير البرمجيات (SDK) من Anthropic في المشاريع","تنفيذ تكوينات التفكير التكيفي","تطوير وكلاء يعملون بنماذج اللغة الكبيرة (LLM) باستخدام Claude Opus"]},"limitations":{"en":["Requires Anthropic SDK installation","Specific to Claude API ecosystem only","Does not trigger for OpenAI or other AI SDKs","Limited to claude-opus-4-6 model by default"],"zh":["需要安装 Anthropic SDK","仅适用于 Claude API 生态系统","不会为 OpenAI 或其他 AI SDK 触发","默认仅限于 claude-opus-4-6 模型"],"ja":["Anthropic SDK のインストールが必要","Claude API エコシステムに限定","OpenAI 或其他 AI SDK ではトリガーされない","デフォルトで claude-opus-4-6 モデルのみに限定"],"ko":["Anthropic SDK 설치 필요","Claude API 생태계에만 해당","OpenAI 또는 다른 AI SDK에서는 트리거되지 않음","기본적으로 claude-opus-4-6 모델로 제한됨"],"es":["Requiere la instalación del SDK de Anthropic","Específico solo para el ecosistema de la API de Claude","No se activa para OpenAI u otros SDKs de IA","Limitado al modelo claude-opus-4-6 por defecto"],"fr":["Nécessite l''installation du SDK Anthropic","Spécifique à l''écosystème de l''API Claude uniquement","Ne se déclenche pas pour OpenAI ou d''autres SDKs d''IA","Limité au modèle claude-opus-4-6 par défaut"],"de":["Erfordert die Installation des Anthropic SDK","Spezifisch nur für das Claude API-Ökosystem","Wird nicht für OpenAI oder andere KI-SDKs ausgelöst","Standardmäßig auf das Modell claude-opus-4-6 beschränkt"],"pt":["Requer a instalação do SDK da Anthropic","Específico apenas para o ecossistema da API do Claude","Não é acionado para OpenAI ou outros SDKs de IA","Limitado ao modelo claude-opus-4-6 por padrão"],"ru":["Требует установки SDK Anthropic","Специфично только для экосистемы Claude API","Не срабатывает для OpenAI или других ИИ SDK","По умолчанию ограничено моделью claude-opus-4-6"],"ar":["يتطلب تثبيت أدوات تطوير البرمجيات (SDK) من Anthropic","مخصص فقط لنظام Claude API البيئي","لا يتم تشغيله لأدوات تطوير البرمجيات (SDK) الخاصة بـ OpenAI أو غيرها من منصات الذكاء الاصطناعي","مقيد بنموذج claude-opus-4-6 افتراضيًا"]},"version":4},"contentHash":"1ec3d558d3364ac7f768471055ded521f95bdb0f3e7239be9e4c8e0b219c587e","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":95}');
