INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/autonomous-loops', 'autonomous-loops', 'affaan-m', 'everything-claude-code', 'official', 'autonomous-loops affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The autonomous-loops skill provides patterns and architectures for running Claude Code autonomously in loops. It enables developers to build everything from simple sequential pipelines to complex RFC-driven multi-agent DAG orchestration systems. Patrones y arquitecturas para bucles autonomos de Claude Code, desde pipelines secuenciales simples hasta sistemas DAG con múltiples agentes Modèles et architectures pour des boucles autonomes de Claude Code, des pipelines séquentiels simples aux systèmes DAG à agents multiples Muster und Architekturen für autonome Loops von Claude Code, von einfachen sequenziellen Pipelines bis hin zu DAG-Systemen mit mehreren Agenten Os loops autônomos permitem que o Claude Code execute tarefas de forma independente, desde pipelines simples até sistemas complexos de multi-agentes Автономные петли позволяют Claude Code выполнять задачи самостоятельно, от простых конвейеров до сложных систем с несколькими агентами تسمح الحلقات المستقلة ل Claude Code بتنفيذ المهام بطريقة مستقلة، من الأنابيب البسيطة إلى أنظمة متعددة الوكلاء المعقدة autonomous-loops setup guide how to use autonomous-loops autonomous-loops vs continuous-agent-loop autonomous-loops install RFC-driven multi-agent DAG systems claude -p pipeline patterns autonomous-loops architecture multi-agent orchestration with Claude Simple `claude -p` pipeline implementation patterns RFC-driven multi-agent DAG orchestration systems Reference implementations for autonomous Claude Code loops Architectural patterns for continuous agent operation autonomous-loops is a skill providing patterns and reference implementations for running Claude Code in autonomous loops. It covers architectures ranging from simple sequential pipelines to RFC-driven multi-agent DAG systems for continuous AI agent operation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/agents-md', 'official', 'getsentry', 'skills', 'getsentry/skills', 'agents-md', 360, 11, 92, '2026-03-06T00:20:36Z', '2026-03-06T04:55:14.788Z', '48b086413d09bab714f61c35b5144ae41932f8178df9099c3fcd1993d64fb318', '{"id":"getsentry/skills/agents-md","name":"agents-md","description":{"en":"The agents-md skill helps developers create and maintain minimal, high-signal agent documentation, targeting under 60 lines in AGENTS.md. It enforces best practices for agent-facing documentation.","es":"AGENTS.md es la documentación estándar para agentes de IA, manténla minimalista y concisa con menos de 60 líneas","fr":"AGENTS.md est la documentation standard pour les outils d''IA, gardez-la minimaliste et concise avec moins de 60 lignes","de":"AGENTS.md ist die Standarddokumentation für KI-Agents, halten Sie sie minimalistisch und prägnant mit weniger als 60 Zeilen","pt":"O AGENTS.md é um arquivo de documentação essencial para agentes de IA, e aqui você encontrará as melhores práticas para criá-lo e mantê-lo","ru":"Файл AGENTS.md является важным документом для ИИ агентов, и здесь вы найдете лучшие практики для его создания и поддержки","ar":"ملف AGENTS.md هو وثيقة أساسية لأدوات الذكاء الاصطناعي، وهنا سوف تجد أفضل الممارسات لإنشائه وضمان استمراريته"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"agents-md","description":"This skill should be used when the user asks to create AGENTS.md, update AGENTS.md, maintain agent docs, set up CLAUDE.md, or needs to keep agent instructions concise. Enforces research-backed best practices for minimal, high-signal agent documentation.","bodyPreview":"# Maintaining AGENTS.md\n\nAGENTS.md is the canonical agent-facing documentation. Keep it minimal—agents are capable and don''t need hand-holding. Target under 60 lines; never exceed 100. Instruction-following quality degrades as document length increases.\n\n## File Setup\n\n1. Create `AGENTS.md` at project root\n2. Create symlink: `ln -s AGENTS.md CLAUDE.md`\n\n## Before Writing\n\nAnalyze the project to understand what belongs in the file:\n\n1. **Package manager** — Check for lock files (`pnpm-lock.yaml`,","body":"# Maintaining AGENTS.md\n\nAGENTS.md is the canonical agent-facing documentation. Keep it minimal—agents are capable and don''t need hand-holding. Target under 60 lines; never exceed 100. Instruction-following quality degrades as document length increases.\n\n## File Setup\n\n1. Create `AGENTS.md` at project root\n2. Create symlink: `ln -s AGENTS.md CLAUDE.md`\n\n## Before Writing\n\nAnalyze the project to understand what belongs in the file:\n\n1. **Package manager** — Check for lock files (`pnpm-lock.yaml`, `yarn.lock`, `package-lock.json`, `uv.lock`, `poetry.lock`)\n2. **Linter/formatter configs** — Look for `.eslintrc`, `biome.json`, `ruff.toml`, `.prettierrc`, etc. (don''t duplicate these in AGENTS.md)\n3. **CI/build commands** — Check `Makefile`, `package.json` scripts, CI configs for canonical commands\n4. **Monorepo indicators** — Check for `pnpm-workspace.yaml`, `nx.json`, Cargo workspace, or subdirectory `package.json` files\n5. **Existing conventions** — Check for existing CONTRIBUTING.md, docs/, or README patterns\n\n## Writing Rules\n\n- **Headers + bullets** — No paragraphs\n- **Code blocks** — For commands and templates\n- **Reference, don''t embed** — Point to existing docs: \"See `CONTRIBUTING.md` for setup\" or \"Follow patterns in `src/api/routes/`\"\n- **No filler** — No intros, conclusions, or pleasantries\n- **Trust capabilities** — Omit obvious context\n- **Prefer file-scoped commands** — Per-file test/lint/typecheck commands over project-wide builds\n- **Don''t duplicate linters** — Code style lives in linter configs, not AGENTS.md\n\n## Required Sections\n\n### Package Manager\nWhich tool and key commands only:\n```markdown\n## Package Manager\nUse **pnpm**: `pnpm install`, `pnpm dev`, `pnpm test`\n```\n\n### File-Scoped Commands\nPer-file commands are faster and cheaper than full project builds. Always include when available:\n```markdown\n## File-Scoped Commands\n| Task | Command |\n|------|---------|\n| Typecheck | `pnpm tsc --noEmit path/to/file.ts` |\n| Lint | `pnpm eslint path/to/file.ts` |\n| Test | `pnpm jest path/to/file.test.ts` |\n```\n\n### Commit Attribution\nAlways include this section. Agents should use their own identity:\n```markdown\n## Commit Attribution\nAI commits MUST include:\n```\nCo-Authored-By: (the agent model''s name and attribution byline)\n```\nExample: `Co-Authored-By: Claude Sonnet 4 <noreply@example.com>`\n```\n\n### Key Conventions\nProject-specific patterns agents must follow. Keep brief.\n\n## Optional Sections\n\nAdd only if truly needed:\n- API route patterns (show template, not explanation)\n- CLI commands (table format)\n- File naming conventions\n- Project structure hints (point to critical files, flag legacy code to avoid)\n- Monorepo overrides (subdirectory `AGENTS.md` files override root)\n\n## Anti-Patterns\n\nOmit these:\n- \"Welcome to...\" or \"This document explains...\"\n- \"You should...\" or \"Remember to...\"\n- Linter/formatter rules already in config files (`.eslintrc`, `biome.json`, `ruff.toml`)\n- Listing installed skills or plugins (agents discover these automatically)\n- Full project-wide build commands when file-scoped alternatives exist\n- Obvious instructions (\"run tests\", \"write clean code\")\n- Explanations of why (just say what)\n- Long prose paragraphs\n\n## Example Structure\n\n```markdown\n# Agent Instructions\n\n## Package Manager\nUse **pnpm**: `pnpm install`, `pnpm dev`\n\n## Commit Attribution\nAI commits MUST include:\n```\nCo-Authored-By: (the agent model''s name and attribution byline)\n```\n\n## File-Scoped Commands\n| Task | Command |\n|------|---------|\n| Typecheck | `pnpm tsc --noEmit path/to/file.ts` |\n| Lint | `pnpm eslint path/to/file.ts` |\n| Test | `pnpm jest path/to/file.test.ts` |\n\n## API Routes\n[Template code block]\n\n## CLI\n| Command | Description |\n|---------|-------------|\n| `pnpm cli sync` | Sync data |\n```\n"},"category":"official","lastSynced":"2026-03-06T04:55:14.788Z","seo":{"title":{"en":"agents-md: Best Practices for AI Agent Documentation Setu...","es":"Guía de Configuración de AGENTS.md para Agentes de IA","fr":"Guide de Configuration d''AGENTS.md pour Outils d''IA","de":"Einrichtungsleitfaden für AGENTS.md für KI-Agents","pt":"Guia de Configuração do AGENTS.md para Ferramentas de IA","ru":"Настройка AGENTS.md для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد AGENTS.md لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create and maintain concise AGENTS.md files with research-backed best practices, and learn to set up CLAUDE.md with ease - get started now!","es":"Aprende a configurar y mantener AGENTS.md para mejorar la documentación de tus agentes de IA con las mejores prácticas","fr":"Découvrez comment configurer et maintenir AGENTS.md pour améliorer la documentation de vos outils d''IA avec les meilleures pratiques","de":"Erfahren Sie, wie Sie AGENTS.md einrichten und warten, um die Dokumentation Ihrer KI-Agents mit bewährten Methoden zu verbessern","pt":"Aprenda a criar e manter o arquivo AGENTS.md com as melhores práticas para documentação de agentes de IA, incluindo dicas para manter a documentação concisa ...","ru":"Узнайте, как создать и поддерживать файл AGENTS.md с помощью рекомендованных практик для документации ИИ агентов, включая советы по поддержанию краткой и эфф...","ar":"تعلم كيفية إنشاء وحدات إدارة ملف AGENTS.md باستخدام أفضل الممارسات لدعم وثائق أدوات الذكاء الاصطناعي، بما في ذلك نصائح للحفاظ على الوثائق الموجزة والفعالة"},"definition":{"en":"agents-md is a skill that provides guidelines for creating and maintaining AGENTS.md files, ensuring concise and effective documentation for AI agents.","es":"AGENTS.md es un archivo de documentación para agentes de IA que proporciona instrucciones concisas","fr":"AGENTS.md est un fichier de documentation pour les outils d''IA qui fournit des instructions concises","de":"AGENTS.md ist eine Dokumentationsdatei für KI-Agents, die prägnante Anweisungen bereitstellt","pt":"O AGENTS.md é um arquivo de documentação que contém instruções e diretrizes para agentes de IA","ru":"Файл AGENTS.md является документом, содержащим инструкции и руководства для ИИ агентов","ar":"ملف AGENTS.md هو وثيقة تحتوي على تعليمات وإرشادات لأدوات الذكاء الاصطناعي"},"features":{"en":["Creates AGENTS.md at project root with minimal documentation","Sets up symlink to CLAUDE.md using ln -s command","Analyzes project package manager for lock files like pnpm-lock.yaml","Enforces research-backed best practices for agent documentation","Targets under 60 lines in AGENTS.md for optimal instruction-following quality"],"es":["Creación de AGENTS.md en la raíz del proyecto","Establecimiento de un enlace simbólico a CLAUDE.md","Análisis de proyecto para determinar el contenido del archivo","Uso de gestores de paquetes como pnpm","Mantenimiento de la documentación por debajo de 100 líneas"],"fr":["Création d''AGENTS.md à la racine du projet","Établissement d''un lien symbolique vers CLAUDE.md","Analyse de projet pour déterminer le contenu du fichier","Utilisation de gestionnaires de paquets tels que pnpm","Maintenance de la documentation en dessous de 100 lignes"],"de":["Erstellung von AGENTS.md im Projektstamm","Einrichtung eines symbolischen Links zu CLAUDE.md","Projektanalyse zur Bestimmung des Dateiinhalts","Verwendung von Paketmanagern wie pnpm","Wartung der Dokumentation unter 100 Zeilen"],"pt":["Criação do arquivo AGENTS.md no diretório raiz do projeto","Configuração de link simbólico para CLAUDE.md","Análise do projeto para entender o que deve ser incluído no arquivo","Manutenção da documentação concisa e eficaz, com menos de 60 linhas","Uso de práticas recomendadas para documentação de agentes de IA"],"ru":["Создание файла AGENTS.md в корневом каталоге проекта","Настройка символической ссылки на CLAUDE.md","Анализ проекта для понимания того, что должно быть включено в файл","Поддержание краткой и эффективной документации, менее 60 строк","Использование рекомендованных практик для документации ИИ агентов"],"ar":["إنشاء ملف AGENTS.md في الدليل الجذري للمشروع","إعداد الارتباط الرمزي لملف CLAUDE.md","تحليل المشروع لفهم ما يجب إدراجه في الملف","الحفاظ على وثائق موجزة وفعالة، أقل من 60 سطرا","استخدام أفضل الممارسات لدعم وثائق أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use agents-md","what is agents-md","agents-md setup guide","agents-md alternative","agents-md vs documentation tools","create AGENTS.md file","maintain CLAUDE.md","agent documentation best practices"],"es":["agentes de ia","documentación de agentes","mejores prácticas para agentes de ia","configuración de AGENTS.md","pnpm","CLAUDE.md","documentación minimalista"],"fr":["outils d''ia","documentation d''outils","meilleures pratiques pour les outils d''ia","configuration d''AGENTS.md","pnpm","CLAUDE.md","documentation minimaliste"],"de":["ki-agents","dokumentation von ki-agents","bewährte methoden für ki-agents","einrichtung von AGENTS.md","pnpm","CLAUDE.md","minimalistische dokumentation"],"pt":["AGENTS.md","documentação de agentes de IA","melhores práticas para documentação","criação de AGENTS.md","manutenção de AGENTS.md","ferramentas de IA","desenvolvimento de software","documentação técnica"],"ru":["AGENTS.md","документация ИИ агентов","лучшие практики для документации","создание AGENTS.md","поддержка AGENTS.md","ИИ агенты","разработка программного обеспечения","техническая документация"],"ar":["AGENTS.md","وثائق أدوات الذكاء الاصطناعي","أفضل الممارسات لدعم الوثائق","إنشاء AGENTS.md","صيانة AGENTS.md","أدوات الذكاء الاصطناعي","تطوير البرمجيات","الوثائق الفنية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing concise and high-signal documentation, such as those using CLAUDE.md or AGENTS.md files.","zh":"非常适合需要简洁高信号文档的AI代理，例如使用CLAUDE.md或AGENTS.md文件的代理。","ja":"CLAUDE.mdやAGENTS.mdファイルを使用するなど、簡潔で高信号のドキュメントが必要なAIエージェントに最適です。","ko":"CLAUDE.md 또는 AGENTS.md 파일을 사용하는 것과 같은 간결하고 높은 신호의 문서가 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan documentación concisa y de alta señal, como aquellos que utilizan archivos CLAUDE.md o AGENTS.md.","fr":"Parfait pour les agents IA ayant besoin d''une documentation concise et à forte signalisation, tels que ceux utilisant des fichiers CLAUDE.md ou AGENTS.md.","de":"Perfekt für KI-Agents, die eine präzise und hochwertige Dokumentation benötigen, wie z.B. solche, die CLAUDE.md- oder AGENTS.md-Dateien verwenden.","pt":"Perfeito para Agentes de IA que necessitam de documentação concisa e de alta qualidade, como aqueles que usam arquivos CLAUDE.md ou AGENTS.md.","ru":"Идеально подходит для агентов ИИ, которым требуется краткая и высококачественная документация, например, использующих файлы CLAUDE.md или AGENTS.md.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى توثيق ممتاز وconcise، مثل تلك التي تستخدم ملفات CLAUDE.md أو AGENTS.md."},"recommendation":{"en":"Empowers agents to maintain minimal and research-backed agent documentation, utilizing markdown files like AGENTS.md and CLAUDE.md, and enforcing best practices for instruction-following quality, with a focus on package managers like pnpm and file formats like .md.","zh":"赋予代理维护最小化和研究支持的代理文档的能力，利用markdown文件（如AGENTS.md和CLAUDE.md），并执行最佳实践以确保指令遵循质量，重点关注包管理器（如pnpm）和文件格式（如.md）。","ja":"AGENTS.mdやCLAUDE.mdなどのマークダウンファイルを使用して、エージェントドキュメントを最小限に保ち、研究に基づいたものにする能力をエージェントに与え、指示の遵守の質を確保するためのベストプラクティスを実施し、pnpmなどのパッケージマネージャーや.mdなどのファイル形式に重点を置く。","ko":"에이전트 문서를 최소화하고 연구에 기반한 에이전트 문서를 유지할 수 있는 능력을 에이전트에게 부여하고, AGENTS.md 및 CLAUDE.md와 같은 마크다운 파일을 사용하여 지침을 따르는 품질에 대한 최고의 관행을 시행하며, pnpm과 같은 패키지 관리자와 .md와 같은 파일 형식에 중점을 둡니다.","es":"Habilita a los agentes a mantener una documentación de agente minimalista y respaldada por la investigación, utilizando archivos markdown como AGENTS.md y CLAUDE.md, y aplicando las mejores prácticas para la calidad de seguimiento de instrucciones, centrándose en administradores de paquetes como pnpm y formatos de archivo como .md.","fr":"Permet aux agents de maintenir une documentation d''agent minimaliste et étayée par la recherche, en utilisant des fichiers markdown comme AGENTS.md et CLAUDE.md, et en appliquant les meilleures pratiques pour la qualité de suivi des instructions, en se concentrant sur les gestionnaires de paquets comme pnpm et les formats de fichiers comme .md.","de":"Ermöglicht es den Agents, eine minimalistische und forschungsbasierte Agentendokumentation zu pflegen, indem sie Markdown-Dateien wie AGENTS.md und CLAUDE.md verwenden und bewährte Methoden für die Qualität der Anweisungsverfolgung anwenden, mit Fokus auf Paketmanager wie pnpm und Dateiformate wie .md.","pt":"Habilita os agentes a manter a documentação do agente minimal e baseada em pesquisas, utilizando arquivos markdown como AGENTS.md e CLAUDE.md, e aplicando as melhores práticas para a qualidade de seguimento de instruções, com foco em gerenciadores de pacotes como pnpm e formatos de arquivo como .md.","ru":"Позволяет агентам поддерживать минималистичную и научно обоснованную документацию агентов, используя файлы markdown, такие как AGENTS.md и CLAUDE.md, и обеспечивая соблюдение лучших практик для качества выполнения инструкций, с акцентом на менеджерах пакетов, таких как pnpm, и форматах файлов, таких как .md.","ar":"تمكين الوكيل من الحفاظ على توثيق الوكيل الأدنى والأكثر دقة، باستخدام ملفات markdown مثل AGENTS.md و CLAUDE.md، وتنفيذ أفضل الممارسات لجودة اتباع الإرشادات، مع التركيز على مديري الحزم مثل pnpm والتنسيقات مثل .md."},"useCases":{"en":["Creating AGENTS.md files for project documentation","Updating CLAUDE.md for agent instructions","Maintaining concise agent documentation under 60 lines"],"zh":["为项目文档创建AGENTS.md文件","更新CLAUDE.md以获取代理指令","保持代理文档在60行以内"],"ja":["プロジェクトドキュメントのためにAGENTS.mdファイルを作成する","エージェントの指示のためにCLAUDE.mdを更新する","エージェントドキュメントを60行以内に保つ"],"ko":["프로젝트 문서를 위한 AGENTS.md 파일 생성","에이전트 지침을 위한 CLAUDE.md 업데이트","에이전트 문서를 60행 이내로 유지"],"es":["Crear archivos AGENTS.md para la documentación de proyectos","Actualizar CLAUDE.md para las instrucciones del agente","Mantener una documentación de agente concisa en menos de 60 líneas"],"fr":["Créer des fichiers AGENTS.md pour la documentation de projet","Mettre à jour CLAUDE.md pour les instructions de l''agent","Maintenir une documentation d''agent concise en moins de 60 lignes"],"de":["Erstellen von AGENTS.md-Dateien für die Projektdokumentation","Aktualisieren von CLAUDE.md für die Anweisungen des Agents","Pflegen einer kompakten Agentendokumentation mit weniger als 60 Zeilen"],"pt":["Criar arquivos AGENTS.md para documentação de projetos","Atualizar CLAUDE.md para instruções do agente","Manter documentação concisa do agente com menos de 60 linhas"],"ru":["Создание файлов AGENTS.md для документации проектов","Обновление CLAUDE.md для инструкций агента","Поддержание краткой документации агента менее 60 строк"],"ar":["إنشاء ملفات AGENTS.md لتوثيق المشاريع","تحديث CLAUDE.md لإرشادات الوكيل","الحفاظ على توثيق الوكيل الموجز أقل من 60 سطرا"]},"limitations":{"en":["Requires project root access for file creation","Limited to markdown file format (.md)","Target document length should not exceed 100 lines"],"zh":["需要项目根目录访问权限以创建文件","仅限markdown文件格式(.md)","目标文档长度不应超过100行"],"ja":["ファイルを作成するためにプロジェクトルートへのアクセスが必要","マークダウンファイル形式(.md)のみ","対象ドキュメントの長さは100行を超えるべきではない"],"ko":["파일을 생성하기 위해 프로젝트 루트에 대한 액세스가 필요함","마크다운 파일 형식(.md)만 해당함","대상 문서의 길이는 100행을 초과해서는 안 됨"],"es":["Requiere acceso a la raíz del proyecto para la creación de archivos","Limitado al formato de archivo markdown (.md)","La longitud del documento de destino no debe exceder las 100 líneas"],"fr":["Nécessite un accès à la racine du projet pour la création de fichiers","Limité au format de fichier markdown (.md)","La longueur du document cible ne doit pas dépasser 100 lignes"],"de":["Benötigt Zugriff auf die Projektwurzel für die Dateierstellung","Begrenzt auf das Markdown-Dateiformat (.md)","Die Länge des Ziel-Dokuments sollte 100 Zeilen nicht überschreiten"],"pt":["Requer acesso à raiz do projeto para criação de arquivos","Limitado ao formato de arquivo markdown (.md)","O comprimento do documento de destino não deve exceder 100 linhas"],"ru":["Требуется доступ к корню проекта для создания файлов","Ограничен форматом файла markdown (.md)","Длина целевого документа не должна превышать 100 строк"],"ar":["يتطلب الوصول إلى الجذر المشروع لإنشاء الملفات","محدود بتنسيق ملف markdown (.md)","يجب ألا يتجاوز طول المستند المستهدف 100 سطر"]},"version":4},"contentHash":"48b086413d09bab714f61c35b5144ae41932f8178df9099c3fcd1993d64fb318","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":92}');
