INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/agents-md', 'agents-md', 'getsentry', 'skills', 'official', 'agents-md getsentry skills official tag-production The agents-md skill helps developers create and maintain minimal, high-signal agent documentation, targeting under 60 lines in AGENTS.md. It enforces best practices for agent-facing documentation. AGENTS.md es la documentación estándar para agentes de IA, manténla minimalista y concisa con menos de 60 líneas AGENTS.md est la documentation standard pour les outils d''IA, gardez-la minimaliste et concise avec moins de 60 lignes AGENTS.md ist die Standarddokumentation für KI-Agents, halten Sie sie minimalistisch und prägnant mit weniger als 60 Zeilen O AGENTS.md é um arquivo de documentação essencial para agentes de IA, e aqui você encontrará as melhores práticas para criá-lo e mantê-lo Файл AGENTS.md является важным документом для ИИ агентов, и здесь вы найдете лучшие практики для его создания и поддержки ملف AGENTS.md هو وثيقة أساسية لأدوات الذكاء الاصطناعي، وهنا سوف تجد أفضل الممارسات لإنشائه وضمان استمراريته how to use agents-md what is agents-md agents-md setup guide agents-md alternative agents-md vs documentation tools create AGENTS.md file maintain CLAUDE.md agent documentation best practices Creates AGENTS.md at project root with minimal documentation Sets up symlink to CLAUDE.md using ln -s command Analyzes project package manager for lock files like pnpm-lock.yaml Enforces research-backed best practices for agent documentation Targets under 60 lines in AGENTS.md for optimal instruction-following quality agents-md is a skill that provides guidelines for creating and maintaining AGENTS.md files, ensuring concise and effective documentation for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vercel-labs/skills/find-skills', 'official', 'vercel-labs', 'skills', 'vercel-labs/skills', 'find-skills', 8519, 715, 92, '2026-03-06T03:23:03Z', '2026-03-06T03:27:31.943Z', '54b44dc9539df865fbb060f62fb062e8232e765852a0cf14c38301fe0c1eb264', '{"id":"vercel-labs/skills/find-skills","name":"find-skills","description":{"en":"The find-skills agent skill enables developers and users to discover and install new capabilities from the open agent skills ecosystem. It parses user intent to recommend relevant skills for extending an agent''s functionality.","zh":"find-skills是一个专门用于发现和安装AI代理技能的专用工具。当开发者询问如何实现特定功能或寻找现有解决方案时，该技能会自动搜索开放的技能生态系统，推荐并安装相关工具、模板和工作流。","ja":"find-skillsはAIエージェントスキルの検索・インストール専用ツールです。開発者が特定機能の実現方法を問う際、オープンスキルエコシステムを自動検索し、関連ツールやテンプレートを推薦します。","ko":"find-skills는 AI 에이전트 스킬 발견 및 설치를 위한 전문 도구입니다. 개발자가 특정 기능 구현 방법을 질문할 때 오픈 스킬 생태계를 자동 검색하여 관련 도구와 템플릿을 추천합니다.","pt":"A skill find-skills é um utilitário técnico para desenvolvedores que permite descobrir e instalar habilidades de agentes IA a partir de um ecossistema aberto. Ela é ativada quando um usuário solicita funcionalidades específicas ou extensões de capacidade.","ru":"Навык find-skills — это техническая утилита для разработчиков, позволяющая находить и устанавливать навыки ИИ Агентов из открытой экосистемы. Он активируется, когда пользователь запрашивает определенные функции или расширения возможностей.","ar":"مهارة find-skills هي أداة تقنية للمطورين تتيح اكتشاف وتثبيت مهارات وكلاء الذكاء الاصطناعي من نظام مفتوح. يتم تنشيطها عندما يطلب المستخدم وظائف محددة أو توسيع القدرات."},"owner":"vercel-labs","repo":"skills","repoPath":"vercel-labs/skills","stars":8519,"forks":715,"updatedAt":"2026-03-06T03:23:03Z","topics":[],"skillMd":{"name":"find-skills","description":"Helps users discover and install agent skills when they ask questions like how do I do X, find a skill for X, is there a skill that can..., or express interest in extending capabilities. This skill should be used when the user is looking for functionality that might exist as an installable skill.","bodyPreview":"# Find Skills\n\nThis skill helps you discover and install skills from the open agent skills ecosystem.\n\n## When to Use This Skill\n\nUse this skill when the user:\n\n- Asks \"how do I do X\" where X might be a common task with an existing skill\n- Says \"find a skill for X\" or \"is there a skill for X\"\n- Asks \"can you do X\" where X is a specialized capability\n- Expresses interest in extending agent capabilities\n- Wants to search for tools, templates, or workflows\n- Mentions they wish they had help with a","body":"# Find Skills\n\nThis skill helps you discover and install skills from the open agent skills ecosystem.\n\n## When to Use This Skill\n\nUse this skill when the user:\n\n- Asks \"how do I do X\" where X might be a common task with an existing skill\n- Says \"find a skill for X\" or \"is there a skill for X\"\n- Asks \"can you do X\" where X is a specialized capability\n- Expresses interest in extending agent capabilities\n- Wants to search for tools, templates, or workflows\n- Mentions they wish they had help with a specific domain (design, testing, deployment, etc.)\n\n## What is the Skills CLI?\n\nThe Skills CLI (`npx skills`) is the package manager for the open agent skills ecosystem. Skills are modular packages that extend agent capabilities with specialized knowledge, workflows, and tools.\n\n**Key commands:**\n\n- `npx skills find [query]` - Search for skills interactively or by keyword\n- `npx skills add <package>` - Install a skill from GitHub or other sources\n- `npx skills check` - Check for skill updates\n- `npx skills update` - Update all installed skills\n\n**Browse skills at:** https://skills.sh/\n\n## How to Help Users Find Skills\n\n### Step 1: Understand What They Need\n\nWhen a user asks for help with something, identify:\n\n1. The domain (e.g., React, testing, design, deployment)\n2. The specific task (e.g., writing tests, creating animations, reviewing PRs)\n3. Whether this is a common enough task that a skill likely exists\n\n### Step 2: Search for Skills\n\nRun the find command with a relevant query:\n\n```bash\nnpx skills find [query]\n```\n\nFor example:\n\n- User asks \"how do I make my React app faster?\" → `npx skills find react performance`\n- User asks \"can you help me with PR reviews?\" → `npx skills find pr review`\n- User asks \"I need to create a changelog\" → `npx skills find changelog`\n\nThe command will return results like:\n\n```\nInstall with npx skills add <owner/repo@skill>\n\nvercel-labs/agent-skills@vercel-react-best-practices\n└ https://skills.sh/vercel-labs/agent-skills/vercel-react-best-practices\n```\n\n### Step 3: Present Options to the User\n\nWhen you find relevant skills, present them to the user with:\n\n1. The skill name and what it does\n2. The install command they can run\n3. A link to learn more at skills.sh\n\nExample response:\n\n```\nI found a skill that might help! The \"vercel-react-best-practices\" skill provides\nReact and Next.js performance optimization guidelines from Vercel Engineering.\n\nTo install it:\nnpx skills add vercel-labs/agent-skills@vercel-react-best-practices\n\nLearn more: https://skills.sh/vercel-labs/agent-skills/vercel-react-best-practices\n```\n\n### Step 4: Offer to Install\n\nIf the user wants to proceed, you can install the skill for them:\n\n```bash\nnpx skills add <owner/repo@skill> -g -y\n```\n\nThe `-g` flag installs globally (user-level) and `-y` skips confirmation prompts.\n\n## Common Skill Categories\n\nWhen searching, consider these common categories:\n\n| Category        | Example Queries                          |\n| --------------- | ---------------------------------------- |\n| Web Development | react, nextjs, typescript, css, tailwind |\n| Testing         | testing, jest, playwright, e2e           |\n| DevOps          | deploy, docker, kubernetes, ci-cd        |\n| Documentation   | docs, readme, changelog, api-docs        |\n| Code Quality    | review, lint, refactor, best-practices   |\n| Design          | ui, ux, design-system, accessibility     |\n| Productivity    | workflow, automation, git                |\n\n## Tips for Effective Searches\n\n1. **Use specific keywords**: \"react testing\" is better than just \"testing\"\n2. **Try alternative terms**: If \"deploy\" doesn''t work, try \"deployment\" or \"ci-cd\"\n3. **Check popular sources**: Many skills come from `vercel-labs/agent-skills` or `ComposioHQ/awesome-claude-skills`\n\n## When No Skills Are Found\n\nIf no relevant skills exist:\n\n1. Acknowledge that no existing skill was found\n2. Offer to help with the task directly using your general capabilities\n3. Suggest the user could create their own skill with `npx skills init`\n\nExample:\n\n```\nI searched for skills related to \"xyz\" but didn''t find any matches.\nI can still help you with this task directly! Would you like me to proceed?\n\nIf this is something you do often, you could create your own skill:\nnpx skills init my-xyz-skill\n```\n"},"category":"official","lastSynced":"2026-03-06T03:27:31.943Z","seo":{"title":{"en":"find-skills: Discover & Install AI Agent Skills | Setup G...","zh":"find-skills 技能安装指南：扩展AI代理功能的最佳实践","ja":"find-skills セットアップガイド：AIエージェントの機能拡張","ko":"find-skills 설치 가이드: AI 에이전트 기능 확장 방법","pt":"find-skills: Guia de Instalação para Desenvolvedores de A...","ru":"find-skills: Руководство по поиску и установке навыков ИИ...","ar":"find-skills: دليل المطورين لاكتشاف وتثبيت مهارات وكيل الذ..."},"description":{"en":"Master your AI agent''s potential. Use the find-skills agent skill to instantly discover and install new capabilities from the open ecosystem. Extend function...","zh":"find-skills技能帮助开发者发现和安装AI代理技能。当用户询问如何实现特定功能或寻找现有技能时，自动搜索开放技能生态系统并推荐相关工具和工作流。","ja":"find-skillsはAIエージェントスキルの検索とインストールを支援します。特定機能の実現方法を問う際に、オープンスキルエコシステムからツールやワークフローを推薦します。","ko":"find-skills는 AI 에이전트 스킬 발견 및 설치를 지원합니다. 특정 기능 구현 방법 질문 시 오픈 스킬 생태계에서 도구와 워크플로우를 추천합니다.","pt":"Saiba como usar a skill find-skills para descobrir e instalar capacidades em agentes IA. Expanda funcionalidades com skills para tarefas comuns, ferramentas ...","ru":"Узнайте, как использовать навык find-skills для поиска и установки возможностей в ИИ Агентах. Расширяйте функциональность с помощью навыков для общих задач, ...","ar":"تعرف على كيفية استخدام مهارة find-skills لاكتشاف وتثبيت قدرات جديدة لوكلاء الذكاء الاصطناعي. قم بتوسيع الوظائف باستخدام مهارات للمهام الشائعة والأدوات وسير ا..."},"definition":{"en":"find-skills is an AI agent skill that helps users discover and install other skills from the open ecosystem. It is triggered when a user asks how to perform a task, searches for a specific capability, or expresses interest in extending their agent''s functionalities.","zh":"find-skills是一个AI代理技能，专门帮助用户发现和安装来自开放技能生态系统的功能扩展。当用户询问如何实现特定任务、寻找现有技能或表达扩展能力需求时，该技能会自动搜索并提供可安装的技能解决方案。","ja":"find-skillsは、オープンスキルエコシステムから機能拡張を発見・インストールするAIエージェントスキルです。特定タスクの実現方法や既存スキルの検索時に、自動的にソリューションを提供します。","ko":"find-skills는 오픈 스킬 생태계에서 기능 확장을 발견하고 설치하는 AI 에이전트 스킬입니다. 특정 작업 구현 방법이나 기존 스킬 검색 시 자동으로 솔루션을 제공합니다.","pt":"A find-skills é uma habilidade de agente IA projetada para ajudar usuários a descobrir e instalar outras skills de um ecossistema aberto. Ela responde a consultas como ''como faço X'' ou ''existe uma skill para X'', facilitando a extensão de capacidades do agente.","ru":"find-skills — это навык ИИ Агента, предназначенный для помощи пользователям в поиске и установке других навыков из открытой экосистемы. Он реагирует на запросы, такие как ''как сделать X'' или ''есть ли навык для X'', упрощая расширение возможностей агента.","ar":"find-skills هي مهارة وكيل ذكاء اصطناعي مصممة لمساعدة المستخدمين في اكتشاف وتثبيت مهارات أخرى من نظام مفتوح. تستجيب لاستفسارات مثل ''كيف أفعل X'' أو ''هل توجد مهارة لـ X''، مما يسهل توسيع قدرات الوكيل."},"features":{"en":["Responds to user queries like ''how do I do X'' or ''find a skill for X''","Processes user intent to find skills for specialized capabilities","Activates when a user expresses interest in extending agent capabilities","Helps users search for tools, templates, or workflows as installable skills"],"zh":["自动响应“如何实现X功能”类查询并搜索技能库","处理“寻找X技能”和“是否有X技能”等直接请求","识别专业化能力需求并推荐对应技能","支持工具、模板和工作流的生态系统搜索","开放代理技能生态系统的集成访问","根据用户能力扩展需求提供智能推荐"],"ja":["「X機能の実現方法」クエリへの自動応答とスキル検索","「Xスキルを探して」といった直接リクエストの処理","専門能力要件の識別と対応スキルの推薦","ツール・テンプレート・ワークフローのエコシステム検索","オープンエージェントスキルエコシステムへの統合アクセス","ユーザーの能力拡張ニーズに基づく智能推薦"],"ko":["“X 기능 구현 방법” 쿼리에 대한 자동 응답 및 스킬 검색","“X 스킬 찾기” 등의 직접 요청 처리","전문 능력 요구 사항 식별 및 해당 스킬 추천","도구, 템플릿, 워크플로우 생태계 검색 지원","오픈 에이전트 스킬 생태계 통합 접근","사용자 능력 확장 요구에 따른 지능형 추천"],"pt":["Descoberta de skills para tarefas comuns (ex: ''como faço X'')","Instalação de habilidades de ecossistema aberto de agentes","Ativação por solicitações de extensão de capacidades","Suporte a pesquisa de ferramentas, templates e fluxos de trabalho","Resposta a consultas como ''encontre uma skill para X''"],"ru":["Поиск навыков для общих задач (например: ''как сделать X'')","Установка навыков из открытой экосистемы агентов","Активация по запросам на расширение возможностей","Поддержка поиска инструментов, шаблонов и рабочих процессов","Ответ на запросы типа ''найти навык для X''"],"ar":["اكتشاف المهارات للمهام الشائعة (مثال: ''كيف أفعل X'')","تثبيت مهارات من نظام مفتوح للوكلاء","التنشيط عند طلب توسيع القدرات","دعم البحث عن الأدوات والقوالب وسير العمل","الاستجابة لاستفسارات مثل ''ابحث عن مهارة لـ X''"]},"keywords":{"en":["how to use find-skills","what is find-skills","find-skills alternative","find-skills vs skill discovery","find-skills install","find-skills setup guide","AI agent skill discovery","install agent capabilities","extend AI agent functionality"],"zh":["AI代理技能安装","find-skills使用指南","扩展AI代理功能","技能生态系统搜索","开发者工具推荐","AI技能发现平台","如何安装代理技能","工作流模板安装"],"ja":["AIエージェントスキルインストール","find-skills 使い方","AIエージェント機能拡張","スキルエコシステム検索","開発者向けツール推薦","AIスキル発見プラットフォーム","エージェントスキルインストール方法","ワークフローテンプレート設定"],"ko":["AI 에이전트 스킬 설치","find-skills 사용법","AI 에이전트 기능 확장","스킬 생태계 검색","개발자 도구 추천","AI 스킬 발견 플랫폼","에이전트 스킬 설치 방법","워크플로우 템플릿 설정"],"pt":["skill find-skills instalação","descobrir habilidades agente IA","ecossistema aberto skills","como instalar skills agente","extender capacidades agente IA","encontrar skill para tarefa"],"ru":["навык find-skills установка","найти навыки ИИ Агента","открытая экосистема навыков","как установить навыки агента","расширить возможности ИИ Агента","поиск навыка для задачи"],"ar":["تثبيت مهارة find-skills","اكتشاف مهارات وكيل الذكاء الاصطناعي","نظام مهارات مفتوح","كيفية تثبيت مهارات الوكيل","توسيع قدرات وكيل الذكاء الاصطناعي","العثور على مهارة للمهمة"]}},"agentAnalysis":{"suitability":{"en":"Essential for any agent ecosystem manager needing to expand capabilities through skill discovery and installation.","zh":"对于需要通过技能发现和安装来扩展能力的任何智能体生态系统管理者来说至关重要。","ja":"スキルの発見とインストールを通じて機能拡張を必要とするあらゆるエージェントエコシステム管理者にとって不可欠です。","ko":"스킬 발견 및 설치를 통해 기능을 확장해야 하는 모든 에이전트 생태계 관리자에게 필수적입니다.","es":"Esencial para cualquier gestor de ecosistema de agentes que necesite expandir capacidades mediante el descubrimiento e instalación de skills.","fr":"Essentiel pour tout gestionnaire d''écosystème d''agents ayant besoin d''étendre les capacités par la découverte et l''installation de skills.","de":"Essenziell für jeden Manager eines Agenten-Ökosystems, der Fähigkeiten durch Skill-Entdeckung und -Installation erweitern muss.","pt":"Essencial para qualquer gestor de ecossistema de agentes que precise expandir capacidades através da descoberta e instalação de habilidades.","ru":"Необходим для любого менеджера экосистемы агентов, которому требуется расширить возможности за счет обнаружения и установки навыков.","ar":"أساسي لأي مدير لنظام بيئة الوكلاء يحتاج إلى توسيع القدرات من خلال اكتشاف المهارات وتثبيتها."},"recommendation":{"en":"Enables dynamic capability expansion by searching and installing from the open agent skills ecosystem. Directly addresses user queries about functionality gaps by providing access to specialized tools, templates, and workflows.","zh":"通过从开放的智能体技能生态系统中搜索和安装来实现动态能力扩展。通过提供对专用工具、模板和工作流程的访问，直接解决用户关于功能差距的查询。","ja":"オープンなエージェントスキルエコシステムから検索してインストールすることで、動的な機能拡張を可能にします。専門的なツール、テンプレート、ワークフローへのアクセスを提供することで、機能ギャップに関するユーザーのクエリに直接対応します。","ko":"오픈 에이전트 스킬 생태계에서 검색 및 설치를 통해 동적 기능 확장을 가능하게 합니다. 전문 도구, 템플릿 및 워크플로우에 대한 접근을 제공하여 기능 격차에 대한 사용자 쿼리를 직접 해결합니다.","es":"Permite la expansión dinámica de capacidades mediante la búsqueda e instalación desde el ecosistema abierto de skills de agentes. Aborda directamente las consultas de los usuarios sobre brechas de funcionalidad al proporcionar acceso a herramientas especializadas, templates y workflows.","fr":"Permet l''expansion dynamique des capacités en recherchant et en installant depuis l''écosystème ouvert de skills d''agents. Répond directement aux requêtes des utilisateurs concernant les lacunes fonctionnelles en fournissant l''accès à des outils spécialisés, des templates et des workflows.","de":"Ermöglicht die dynamische Erweiterung von Fähigkeiten durch Suche und Installation aus dem offenen Agenten-Skills-Ökosystem. Geht direkt auf Benutzeranfragen zu Funktionslücken ein, indem spezialisierte Tools, Templates und Workflows bereitgestellt werden.","pt":"Permite a expansão dinâmica de capacidades através da busca e instalação a partir do ecossistema aberto de habilidades de agentes. Aborda diretamente consultas dos usuários sobre lacunas de funcionalidade, fornecendo acesso a ferramentas especializadas, modelos e fluxos de trabalho.","ru":"Обеспечивает динамическое расширение возможностей за счет поиска и установки из открытой экосистемы навыков агентов. Непосредственно отвечает на запросы пользователей о пробелах в функциональности, предоставляя доступ к специализированным инструментам, шаблонам и рабочим процессам.","ar":"يمكن من التوسع الديناميكي للقدرات من خلال البحث والتثبيت من نظام بيئة مهارات الوكلاء المفتوح. يتناول مباشرة استفسارات المستخدمين حول فجوات الوظائف من خلال توفير الوصول إلى أدوات متخصصة وقوالب وسير عمل."},"useCases":{"en":["Responding to ''how do I do X'' queries with skill recommendations","Finding installable skills for specialized capabilities","Extending agent functionality based on user-expressed needs","Searching for tools and workflows in the skills ecosystem"],"zh":["通过技能推荐响应‘我如何做X’的查询","为专业能力寻找可安装的技能","根据用户表达的需求扩展智能体功能","在技能生态系统中搜索工具和工作流程"],"ja":["「Xの実行方法」というクエリにスキル推薦で応答する","専門的な機能のためにインストール可能なスキルを見つける","ユーザーが表明したニーズに基づいてエージェント機能を拡張する","スキルエコシステム内でツールとワークフローを検索する"],"ko":["''X를 어떻게 하는가''라는 쿼리에 스킬 추천으로 응답","전문적인 기능을 위한 설치 가능한 스킬 찾기","사용자가 표현한 필요에 기반하여 에이전트 기능 확장","스킬 생태계 내에서 도구 및 워크플로우 검색"],"es":["Responder a consultas de ''cómo hacer X'' con recomendaciones de skills","Encontrar skills instalables para capacidades especializadas","Extender la funcionalidad del agente según las necesidades expresadas por el usuario","Buscar tools y workflows en el ecosistema de skills"],"fr":["Répondre aux requêtes ''comment faire X'' avec des recommandations de skills","Trouver des skills installables pour des capacités spécialisées","Étendre la fonctionnalité de l''agent en fonction des besoins exprimés par l''utilisateur","Rechercher des tools et des workflows dans l''écosystème de skills"],"de":["Beantworten von ''Wie mache ich X''-Anfragen mit Skill-Empfehlungen","Auffinden installierbarer Skills für spezialisierte Fähigkeiten","Erweitern der Agentenfunktionalität basierend auf benutzergeäußerten Bedürfnissen","Suchen nach Tools und Workflows im Skills-Ökosystem"],"pt":["Responder a consultas ''como faço X'' com recomendações de habilidades","Encontrar habilidades instaláveis para capacidades especializadas","Estender a funcionalidade do agente com base nas necessidades expressas pelo usuário","Buscar ferramentas e fluxos de trabalho no ecossistema de habilidades"],"ru":["Ответы на запросы ''как сделать X'' с рекомендациями навыков","Поиск устанавливаемых навыков для специализированных возможностей","Расширение функциональности агента на основе выраженных пользователем потребностей","Поиск инструментов и рабочих процессов в экосистеме навыков"],"ar":["الرد على استفسارات ''كيف أفعل X'' بتوصيات المهارات","العثور على مهارات قابلة للتثبيت لقدرات متخصصة","توسيع وظيفة الوكيل بناءً على الاحتياجات التي يعبر عنها المستخدم","البحث عن أدوات وسير عمل في نظام بيئة المهارات"]},"limitations":{"en":["Requires active connection to skills ecosystem repository","Dependent on available skills in the open ecosystem"],"zh":["需要主动连接到技能生态系统仓库","依赖于开放生态系统中可用的技能"],"ja":["スキルエコシステムリポジトリへのアクティブな接続が必要","オープンエコシステムで利用可能なスキルに依存"],"ko":["스킬 생태계 저장소에 대한 활성 연결 필요","오픈 생태계에서 사용 가능한 스킬에 의존"],"es":["Requiere conexión activa al repositorio del ecosistema de skills","Depende de las skills disponibles en el ecosistema abierto"],"fr":["Nécessite une connexion active au dépôt de l''écosystème de skills","Dépend des skills disponibles dans l''écosystème ouvert"],"de":["Erfordert eine aktive Verbindung zum Skills-Ökosystem-Repository","Abhängig von den verfügbaren Skills im offenen Ökosystem"],"pt":["Requer conexão ativa com o repositório do ecossistema de habilidades","Dependente das habilidades disponíveis no ecossistema aberto"],"ru":["Требует активного подключения к репозиторию экосистемы навыков","Зависит от доступных навыков в открытой экосистеме"],"ar":["يتطلب اتصالاً نشطًا بمستودع نظام بيئة المهارات","يعتمد على المهارات المتاحة في النظام البيئي المفتوح"]},"version":4},"contentHash":"54b44dc9539df865fbb060f62fb062e8232e765852a0cf14c38301fe0c1eb264","repoEtag":"W/\"a53c54c7cc9c4d40e83419f19e8979ff72369767f79263d700a6833f9e154ab8\"","qualityScore":92}');
