INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vercel-labs/skills/find-skills', 'find-skills', 'vercel-labs', 'skills', 'official', 'find-skills vercel-labs skills official The find-skills agent skill enables developers and users to discover and install new capabilities from the open agent skills ecosystem. It parses user intent to recommend relevant skills for extending an agent''s functionality. find-skills是一个专门用于发现和安装AI代理技能的专用工具。当开发者询问如何实现特定功能或寻找现有解决方案时，该技能会自动搜索开放的技能生态系统，推荐并安装相关工具、模板和工作流。 find-skillsはAIエージェントスキルの検索・インストール専用ツールです。開発者が特定機能の実現方法を問う際、オープンスキルエコシステムを自動検索し、関連ツールやテンプレートを推薦します。 find-skills는 AI 에이전트 스킬 발견 및 설치를 위한 전문 도구입니다. 개발자가 특정 기능 구현 방법을 질문할 때 오픈 스킬 생태계를 자동 검색하여 관련 도구와 템플릿을 추천합니다. A skill find-skills é um utilitário técnico para desenvolvedores que permite descobrir e instalar habilidades de agentes IA a partir de um ecossistema aberto. Ela é ativada quando um usuário solicita funcionalidades específicas ou extensões de capacidade. Навык find-skills — это техническая утилита для разработчиков, позволяющая находить и устанавливать навыки ИИ Агентов из открытой экосистемы. Он активируется, когда пользователь запрашивает определенные функции или расширения возможностей. مهارة find-skills هي أداة تقنية للمطورين تتيح اكتشاف وتثبيت مهارات وكلاء الذكاء الاصطناعي من نظام مفتوح. يتم تنشيطها عندما يطلب المستخدم وظائف محددة أو توسيع القدرات. how to use find-skills what is find-skills find-skills alternative find-skills vs skill discovery find-skills install find-skills setup guide AI agent skill discovery install agent capabilities extend AI agent functionality AI代理技能安装 find-skills使用指南 扩展AI代理功能 技能生态系统搜索 开发者工具推荐 AI技能发现平台 如何安装代理技能 工作流模板安装 Responds to user queries like ''how do I do X'' or ''find a skill for X'' Processes user intent to find skills for specialized capabilities Activates when a user expresses interest in extending agent capabilities Helps users search for tools, templates, or workflows as installable skills find-skills is an AI agent skill that helps users discover and install other skills from the open ecosystem. It is triggered when a user asks how to perform a task, searches for a specific capability, or expresses interest in extending their agent''s functionalities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/cpp-testing', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'cpp-testing', 61988, 7678, 92, '2026-03-06T03:39:20Z', '2026-03-06T03:58:40.188Z', '84e58979240d0387d55dd5bf0d4ba9976733098e2f839f10b17251797eae7e50', '{"id":"affaan-m/everything-claude-code/cpp-testing","name":"cpp-testing","description":{"en":"The cpp-testing skill streamlines C++ test development, configuration, and diagnosis for AI agents, utilizing GoogleTest and CMake. It benefits developers writing or updating C++ tests.","zh":"C++测试技能提供了GoogleTest/CTest的配置和优化，帮助开发者提高测试效率","ja":"C++テストスキルはGoogleTest/CTestの設定と最適化を提供し、開発者のテスト効率を向上させる","ko":"C++ 테스트 기능은 GoogleTest/CTest의 구성 및 최적화를 제공하여 개발자의 테스트 효율성을 높입니다","es":"El skill de pruebas C++ utiliza GoogleTest y CTest para proporcionar una workflow de pruebas para C++ moderno. Permite escribir y ejecutar pruebas unitarias e de integración.","fr":"Le skill de tests C++ utilise GoogleTest et CTest pour fournir une workflow de tests pour C++ moderne. Il permet d''écrire et d''exécuter des tests unitaires et d''intégration.","de":"Das C++-Test-Skill verwendet GoogleTest und CTest, um eine Test-Workflow für modernes C++ bereitzustellen. Es ermöglicht das Schreiben und Ausführen von Unit- und Integrations-tests.","pt":"O skill cpp-testing ajuda a escrever e configurar testes C++ com GoogleTest e CMake, melhorando a cobertura de testes e a produtividade do desenvolvedor.","ru":"Навык cpp-testing помогает писать и настраивать тесты C++ с помощью GoogleTest и CMake, улучшая покрытие тестов и производительность разработчика с помощью ИИ Агентов.","ar":"المهارة cpp-testing تساعد في كتابة وضبط اختبارات سي++ باستخدام جوجل تيست وسي ميك، مما يحسن تغطية الاختبارات وإنتاجية المطور"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"cpp-testing","description":"Use only when writing/updating/fixing C++ tests, configuring GoogleTest/CTest, diagnosing failing or flaky tests, or adding coverage/sanitizers.","bodyPreview":"# C++ Testing (Agent Skill)\n\nAgent-focused testing workflow for modern C++ (C++17/20) using GoogleTest/GoogleMock with CMake/CTest.\n\n## When to Use\n\n- Writing new C++ tests or fixing existing tests\n- Designing unit/integration test coverage for C++ components\n- Adding test coverage, CI gating, or regression protection\n- Configuring CMake/CTest workflows for consistent execution\n- Investigating test failures or flaky behavior\n- Enabling sanitizers for memory/race diagnostics\n\n### When NOT to Use","body":"# C++ Testing (Agent Skill)\n\nAgent-focused testing workflow for modern C++ (C++17/20) using GoogleTest/GoogleMock with CMake/CTest.\n\n## When to Use\n\n- Writing new C++ tests or fixing existing tests\n- Designing unit/integration test coverage for C++ components\n- Adding test coverage, CI gating, or regression protection\n- Configuring CMake/CTest workflows for consistent execution\n- Investigating test failures or flaky behavior\n- Enabling sanitizers for memory/race diagnostics\n\n### When NOT to Use\n\n- Implementing new product features without test changes\n- Large-scale refactors unrelated to test coverage or failures\n- Performance tuning without test regressions to validate\n- Non-C++ projects or non-test tasks\n\n## Core Concepts\n\n- **TDD loop**: red → green → refactor (tests first, minimal fix, then cleanups).\n- **Isolation**: prefer dependency injection and fakes over global state.\n- **Test layout**: `tests/unit`, `tests/integration`, `tests/testdata`.\n- **Mocks vs fakes**: mock for interactions, fake for stateful behavior.\n- **CTest discovery**: use `gtest_discover_tests()` for stable test discovery.\n- **CI signal**: run subset first, then full suite with `--output-on-failure`.\n\n## TDD Workflow\n\nFollow the RED → GREEN → REFACTOR loop:\n\n1. **RED**: write a failing test that captures the new behavior\n2. **GREEN**: implement the smallest change to pass\n3. **REFACTOR**: clean up while tests stay green\n\n```cpp\n// tests/add_test.cpp\n#include <gtest/gtest.h>\n\nint Add(int a, int b); // Provided by production code.\n\nTEST(AddTest, AddsTwoNumbers) { // RED\n  EXPECT_EQ(Add(2, 3), 5);\n}\n\n// src/add.cpp\nint Add(int a, int b) { // GREEN\n  return a + b;\n}\n\n// REFACTOR: simplify/rename once tests pass\n```\n\n## Code Examples\n\n### Basic Unit Test (gtest)\n\n```cpp\n// tests/calculator_test.cpp\n#include <gtest/gtest.h>\n\nint Add(int a, int b); // Provided by production code.\n\nTEST(CalculatorTest, AddsTwoNumbers) {\n    EXPECT_EQ(Add(2, 3), 5);\n}\n```\n\n### Fixture (gtest)\n\n```cpp\n// tests/user_store_test.cpp\n// Pseudocode stub: replace UserStore/User with project types.\n#include <gtest/gtest.h>\n#include <memory>\n#include <optional>\n#include <string>\n\nstruct User { std::string name; };\nclass UserStore {\npublic:\n    explicit UserStore(std::string /*path*/) {}\n    void Seed(std::initializer_list<User> /*users*/) {}\n    std::optional<User> Find(const std::string &/*name*/) { return User{\"alice\"}; }\n};\n\nclass UserStoreTest : public ::testing::Test {\nprotected:\n    void SetUp() override {\n        store = std::make_unique<UserStore>(\":memory:\");\n        store->Seed({{\"alice\"}, {\"bob\"}});\n    }\n\n    std::unique_ptr<UserStore> store;\n};\n\nTEST_F(UserStoreTest, FindsExistingUser) {\n    auto user = store->Find(\"alice\");\n    ASSERT_TRUE(user.has_value());\n    EXPECT_EQ(user->name, \"alice\");\n}\n```\n\n### Mock (gmock)\n\n```cpp\n// tests/notifier_test.cpp\n#include <gmock/gmock.h>\n#include <gtest/gtest.h>\n#include <string>\n\nclass Notifier {\npublic:\n    virtual ~Notifier() = default;\n    virtual void Send(const std::string &message) = 0;\n};\n\nclass MockNotifier : public Notifier {\npublic:\n    MOCK_METHOD(void, Send, (const std::string &message), (override));\n};\n\nclass Service {\npublic:\n    explicit Service(Notifier &notifier) : notifier_(notifier) {}\n    void Publish(const std::string &message) { notifier_.Send(message); }\n\nprivate:\n    Notifier &notifier_;\n};\n\nTEST(ServiceTest, SendsNotifications) {\n    MockNotifier notifier;\n    Service service(notifier);\n\n    EXPECT_CALL(notifier, Send(\"hello\")).Times(1);\n    service.Publish(\"hello\");\n}\n```\n\n### CMake/CTest Quickstart\n\n```cmake\n# CMakeLists.txt (excerpt)\ncmake_minimum_required(VERSION 3.20)\nproject(example LANGUAGES CXX)\n\nset(CMAKE_CXX_STANDARD 20)\nset(CMAKE_CXX_STANDARD_REQUIRED ON)\n\ninclude(FetchContent)\n# Prefer project-locked versions. If using a tag, use a pinned version per project policy.\nset(GTEST_VERSION v1.17.0) # Adjust to project policy.\nFetchContent_Declare(\n  googletest\n  # Google Test framework (official repository)\n  URL https://github.com/google/googletest/archive/refs/tags/${GTEST_VERSION}.zip\n)\nFetchContent_MakeAvailable(googletest)\n\nadd_executable(example_tests\n  tests/calculator_test.cpp\n  src/calculator.cpp\n)\ntarget_link_libraries(example_tests GTest::gtest GTest::gmock GTest::gtest_main)\n\nenable_testing()\ninclude(GoogleTest)\ngtest_discover_tests(example_tests)\n```\n\n```bash\ncmake -S . -B build -DCMAKE_BUILD_TYPE=Debug\ncmake --build build -j\nctest --test-dir build --output-on-failure\n```\n\n## Running Tests\n\n```bash\nctest --test-dir build --output-on-failure\nctest --test-dir build -R ClampTest\nctest --test-dir build -R \"UserStoreTest.*\" --output-on-failure\n```\n\n```bash\n./build/example_tests --gtest_filter=ClampTest.*\n./build/example_tests --gtest_filter=UserStoreTest.FindsExistingUser\n```\n\n## Debugging Failures\n\n1. Re-run the single failing test with gtest filter.\n2. Add scoped logging around the failing assertion.\n3. Re-run with sanitizers enabled.\n4. Expand to full suite once the root cause is fixed.\n\n## Coverage\n\nPrefer target-level settings instead of global flags.\n\n```cmake\noption(ENABLE_COVERAGE \"Enable coverage flags\" OFF)\n\nif(ENABLE_COVERAGE)\n  if(CMAKE_CXX_COMPILER_ID MATCHES \"GNU\")\n    target_compile_options(example_tests PRIVATE --coverage)\n    target_link_options(example_tests PRIVATE --coverage)\n  elseif(CMAKE_CXX_COMPILER_ID MATCHES \"Clang\")\n    target_compile_options(example_tests PRIVATE -fprofile-instr-generate -fcoverage-mapping)\n    target_link_options(example_tests PRIVATE -fprofile-instr-generate)\n  endif()\nendif()\n```\n\nGCC + gcov + lcov:\n\n```bash\ncmake -S . -B build-cov -DENABLE_COVERAGE=ON\ncmake --build build-cov -j\nctest --test-dir build-cov\nlcov --capture --directory build-cov --output-file coverage.info\nlcov --remove coverage.info ''/usr/*'' --output-file coverage.info\ngenhtml coverage.info --output-directory coverage\n```\n\nClang + llvm-cov:\n\n```bash\ncmake -S . -B build-llvm -DENABLE_COVERAGE=ON -DCMAKE_CXX_COMPILER=clang++\ncmake --build build-llvm -j\nLLVM_PROFILE_FILE=\"build-llvm/default.profraw\" ctest --test-dir build-llvm\nllvm-profdata merge -sparse build-llvm/default.profraw -o build-llvm/default.profdata\nllvm-cov report build-llvm/example_tests -instr-profile=build-llvm/default.profdata\n```\n\n## Sanitizers\n\n```cmake\noption(ENABLE_ASAN \"Enable AddressSanitizer\" OFF)\noption(ENABLE_UBSAN \"Enable UndefinedBehaviorSanitizer\" OFF)\noption(ENABLE_TSAN \"Enable ThreadSanitizer\" OFF)\n\nif(ENABLE_ASAN)\n  add_compile_options(-fsanitize=address -fno-omit-frame-pointer)\n  add_link_options(-fsanitize=address)\nendif()\nif(ENABLE_UBSAN)\n  add_compile_options(-fsanitize=undefined -fno-omit-frame-pointer)\n  add_link_options(-fsanitize=undefined)\nendif()\nif(ENABLE_TSAN)\n  add_compile_options(-fsanitize=thread)\n  add_link_options(-fsanitize=thread)\nendif()\n```\n\n## Flaky Tests Guardrails\n\n- Never use `sleep` for synchronization; use condition variables or latches.\n- Make temp directories unique per test and always clean them.\n- Avoid real time, network, or filesystem dependencies in unit tests.\n- Use deterministic seeds for randomized inputs.\n\n## Best Practices\n\n### DO\n\n- Keep tests deterministic and isolated\n- Prefer dependency injection over globals\n- Use `ASSERT_*` for preconditions, `EXPECT_*` for multiple checks\n- Separate unit vs integration tests in CTest labels or directories\n- Run sanitizers in CI for memory and race detection\n\n### DON''T\n\n- Don''t depend on real time or network in unit tests\n- Don''t use sleeps as synchronization when a condition variable can be used\n- Don''t over-mock simple value objects\n- Don''t use brittle string matching for non-critical logs\n\n### Common Pitfalls\n\n- **Using fixed temp paths** → Generate unique temp directories per test and clean them.\n- **Relying on wall clock time** → Inject a clock or use fake time sources.\n- **Flaky concurrency tests** → Use condition variables/latches and bounded waits.\n- **Hidden global state** → Reset global state in fixtures or remove globals.\n- **Over-mocking** → Prefer fakes for stateful behavior and only mock interactions.\n- **Missing sanitizer runs** → Add ASan/UBSan/TSan builds in CI.\n- **Coverage on debug-only builds** → Ensure coverage targets use consistent flags.\n\n## Optional Appendix: Fuzzing / Property Testing\n\nOnly use if the project already supports LLVM/libFuzzer or a property-testing library.\n\n- **libFuzzer**: best for pure functions with minimal I/O.\n- **RapidCheck**: property-based tests to validate invariants.\n\nMinimal libFuzzer harness (pseudocode: replace ParseConfig):\n\n```cpp\n#include <cstddef>\n#include <cstdint>\n#include <string>\n\nextern \"C\" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {\n    std::string input(reinterpret_cast<const char *>(data), size);\n    // ParseConfig(input); // project function\n    return 0;\n}\n```\n\n## Alternatives to GoogleTest\n\n- **Catch2**: header-only, expressive matchers\n- **doctest**: lightweight, minimal compile overhead\n"},"category":"official","lastSynced":"2026-03-06T03:58:40.188Z","seo":{"title":{"en":"cpp-testing: C++ Test Automation Setup Guide | AI Agent S...","zh":"C++测试配置指南 - GoogleTest/CTest集成","ja":"C++テストのベストプラクティス - GoogleTest/CTest設定","ko":"C++ 테스트 설정 가이드 - GoogleTest/CTest 통합","es":"Guía de configuración de pruebas C++ con GoogleTest","fr":"Guide de mise en place des tests C++ avec GoogleTest","de":"Einrichtungsleitfaden für C++-Tests mit GoogleTest","pt":"Guia de Configuração de Testes C++ com GoogleTest","ru":"Настройка тестирования C++ с помощью GoogleTest и ИИ Агентов","ar":"دليل إعداد اختبارات سي++ باستخدام جوجل تيست"},"description":{"en":"Unlock efficient C++ testing with cpp-testing. Learn how to configure GoogleTest, CTest, and CMake for seamless test execution and debugging.","zh":"使用AIエージェント的C++测试技能，提高测试效率，优化GoogleTest/CTest配置，诊断测试失败","ja":"AIエージェントのC++テストスキルを使用して、テストの効率を高め、GoogleTest/CTestの設定を最適化する","ko":"AI 에이전트의 C++ 테스트 기능을 사용하여 테스트 효율성을 높이고 GoogleTest/CTest 구성 최적화","es":"Aprende a configurar y ejecutar pruebas C++ con GoogleTest y CTest. Mejora la cobertura de tus pruebas y diagnostica errores con sanitizadores.","fr":"Découvrez comment configurer et exécuter des tests C++ avec GoogleTest et CTest. Améliorez la couverture de vos tests et diagnostiquez les erreurs avec des s...","de":"Erfahren Sie, wie Sie C++-Tests mit GoogleTest und CTest konfigurieren und ausführen. Verbessern Sie die Testabdeckung und diagnostizieren Sie Fehler mit San...","pt":"Aprenda a configurar e otimizar testes C++ com GoogleTest e CMake para melhorar a produtividade do desenvolvedor","ru":"Узнайте, как настроить и оптимизировать тесты C++ с помощью GoogleTest и CMake для повышения производительности разработчика с помощью ИИ Агентов","ar":"تعرف على كيف