INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/cpp-testing', 'cpp-testing', 'affaan-m', 'everything-claude-code', 'official', 'cpp-testing affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The cpp-testing skill streamlines C++ test development, configuration, and diagnosis for AI agents, utilizing GoogleTest and CMake. It benefits developers writing or updating C++ tests. C++测试技能提供了GoogleTest/CTest的配置和优化，帮助开发者提高测试效率 C++テストスキルはGoogleTest/CTestの設定と最適化を提供し、開発者のテスト効率を向上させる C++ 테스트 기능은 GoogleTest/CTest의 구성 및 최적화를 제공하여 개발자의 테스트 효율성을 높입니다 El skill de pruebas C++ utiliza GoogleTest y CTest para proporcionar una workflow de pruebas para C++ moderno. Permite escribir y ejecutar pruebas unitarias e de integración. Le skill de tests C++ utilise GoogleTest et CTest pour fournir une workflow de tests pour C++ moderne. Il permet d''écrire et d''exécuter des tests unitaires et d''intégration. Das C++-Test-Skill verwendet GoogleTest und CTest, um eine Test-Workflow für modernes C++ bereitzustellen. Es ermöglicht das Schreiben und Ausführen von Unit- und Integrations-tests. O skill cpp-testing ajuda a escrever e configurar testes C++ com GoogleTest e CMake, melhorando a cobertura de testes e a produtividade do desenvolvedor. Навык cpp-testing помогает писать и настраивать тесты C++ с помощью GoogleTest и CMake, улучшая покрытие тестов и производительность разработчика с помощью ИИ Агентов. المهارة cpp-testing تساعد في كتابة وضبط اختبارات سي++ باستخدام جوجل تيست وسي ميك، مما يحسن تغطية الاختبارات وإنتاجية المطور cpp-testing setup guide C++ test automation with GoogleTest how to use cpp-testing for C++ development cpp-testing vs CTest installing cpp-testing for AI agents C++ testing best practices with cpp-testing what is cpp-testing cpp-testing tutorial for C++ developers configuring CMake for cpp-testing C++测试 GoogleTest CTest AIエージェント C++测试配置 C++测试优化 测试覆盖率 CI闸门 Configures GoogleTest and GoogleMock for unit and integration testing Utilizes CMake and CTest for consistent test execution and workflow management Enables test coverage and sanitizers for memory and race diagnostics Supports C++17 and C++20 standards for modern C++ development Facilitates debugging of failing or flaky tests for improved test reliability cpp-testing is a specialized AI agent skill for automating and optimizing C++ testing workflows using GoogleTest, CTest, and CMake.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/django-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'django-patterns', 61988, 7678, 92, '2026-03-06T03:39:20Z', '2026-03-06T04:02:05.535Z', '267eb89f537a6626937d60fc732675f685b11209fa9025599c80e0f322e9a503', '{"id":"affaan-m/everything-claude-code/django-patterns","name":"django-patterns","description":{"en":"This AI Agent skill provides expert guidance on Django architecture patterns, REST API design with Django REST Framework, ORM optimization, caching, signals, and middleware implementation. It benefits developers building scalable, maintainable Django applications.","zh":"专为开发者设计的AI助手技能，提供Django生产级架构模式指导，包括REST API设计、ORM优化、缓存策略和项目结构规划，帮助构建可扩展的Django应用。","ja":"開発者向けAIエージェントスキルで、Djangoの本番環境対応アーキテクチャパターン、DRFを使ったREST API設計、ORMベストプラクティス、キャッシュ戦略を提供します。","ko":"개발자를 위한 AI 에이전트 스킬로, Django 프로덕션급 아키텍처 패턴, DRF를 이용한 REST API 설계, ORM 모범 사례, 캐싱 전략을 제공합니다.","es":"Django Patterns proporciona patrones de arquitectura para aplicaciones web escalables y mantenibles con Django y Django REST Framework","fr":"Django Patterns fournit des modèles d''architecture pour des applications web évolutives et maintenables avec Django et Django REST Framework","de":"Django Patterns bietet Architekturmuster für skalierbare und wartbare Webanwendungen mit Django und Django REST Framework","pt":"AI Agent especializado em padrões de desenvolvimento Django, incluindo design de APIs REST com Django REST Framework, otimizações de ORM e implementação de caching, signals e middleware para aplicações escaláveis.","ru":"ИИ Агент, специализирующийся на шаблонах разработки Django, включая проектирование REST API с Django REST Framework, оптимизацию ORM и реализацию кэширования, сигналов и middleware для масштабируемых приложений.","ar":"وكيل الذكاء الاصطناعي المتخصص في أنماط تطوير Django، بما في ذلك تصميم واجهات برمجة التطبيقات REST باستخدام Django REST Framework، وتحسينات ORM، وتنفيذ التخزين المؤقت والإشارات والوسيطة للتطبيقات القابلة للتوسع."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"django-patterns","description":"Django architecture patterns, REST API design with DRF, ORM best practices, caching, signals, middleware, and production-grade Django apps.","bodyPreview":"# Django Development Patterns\n\nProduction-grade Django architecture patterns for scalable, maintainable applications.\n\n## When to Activate\n\n- Building Django web applications\n- Designing Django REST Framework APIs\n- Working with Django ORM and models\n- Setting up Django project structure\n- Implementing caching, signals, middleware\n\n## Project Structure\n\n### Recommended Layout\n\n```\nmyproject/\n├── config/\n│   ├── __init__.py\n│   ├── settings/\n│   │   ├── __init__.py\n│   │   ├── base.py          #","body":"# Django Development Patterns\n\nProduction-grade Django architecture patterns for scalable, maintainable applications.\n\n## When to Activate\n\n- Building Django web applications\n- Designing Django REST Framework APIs\n- Working with Django ORM and models\n- Setting up Django project structure\n- Implementing caching, signals, middleware\n\n## Project Structure\n\n### Recommended Layout\n\n```\nmyproject/\n├── config/\n│   ├── __init__.py\n│   ├── settings/\n│   │   ├── __init__.py\n│   │   ├── base.py          # Base settings\n│   │   ├── development.py   # Dev settings\n│   │   ├── production.py    # Production settings\n│   │   └── test.py          # Test settings\n│   ├── urls.py\n│   ├── wsgi.py\n│   └── asgi.py\n├── manage.py\n└── apps/\n    ├── __init__.py\n    ├── users/\n    │   ├── __init__.py\n    │   ├── models.py\n    │   ├── views.py\n    │   ├── serializers.py\n    │   ├── urls.py\n    │   ├── permissions.py\n    │   ├── filters.py\n    │   ├── services.py\n    │   └── tests/\n    └── products/\n        └── ...\n```\n\n### Split Settings Pattern\n\n```python\n# config/settings/base.py\nfrom pathlib import Path\n\nBASE_DIR = Path(__file__).resolve().parent.parent.parent\n\nSECRET_KEY = env(''DJANGO_SECRET_KEY'')\nDEBUG = False\nALLOWED_HOSTS = []\n\nINSTALLED_APPS = [\n    ''django.contrib.admin'',\n    ''django.contrib.auth'',\n    ''django.contrib.contenttypes'',\n    ''django.contrib.sessions'',\n    ''django.contrib.messages'',\n    ''django.contrib.staticfiles'',\n    ''rest_framework'',\n    ''rest_framework.authtoken'',\n    ''corsheaders'',\n    # Local apps\n    ''apps.users'',\n    ''apps.products'',\n]\n\nMIDDLEWARE = [\n    ''django.middleware.security.SecurityMiddleware'',\n    ''whitenoise.middleware.WhiteNoiseMiddleware'',\n    ''django.contrib.sessions.middleware.SessionMiddleware'',\n    ''corsheaders.middleware.CorsMiddleware'',\n    ''django.middleware.common.CommonMiddleware'',\n    ''django.middleware.csrf.CsrfViewMiddleware'',\n    ''django.contrib.auth.middleware.AuthenticationMiddleware'',\n    ''django.contrib.messages.middleware.MessageMiddleware'',\n    ''django.middleware.clickjacking.XFrameOptionsMiddleware'',\n]\n\nROOT_URLCONF = ''config.urls''\nWSGI_APPLICATION = ''config.wsgi.application''\n\nDATABASES = {\n    ''default'': {\n        ''ENGINE'': ''django.db.backends.postgresql'',\n        ''NAME'': env(''DB_NAME''),\n        ''USER'': env(''DB_USER''),\n        ''PASSWORD'': env(''DB_PASSWORD''),\n        ''HOST'': env(''DB_HOST''),\n        ''PORT'': env(''DB_PORT'', default=''5432''),\n    }\n}\n\n# config/settings/development.py\nfrom .base import *\n\nDEBUG = True\nALLOWED_HOSTS = [''localhost'', ''127.0.0.1'']\n\nDATABASES[''default''][''NAME''] = ''myproject_dev''\n\nINSTALLED_APPS += [''debug_toolbar'']\n\nMIDDLEWARE += [''debug_toolbar.middleware.DebugToolbarMiddleware'']\n\nEMAIL_BACKEND = ''django.core.mail.backends.console.EmailBackend''\n\n# config/settings/production.py\nfrom .base import *\n\nDEBUG = False\nALLOWED_HOSTS = env.list(''ALLOWED_HOSTS'')\nSECURE_SSL_REDIRECT = True\nSESSION_COOKIE_SECURE = True\nCSRF_COOKIE_SECURE = True\nSECURE_HSTS_SECONDS = 31536000\nSECURE_HSTS_INCLUDE_SUBDOMAINS = True\nSECURE_HSTS_PRELOAD = True\n\n# Logging\nLOGGING = {\n    ''version'': 1,\n    ''disable_existing_loggers'': False,\n    ''handlers'': {\n        ''file'': {\n            ''level'': ''WARNING'',\n            ''class'': ''logging.FileHandler'',\n            ''filename'': ''/var/log/django/django.log'',\n        },\n    },\n    ''loggers'': {\n        ''django'': {\n            ''handlers'': [''file''],\n            ''level'': ''WARNING'',\n            ''propagate'': True,\n        },\n    },\n}\n```\n\n## Model Design Patterns\n\n### Model Best Practices\n\n```python\nfrom django.db import models\nfrom django.contrib.auth.models import AbstractUser\nfrom django.core.validators import MinValueValidator, MaxValueValidator\n\nclass User(AbstractUser):\n    \"\"\"Custom user model extending AbstractUser.\"\"\"\n    email = models.EmailField(unique=True)\n    phone = models.CharField(max_length=20, blank=True)\n    birth_date = models.DateField(null=True, blank=True)\n\n    USERNAME_FIELD = ''email''\n    REQUIRED_FIELDS = [''username'']\n\n    class Meta:\n        db_table = ''users''\n        verbose_name = ''user''\n        verbose_name_plural = ''users''\n        ordering = [''-date_joined'']\n\n    def __str__(self):\n        return self.email\n\n    def get_full_name(self):\n        return f\"{self.first_name} {self.last_name}\".strip()\n\nclass Product(models.Model):\n    \"\"\"Product model with proper field configuration.\"\"\"\n    name = models.CharField(max_length=200)\n    slug = models.SlugField(unique=True, max_length=250)\n    description = models.TextField(blank=True)\n    price = models.DecimalField(\n        max_digits=10,\n        decimal_places=2,\n        validators=[MinValueValidator(0)]\n    )\n    stock = models.PositiveIntegerField(default=0)\n    is_active = models.BooleanField(default=True)\n    category = models.ForeignKey(\n        ''Category'',\n        on_delete=models.CASCADE,\n        related_name=''products''\n    )\n    tags = models.ManyToManyField(''Tag'', blank=True, related_name=''products'')\n    created_at = models.DateTimeField(auto_now_add=True)\n    updated_at = models.DateTimeField(auto_now=True)\n\n    class Meta:\n        db_table = ''products''\n        ordering = [''-created_at'']\n        indexes = [\n            models.Index(fields=[''slug'']),\n            models.Index(fields=[''-created_at'']),\n            models.Index(fields=[''category'', ''is_active'']),\n        ]\n        constraints = [\n            models.CheckConstraint(\n                check=models.Q(price__gte=0),\n                name=''price_non_negative''\n            )\n        ]\n\n    def __str__(self):\n        return self.name\n\n    def save(self, *args, **kwargs):\n        if not self.slug:\n            self.slug = slugify(self.name)\n        super().save(*args, **kwargs)\n```\n\n### QuerySet Best Practices\n\n```python\nfrom django.db import models\n\nclass ProductQuerySet(models.QuerySet):\n    \"\"\"Custom QuerySet for Product model.\"\"\"\n\n    def active(self):\n        \"\"\"Return only active products.\"\"\"\n        return self.filter(is_active=True)\n\n    def with_category(self):\n        \"\"\"Select related category to avoid N+1 queries.\"\"\"\n        return self.select_related(''category'')\n\n    def with_tags(self):\n        \"\"\"Prefetch tags for many-to-many relationship.\"\"\"\n        return self.prefetch_related(''tags'')\n\n    def in_stock(self):\n        \"\"\"Return products with stock > 0.\"\"\"\n        return self.filter(stock__gt=0)\n\n    def search(self, query):\n        \"\"\"Search products by name or description.\"\"\"\n        return self.filter(\n            models.Q(name__icontains=query) |\n            models.Q(description__icontains=query)\n        )\n\nclass Product(models.Model):\n    # ... fields ...\n\n    objects = ProductQuerySet.as_manager()  # Use custom QuerySet\n\n# Usage\nProduct.objects.active().with_category().in_stock()\n```\n\n### Manager Methods\n\n```python\nclass ProductManager(models.Manager):\n    \"\"\"Custom manager for complex queries.\"\"\"\n\n    def get_or_none(self, **kwargs):\n        \"\"\"Return object or None instead of DoesNotExist.\"\"\"\n        try:\n            return self.get(**kwargs)\n        except self.model.DoesNotExist:\n            return None\n\n    def create_with_tags(self, name, price, tag_names):\n        \"\"\"Create product with associated tags.\"\"\"\n        product = self.create(name=name, price=price)\n        tags = [Tag.objects.get_or_create(name=name)[0] for name in tag_names]\n        product.tags.set(tags)\n        return product\n\n    def bulk_update_stock(self, product_ids, quantity):\n        \"\"\"Bulk update stock for multiple products.\"\"\"\n        return self.filter(id__in=product_ids).update(stock=quantity)\n\n# In model\nclass Product(models.Model):\n    # ... fields ...\n    custom = ProductManager()\n```\n\n## Django REST Framework Patterns\n\n### Serializer Patterns\n\n```python\nfrom rest_framework import serializers\nfrom django.contrib.auth.password_validation import validate_password\nfrom .models import Product, User\n\nclass ProductSerializer(serializers.ModelSerializer):\n    \"\"\"Serializer for Product model.\"\"\"\n\n    category_name = serializers.CharField(source=''category.name'', read_only=True)\n    average_rating = serializers.FloatField(read_only=True)\n    discount_price = serializers.SerializerMethodField()\n\n    class Meta:\n        model = Product\n        fields = [\n            ''id'', ''name'', ''slug'', ''description'', ''price'',\n            ''discount_price'', ''stock'', ''category_name'',\n            ''average_rating'', ''created_at''\n        ]\n        read_only_fields = [''id'', ''slug'', ''created_at'']\n\n    def get_discount_price(self, obj):\n        \"\"\"Calculate discount price if applicable.\"\"\"\n        if hasattr(obj, ''discount'') and obj.discount:\n            return obj.price * (1 - obj.discount.percent / 100)\n        return obj.price\n\n    def validate_price(self, value):\n        \"\"\"Ensure price is non-negative.\"\"\"\n        if value < 0:\n            raise serializers.ValidationError(\"Price cannot be negative.\")\n        return value\n\nclass ProductCreateSerializer(serializers.ModelSerializer):\n    \"\"\"Serializer for creating products.\"\"\"\n\n    class Meta:\n        model = Product\n        fields = [''name'', ''description'', ''price'', ''stock'', ''category'']\n\n    def validate(self, data):\n        \"\"\"Custom validation for multiple fields.\"\"\"\n        if data[''price''] > 10000 and data[''stock''] > 100:\n            raise serializers.ValidationError(\n                \"Cannot have high-value products with large stock.\"\n            )\n        return data\n\nclass UserRegistrationSerializer(serializers.ModelSerializer):\n    \"\"\"Serializer for user registration.\"\"\"\n\n    password = serializers.CharField(\n        write_only=True,\n        required=True,\n        validators=[validate_password],\n        style={''input_type'': ''password''}\n    )\n    password_confirm = serializers.CharField(write_only=True, style={''input_type'': ''password''})\n\n    class Meta:\n        model = User\n        fields = [''email'', ''username'', ''password'', ''password_confirm'']\n\n    def validate(self, data):\n        \"\"\"Validate passwords match.\"\"\"\n        if data[''password''] != data[''password_confirm'']:\n            raise serializers.ValidationError({\n                \"password_confirm\": \"Password fields didn''t match.\"\n            })\n        return data\n\n    def create(self, validated_data):\n        \"\"\"Create user with hashed password.\"\"\"\n        validated_data.pop(''password_confirm'')\n        password = validated_data.pop(''password'')\n        user = User.objects.create(**validated_data)\n        user.set_password(password)\n        user.save()\n        return user\n```\n\n### ViewSet Patterns\n\n```python\nfrom rest_framework import viewsets, status, filters\nfrom rest_framework.decorators import action\nfrom rest_framework.response import Response\nfrom rest_framework.permissions import IsAuthenticated, IsAdminUser\nfrom django_filters.rest_framework import DjangoFilterBackend\nfrom .models import Product\nfrom .serializers import ProductSerializer, ProductCreateSerializer\nfrom .permissions import IsOwnerOrReadOnly\nfrom .filters import ProductFilter\nfrom .services import ProductService\n\nclass ProductViewSet(viewsets.ModelViewSet):\n    \"\"\"ViewSet for Product model.\"\"\"\n\n    queryset = Product.objects.select_related(''category'').prefetch_related(''tags'')\n    permission_classes = [IsAuthenticated, IsOwnerOrReadOnly]\n    filter_backends = [DjangoFilterBackend, filters.SearchFilter, filters.OrderingFilter]\n    filterset_class = ProductFilter\n    search_fields = [''name'', ''description'']\n    ordering_fields = [''price'', ''created_at'', ''name'']\n    ordering = [''-created_at'']\n\n    def get_serializer_class(self):\n        \"\"\"Return appropriate serializer based on action.\"\"\"\n        if self.action == ''create'':\n            return ProductCreateSerializer\n        return ProductSerializer\n\n    def perform_create(self, serializer):\n        \"\"\"Save with user context.\"\"\"\n        serializer.save(created_by=self.request.user)\n\n    @action(detail=False, methods=[''get''])\n    def featured(self, request):\n        \"\"\"Return featured products.\"\"\"\n        featured = self.queryset.filter(is_featured=True)[:10]\n        serializer = self.get_serializer(featured, many=True)\n        return Response(serializer.data)\n\n    @action(detail=True, methods=[''post''])\n    def purchase(self, request, pk=None):\n        \"\"\"Purchase a product.\"\"\"\n        product = self.get_object()\n        service = ProductService()\n        result = service.purchase(product, request.user)\n        return Response(result, status=status.HTTP_201_CREATED)\n\n    @action(detail=False, methods=[''get''], permission_classes=[IsAuthenticated])\n    def my_products(self, request):\n        \"\"\"Return products created by current user.\"\"\"\n        products = self.queryset.filter(created_by=request.user)\n        page = self.paginate_queryset(products)\n        serializer = self.get_serializer(page, many=True)\n        return self.get_paginated_response(serializer.data)\n```\n\n### Custom Actions\n\n```python\nfrom rest_framework.decorators import api_view, permission_classes\nfrom rest_framework.permissions import IsAuthenticated\nfrom rest_framework.response import Response\n\n@api_view([''POST''])\n@permission_classes([IsAuthenticated])\ndef add_to_cart(request):\n    \"\"\"Add product to user cart.\"\"\"\n    product_id = request.data.get(''product_id'')\n    quantity = request.data.get(''quantity'', 1)\n\n    try:\n        product = Product.objects.get(id=product_id)\n    except Product.DoesNotExist:\n        return Response(\n            {''error'': ''Product not found''},\n            status=status.HTTP_404_NOT_FOUND\n        )\n\n    cart, _ = Cart.objects.get_or_create(user=request.user)\n    CartItem.objects.create(\n        cart=cart,\n        product=product,\n        quantity=quantity\n    )\n\n    return Response({''message'': ''Added to cart''}, status=status.HTTP_201_CREATED)\n```\n\n## Service Layer Pattern\n\n```python\n# apps/orders/services.py\nfrom typing import Optional\nfrom django.db import transaction\nfrom .models import Order, OrderItem\n\nclass OrderService:\n    \"\"\"Service layer for order-related business logic.\"\"\"\n\n    @staticmethod\n    @transaction.atomic\n    def create_order(user, cart: Cart) -> Order:\n        \"\"\"Create order from cart.\"\"\"\n        order = Order.objects.create(\n            user=user,\n            total_price=cart.total_price\n        )\n\n        for item in cart.items.all():\n            OrderItem.objects.create(\n                order=order,\n                product=item.product,\n                quantity=item.quantity,\n                price=item.product.price\n            )\n\n        # Clear cart\n        cart.items.all().delete()\n\n        return order\n\n    @staticmethod\n    def process_payment(order: Order, payment_data: dict) -> bool:\n        \"\"\"Process payment for order.\"\"\"\n        # Integration with payment gateway\n        payment = PaymentGateway.charge(\n            amount=order.total_price,\n            token=payment_data[''token'']\n        )\n\n        if payment.success:\n            order.status = Order.Status.PAID\n            order.save()\n            # Send confirmation email\n            OrderService.send_confirmation_email(order)\n            return True\n\n        return False\n\n    @staticmethod\n    def send_confirmation_email(order: Order):\n        \"\"\"Send order confirmation email.\"\"\"\n        # Email sending logic\n        pass\n```\n\n## Caching Strategies\n\n### View-Level Caching\n\n```python\nfrom django.views.decorators.cache import cache_page\nfrom django.utils.decorators import method_decorator\n\n@method_decorator(cache_page(60 * 15), name=''dispatch'')  # 15 minutes\nclass ProductListView(generic.ListView):\n    model = Product\n    template_name = ''products/list.html''\n    context_object_name = ''products''\n```\n\n### Template Fragment Caching\n\n```django\n{% load cache %}\n{% cache 500 sidebar %}\n    ... expensive sidebar content ...\n{% endcache %}\n```\n\n### Low-Level Caching\n\n```python\nfrom django.core.cache import cache\n\ndef get_featured_products():\n    \"\"\"Get featured products with caching.\"\"\"\n    cache_key = ''featured_products''\n    products = cache.get(cache_key)\n\n    if products is None:\n        products = list(Product.objects.filter(is_featured=True))\n        cache.set(cache_key, products, timeout=60 * 15)  # 15 minutes\n\n    return products\n```\n\n### QuerySet Caching\n\n```python\nfrom django.core.cache import cache\n\ndef get_popular_categories():\n    cache_key = ''popular_categories''\n    categories = cache.get(cache_key)\n\n    if categories is None:\n        categories = list(Category.objects.annotate(\n            product_count=Count(''products'')\n        ).filter(product_count__gt=10).order_by(''-product_count'')[:20])\n        cache.set(cache_key, categories, timeout=60 * 60)  # 1 hour\n\n    return categories\n```\n\n## Signals\n\n### Signal Patterns\n\n```python\n# apps/users/signals.py\nfrom django.db.models.signals import post_save\nfrom django.dispatch import receiver\nfrom django.contrib.auth import get_user_model\nfrom .models import Profile\n\nUser = get_user_model()\n\n@receiver(post_save, sender=User)\ndef create_user_profile(sender, instance, created, **kwargs):\n    \"\"\"Create profile when user is created.\"\"\"\n    if created:\n        Profile.objects.create(user=instance)\n\n@receiver(post_save, sender=User)\ndef save_user_profile(sender, instance, **kwargs):\n    \"\"\"Save profile when user is saved.\"\"\"\n    instance.profile.save()\n\n# apps/users/apps.py\nfrom django.apps import AppConfig\n\nclass UsersConfig(AppConfig):\n    default_auto_field = ''django.db.models.BigAutoField''\n    name = ''apps.users''\n\n    def ready(self):\n        \"\"\"Import signals when app is ready.\"\"\"\n        import apps.users.signals\n```\n\n## Middleware\n\n### Custom Middleware\n\n```python\n# middleware/active_user_middleware.py\nimport time\nfrom django.utils.deprecation import MiddlewareMixin\n\nclass ActiveUserMiddleware(MiddlewareMixin):\n    \"\"\"Middleware to track active users.\"\"\"\n\n    def process_request(self, request):\n        \"\"\"Process incoming request.\"\"\"\n        if request.user.is_authenticated:\n            # Update last active time\n            request.user.last_active = timezone.now()\n            request.user.save(update_fields=[''last_active''])\n\nclass RequestLoggingMiddleware(MiddlewareMixin):\n    \"\"\"Middleware for logging requests.\"\"\"\n\n    def process_request(self, request):\n        \"\"\"Log request start time.\"\"\"\n        request.start_time = time.time()\n\n    def process_response(self, request, response):\n        \"\"\"Log request duration.\"\"\"\n        if hasattr(request, ''start_time''):\n            duration = time.time() - request.start_time\n            logger.info(f''{request.method} {request.path} - {response.status_code} - {duration:.3f}s'')\n        return response\n```\n\n## Performance Optimization\n\n### N+1 Query Prevention\n\n```python\n# Bad - N+1 queries\nproducts = Product.objects.all()\nfor product in products:\n    print(product.category.name)  # Separate query for each product\n\n# Good - Single query with select_related\nproducts = Product.objects.select_related(''category'').all()\nfor product in products:\n    print(product.category.name)\n\n# Good - Prefetch for many-to-many\nproducts = Product.objects.prefetch_related(''tags'').all()\nfor product in products:\n    for tag in product.tags.all():\n        print(tag.name)\n```\n\n### Database Indexing\n\n```python\nclass Product(models.Model):\n    name = models.CharField(max_length=200, db_index=True)\n    slug = models.SlugField(unique=True)\n    category = models.ForeignKey(''Category'', on_delete=models.CASCADE)\n    created_at = models.DateTimeField(auto_now_add=True)\n\n    class Meta:\n        indexes = [\n            models.Index(fields=[''name'']),\n            models.Index(fields=[''-created_at'']),\n            models.Index(fields=[''category'', ''created_at'']),\n        ]\n```\n\n### Bulk Operations\n\n```python\n# Bulk create\nProduct.objects.bulk_create([\n    Product(name=f''Product {i}'', price=10.00)\n    for i in range(1000)\n])\n\n# Bulk update\nproducts = Product.objects.all()[:100]\nfor product in products:\n    product.is_active = True\nProduct.objects.bulk_update(products, [''is_active''])\n\n# Bulk delete\nProduct.objects.filter(stock=0).delete()\n```\n\n## Quick Reference\n\n| Pattern | Description |\n|---------|-------------|\n| Split settings | Separate dev/prod/test settings |\n| Custom QuerySet | Reusable query methods |\n| Service Layer | Business logic separation |\n| ViewSet | REST API endpoints |\n| Serializer validation | Request/response transformation |\n| select_related | Foreign key optimization |\n| prefetch_related | Many-to-many optimization |\n| Cache first | Cache expensive operations |\n| Signals | Event-driven actions |\n| Middleware | Request/response processing |\n\nRemember: Django provides many shortcuts, but for production applications, structure and organization matter more than concise code. Build for maintainability.\n"},"category":"official","lastSynced":"2026-03-06T04:02:05.535Z","seo":{"title":{"en":"django-patterns: Production-Grade Architecture & DRF API ...","zh":"Django架构模式最佳实践 - AI助手设置指南","ja":"DjangoパターンAIエージェントのセットアップと活用ガイド","ko":"Django 패턴 AI 에이전트 설정 가이드 및 모범 사례","es":"Patrones de Django: Guía de Configuración para Aplicacion...","fr":"Modèles Django : Guide de Configuration pour des Applicat...","de":"Django-Muster: Einrichtungsleitfaden für Skalierbare Anwe...","pt":"Django Patterns: Melhores Práticas para APIs REST e ORM","ru":"Django Patterns: Лучшие практики для REST API и ORM","ar":"Django Patterns: أفضل الممارسات لواجهات برمجة التطبيقات R..."},"description":{"en":"Leverage this AI Agent skill for Django ORM best practices, REST API design with Django REST Framework, caching strategies, signals, middleware, and scalable...","zh":"通过AI助手掌握Django生产级架构模式，包括DRF API设计、ORM最佳实践、缓存策略、信号和中间件实现。提升Django应用的可扩展性和可维护性。","ja":"AIエージェントを使用したDjango本番環境対応のアーキテクチャパターン。DRF API設計、ORMベストプラクティス、キャッシュ、シグナル、ミドルウェアの実装方法を学べます。","ko":"AI 에이전트를 활용한 Django 프로덕션급 아키텍처 패턴. DRF API 설계, ORM 모범 사례, 캐싱, 시그널, 미들웨어 구현 방법을 배울 수 있습니다.","es":"Aprende a diseñar patrones de arquitectura Django para aplicaciones web escalables y mantenibles con REST API, ORM y caché","fr":"Découvrez comment concevoir des modèles d''architecture Django pour des applications web évolutives et maintenables avec REST API, ORM et cache","de":"Erfahren Sie, wie Sie Django-Architekturmuster für skalierbare und wartbare Webanwendungen mit REST-API, ORM und Cache entwerfen","pt":"AI Agent para padrões de arquitetura Django, design de API REST com DRF, melhores práticas ORM, caching, signals e middleware para aplicações de nível de pro...","ru":"ИИ Агент для архитектурных шаблонов Django, проектирования REST API с DRF, лучших практик ORM, кэширования, сигналов и middleware для production-приложений.","ar":"وكيل الذكاء الاصطناعي لأنماط هندسة Django، تصميم واجهات برمجة التطبيقات REST باستخدام DRF، أفضل ممارسات ORM، التخزين المؤقت، الإشارات والوسيطة للتطبيقات على ..."},"definition":{"en":"django-patterns is an AI Agent skill that delivers production-grade Django development patterns. It covers scalable architecture, Django REST Framework API design, ORM best practices, caching implementation, signals usage, middleware setup, and recommended project structure.","zh":"django-patterns是一个AI助手技能，专门为Django开发者提供生产级架构模式指导。它涵盖REST API设计、ORM最佳实践、缓存实现、信号和中间件使用，帮助构建可扩展、可维护的Django应用程序。","ja":"django-patternsは、Django開発者のためのAIエージェントスキルです。本番環境対応のアーキテクチャパターン、REST API設計、ORMベストプラクティス、キャッシュ、シグナル、ミドルウェアの実装を指導します。","ko":"django-patterns는 Django 개발자를 위한 AI 에이전트 스킬입니다. 프로덕션급 아키텍처 패턴, REST API 설계, ORM 모범 사례, 캐싱, 시그널, 미들웨어 구현을 안내합니다.","es":"Django Patterns es un conjunto de patrones de arquitectura para desarrollar aplicaciones web escalables y mantenibles con Django","fr":"Django Patterns est un ensemble de modèles d''architecture pour développer des applications web évolutives et maintenables avec Django","de":"Django Patterns ist eine Sammlung von Architekturmustern für die Entwicklung von skalierbaren und wartbaren Webanwendungen mit Django","pt":"Django Patterns é uma AI Agent que fornece padrões de arquitetura Django para aplicações escaláveis, incluindo design de API REST com DRF, melhores práticas de ORM, caching, signals, middleware e estrutura de projetos de nível de produção.","ru":"Django Patterns — это ИИ Агент, предоставляющий архитектурные шаблоны Django для масштабируемых приложений, включая проектирование REST API с DRF, лучшие практики ORM, кэширование, сигналы, middleware и структуру проектов production-уровня.","ar":"Django Patterns هو وكيل الذكاء الاصطناعي الذي يوفر أنماط هندسة Django للتطبيقات القابلة للتوسع، بما في ذلك تصميم واجهات برمجة التطبيقات REST باستخدام DRF، أفضل ممارسات ORM، التخزين المؤقت، الإشارات، الوسيطة وهيكل المشاريع على مستوى الإنتاج."},"features":{"en":["Provides Django REST Framework (DRF) API design patterns","Offers Django ORM optimization and model best practices","Guides implementation of Django caching strategies","Covers Django signals and middleware development patterns","Recommends scalable Django project structure and settings organization","Delivers production-grade Django application architecture guidance"],"zh":["Django REST Framework API设计最佳实践","Django ORM优化和模型管理策略","生产级缓存配置和性能优化","Django信号和中间件的正确使用方法","推荐的项目结构和设置配置","可扩展Django应用架构模式"],"ja":["Django REST Frameworkを使ったAPI設計のベストプラクティス","Django ORMの最適化とモデル管理戦略","本番環境対応のキャッシュ設定とパフォーマンス最適化","Djangoシグナルとミドルウェアの正しい使用方法","推奨プロジェクト構造と設定構成","スケーラブルなDjangoアプリケーションアーキテクチャ"],"ko":["Django REST Framework를 이용한 API 설계 모범 사례","Django ORM 최적화 및 모델 관리 전략","프로덕션급 캐싱 설정과 성능 최적화","Django 시그널과 미들웨어 올바른 사용 방법","권장 프로젝트 구조와 설정 구성","확장 가능한 Django 애플리케이션 아키텍처"],"es":["Patrones de arquitectura Django para aplicaciones escalables","Diseño de REST API con Django REST Framework","Mejores prácticas para ORM y modelos","Implementación de caché y señales","Configuración de middleware y estructura de proyecto"],"fr":["Modèles d''architecture Django pour des applications évolutives","Conception de REST API avec Django REST Framework","Meilleures pratiques pour ORM et modèles","Mise en œuvre de cache et signaux","Configuration de middleware et structure de projet"],"de":["Django-Architekturmuster für skalierbare Anwendungen","Entwurf von REST-API mit Django REST Framework","Best Practices für ORM und Modelle","Implementierung von Cache und Signalen","Konfiguration von Middleware und Projektstruktur"],"pt":["Padrões de arquitetura Django para aplicações escaláveis","Design de API REST com Django REST Framework (DRF)","Melhores práticas de ORM e modelagem de dados","Implementação de caching para performance otimizada","Gerenciamento de signals e middleware personalizado","Estrutura de projeto recomendada para aplicações de produção"],"ru":["Архитектурные шаблоны Django для масштабируемых приложений","Проектирование REST API с Django REST Framework (DRF)","Лучшие практики ORM и моделирования данных","Реализация кэширования для оптимизации производительности","Управление сигналами и пользовательским middleware","Рекомендуемая структура проекта для production-приложений"],"ar":["أنماط هندسة Django للتطبيقات القابلة للتوسع","تصميم واجهات برمجة التطبيقات REST باستخدام Django REST Framework (DRF)","أفضل ممارسات ORM ونمذجة البيانات","تنفيذ التخزين المؤقت لأداء مُحسَّن","إدارة الإشارات والوسيطة المخصصة","هيكل المشروع الموصى به للتطبيقات على مستوى الإنتاج"]},"keywords":{"en":["django-patterns setup guide","how to use django-patterns with DRF","django-patterns vs django cookiecutter","django ORM best practices AI agent","Django REST Framework API design patterns","django caching strategies implementation","django signals and middleware patterns","production django project structure","install django-patterns AI skill","what is django-patterns skill"],"zh":["Django架构模式AI助手","DRF API设计最佳实践","Django ORM优化指南","Django缓存策略实现","生产级Django应用开发","Django信号和中间件使用","AI助手Django开发工具","Claude代码Django模式"],"ja":["DjangoパターンAIエージェント","DRF API設計ベストプラクティス","Django ORM最適化ガイド","Djangoキャッシュ戦略実装","本番環境Django開発","Djangoシグナルミドルウェア活用","AIエージェント開発ツール","ClaudeコードDjangoパターン"],"ko":["Django 패턴 AI 에이전트","DRF API 설계 모범 사례","Django ORM 최적화 가이드","Django 캐싱 전략 구현","프로덕션급 Django 개발","Django 시그널 미들웨어 활용","AI 에이전트 개발 도구","Claude 코드 Django 패턴"],"es":["patrones de django","arquitectura django","rest api django","orm django","caché django","señales django","middleware django","desarrollo web django","aplicaciones web escalables"],"fr":["modèles django","architecture django","rest api django","orm django","cache django","signaux django","middleware django","développement web django","applications web évolutives"],"de":["django-muster","django-architektur","rest-api django","orm django","cache django","signale django","middleware django","webentwicklung django","skalierbare webanwendungen"],"pt":["django patterns ai agent","django rest framework best practices","django orm optimization","django caching implementation","django signals middleware","django production architecture","django project structure","drf api design patterns","python django development","ai agent desenvolvimento django"],"ru":["django patterns ии агенты","django rest framework лучшие практики","django orm оптимизация","django кэширование реализация","django сигналы middleware","django production архитектура","django структура проекта","drf api шаблоны проектирования","python django разработка","ии агенты для django"],"ar":["django patterns وكيل الذكاء الاصطناعي","django rest framework أفضل الممارسات","django orm تحسين","django تنفيذ التخزين المؤقت","django إشارات وسيطة","django هندسة الإنتاج","django هيكل المشروع","drf أنماط تصميم واجهات برمجة التطبيقات","python django تطوير","وكلاء الذكاء الاصطناعي لتطوير django"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing scalable Django architecture patterns and REST API design expertise","zh":"非常适合需要可扩展的Django架构模式和REST API设计专业知识的Web开发代理","ja":"Web開発エージェントがスケーラブルなDjangoアーキテクチャパターンとREST API設計の専門知識を必要とする場合に最適","ko":"스케일러블한 Django 아키텍처 패턴과 REST API 설계 전문 지식이 필요한 웹 개발 에이전트에게 적합","es":"Perfecto para Agentes de Desarrollo Web que necesitan patrones de arquitectura escalable de Django y experiencia en diseño de API REST","fr":"Parfait pour les Agents de Développement Web ayant besoin de modèles d''architecture Django évolutifs et d''une expertise en conception d''API REST","de":"Perfekt für Webentwicklungs-Agenten, die skalierbare Django-Architekturmuster und Expertise im REST API-Design benötigen","pt":"Perfect for Web Development Agents needing scalable Django architecture patterns and REST API design expertise","ru":"Perfect for Web Development Agents needing scalable Django architecture patterns and REST API design expertise","ar":"Perfect for Web Development Agents needing scalable Django architecture patterns and REST API design expertise"},"recommendation":{"en":"Empowers agents to design production-grade Django applications using Django REST Framework, implement efficient ORM best practices, and leverage caching, signals, and middleware for enhanced performance, all while following standardized project structures","zh":"赋予代理设计生产级Django应用程序的能力，使用Django REST Framework，实现高效的ORM最佳实践，并利用缓存、信号和中间件以提高性能，同时遵循标准化的项目结构","ja":"エージェントに、Django REST Frameworkを使用して本番レベルのDjangoアプリケーションを設計し、効率的なORMのベストプラクティスを実装し、キャッシュ、シグナル、およびミドルウェアを使用してパフォーマンスを向上させ、標準化されたプロジェクト構造に従う能力を付与","ko":"에이전트가 Django REST Framework를 사용하여 프로덕션급 Django 애플리케이션을 설계하고 효율적인 ORM의 모범 사례를 구현하며 캐싱, 신호 및 미들웨어를 활용하여 성능을 향상시키는 동시에 표준화된 프로젝트 구조를 따르는 기능을 부여","es":"Permite a los agentes diseñar aplicaciones Django de nivel de producción utilizando Django REST Framework, implementar las mejores prácticas eficientes de ORM y aprovechar el almacenamiento en caché, las señales y el middleware para un rendimiento mejorado, todo mientras siguen estructuras de proyecto estandarizadas","fr":"P