INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/django-patterns', 'django-patterns', 'affaan-m', 'everything-claude-code', 'official', 'django-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity This AI Agent skill provides expert guidance on Django architecture patterns, REST API design with Django REST Framework, ORM optimization, caching, signals, and middleware implementation. It benefits developers building scalable, maintainable Django applications. 专为开发者设计的AI助手技能，提供Django生产级架构模式指导，包括REST API设计、ORM优化、缓存策略和项目结构规划，帮助构建可扩展的Django应用。 開発者向けAIエージェントスキルで、Djangoの本番環境対応アーキテクチャパターン、DRFを使ったREST API設計、ORMベストプラクティス、キャッシュ戦略を提供します。 개발자를 위한 AI 에이전트 스킬로, Django 프로덕션급 아키텍처 패턴, DRF를 이용한 REST API 설계, ORM 모범 사례, 캐싱 전략을 제공합니다. Django Patterns proporciona patrones de arquitectura para aplicaciones web escalables y mantenibles con Django y Django REST Framework Django Patterns fournit des modèles d''architecture pour des applications web évolutives et maintenables avec Django et Django REST Framework Django Patterns bietet Architekturmuster für skalierbare und wartbare Webanwendungen mit Django und Django REST Framework AI Agent especializado em padrões de desenvolvimento Django, incluindo design de APIs REST com Django REST Framework, otimizações de ORM e implementação de caching, signals e middleware para aplicações escaláveis. ИИ Агент, специализирующийся на шаблонах разработки Django, включая проектирование REST API с Django REST Framework, оптимизацию ORM и реализацию кэширования, сигналов и middleware для масштабируемых приложений. وكيل الذكاء الاصطناعي المتخصص في أنماط تطوير Django، بما في ذلك تصميم واجهات برمجة التطبيقات REST باستخدام Django REST Framework، وتحسينات ORM، وتنفيذ التخزين المؤقت والإشارات والوسيطة للتطبيقات القابلة للتوسع. django-patterns setup guide how to use django-patterns with DRF django-patterns vs django cookiecutter django ORM best practices AI agent Django REST Framework API design patterns django caching strategies implementation django signals and middleware patterns production django project structure install django-patterns AI skill what is django-patterns skill Django架构模式AI助手 DRF API设计最佳实践 Django ORM优化指南 Django缓存策略实现 生产级Django应用开发 Django信号和中间件使用 AI助手Django开发工具 Claude代码Django模式 Provides Django REST Framework (DRF) API design patterns Offers Django ORM optimization and model best practices Guides implementation of Django caching strategies Covers Django signals and middleware development patterns Recommends scalable Django project structure and settings organization Delivers production-grade Django application architecture guidance django-patterns is an AI Agent skill that delivers production-grade Django development patterns. It covers scalable architecture, Django REST Framework API design, ORM best practices, caching implementation, signals usage, middleware setup, and recommended project structure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/golang-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'golang-patterns', 61988, 7678, 92, '2026-03-06T03:39:20Z', '2026-03-06T04:13:36.237Z', 'f36a89926fab1e895e7e2e2522e4104e1d7b07452244f31ff09ef1eeb069495c', '{"id":"affaan-m/everything-claude-code/golang-patterns","name":"golang-patterns","description":{"en":"The golang-patterns AI Agent Skill delivers idiomatic Go patterns and conventions directly within your development environment. It assists Go developers in writing clean, efficient, and maintainable code during development, review, and refactoring phases.","es":"Patrones de Go idiomáticos y mejores prácticas para desarrollar aplicaciones robustas y eficientes","fr":"Modèles Go idiomatiques et bonnes pratiques pour développer des applications robustes et efficaces","de":"Go-Muster idiomatisch und beste Praktiken für die Entwicklung robuster und effizienter Anwendungen","pt":"Skill de AI Agent que fornece padrões Go idiomáticos, melhores práticas e convenções para desenvolver aplicações robustas, eficientes e maintainable em Go através do Claude Code.","ru":"ИИ Агент, предоставляющий идиоматические шаблоны Go, лучшие практики и соглашения для создания надежных, эффективных и поддерживаемых приложений на Go через Claude Code.","ar":"أداة ذكاء اصطناعي تقدم أنماط Go الاصطلاحية وأفضل الممارسات والاتفاقيات لبناء تطبيقات قوية وفعالة وسهلة الصيانة باستخدام Go من خلال Claude Code."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"golang-patterns","description":"Idiomatic Go patterns, best practices, and conventions for building robust, efficient, and maintainable Go applications.","bodyPreview":"# Go Development Patterns\n\nIdiomatic Go patterns and best practices for building robust, efficient, and maintainable applications.\n\n## When to Activate\n\n- Writing new Go code\n- Reviewing Go code\n- Refactoring existing Go code\n- Designing Go packages/modules\n\n## Core Principles\n\n### 1. Simplicity and Clarity\n\nGo favors simplicity over cleverness. Code should be obvious and easy to read.\n\n```go\n// Good: Clear and direct\nfunc GetUser(id string) (*User, error) {\n    user, err := db.FindUser(id)","body":"# Go Development Patterns\n\nIdiomatic Go patterns and best practices for building robust, efficient, and maintainable applications.\n\n## When to Activate\n\n- Writing new Go code\n- Reviewing Go code\n- Refactoring existing Go code\n- Designing Go packages/modules\n\n## Core Principles\n\n### 1. Simplicity and Clarity\n\nGo favors simplicity over cleverness. Code should be obvious and easy to read.\n\n```go\n// Good: Clear and direct\nfunc GetUser(id string) (*User, error) {\n    user, err := db.FindUser(id)\n    if err != nil {\n        return nil, fmt.Errorf(\"get user %s: %w\", id, err)\n    }\n    return user, nil\n}\n\n// Bad: Overly clever\nfunc GetUser(id string) (*User, error) {\n    return func() (*User, error) {\n        if u, e := db.FindUser(id); e == nil {\n            return u, nil\n        } else {\n            return nil, e\n        }\n    }()\n}\n```\n\n### 2. Make the Zero Value Useful\n\nDesign types so their zero value is immediately usable without initialization.\n\n```go\n// Good: Zero value is useful\ntype Counter struct {\n    mu    sync.Mutex\n    count int // zero value is 0, ready to use\n}\n\nfunc (c *Counter) Inc() {\n    c.mu.Lock()\n    c.count++\n    c.mu.Unlock()\n}\n\n// Good: bytes.Buffer works with zero value\nvar buf bytes.Buffer\nbuf.WriteString(\"hello\")\n\n// Bad: Requires initialization\ntype BadCounter struct {\n    counts map[string]int // nil map will panic\n}\n```\n\n### 3. Accept Interfaces, Return Structs\n\nFunctions should accept interface parameters and return concrete types.\n\n```go\n// Good: Accepts interface, returns concrete type\nfunc ProcessData(r io.Reader) (*Result, error) {\n    data, err := io.ReadAll(r)\n    if err != nil {\n        return nil, err\n    }\n    return &Result{Data: data}, nil\n}\n\n// Bad: Returns interface (hides implementation details unnecessarily)\nfunc ProcessData(r io.Reader) (io.Reader, error) {\n    // ...\n}\n```\n\n## Error Handling Patterns\n\n### Error Wrapping with Context\n\n```go\n// Good: Wrap errors with context\nfunc LoadConfig(path string) (*Config, error) {\n    data, err := os.ReadFile(path)\n    if err != nil {\n        return nil, fmt.Errorf(\"load config %s: %w\", path, err)\n    }\n\n    var cfg Config\n    if err := json.Unmarshal(data, &cfg); err != nil {\n        return nil, fmt.Errorf(\"parse config %s: %w\", path, err)\n    }\n\n    return &cfg, nil\n}\n```\n\n### Custom Error Types\n\n```go\n// Define domain-specific errors\ntype ValidationError struct {\n    Field   string\n    Message string\n}\n\nfunc (e *ValidationError) Error() string {\n    return fmt.Sprintf(\"validation failed on %s: %s\", e.Field, e.Message)\n}\n\n// Sentinel errors for common cases\nvar (\n    ErrNotFound     = errors.New(\"resource not found\")\n    ErrUnauthorized = errors.New(\"unauthorized\")\n    ErrInvalidInput = errors.New(\"invalid input\")\n)\n```\n\n### Error Checking with errors.Is and errors.As\n\n```go\nfunc HandleError(err error) {\n    // Check for specific error\n    if errors.Is(err, sql.ErrNoRows) {\n        log.Println(\"No records found\")\n        return\n    }\n\n    // Check for error type\n    var validationErr *ValidationError\n    if errors.As(err, &validationErr) {\n        log.Printf(\"Validation error on field %s: %s\",\n            validationErr.Field, validationErr.Message)\n        return\n    }\n\n    // Unknown error\n    log.Printf(\"Unexpected error: %v\", err)\n}\n```\n\n### Never Ignore Errors\n\n```go\n// Bad: Ignoring error with blank identifier\nresult, _ := doSomething()\n\n// Good: Handle or explicitly document why it''s safe to ignore\nresult, err := doSomething()\nif err != nil {\n    return err\n}\n\n// Acceptable: When error truly doesn''t matter (rare)\n_ = writer.Close() // Best-effort cleanup, error logged elsewhere\n```\n\n## Concurrency Patterns\n\n### Worker Pool\n\n```go\nfunc WorkerPool(jobs <-chan Job, results chan<- Result, numWorkers int) {\n    var wg sync.WaitGroup\n\n    for i := 0; i < numWorkers; i++ {\n        wg.Add(1)\n        go func() {\n            defer wg.Done()\n            for job := range jobs {\n                results <- process(job)\n            }\n        }()\n    }\n\n    wg.Wait()\n    close(results)\n}\n```\n\n### Context for Cancellation and Timeouts\n\n```go\nfunc FetchWithTimeout(ctx context.Context, url string) ([]byte, error) {\n    ctx, cancel := context.WithTimeout(ctx, 5*time.Second)\n    defer cancel()\n\n    req, err := http.NewRequestWithContext(ctx, \"GET\", url, nil)\n    if err != nil {\n        return nil, fmt.Errorf(\"create request: %w\", err)\n    }\n\n    resp, err := http.DefaultClient.Do(req)\n    if err != nil {\n        return nil, fmt.Errorf(\"fetch %s: %w\", url, err)\n    }\n    defer resp.Body.Close()\n\n    return io.ReadAll(resp.Body)\n}\n```\n\n### Graceful Shutdown\n\n```go\nfunc GracefulShutdown(server *http.Server) {\n    quit := make(chan os.Signal, 1)\n    signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)\n\n    <-quit\n    log.Println(\"Shutting down server...\")\n\n    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)\n    defer cancel()\n\n    if err := server.Shutdown(ctx); err != nil {\n        log.Fatalf(\"Server forced to shutdown: %v\", err)\n    }\n\n    log.Println(\"Server exited\")\n}\n```\n\n### errgroup for Coordinated Goroutines\n\n```go\nimport \"golang.org/x/sync/errgroup\"\n\nfunc FetchAll(ctx context.Context, urls []string) ([][]byte, error) {\n    g, ctx := errgroup.WithContext(ctx)\n    results := make([][]byte, len(urls))\n\n    for i, url := range urls {\n        i, url := i, url // Capture loop variables\n        g.Go(func() error {\n            data, err := FetchWithTimeout(ctx, url)\n            if err != nil {\n                return err\n            }\n            results[i] = data\n            return nil\n        })\n    }\n\n    if err := g.Wait(); err != nil {\n        return nil, err\n    }\n    return results, nil\n}\n```\n\n### Avoiding Goroutine Leaks\n\n```go\n// Bad: Goroutine leak if context is cancelled\nfunc leakyFetch(ctx context.Context, url string) <-chan []byte {\n    ch := make(chan []byte)\n    go func() {\n        data, _ := fetch(url)\n        ch <- data // Blocks forever if no receiver\n    }()\n    return ch\n}\n\n// Good: Properly handles cancellation\nfunc safeFetch(ctx context.Context, url string) <-chan []byte {\n    ch := make(chan []byte, 1) // Buffered channel\n    go func() {\n        data, err := fetch(url)\n        if err != nil {\n            return\n        }\n        select {\n        case ch <- data:\n        case <-ctx.Done():\n        }\n    }()\n    return ch\n}\n```\n\n## Interface Design\n\n### Small, Focused Interfaces\n\n```go\n// Good: Single-method interfaces\ntype Reader interface {\n    Read(p []byte) (n int, err error)\n}\n\ntype Writer interface {\n    Write(p []byte) (n int, err error)\n}\n\ntype Closer interface {\n    Close() error\n}\n\n// Compose interfaces as needed\ntype ReadWriteCloser interface {\n    Reader\n    Writer\n    Closer\n}\n```\n\n### Define Interfaces Where They''re Used\n\n```go\n// In the consumer package, not the provider\npackage service\n\n// UserStore defines what this service needs\ntype UserStore interface {\n    GetUser(id string) (*User, error)\n    SaveUser(user *User) error\n}\n\ntype Service struct {\n    store UserStore\n}\n\n// Concrete implementation can be in another package\n// It doesn''t need to know about this interface\n```\n\n### Optional Behavior with Type Assertions\n\n```go\ntype Flusher interface {\n    Flush() error\n}\n\nfunc WriteAndFlush(w io.Writer, data []byte) error {\n    if _, err := w.Write(data); err != nil {\n        return err\n    }\n\n    // Flush if supported\n    if f, ok := w.(Flusher); ok {\n        return f.Flush()\n    }\n    return nil\n}\n```\n\n## Package Organization\n\n### Standard Project Layout\n\n```text\nmyproject/\n├── cmd/\n│   └── myapp/\n│       └── main.go           # Entry point\n├── internal/\n│   ├── handler/              # HTTP handlers\n│   ├── service/              # Business logic\n│   ├── repository/           # Data access\n│   └── config/               # Configuration\n├── pkg/\n│   └── client/               # Public API client\n├── api/\n│   └── v1/                   # API definitions (proto, OpenAPI)\n├── testdata/                 # Test fixtures\n├── go.mod\n├── go.sum\n└── Makefile\n```\n\n### Package Naming\n\n```go\n// Good: Short, lowercase, no underscores\npackage http\npackage json\npackage user\n\n// Bad: Verbose, mixed case, or redundant\npackage httpHandler\npackage json_parser\npackage userService // Redundant ''Service'' suffix\n```\n\n### Avoid Package-Level State\n\n```go\n// Bad: Global mutable state\nvar db *sql.DB\n\nfunc init() {\n    db, _ = sql.Open(\"postgres\", os.Getenv(\"DATABASE_URL\"))\n}\n\n// Good: Dependency injection\ntype Server struct {\n    db *sql.DB\n}\n\nfunc NewServer(db *sql.DB) *Server {\n    return &Server{db: db}\n}\n```\n\n## Struct Design\n\n### Functional Options Pattern\n\n```go\ntype Server struct {\n    addr    string\n    timeout time.Duration\n    logger  *log.Logger\n}\n\ntype Option func(*Server)\n\nfunc WithTimeout(d time.Duration) Option {\n    return func(s *Server) {\n        s.timeout = d\n    }\n}\n\nfunc WithLogger(l *log.Logger) Option {\n    return func(s *Server) {\n        s.logger = l\n    }\n}\n\nfunc NewServer(addr string, opts ...Option) *Server {\n    s := &Server{\n        addr:    addr,\n        timeout: 30 * time.Second, // default\n        logger:  log.Default(),    // default\n    }\n    for _, opt := range opts {\n        opt(s)\n    }\n    return s\n}\n\n// Usage\nserver := NewServer(\":8080\",\n    WithTimeout(60*time.Second),\n    WithLogger(customLogger),\n)\n```\n\n### Embedding for Composition\n\n```go\ntype Logger struct {\n    prefix string\n}\n\nfunc (l *Logger) Log(msg string) {\n    fmt.Printf(\"[%s] %s\\n\", l.prefix, msg)\n}\n\ntype Server struct {\n    *Logger // Embedding - Server gets Log method\n    addr    string\n}\n\nfunc NewServer(addr string) *Server {\n    return &Server{\n        Logger: &Logger{prefix: \"SERVER\"},\n        addr:   addr,\n    }\n}\n\n// Usage\ns := NewServer(\":8080\")\ns.Log(\"Starting...\") // Calls embedded Logger.Log\n```\n\n## Memory and Performance\n\n### Preallocate Slices When Size is Known\n\n```go\n// Bad: Grows slice multiple times\nfunc processItems(items []Item) []Result {\n    var results []Result\n    for _, item := range items {\n        results = append(results, process(item))\n    }\n    return results\n}\n\n// Good: Single allocation\nfunc processItems(items []Item) []Result {\n    results := make([]Result, 0, len(items))\n    for _, item := range items {\n        results = append(results, process(item))\n    }\n    return results\n}\n```\n\n### Use sync.Pool for Frequent Allocations\n\n```go\nvar bufferPool = sync.Pool{\n    New: func() interface{} {\n        return new(bytes.Buffer)\n    },\n}\n\nfunc ProcessRequest(data []byte) []byte {\n    buf := bufferPool.Get().(*bytes.Buffer)\n    defer func() {\n        buf.Reset()\n        bufferPool.Put(buf)\n    }()\n\n    buf.Write(data)\n    // Process...\n    return buf.Bytes()\n}\n```\n\n### Avoid String Concatenation in Loops\n\n```go\n// Bad: Creates many string allocations\nfunc join(parts []string) string {\n    var result string\n    for _, p := range parts {\n        result += p + \",\"\n    }\n    return result\n}\n\n// Good: Single allocation with strings.Builder\nfunc join(parts []string) string {\n    var sb strings.Builder\n    for i, p := range parts {\n        if i > 0 {\n            sb.WriteString(\",\")\n        }\n        sb.WriteString(p)\n    }\n    return sb.String()\n}\n\n// Best: Use standard library\nfunc join(parts []string) string {\n    return strings.Join(parts, \",\")\n}\n```\n\n## Go Tooling Integration\n\n### Essential Commands\n\n```bash\n# Build and run\ngo build ./...\ngo run ./cmd/myapp\n\n# Testing\ngo test ./...\ngo test -race ./...\ngo test -cover ./...\n\n# Static analysis\ngo vet ./...\nstaticcheck ./...\ngolangci-lint run\n\n# Module management\ngo mod tidy\ngo mod verify\n\n# Formatting\ngofmt -w .\ngoimports -w .\n```\n\n### Recommended Linter Configuration (.golangci.yml)\n\n```yaml\nlinters:\n  enable:\n    - errcheck\n    - gosimple\n    - govet\n    - ineffassign\n    - staticcheck\n    - unused\n    - gofmt\n    - goimports\n    - misspell\n    - unconvert\n    - unparam\n\nlinters-settings:\n  errcheck:\n    check-type-assertions: true\n  govet:\n    check-shadowing: true\n\nissues:\n  exclude-use-default: false\n```\n\n## Quick Reference: Go Idioms\n\n| Idiom | Description |\n|-------|-------------|\n| Accept interfaces, return structs | Functions accept interface params, return concrete types |\n| Errors are values | Treat errors as first-class values, not exceptions |\n| Don''t communicate by sharing memory | Use channels for coordination between goroutines |\n| Make the zero value useful | Types should work without explicit initialization |\n| A little copying is better than a little dependency | Avoid unnecessary external dependencies |\n| Clear is better than clever | Prioritize readability over cleverness |\n| gofmt is no one''s favorite but everyone''s friend | Always format with gofmt/goimports |\n| Return early | Handle errors first, keep happy path unindented |\n\n## Anti-Patterns to Avoid\n\n```go\n// Bad: Naked returns in long functions\nfunc process() (result int, err error) {\n    // ... 50 lines ...\n    return // What is being returned?\n}\n\n// Bad: Using panic for control flow\nfunc GetUser(id string) *User {\n    user, err := db.Find(id)\n    if err != nil {\n        panic(err) // Don''t do this\n    }\n    return user\n}\n\n// Bad: Passing context in struct\ntype Request struct {\n    ctx context.Context // Context should be first param\n    ID  string\n}\n\n// Good: Context as first parameter\nfunc ProcessRequest(ctx context.Context, id string) error {\n    // ...\n}\n\n// Bad: Mixing value and pointer receivers\ntype Counter struct{ n int }\nfunc (c Counter) Value() int { return c.n }    // Value receiver\nfunc (c *Counter) Increment() { c.n++ }        // Pointer receiver\n// Pick one style and be consistent\n```\n\n**Remember**: Go code should be boring in the best way - predictable, consistent, and easy to understand. When in doubt, keep it simple.\n"},"category":"official","lastSynced":"2026-03-06T04:13:36.237Z","seo":{"title":{"en":"golang-patterns: Idiomatic Go Best Practices | AI Agent S...","es":"Guía de patrones de Go: Mejores prácticas para desarrolla...","fr":"Guide des modèles Go: Bonnes pratiques pour les développeurs","de":"Go-Muster-Setup: Beste Praktiken für Entwickler","pt":"Padrões Go Idiomáticos: Guia de Melhores Práticas para AI...","ru":"Идиоматические шаблоны Go: Лучшие практики для ИИ Агентов","ar":"أنماط Go الاصطلاحية: أفضل الممارسات لأدوات الذكاء الاصطناعي"},"description":{"en":"Leverage Claude AI to write idiomatic Go code. This MCP skill provides real-time guidance on Go patterns, package design, and error handling for building rob...","es":"Aprende a aplicar patrones de Go idiomáticos para construir aplicaciones robustas y eficientes. Descubre las mejores prácticas para desarrolladores","fr":"Découvrez comment appliquer des modèles Go idiomatiques pour construire des applications robustes et efficaces. Les meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie Go-Muster idiomatisch anwenden, um robuste und effiziente Anwendungen zu erstellen. Die besten Praktiken für Entwickler","pt":"AI Agent especializado em padrões Go idiomáticos. Aprenda melhores práticas para código robusto, eficiente e maintainable com Claude Code através do MCP.","ru":"ИИ Агент для идиоматических шаблонов Go. Изучите лучшие практики для создания надежного, эффективного и поддерживаемого кода с Claude Code через MCP.","ar":"أداة ذكاء اصطناعي متخصصة في أنماط Go الاصطلاحية. تعلم أفضل الممارسات لكتابة كود قوي وفعال وسهل الصيانة باستخدام Claude Code من خلال MCP."},"definition":{"en":"golang-patterns is an AI Agent Skill for Model Context Protocol (MCP) that provides real-time guidance on idiomatic Go patterns, best practices, and conventions. It helps developers build robust, efficient, and maintainable Go applications by offering suggestions during coding, code review, and package design.","es":"Patrones de Go idiomáticos son convenciones y principios de diseño para escribir código Go claro y eficiente","fr":"Les modèles Go idiomatiques sont des conventions et des principes de conception pour écrire du code Go clair et efficace","de":"Go-Muster idiomatisch sind Konventionen und Designprinzipien für das Schreiben von klarem und effizientem Go-Code","pt":"O golang-patterns é um skill de AI Agent que oferece padrões de desenvolvimento Go idiomáticos através do Claude Code. Foca em simplicidade, clareza e convenções para código robusto durante escrita, revisão e refatoração.","ru":"golang-patterns - это ИИ Агент, предоставляющий идиоматические шаблоны разработки на Go через Claude Code. Сосредоточен на простоте, ясности и соглашениях для надежного кода при написании, проверке и рефакторинге.","ar":"golang-patterns هي أداة ذكاء اصطناعي تقدم أنماط تطوير Go اصطلاحية من خلال Claude Code. تركز على البساطة والوضوح والاتفاقيات لكتابة كود قوي أثناء البرمجة والمراجعة وإعادة الهيكلة."},"features":{"en":["Provides idiomatic Go patterns for writing clear and direct code (e.g., `func GetUser(id string) (*User, error)`)","Activates during Go code writing, reviewing, and refactoring tasks","Offers guidance on designing Go packages and modules","Emphasizes core Go principles like simplicity and clarity over cleverness"],"es":["Simplificación y claridad en el código","Patrones de diseño para paquetes y módulos","Refactorización de código existente","Creación de aplicaciones robustas y eficientes","Aplicación de convenciones y principios de diseño"],"fr":["Simplification et clarté du code","Modèles de conception pour les paquets et les modules","Réfactorisation du code existant","Création d''applications robustes et efficaces","Application des conventions et des principes de conception"],"de":["Vereinfachung und Klarheit im Code","Muster für die Gestaltung von Paketen und Modulen","Refaktorisierung von bestehendem Code","Erstellung robuster und effizienter Anwendungen","Anwendung von Konventionen und Designprinzipien"],"pt":["Padrões idiomáticos Go para simplicidade e clareza de código","Melhores práticas para aplicações robustas e eficientes","Convenções para design de packages e módulos Go","Suporte MCP para integração com ferramentas de desenvolvimento","Otimização para escrita, revisão e refatoração de código Go","Exemplos práticos como func GetUser(id string) (*User, error)"],"ru":["Идиоматические шаблоны Go для простоты и ясности кода","Лучшие практики для надежных и эффективных приложений","Соглашения для проектирования пакетов и модулей Go","Поддержка MCP для интеграции с инструментами разработки","Оптимизация для написания, проверки и рефакторинга кода Go","Практические примеры типа func GetUser(id string) (*User, error)"],"ar":["أنماط Go اصطلاحية لتبسيط ووضوح الكود","أفضل الممارسات للتطبيقات القوية والفعالة","اتفاقيات لتصميم الحزم والوحدات في Go","دعم MCP للتكامل مع أدوات التطوير","تحسين لكتابة ومراجعة وإعادة هيكلة كود Go","أمثلة عملية مثل func GetUser(id string) (*User, error)"]},"keywords":{"en":["golang-patterns MCP install","how to use golang-patterns with Claude","golang-patterns vs other Go AI tools","golang-patterns setup guide for AI agents","what is golang-patterns skill","Go development patterns best practices","idiomatic Go code generation","refactoring Go code with AI","Model Context Protocol Go skills"],"es":["patrones de Go","desarrollo de aplicaciones en Go","mejores prácticas para desarrolladores de Go","construcción de aplicaciones robustas","eficiencia en el código Go","herramientas de desarrollo de Go","agentes de inteligencia artificial para desarrolladores"],"fr":["modèles Go","développement d''applications en Go","bonnes pratiques pour les développeurs Go","construction d''applications robustes","efficacité dans le code Go","outils de développement Go","agents d''intelligence artificielle pour les développeurs"],"de":["Go-Muster","Entwicklung von Anwendungen in Go","beste Praktiken für Go-Entwickler","Erstellung robuster Anwendungen","Effizienz im Go-Code","Entwicklungstools für Go","Künstliche Intelligenz-Tools für Entwickler"],"pt":["padrões go idiomáticos","ai agent golang","claude code go","melhores práticas go","mcp developer tools","refatoração código go","go packages design","aplicações robustas go"],"ru":["идиоматические шаблоны go","ИИ агент golang","claude code go","лучшие практики go","mcp инструменты разработки","рефакторинг кода go","дизайн пакетов go","надежные приложения go"],"ar":["أنماط go اصطلاحية","أدوات الذكاء الاصطناعي golang","claude code go","أفضل ممارسات go","أدوات مطوري mcp","إعادة هيكلة كود go","تصميم حزم go","تطبيقات go قوية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents specializing in Go development and architectural review.","zh":"非常适合专注于 Go 开发和架构审查的代码分析智能体。","ja":"Go開発とアーキテクチャレビューを専門とするコード分析エージェントに最適です。","ko":"Go 개발 및 아키텍처 검토를 전문으로 하는 코드 분석 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Análisis de Código especializados en desarrollo Go y revisión arquitectónica.","fr":"Parfait pour les Agents d''Analyse de Code spécialisés dans le développement Go et la revue architecturale.","de":"Perfekt für Codeanalyse-Agenten, die sich auf Go-Entwicklung und Architekturbewertung spezialisieren.","pt":"Perfeito para Agentes de Análise de Código especializados em desenvolvimento Go e revisão arquitetural.","ru":"Идеально подходит для Агентов Анализа Кода, специализирующихся на разработке на Go и архитектурном обзоре.","ar":"مثالي لوكلاء تحليل الشيفرة المتخصصين في تطوير Go والمراجعة المعمارية."},"recommendation":{"en":"Empowers agents to analyze and generate idiomatic Go code by providing patterns for robust error handling, concurrency management with goroutines and channels, and efficient package design. It enables code quality assessment against Go''s core principles of simplicity, clarity, and explicit error handling.","zh":"通过提供用于健壮错误处理、使用 goroutines 和 channels 进行并发管理以及高效包设计的模式，使智能体能够分析和生成符合 Go 语言习惯的代码。它支持根据 Go 的核心原则（简洁性、清晰性和显式错误处理）进行代码质量评估。","ja":"堅牢なエラー処理、goroutinesとchannelsを用いた並行性管理、効率的なパッケージ設計のためのパターンを提供することで、エージェントが慣用的なGoコードを分析および生成することを可能にします。これは、シンプルさ、明確さ、明示的なエラー処理というGoの核心原則に基づいたコード品質評価を可能にします。","ko":"강력한 오류 처리, 고루틴과 채널을 이용한 동시성 관리, 효율적인 패키지 설계를 위한 패턴을 제공함으로써 에이전트가 관용적인 Go 코드를 분석하고 생성할 수 있도록 합니다. 이는 단순성, 명확성, 명시적 오류 처리라는 Go의 핵심 원칙에 대해 코드 품질 평가를 가능하게 합니다.","es":"Permite a los agentes analizar y generar código Go idiomático al proporcionar patrones para un manejo robusto de errores, gestión de concurrencia con goroutines y channels, y un diseño eficiente de paquetes. Permite la evaluación de la calidad del código según los principios fundamentales de Go: simplicidad, claridad y manejo explícito de errores.","fr":"Permet aux agents d''analyser et de générer du code Go idiomatique en fournissant des modèles pour une gestion robuste des erreurs, une gestion de la concurrence avec les goroutines et les channels, et une conception efficace des packages. Il permet l''évaluation de la qualité du code par rapport aux principes fondamentaux de Go que sont la simplicité, la clarté et la gestion explicite des erreurs.","de":"Ermöglicht es Agenten, idiomatischen Go-Code zu analysieren und zu generieren, indem Muster für robustes Error Handling, Nebenläufigkeitsverwaltung mit Goroutines und Channels sowie effizientes Package-Design bereitgestellt werden. Es ermöglicht die Bewertung der Codequalität anhand der Kernprinzipien von Go: Einfachheit, Klarheit und explizites Error Handling.","pt":"Capacita agentes a analisar e gerar código Go idiomático, fornecendo padrões para tratamento robusto de erros, gerenciamento de concorrência com gorrotinas e canais, e design eficiente de pacotes. Permite avaliar a qualidade do código com base nos princípios fundamentais do Go: simplicidade, clareza e tratamento explícito de erros.","ru":"Предоставляет агентам возможность анализировать и генерировать идиоматический код Go, предлагая шаблоны для надежной обработки ошибок, управления конкурентностью с помощью горутин и каналов, а также эффективного проектирования пакетов. Позволяет оценивать качество кода в соответствии с основными принципами Go: простотой, ясностью и явной обработкой ошибок.","ar":"يمكّن الوكلاء من تحليل وإنشاء شيفرة Go اصطلاحية من خلال تقديم أنماط للمعالجة القوية للأخطاء، وإدارة التزامن باستخدام goroutines والقنوات، وتصميم الحزم بكفاءة. يتيح تقييم جودة الشيفرة مقابل المبادئ الأساسية لـ Go المتمثلة في البساطة والوضوح والمعالجة الصريحة للأخطاء."},"useCases":{"en":["Refactoring legacy Go code to idiomatic patterns","Designing concurrent systems with goroutines and channels","Reviewing code for Go best practices and conventions","Generating maintainable package/module structures"],"zh":["将遗留 Go 代码重构为符合语言习惯的模式","使用 goroutines 和 channels 设计并发系统","审查代码是否符合 Go 最佳实践和约定","生成可维护的包/模块结构"],"ja":["レガシーなGoコードを慣用的なパターンにリファクタリング","goroutinesとchannelsを使用した並行システムの設計","Goのベストプラクティスと規約に基づくコードレビュー","保守可能なパッケージ/モジュール構造の生成"],"ko":["레거시 Go 코드를 관용적인 패턴으로 리팩토링","고루틴과 채널을 사용한 동시성 시스템 설계","Go 모범 사례 및 규약에 대한 코드 검토","유지보수 가능한 패키지/모듈 구조 생성"],"es":["Refactorizar código Go heredado a patrones idiomáticos","Diseñar sistemas concurrentes con goroutines y channels","Revisar código para las mejores prácticas y convenciones de Go","Generar estructuras de paquetes/módulos mantenibles"],"fr":["Refactoriser du code Go legacy vers des modèles idiomatiques","Concevoir des systèmes concurrents avec des goroutines et des channels","Examiner le code pour les bonnes pratiques et conventions Go","Générer des structures de packages/modules maintenables"],"de":["Refaktorisierung von Legacy-Go-Code in idiomatische Muster","Entwicklung nebenläufiger Systeme mit Goroutines und Channels","Überprüfung von Code auf Go-Best Practices und Konventionen","Generierung wartbarer Package-/Modulstrukturen"],"pt":["Refatorar código Go legado para padrões idiomáticos","Projetar sistemas concorrentes com gorrotinas e canais","Revisar código para melhores práticas e convenções do Go","Gerar estruturas de pacotes/módulos sustentáveis"],"ru":["Рефакторинг унаследованного кода Go в идиоматические шаблоны","Проектирование конкурентных систем с использованием горутин и каналов","Проверка кода на соответствие лучшим практикам и соглашениям Go","Генерация поддерживаемых структур пакетов/модулей"],"ar":["إعادة هيكلة شيفرة Go القديمة إلى أنماط اصطلاحية","تصميم أنظمة متزامنة باستخدام goroutines والقنوات","مراجعة الشيفرة لأفضل ممارسات وقواعد Go","إنشاء هياكل حزم/وحدات قابلة للصيانة"]},"limitations":{"en":["Go-specific patterns only","Requires understanding of Go syntax and semantics","Focuses on conventions rather than syntax validation"],"zh":["仅限 Go 特定模式","需要理解 Go 语法和语义","侧重于约定而非语法验证"],"ja":["Go固有のパターンのみ","Goの構文とセマンティクスの理解が必要","構文検証ではなく規約に焦点を当てている"],"ko":["Go 특정 패턴만 해당","Go 구문과 의미론에 대한 이해 필요","구문 검증보다는 규약에 중점을 둠"],"es":["Patrones específicos de Go únicamente","Requiere comprensión de la sintaxis y semántica de Go","Se centra en las convenciones en lugar de la validación de sintaxis"],"fr":["Modèles spécifiques à Go uniquement","Nécessite une compréhension de la syntaxe et de la sémantique de Go","Se concentre sur les conventions plutôt que sur la validation de la syntaxe"],"de":["Nur Go-spezifische Muster","Erfordert ein Verständnis der Go-Syntax und -Semantik","Konzentriert sich auf Konventionen anstelle von Syntaxvalidierung"],"pt":["Padrões específicos do Go apenas","Requer compreensão da sintaxe e semântica do Go","Foca em convenções em vez de validação de sintaxe"],"ru":["Только Go-специфичные шаблоны","Требует понимания синтаксиса и семантики Go","Сосредоточен на соглашениях, а не на проверке синтаксиса"],"ar":["أنماط محددة لـ Go فقط","يتطلب فهمًا لبناء الجملة ودلالات Go","يركز على الاصطلاحات بدلاً من التحقق من صحة بناء الجملة"]},"version":4},"contentHash":"f36a89926fab1e895e7e2e2522e4104e1d7b07452244f31ff09ef1eeb069495c","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":92}');
