INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/golang-patterns', 'golang-patterns', 'affaan-m', 'everything-claude-code', 'official', 'golang-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The golang-patterns AI Agent Skill delivers idiomatic Go patterns and conventions directly within your development environment. It assists Go developers in writing clean, efficient, and maintainable code during development, review, and refactoring phases. Patrones de Go idiomáticos y mejores prácticas para desarrollar aplicaciones robustas y eficientes Modèles Go idiomatiques et bonnes pratiques pour développer des applications robustes et efficaces Go-Muster idiomatisch und beste Praktiken für die Entwicklung robuster und effizienter Anwendungen Skill de AI Agent que fornece padrões Go idiomáticos, melhores práticas e convenções para desenvolver aplicações robustas, eficientes e maintainable em Go através do Claude Code. ИИ Агент, предоставляющий идиоматические шаблоны Go, лучшие практики и соглашения для создания надежных, эффективных и поддерживаемых приложений на Go через Claude Code. أداة ذكاء اصطناعي تقدم أنماط Go الاصطلاحية وأفضل الممارسات والاتفاقيات لبناء تطبيقات قوية وفعالة وسهلة الصيانة باستخدام Go من خلال Claude Code. golang-patterns MCP install how to use golang-patterns with Claude golang-patterns vs other Go AI tools golang-patterns setup guide for AI agents what is golang-patterns skill Go development patterns best practices idiomatic Go code generation refactoring Go code with AI Model Context Protocol Go skills Provides idiomatic Go patterns for writing clear and direct code (e.g., `func GetUser(id string) (*User, error)`) Activates during Go code writing, reviewing, and refactoring tasks Offers guidance on designing Go packages and modules Emphasizes core Go principles like simplicity and clarity over cleverness golang-patterns is an AI Agent Skill for Model Context Protocol (MCP) that provides real-time guidance on idiomatic Go patterns, best practices, and conventions. It helps developers build robust, efficient, and maintainable Go applications by offering suggestions during coding, code review, and package design.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/security-review', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'security-review', 61988, 7678, 92, '2026-03-06T03:39:20Z', '2026-03-06T04:32:21.210Z', 'f7530a63c7561bd1036cf4cd4d5939b04ac7a9e919ceefeb4c1a3586eb907d82', '{"id":"affaan-m/everything-claude-code/security-review","name":"security-review","description":{"en":"The security-review skill provides developers with a comprehensive security checklist and patterns when working on authentication, user input, API endpoints, or payment features. It helps identify potential vulnerabilities and ensures code follows security best practices.","zh":"security-review是一款AI代理技能，专为处理用户输入、实现支付功能和集成第三方API时提供全面的安全模式检查。通过具体的TypeScript示例展示密钥管理的最佳实践。","ja":"security-reviewは、ユーザー入力の処理や決済機能の実装時に包括的なセキュリティパターンを提供するAIエージェントスキルです。Claude Code連携で具体的なTypeScript例を用いたチェックを実現。","ko":"security-review는 사용자 입력 처리, 결제 기능 구현 시 포괄적인 보안 패턴을 제공하는 AI 에이전트 스킬입니다. Claude Code 연동으로 TypeScript 예제를 통한 구체적인 점검 가능.","es":"Esta skill proporciona revisiones de seguridad exhaustivas para desarrollo de APIs, manejo de autenticación y implementación de endpoints seguros. Incluye checklist de mejores prácticas para gestión de secrets, validación de input y protección contra vulnerabilidades comunes.","fr":"Cette compétence offre des revues de sécurité complètes pour le développement d''APIs, la gestion de l''authentification et l''implémentation d''endpoints sécurisés. Comprend une checklist de meilleures pratiques pour la gestion des secrets, la validation des inputs et la protection contre les vulnér...","de":"Dieser Skill bietet umfassende Sicherheitsüberprüfungen für die API-Entwicklung, die Handhabung von Authentifizierung und die Implementierung sicherer Endpoints. Enthält eine Checkliste der Best Practices für das Secrets-Management, die Input-Validierung und den Schutz gegen häufige Schwachstellen.","pt":"Skill security-review para AI Agents que fornece checklist abrangente de segurança para desenvolvimento. Cobre autenticação, gerenciamento de secrets, criação de API endpoints e tratamento de input do usuário seguindo melhores práticas.","ru":"Навык security-review для ИИ Агентов, предоставляющий комплексный чеклист безопасности для разработки. Охватывает аутентификацию, управление секретами, создание API эндпоинтов и обработку пользовательского ввода по лучшим практикам.","ar":"مهارة security-review لأدوات الذكاء الاصطناعي التي توفر قائمة مراجعة شاملة للأمان للتطوير. تغطي المصادقة وإدارة الأسرار وإنشاء نقاط نهاية API ومعالجة مدخلات المستخدم وفقًا لأفضل الممارسات."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"security-review","description":"Use this skill when adding authentication, handling user input, working with secrets, creating API endpoints, or implementing payment/sensitive features. Provides comprehensive security checklist and patterns.","bodyPreview":"# Security Review Skill\n\nThis skill ensures all code follows security best practices and identifies potential vulnerabilities.\n\n## When to Activate\n\n- Implementing authentication or authorization\n- Handling user input or file uploads\n- Creating new API endpoints\n- Working with secrets or credentials\n- Implementing payment features\n- Storing or transmitting sensitive data\n- Integrating third-party APIs\n\n## Security Checklist\n\n### 1. Secrets Management\n\n#### ❌ NEVER Do This\n```typescript\nconst api","body":"# Security Review Skill\n\nThis skill ensures all code follows security best practices and identifies potential vulnerabilities.\n\n## When to Activate\n\n- Implementing authentication or authorization\n- Handling user input or file uploads\n- Creating new API endpoints\n- Working with secrets or credentials\n- Implementing payment features\n- Storing or transmitting sensitive data\n- Integrating third-party APIs\n\n## Security Checklist\n\n### 1. Secrets Management\n\n#### ❌ NEVER Do This\n```typescript\nconst apiKey = \"sk-proj-xxxxx\"  // Hardcoded secret\nconst dbPassword = \"password123\" // In source code\n```\n\n#### ✅ ALWAYS Do This\n```typescript\nconst apiKey = process.env.OPENAI_API_KEY\nconst dbUrl = process.env.DATABASE_URL\n\n// Verify secrets exist\nif (!apiKey) {\n  throw new Error(''OPENAI_API_KEY not configured'')\n}\n```\n\n#### Verification Steps\n- [ ] No hardcoded API keys, tokens, or passwords\n- [ ] All secrets in environment variables\n- [ ] `.env.local` in .gitignore\n- [ ] No secrets in git history\n- [ ] Production secrets in hosting platform (Vercel, Railway)\n\n### 2. Input Validation\n\n#### Always Validate User Input\n```typescript\nimport { z } from ''zod''\n\n// Define validation schema\nconst CreateUserSchema = z.object({\n  email: z.string().email(),\n  name: z.string().min(1).max(100),\n  age: z.number().int().min(0).max(150)\n})\n\n// Validate before processing\nexport async function createUser(input: unknown) {\n  try {\n    const validated = CreateUserSchema.parse(input)\n    return await db.users.create(validated)\n  } catch (error) {\n    if (error instanceof z.ZodError) {\n      return { success: false, errors: error.errors }\n    }\n    throw error\n  }\n}\n```\n\n#### File Upload Validation\n```typescript\nfunction validateFileUpload(file: File) {\n  // Size check (5MB max)\n  const maxSize = 5 * 1024 * 1024\n  if (file.size > maxSize) {\n    throw new Error(''File too large (max 5MB)'')\n  }\n\n  // Type check\n  const allowedTypes = [''image/jpeg'', ''image/png'', ''image/gif'']\n  if (!allowedTypes.includes(file.type)) {\n    throw new Error(''Invalid file type'')\n  }\n\n  // Extension check\n  const allowedExtensions = [''.jpg'', ''.jpeg'', ''.png'', ''.gif'']\n  const extension = file.name.toLowerCase().match(/\\.[^.]+$/)?.[0]\n  if (!extension || !allowedExtensions.includes(extension)) {\n    throw new Error(''Invalid file extension'')\n  }\n\n  return true\n}\n```\n\n#### Verification Steps\n- [ ] All user inputs validated with schemas\n- [ ] File uploads restricted (size, type, extension)\n- [ ] No direct use of user input in queries\n- [ ] Whitelist validation (not blacklist)\n- [ ] Error messages don''t leak sensitive info\n\n### 3. SQL Injection Prevention\n\n#### ❌ NEVER Concatenate SQL\n```typescript\n// DANGEROUS - SQL Injection vulnerability\nconst query = `SELECT * FROM users WHERE email = ''${userEmail}''`\nawait db.query(query)\n```\n\n#### ✅ ALWAYS Use Parameterized Queries\n```typescript\n// Safe - parameterized query\nconst { data } = await supabase\n  .from(''users'')\n  .select(''*'')\n  .eq(''email'', userEmail)\n\n// Or with raw SQL\nawait db.query(\n  ''SELECT * FROM users WHERE email = $1'',\n  [userEmail]\n)\n```\n\n#### Verification Steps\n- [ ] All database queries use parameterized queries\n- [ ] No string concatenation in SQL\n- [ ] ORM/query builder used correctly\n- [ ] Supabase queries properly sanitized\n\n### 4. Authentication & Authorization\n\n#### JWT Token Handling\n```typescript\n// ❌ WRONG: localStorage (vulnerable to XSS)\nlocalStorage.setItem(''token'', token)\n\n// ✅ CORRECT: httpOnly cookies\nres.setHeader(''Set-Cookie'',\n  `token=${token}; HttpOnly; Secure; SameSite=Strict; Max-Age=3600`)\n```\n\n#### Authorization Checks\n```typescript\nexport async function deleteUser(userId: string, requesterId: string) {\n  // ALWAYS verify authorization first\n  const requester = await db.users.findUnique({\n    where: { id: requesterId }\n  })\n\n  if (requester.role !== ''admin'') {\n    return NextResponse.json(\n      { error: ''Unauthorized'' },\n      { status: 403 }\n    )\n  }\n\n  // Proceed with deletion\n  await db.users.delete({ where: { id: userId } })\n}\n```\n\n#### Row Level Security (Supabase)\n```sql\n-- Enable RLS on all tables\nALTER TABLE users ENABLE ROW LEVEL SECURITY;\n\n-- Users can only view their own data\nCREATE POLICY \"Users view own data\"\n  ON users FOR SELECT\n  USING (auth.uid() = id);\n\n-- Users can only update their own data\nCREATE POLICY \"Users update own data\"\n  ON users FOR UPDATE\n  USING (auth.uid() = id);\n```\n\n#### Verification Steps\n- [ ] Tokens stored in httpOnly cookies (not localStorage)\n- [ ] Authorization checks before sensitive operations\n- [ ] Row Level Security enabled in Supabase\n- [ ] Role-based access control implemented\n- [ ] Session management secure\n\n### 5. XSS Prevention\n\n#### Sanitize HTML\n```typescript\nimport DOMPurify from ''isomorphic-dompurify''\n\n// ALWAYS sanitize user-provided HTML\nfunction renderUserContent(html: string) {\n  const clean = DOMPurify.sanitize(html, {\n    ALLOWED_TAGS: [''b'', ''i'', ''em'', ''strong'', ''p''],\n    ALLOWED_ATTR: []\n  })\n  return <div dangerouslySetInnerHTML={{ __html: clean }} />\n}\n```\n\n#### Content Security Policy\n```typescript\n// next.config.js\nconst securityHeaders = [\n  {\n    key: ''Content-Security-Policy'',\n    value: `\n      default-src ''self'';\n      script-src ''self'' ''unsafe-eval'' ''unsafe-inline'';\n      style-src ''self'' ''unsafe-inline'';\n      img-src ''self'' data: https:;\n      font-src ''self'';\n      connect-src ''self'' https://api.example.com;\n    `.replace(/\\s{2,}/g, '' '').trim()\n  }\n]\n```\n\n#### Verification Steps\n- [ ] User-provided HTML sanitized\n- [ ] CSP headers configured\n- [ ] No unvalidated dynamic content rendering\n- [ ] React''s built-in XSS protection used\n\n### 6. CSRF Protection\n\n#### CSRF Tokens\n```typescript\nimport { csrf } from ''@/lib/csrf''\n\nexport async function POST(request: Request) {\n  const token = request.headers.get(''X-CSRF-Token'')\n\n  if (!csrf.verify(token)) {\n    return NextResponse.json(\n      { error: ''Invalid CSRF token'' },\n      { status: 403 }\n    )\n  }\n\n  // Process request\n}\n```\n\n#### SameSite Cookies\n```typescript\nres.setHeader(''Set-Cookie'',\n  `session=${sessionId}; HttpOnly; Secure; SameSite=Strict`)\n```\n\n#### Verification Steps\n- [ ] CSRF tokens on state-changing operations\n- [ ] SameSite=Strict on all cookies\n- [ ] Double-submit cookie pattern implemented\n\n### 7. Rate Limiting\n\n#### API Rate Limiting\n```typescript\nimport rateLimit from ''express-rate-limit''\n\nconst limiter = rateLimit({\n  windowMs: 15 * 60 * 1000, // 15 minutes\n  max: 100, // 100 requests per window\n  message: ''Too many requests''\n})\n\n// Apply to routes\napp.use(''/api/'', limiter)\n```\n\n#### Expensive Operations\n```typescript\n// Aggressive rate limiting for searches\nconst searchLimiter = rateLimit({\n  windowMs: 60 * 1000, // 1 minute\n  max: 10, // 10 requests per minute\n  message: ''Too many search requests''\n})\n\napp.use(''/api/search'', searchLimiter)\n```\n\n#### Verification Steps\n- [ ] Rate limiting on all API endpoints\n- [ ] Stricter limits on expensive operations\n- [ ] IP-based rate limiting\n- [ ] User-based rate limiting (authenticated)\n\n### 8. Sensitive Data Exposure\n\n#### Logging\n```typescript\n// ❌ WRONG: Logging sensitive data\nconsole.log(''User login:'', { email, password })\nconsole.log(''Payment:'', { cardNumber, cvv })\n\n// ✅ CORRECT: Redact sensitive data\nconsole.log(''User login:'', { email, userId })\nconsole.log(''Payment:'', { last4: card.last4, userId })\n```\n\n#### Error Messages\n```typescript\n// ❌ WRONG: Exposing internal details\ncatch (error) {\n  return NextResponse.json(\n    { error: error.message, stack: error.stack },\n    { status: 500 }\n  )\n}\n\n// ✅ CORRECT: Generic error messages\ncatch (error) {\n  console.error(''Internal error:'', error)\n  return NextResponse.json(\n    { error: ''An error occurred. Please try again.'' },\n    { status: 500 }\n  )\n}\n```\n\n#### Verification Steps\n- [ ] No passwords, tokens, or secrets in logs\n- [ ] Error messages generic for users\n- [ ] Detailed errors only in server logs\n- [ ] No stack traces exposed to users\n\n### 9. Blockchain Security (Solana)\n\n#### Wallet Verification\n```typescript\nimport { verify } from ''@solana/web3.js''\n\nasync function verifyWalletOwnership(\n  publicKey: string,\n  signature: string,\n  message: string\n) {\n  try {\n    const isValid = verify(\n      Buffer.from(message),\n      Buffer.from(signature, ''base64''),\n      Buffer.from(publicKey, ''base64'')\n    )\n    return isValid\n  } catch (error) {\n    return false\n  }\n}\n```\n\n#### Transaction Verification\n```typescript\nasync function verifyTransaction(transaction: Transaction) {\n  // Verify recipient\n  if (transaction.to !== expectedRecipient) {\n    throw new Error(''Invalid recipient'')\n  }\n\n  // Verify amount\n  if (transaction.amount > maxAmount) {\n    throw new Error(''Amount exceeds limit'')\n  }\n\n  // Verify user has sufficient balance\n  const balance = await getBalance(transaction.from)\n  if (balance < transaction.amount) {\n    throw new Error(''Insufficient balance'')\n  }\n\n  return true\n}\n```\n\n#### Verification Steps\n- [ ] Wallet signatures verified\n- [ ] Transaction details validated\n- [ ] Balance checks before transactions\n- [ ] No blind transaction signing\n\n### 10. Dependency Security\n\n#### Regular Updates\n```bash\n# Check for vulnerabilities\nnpm audit\n\n# Fix automatically fixable issues\nnpm audit fix\n\n# Update dependencies\nnpm update\n\n# Check for outdated packages\nnpm outdated\n```\n\n#### Lock Files\n```bash\n# ALWAYS commit lock files\ngit add package-lock.json\n\n# Use in CI/CD for reproducible builds\nnpm ci  # Instead of npm install\n```\n\n#### Verification Steps\n- [ ] Dependencies up to date\n- [ ] No known vulnerabilities (npm audit clean)\n- [ ] Lock files committed\n- [ ] Dependabot enabled on GitHub\n- [ ] Regular security updates\n\n## Security Testing\n\n### Automated Security Tests\n```typescript\n// Test authentication\ntest(''requires authentication'', async () => {\n  const response = await fetch(''/api/protected'')\n  expect(response.status).toBe(401)\n})\n\n// Test authorization\ntest(''requires admin role'', async () => {\n  const response = await fetch(''/api/admin'', {\n    headers: { Authorization: `Bearer ${userToken}` }\n  })\n  expect(response.status).toBe(403)\n})\n\n// Test input validation\ntest(''rejects invalid input'', async () => {\n  const response = await fetch(''/api/users'', {\n    method: ''POST'',\n    body: JSON.stringify({ email: ''not-an-email'' })\n  })\n  expect(response.status).toBe(400)\n})\n\n// Test rate limiting\ntest(''enforces rate limits'', async () => {\n  const requests = Array(101).fill(null).map(() =>\n    fetch(''/api/endpoint'')\n  )\n\n  const responses = await Promise.all(requests)\n  const tooManyRequests = responses.filter(r => r.status === 429)\n\n  expect(tooManyRequests.length).toBeGreaterThan(0)\n})\n```\n\n## Pre-Deployment Security Checklist\n\nBefore ANY production deployment:\n\n- [ ] **Secrets**: No hardcoded secrets, all in env vars\n- [ ] **Input Validation**: All user inputs validated\n- [ ] **SQL Injection**: All queries parameterized\n- [ ] **XSS**: User content sanitized\n- [ ] **CSRF**: Protection enabled\n- [ ] **Authentication**: Proper token handling\n- [ ] **Authorization**: Role checks in place\n- [ ] **Rate Limiting**: Enabled on all endpoints\n- [ ] **HTTPS**: Enforced in production\n- [ ] **Security Headers**: CSP, X-Frame-Options configured\n- [ ] **Error Handling**: No sensitive data in errors\n- [ ] **Logging**: No sensitive data logged\n- [ ] **Dependencies**: Up to date, no vulnerabilities\n- [ ] **Row Level Security**: Enabled in Supabase\n- [ ] **CORS**: Properly configured\n- [ ] **File Uploads**: Validated (size, type)\n- [ ] **Wallet Signatures**: Verified (if blockchain)\n\n## Resources\n\n- [OWASP Top 10](https://owasp.org/www-project-top-ten/)\n- [Next.js Security](https://nextjs.org/docs/security)\n- [Supabase Security](https://supabase.com/docs/guides/auth)\n- [Web Security Academy](https://portswigger.net/web-security)\n\n---\n\n**Remember**: Security is not optional. One vulnerability can compromise the entire platform. When in doubt, err on the side of caution.\n"},"category":"official","lastSynced":"2026-03-06T04:32:21.210Z","seo":{"title":{"en":"security-review: Comprehensive Security Checklist for AI ...","zh":"security-review AI代理设置指南：代码安全检查清单","ja":"security-review AIエージェントのセキュリティチェック実践ガイド","ko":"security-review AI 에이전트 설정 가이드: 보안 취약점 점검","es":"Revisión de Seguridad para APIs y Autenticación - Guía de...","fr":"Revue de Sécurité pour API et Authentification - Guide de...","de":"Sicherheitsüberprüfung für APIs und Authentifizierung - I...","pt":"security-review: Guia de Melhores Práticas de Segurança p...","ru":"security-review: Лучшие практики безопасности для ИИ Агентов","ar":"security-review: دليل أفضل ممارسات الأمان لأدوات الذكاء ا..."},"description":{"en":"Integrate security best practices directly into your Claude workflow. This AI agent skill provides a detailed security checklist for authentication, API endp...","zh":"专为开发者设计的AI代理安全审查技能，提供身份验证、API端点、密钥管理和支付功能的安全检查清单。集成Claude Code和MCP工具提升代码安全性。","ja":"認証実装、APIエンドポイント、シークレット管理のための包括的なセキュリティチェックリストを提供するAIエージェントスキル。Claude Codeと連携した開発者向けツール。","ko":"인증 구현, API 엔드포인트, 비밀 관리 보안 체크리스트를 제공하는 AI 에이전트 스킬. Claude Code와 MCP 도구 통합으로 코드 보안성 강화.","es":"Skill de revisión de seguridad para implementar autenticación, manejar datos sensibles y crear endpoints API. Checklist completo de mejores prácticas de segu...","fr":"Compétence de revue de sécurité pour implémenter l''authentification, gérer les données sensibles et créer des endpoints API. Checklist complet des meilleures...","de":"Sicherheitsüberprüfungs-Skill für die Implementierung von Authentifizierung, den Umgang mit sensiblen Daten und die Erstellung von API-Endpoints. Vollständig...","pt":"Skill de AI Agent para revisão de segurança em código. Verifica autenticação, gerenciamento de secrets, endpoints API e tratamento de input do usuário. Check...","ru":"Навык ИИ Агента для проверки безопасности кода. Проверяет аутентификацию, управление секретами, API эндпоинты и обработку пользовательского ввода. Полный чек...","ar":"مهارة أداة الذكاء الاصطناعي لمراجعة أمان الكود. تتحقق من المصادقة وإدارة الأسرار ونقاط نهاية API ومعالجة مدخلات المستخدم. قائمة مراجعة شاملة للمطورين."},"definition":{"en":"security-review is an AI agent skill for Claude that provides a comprehensive security checklist and patterns for developers implementing authentication, handling user input, working with secrets, or creating API endpoints to identify potential vulnerabilities.","zh":"security-review是一款面向开发者的AI代理技能，在处理认证授权、用户输入、API端点和支付功能时提供系统化的安全检查清单和漏洞识别模式，确保代码符合安全最佳实践。","ja":"security-reviewは、認証・認可の実装、ユーザー入力処理、APIエンドポイント作成時にシステマティックなセキュリティチェックリストを提供するAIエージェントスキルです。具体的な脆弱性識別パターンでコーディングの安全性を確保。","ko":"security-review는 인증·권한 부여 구현, 사용자 입력 처리, API 엔드포인트 생성 시 시스템화된 보안 체크리스트를 제공하는 AI 에이전트 스킬입니다. 구체적인 취약점 식별 패턴으로 코딩 보안성 확보.","es":"Skill de revisión de seguridad que analiza código para identificar vulnerabilidades en autenticación, manejo de secrets y endpoints API. Proporciona checklist de mejores prácticas y patrones de seguridad para desarrollo seguro.","fr":"Compétence de revue de sécurité qui analyse le code pour identifier les vulnérabilités dans l''authentification, la gestion des secrets et les endpoints API. Fournit une checklist de meilleures pratiques et des patterns de sécurité pour le développement sécurisé.","de":"Sicherheitsüberprüfungs-Skill, der Code analysiert, um Schwachstellen in der Authentifizierung, im Secrets-Management und in API-Endpoints zu identifizieren. Bietet eine Checkliste der Best Practices und Sicherheitsmuster für die sichere Entwicklung.","pt":"security-review é uma skill de AI Agent que fornece checklist completo de segurança para desenvolvimento. Ativa-se durante implementação de autenticação, manipulação de secrets, criação de API endpoints e tratamento de input do usuário para identificar vulnerabilidades.","ru":"security-review - это навык ИИ Агента, предоставляющий полный чеклист безопасности для разработки. Активируется при реализации аутентификации, работе с секретами, создании API эндпоинтов и обработке пользовательского ввода для выявления уязвимостей.","ar":"security-review هي مهارة لأداة الذكاء الاصطناعي توفر قائمة مراجعة شاملة للأمان للتطوير. يتم تنشيطها أثناء تنفيذ المصادقة والتعامل مع الأسرار وإنشاء نقاط نهاية API ومعالجة مدخلات المستخدم لتحديد الثغرات الأمنية."},"features":{"en":["Provides security checklist for implementing authentication and authorization","Identifies vulnerabilities when handling user input or file uploads","Reviews security best practices for creating new API endpoints","Offers guidance on proper secrets and credentials management","Checks security implementation for payment features and sensitive data","Validates security practices for third-party API integrations"],"zh":["身份验证与授权实现的安全检查","用户输入和文件上传处理指南","API端点创建的安全最佳实践","密钥和凭证管理规范（含TypeScript示例）","支付功能与敏感数据传输保护","第三方API集成的安全模式"],"ja":["認証・認可実装のセキュリティチェック","ユーザー入力とファイルアップロード処理のガイドライン","APIエンドポイント作成の安全なベストプラクティス","シークレット管理規範（TypeScript例付き）","決済機能と機密データ転送の保護","サードパーティAPI連携のセキュリティパターン"],"ko":["인증·권한 부여 구현 보안 점검","사용자 입력 및 파일 업로드 처리 가이드라인","API 엔드포인트 생성 보안 베스트 프랙티스","비밀 키 관리 규범 (TypeScript 예제 포함)","결제 기능 및 민감 데이터 전송 보호","제3자 API 연동 보안 패턴"],"es":["Checklist completa de seguridad para desarrollo de APIs","Validación de manejo de secrets y credentials","Revisión de endpoints para vulnerabilidades comunes","Patrones de autenticación y autorización seguros","Protección contra inyección y XSS","Integración segura con APIs de terceros"],"fr":["Checklist complète de sécurité pour le développement d''APIs","Validation de la gestion des secrets et credentials","Revue des endpoints pour vulnérabilités courantes","Patterns d''authentification et d''autorisation sécurisés","Protection contre l''injection et XSS","Intégration sécurisée avec APIs tierces"],"de":["Vollständige Sicherheits-Checkliste für die API-Entwicklung","Validierung des Secrets- und Credential-Managements","Überprüfung von Endpoints auf häufige Schwachstellen","Sichere Authentifizierungs- und Autorisierungsmuster","Schutz gegen Injection und XSS","Sichere Integration mit Drittanbieter-APIs"],"pt":["Checklist completo para gerenciamento de secrets e credenciais","Validação de implementação de autenticação e autorização","Revisão de tratamento de input do usuário e file uploads","Verificação de segurança em criação de API endpoints","Análise de implementação de features de pagamento","Auditoria de integração com APIs de terceiros"],"ru":["Полный чеклист для управления секретами и учетными данными","Проверка реализации аутентификации и авторизации","Обзор обработки пользовательского ввода и загрузки файлов","Проверка безопасности при создании API эндпоинтов","Анализ реализации платежных функций","Аудит интеграции со сторонними API"],"ar":["قائمة مراجعة شاملة لإدارة الأسرار والبيانات الاعتمادية","التحقق من تنفيذ المصادقة والتفويض","مراجعة معالجة مدخلات المستخدم وتحمل الملفات","فحص الأمان عند إنشاء نقاط نهاية API","تحليل تنفيذ ميزات الدفع","مراجعة التكامل مع واجهات برمجة التطبيقات الخارجية"]},"keywords":{"en":["how to use security-review skill","security-review claude authentication","security-review vs manual code review","security-review secrets management","security-review API endpoint security","install security-review mcp","what is security-review ai agent","security-review alternative","security-review setup guide","security-review for payment features"],"zh":["AI代理安全审查","Claude Code安全检查","TypeScript密钥管理","API端点安全最佳实践","支付功能安全实现","MCP开发者工具","用户输入验证模式","第三方API安全集成"],"ja":["AIエージェントセキュリティレビュー","Claude Codeセキュリティチェック","TypeScriptシークレット管理","APIエンドポイント安全実装","決済機能セキュリティ","MCP開発者ツール","ユーザー入力検証パターン","サードパーティAPI安全連携"],"ko":["AI 에이전트 보안 리뷰","Claude Code 보안 점검","TypeScript 비밀 키 관리","API 엔드포인트 보안 구현","결제 기능 보안","MCP 개발자 도구","사용자 입력 검증 패턴","제3자 API 안전 연동"],"es":["revisión seguridad APIs","autenticación segura JavaScript","manejo secrets TypeScript","endpoints API seguros","checklist seguridad desarrollo","vulnerabilidades OWASP","protección datos sensibles","validación input seguridad"],"fr":["revue sécurité APIs","authentification sécurisée JavaScript","gestion secrets TypeScript","endpoints API sécurisés","checklist sécurité développement","vulnérabilités OWASP","protection données sensibles","validation input sécurité"],"de":["Sicherheitsüberprüfung APIs","sichere Authentifizierung JavaScript","Secrets-Management TypeScript","sichere API-Endpoints","Sicherheits-Checkliste Entwicklung","OWASP-Schwachstellen","Schutz sensibler Daten","Sicherheits-Input-Validierung"],"pt":["security-review AI Agent","checklist segurança desenvolvimento","melhores práticas autenticação","gerenciamento secrets TypeScript","segurança API endpoints","revisão código vulnerabilidades","AI Agent segurança aplicações","tratamento input usuário seguro"],"ru":["security-review ИИ Агент","чеклист безопасности разработки","лучшие практики аутентификации","управление секретами TypeScript","безопасность API эндпоинтов","проверка кода уязвимости","ИИ Агент безопасность приложений","обработка пользовательского ввода безопасная"],"ar":["security-review أداة الذكاء الاصطناعي","قائمة مراجعة أمان التطوير","أفضل ممارسات المصادقة","إدارة الأسرار TypeScript","أمان نقاط نهاية API","مراجعة كود الثغرات الأمنية","أداة الذكاء الاصطناعي أمان التطبيقات","معالجة مدخلات المستخدم الآمنة"]}},"agentAnalysis":{"suitability":{"en":"Essential for Security-Focused Agents tasked with code auditing and vulnerability prevention.","zh":"对于专注于安全并负责代码审计和漏洞预防的Agent而言，这是必不可少的技能。","ja":"コード監査と脆弱性防止を任務とするセキュリティ重視のエージェントにとって必須です。","ko":"코드 감사 및 취약점 방지를 담당하는 보안 중심 에이전트에게 필수적인 기술입니다.","es":"Esencial para agentes centrados en la seguridad encargados de la auditoría de código y la prevención de vulnerabilidades.","fr":"Essentiel pour les agents axés sur la sécurité chargés de l''audit de code et de la prévention des vulnérabilités.","de":"Essenziell für sicherheitsfokussierte Agents, die mit Code-Audits und der Verhinderung von Sicherheitslücken betraut sind.","pt":"Essencial para Agentes com foco em Segurança encarregados de auditoria de código e prevenção de vulnerabilidades.","ru":"Необходим для Агентов, ориентированных на безопасность, которые занимаются аудитом кода и предотвращением уязвимостей.","ar":"أساسي لوكلاء الأمان المكلفين بمراجعة التعليمات البرمجية ومنع الثغرات الأمنية."},"recommendation":{"en":"Empowers agents to conduct comprehensive security audits by providing checklists for secrets management, authentication, and API endpoint security. It identifies critical vulnerabilities like hardcoded credentials and improper input sanitization, ensuring compliance with security best practices.","zh":"通过提供密钥管理、身份验证和API端点安全检查清单，使Agent能够执行全面的安全审计。它能识别硬编码凭据和不正确的输入清理等关键漏洞，确保符合安全最佳实践。","ja":"シークレット管理、認証、APIエンドポイントのセキュリティに関するチェックリストを提供することで、エージェントが包括的なセキュリティ監査を実施できるようにします。ハードコードされた認証情報や不適切な入力サニタイズといった重大な脆弱性を特定し、セキュリティのベストプラクティスへの準拠を保証します。","ko":"비밀 관리, 인증 및 API 엔드포인트 보안을 위한 체크리스트를 제공하여 에이전트가 포괄적인 보안 감사를 수행할 수 있도록 합니다. 하드코딩된 자격 증명과 부적절한 입력 삭제와 같은 중요한 취약점을 식별하여 보안 모범 사례를 준수하도록 보장합니다.","es":"Permite a los agentes realizar auditorías de seguridad exhaustivas al proporcionar listas de verificación para la gestión de secrets, la autenticación y la seguridad de los endpoints de la API. Identifica vulnerabilidades críticas como las credenciales embebidas y la sanitización incorrecta de las entradas, garantizando el cumplimiento de las mejores prácticas de seguridad.","fr":"Permet aux agents de réaliser des audits de sécurité complets en fournissant des listes de contrôle pour la gestion des secrets, l''authentification et la sécurité des points de terminaison d''API. Il identifie les vulnérabilités critiques telles que les informations d''identification en dur et l''assainissement incorrect des entrées, garantissant ainsi la conformité aux meilleures pratiques de sécurité.","de":"Ermächtigt Agents, umfassende Sicherheitsaudits durchzuführen, indem Checklisten für Secrets-Management, Authentifizierung und die Sicherheit von API-Endpoints bereitgestellt werden. Er identifiziert kritische Schwachstellen wie hardcodierte Anmeldeinformationen und unsachgemäße Eingabebereinigung und stellt so die Einhaltung von Sicherheitsbest practices sicher.","pt":"Capacita os agentes a realizar auditorias de segurança abrangentes, fornecendo listas de verificação para gerenciamento de segredos, autenticação e segurança de endpoints de API. Identifica vulnerabilidades críticas, como credenciais embutidas no código e sanitização inadequada de entrada, garantindo conformidade com as melhores práticas de segurança.","ru":"Позволяет агентам проводить комплексные аудиты безопасности, предоставляя контрольные списки для управления секретами, аутентификации и безопасности конечных точек API. Выявляет критические уязвимости, такие как жестко заданные учетные данные и неправильная санация входных данных, обеспечивая соответствие лучшим практикам безопасности.","ar":"يمكن الوكلاء من إجراء عمليات تدقيق أمني شاملة من خلال توفير قوائم مراجعة لإدارة الأسرار والمصادقة وأمان نقاط نهاية API. يحدد الثغرات الأمنية الحرجة مثل بيانات الاعتماد المضمنة والمعالجة غير السليمة للمدخلات، مما يضمن الامتثال لأفضل الممارسات الأمنية."},"useCases":{"en":["Auditing authentication implementations","Validating user input handling","Reviewing API endpoint security","Checking secrets management practices","Assessing payment feature integrations"],"zh":["审计身份验证实现","验证用户输入处理","审查API端点安全性","检查密钥管理实践","评估支付功能集成"],"ja":["認証実装の監査","ユーザー入力処理の検証","APIエンドポイントのセキュリティレビュー","シークレット管理プラクティスのチェック","決済機能統合の評価"],"ko":["인증 구현 감사","사용자 입력 처리 검증","API 엔드포인트 보안 검토","비밀 관리 관행 확인","결제 기능 통합 평가"],"es":["Auditoría de implementaciones de autenticación","Validación del manejo de entradas de usuario","Revisión de la seguridad de los endpoints de la API","Verificación de las prácticas de gestión de secrets","Evaluación de integraciones de funciones de pago"],"fr":["Audit des implémentations d''authentification","Validation de la gestion des entrées utilisateur","Examen de la sécurité des points de terminaison d''API","Vérification des pratiques de gestion des secrets","Évaluation des intégrations de fonctionnalités de paiement"],"de":["Audit von Authentifizierungsimplementierungen","Validierung der Behandlung von Benutzereingaben","Überprüfung der Sicherheit von API-Endpoints","Überprüfung der Practices im Secrets-Management","Bewertung von Integrationen von Zahlungsfunktionen"],"pt":["Auditoria de implementações de autenticação","Validação do tratamento de entrada do usuário","Revisão da segurança de endpoints de API","Verificação de práticas de gerenciamento de segredos","Avaliação de integrações de recursos de pagamento"],"ru":["Аудит реализаций аутентификации","Проверка обработки пользовательского ввода","Обзор безопасности конечных точек API","Проверка практик управления секретами","Оценка интеграций платежных функций"],"ar":["مراجعة تنفيذات المصادقة","التحقق من معالجة مدخلات المستخدم","مراجعة أمان نقاط نهاية API","فحص ممارسات إدارة الأسرار","تقييم تكاملات ميزات الدفع"]},"limitations":{"en":["Requires access to codebase for analysis","Focuses on common patterns rather than exhaustive testing","May need complementary tools for runtime analysis"],"zh":["需要访问代码库以进行分析","侧重于常见模式而非详尽测试","可能需借助辅助工具进行运行时分析"],"ja":["分析にはコードベースへのアクセスが必要","網羅的なテストではなく一般的なパターンに焦点を当てる","ランタイム分析には補完的なツールが必要な場合がある"],"ko":["분석을 위해 코드베이스에 대한 액세스 필요","철저한 테스트보다는 일반적인 패턴에 중점을 둠","런타임 분석을 위해 보완 도구가 필요할 수 있음"],"es":["Requiere acceso al codebase para su análisis","Se centra en patrones comunes en lugar de realizar pruebas exhaustivas","Puede necesitar herramientas complementarias para el análisis en runtime"],"fr":["Nécessite un accès au codebase pour analyse","Se concentre sur les modèles courants plutôt que sur des tests exhaustifs","Peut nécessiter des outils complémentaires pour l''analyse à l''exécution"],"de":["Erfordert Zugriff auf das Codebase für die Analyse","Konzentriert sich auf gängige Patterns anstelle von exhaustiven Tests","Kann komplementäre Tools für die Runtime-Analyse benötigen"],"pt":["Requer acesso à base de código para análise","Foca em padrões comuns em vez de testes exaustivos","Pode necessitar de ferramentas complementares para análise em tempo de execução"],"ru":["Требует доступа к кодовой базе для анализа","Сосредоточен на общих шаблонах, а не на исчерпывающем тестировании","Может потребовать дополнительных инструментов для анализа во время выполнения"],"ar":["يتطلب الوصول إلى قاعدة التعليمات البرمجية للتحليل","يركز على الأنماط الشائعة بدلاً من الاختبار الشامل","قد يحتاج إلى أدوات تكميلية للتحليل في وقت التشغيل"]},"version":4},"contentHash":"f7530a63c7561bd1036cf4cd4d5939b04ac7a9e919ceefeb4c1a3586eb907d82","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":92}');
