INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/security-review', 'security-review', 'affaan-m', 'everything-claude-code', 'official', 'security-review affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The security-review skill provides developers with a comprehensive security checklist and patterns when working on authentication, user input, API endpoints, or payment features. It helps identify potential vulnerabilities and ensures code follows security best practices. security-review是一款AI代理技能，专为处理用户输入、实现支付功能和集成第三方API时提供全面的安全模式检查。通过具体的TypeScript示例展示密钥管理的最佳实践。 security-reviewは、ユーザー入力の処理や決済機能の実装時に包括的なセキュリティパターンを提供するAIエージェントスキルです。Claude Code連携で具体的なTypeScript例を用いたチェックを実現。 security-review는 사용자 입력 처리, 결제 기능 구현 시 포괄적인 보안 패턴을 제공하는 AI 에이전트 스킬입니다. Claude Code 연동으로 TypeScript 예제를 통한 구체적인 점검 가능. Esta skill proporciona revisiones de seguridad exhaustivas para desarrollo de APIs, manejo de autenticación y implementación de endpoints seguros. Incluye checklist de mejores prácticas para gestión de secrets, validación de input y protección contra vulnerabilidades comunes. Cette compétence offre des revues de sécurité complètes pour le développement d''APIs, la gestion de l''authentification et l''implémentation d''endpoints sécurisés. Comprend une checklist de meilleures pratiques pour la gestion des secrets, la validation des inputs et la protection contre les vulnér... Dieser Skill bietet umfassende Sicherheitsüberprüfungen für die API-Entwicklung, die Handhabung von Authentifizierung und die Implementierung sicherer Endpoints. Enthält eine Checkliste der Best Practices für das Secrets-Management, die Input-Validierung und den Schutz gegen häufige Schwachstellen. Skill security-review para AI Agents que fornece checklist abrangente de segurança para desenvolvimento. Cobre autenticação, gerenciamento de secrets, criação de API endpoints e tratamento de input do usuário seguindo melhores práticas. Навык security-review для ИИ Агентов, предоставляющий комплексный чеклист безопасности для разработки. Охватывает аутентификацию, управление секретами, создание API эндпоинтов и обработку пользовательского ввода по лучшим практикам. مهارة security-review لأدوات الذكاء الاصطناعي التي توفر قائمة مراجعة شاملة للأمان للتطوير. تغطي المصادقة وإدارة الأسرار وإنشاء نقاط نهاية API ومعالجة مدخلات المستخدم وفقًا لأفضل الممارسات. how to use security-review skill security-review claude authentication security-review vs manual code review security-review secrets management security-review API endpoint security install security-review mcp what is security-review ai agent security-review alternative security-review setup guide security-review for payment features AI代理安全审查 Claude Code安全检查 TypeScript密钥管理 API端点安全最佳实践 支付功能安全实现 MCP开发者工具 用户输入验证模式 第三方API安全集成 Provides security checklist for implementing authentication and authorization Identifies vulnerabilities when handling user input or file uploads Reviews security best practices for creating new API endpoints Offers guidance on proper secrets and credentials management Checks security implementation for payment features and sensitive data Validates security practices for third-party API integrations security-review is an AI agent skill for Claude that provides a comprehensive security checklist and patterns for developers implementing authentication, handling user input, working with secrets, or creating API endpoints to identify potential vulnerabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/springboot-verification', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'springboot-verification', 61988, 7678, 92, '2026-03-06T03:39:20Z', '2026-03-06T04:38:07.402Z', '4895b880d86d5703f167f88ca376a55195b40c3b459ec228f5ec8f27bd1a704a', '{"id":"affaan-m/everything-claude-code/springboot-verification","name":"springboot-verification","description":{"en":"The springboot-verification skill automates a comprehensive verification pipeline for Spring Boot projects. It executes a sequence including build, linting, testing with coverage thresholds, and security scans, specifically designed for developers to run before PRs or deployments.","zh":"Spring Boot 验证循环是一个用于确保 Spring Boot 项目代码质量的工具，包括构建、静态分析、测试和安全扫描","ja":"Spring Boot プロジェクトのコード品質を確保するための検証ループは、ビルド、静的分析、テスト、セキュリティスキャンを含みます","ko":"Spring Boot 프로젝트의 코드 품질을 보장하기 위한 검증 루프는 빌드, 정적 분석, 테스트, 보안 스캔을 포함합니다","es":"springboot-verification es un bucle de verificación para proyectos Spring Boot que incluye compilación, análisis estático, pruebas con cobertura y escaneos de seguridad","fr":"springboot-verification est une boucle de vérification pour les projets Spring Boot qui inclut la compilation, l''analyse statique, les tests avec couverture et les scans de sécurité","de":"springboot-verification ist ein Überprüfungszyklus für Spring-Boot-Projekte, der die Kompilierung, die statische Analyse, die Tests mit Abdeckung und die Sicherheitsscans umfasst","pt":"Loop de verificação automatizado para projetos Spring Boot que executa build, análise estática, testes com cobertura, scans de segurança e revisão de diffs antes de PRs ou deploy. Otimiza o fluxo de desenvolvimento com ferramentas de IA Agents.","ru":"Автоматизированный цикл проверки Spring Boot проектов: сборка, статический анализ, тесты с покрытием, security сканы и проверка изменений перед PR или релизом. Интегрируется с ИИ Агентами для разработчиков.","ar":"حلقة تحقق تلقائية لمشاريع Spring Boot تشمل البناء، التحليل الثابت، الاختبارات مع التغطية، فحوصات الأمان ومراجعة الاختلافات قبل الطلبات السحابية أو النشر. تعمل مع أدوات الذكاء الاصطناعي للمطورين."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"springboot-verification","description":"Verification loop for Spring Boot projects: build, static analysis, tests with coverage, security scans, and diff review before release or PR.","bodyPreview":"# Spring Boot Verification Loop\n\nRun before PRs, after major changes, and pre-deploy.\n\n## When to Activate\n\n- Before opening a pull request for a Spring Boot service\n- After major refactoring or dependency upgrades\n- Pre-deployment verification for staging or production\n- Running full build → lint → test → security scan pipeline\n- Validating test coverage meets thresholds\n\n## Phase 1: Build\n\n```bash\nmvn -T 4 clean verify -DskipTests\n# or\n./gradlew clean assemble -x test\n```\n\nIf build fails, stop","body":"# Spring Boot Verification Loop\n\nRun before PRs, after major changes, and pre-deploy.\n\n## When to Activate\n\n- Before opening a pull request for a Spring Boot service\n- After major refactoring or dependency upgrades\n- Pre-deployment verification for staging or production\n- Running full build → lint → test → security scan pipeline\n- Validating test coverage meets thresholds\n\n## Phase 1: Build\n\n```bash\nmvn -T 4 clean verify -DskipTests\n# or\n./gradlew clean assemble -x test\n```\n\nIf build fails, stop and fix.\n\n## Phase 2: Static Analysis\n\nMaven (common plugins):\n```bash\nmvn -T 4 spotbugs:check pmd:check checkstyle:check\n```\n\nGradle (if configured):\n```bash\n./gradlew checkstyleMain pmdMain spotbugsMain\n```\n\n## Phase 3: Tests + Coverage\n\n```bash\nmvn -T 4 test\nmvn jacoco:report   # verify 80%+ coverage\n# or\n./gradlew test jacocoTestReport\n```\n\nReport:\n- Total tests, passed/failed\n- Coverage % (lines/branches)\n\n### Unit Tests\n\nTest service logic in isolation with mocked dependencies:\n\n```java\n@ExtendWith(MockitoExtension.class)\nclass UserServiceTest {\n\n  @Mock private UserRepository userRepository;\n  @InjectMocks private UserService userService;\n\n  @Test\n  void createUser_validInput_returnsUser() {\n    var dto = new CreateUserDto(\"Alice\", \"alice@example.com\");\n    var expected = new User(1L, \"Alice\", \"alice@example.com\");\n    when(userRepository.save(any(User.class))).thenReturn(expected);\n\n    var result = userService.create(dto);\n\n    assertThat(result.name()).isEqualTo(\"Alice\");\n    verify(userRepository).save(any(User.class));\n  }\n\n  @Test\n  void createUser_duplicateEmail_throwsException() {\n    var dto = new CreateUserDto(\"Alice\", \"existing@example.com\");\n    when(userRepository.existsByEmail(dto.email())).thenReturn(true);\n\n    assertThatThrownBy(() -> userService.create(dto))\n        .isInstanceOf(DuplicateEmailException.class);\n  }\n}\n```\n\n### Integration Tests with Testcontainers\n\nTest against a real database instead of H2:\n\n```java\n@SpringBootTest\n@Testcontainers\nclass UserRepositoryIntegrationTest {\n\n  @Container\n  static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>(\"postgres:16-alpine\")\n      .withDatabaseName(\"testdb\");\n\n  @DynamicPropertySource\n  static void configureProperties(DynamicPropertyRegistry registry) {\n    registry.add(\"spring.datasource.url\", postgres::getJdbcUrl);\n    registry.add(\"spring.datasource.username\", postgres::getUsername);\n    registry.add(\"spring.datasource.password\", postgres::getPassword);\n  }\n\n  @Autowired private UserRepository userRepository;\n\n  @Test\n  void findByEmail_existingUser_returnsUser() {\n    userRepository.save(new User(\"Alice\", \"alice@example.com\"));\n\n    var found = userRepository.findByEmail(\"alice@example.com\");\n\n    assertThat(found).isPresent();\n    assertThat(found.get().getName()).isEqualTo(\"Alice\");\n  }\n}\n```\n\n### API Tests with MockMvc\n\nTest controller layer with full Spring context:\n\n```java\n@WebMvcTest(UserController.class)\nclass UserControllerTest {\n\n  @Autowired private MockMvc mockMvc;\n  @MockBean private UserService userService;\n\n  @Test\n  void createUser_validInput_returns201() throws Exception {\n    var user = new UserDto(1L, \"Alice\", \"alice@example.com\");\n    when(userService.create(any())).thenReturn(user);\n\n    mockMvc.perform(post(\"/api/users\")\n            .contentType(MediaType.APPLICATION_JSON)\n            .content(\"\"\"\n                {\"name\": \"Alice\", \"email\": \"alice@example.com\"}\n                \"\"\"))\n        .andExpect(status().isCreated())\n        .andExpect(jsonPath(\"$.name\").value(\"Alice\"));\n  }\n\n  @Test\n  void createUser_invalidEmail_returns400() throws Exception {\n    mockMvc.perform(post(\"/api/users\")\n            .contentType(MediaType.APPLICATION_JSON)\n            .content(\"\"\"\n                {\"name\": \"Alice\", \"email\": \"not-an-email\"}\n                \"\"\"))\n        .andExpect(status().isBadRequest());\n  }\n}\n```\n\n## Phase 4: Security Scan\n\n```bash\n# Dependency CVEs\nmvn org.owasp:dependency-check-maven:check\n# or\n./gradlew dependencyCheckAnalyze\n\n# Secrets in source\ngrep -rn \"password\\s*=\\s*\\\"\" src/ --include=\"*.java\" --include=\"*.yml\" --include=\"*.properties\"\ngrep -rn \"sk-\\|api_key\\|secret\" src/ --include=\"*.java\" --include=\"*.yml\"\n\n# Secrets (git history)\ngit secrets --scan  # if configured\n```\n\n### Common Security Findings\n\n```\n# Check for System.out.println (use logger instead)\ngrep -rn \"System\\.out\\.print\" src/main/ --include=\"*.java\"\n\n# Check for raw exception messages in responses\ngrep -rn \"e\\.getMessage()\" src/main/ --include=\"*.java\"\n\n# Check for wildcard CORS\ngrep -rn \"allowedOrigins.*\\*\" src/main/ --include=\"*.java\"\n```\n\n## Phase 5: Lint/Format (optional gate)\n\n```bash\nmvn spotless:apply   # if using Spotless plugin\n./gradlew spotlessApply\n```\n\n## Phase 6: Diff Review\n\n```bash\ngit diff --stat\ngit diff\n```\n\nChecklist:\n- No debugging logs left (`System.out`, `log.debug` without guards)\n- Meaningful errors and HTTP statuses\n- Transactions and validation present where needed\n- Config changes documented\n\n## Output Template\n\n```\nVERIFICATION REPORT\n===================\nBuild:     [PASS/FAIL]\nStatic:    [PASS/FAIL] (spotbugs/pmd/checkstyle)\nTests:     [PASS/FAIL] (X/Y passed, Z% coverage)\nSecurity:  [PASS/FAIL] (CVE findings: N)\nDiff:      [X files changed]\n\nOverall:   [READY / NOT READY]\n\nIssues to Fix:\n1. ...\n2. ...\n```\n\n## Continuous Mode\n\n- Re-run phases on significant changes or every 30–60 minutes in long sessions\n- Keep a short loop: `mvn -T 4 test` + spotbugs for quick feedback\n\n**Remember**: Fast feedback beats late surprises. Keep the gate strict—treat warnings as defects in production systems.\n"},"category":"official","lastSynced":"2026-03-06T04:38:07.402Z","seo":{"title":{"en":"springboot-verification: Maven & Gradle CI Pipeline Setup...","zh":"Spring Boot 项目验证设置指南","ja":"Spring Boot プロジェクトの検証ループベストプラクティス","ko":"Spring Boot 프로젝트 검증 설정 가이드","es":"Guía de Configuración de springboot-verification para Des...","fr":"Configurer springboot-verification : Meilleures Pratiques...","de":"Einrichtung von springboot-verification: Leitfaden für En...","pt":"Guia de Verificação Spring Boot: Pipeline para PRs e Deploy","ru":"Spring Boot Верификация: Полный цикл проверки перед PR и ...","ar":"دليل التحقق من Spring Boot: خط أنابيب للطلبات السحابية وا..."},"description":{"en":"Automate your Spring Boot CI/CD with this AI Agent skill. Run a full verification loop including Maven/Gradle builds, static analysis, test coverage validati...","zh":"使用 Spring Boot 验证循环来确保代码质量，包括构建、静态分析、测试和安全扫描","ja":"Spring Boot プロジェクトの品質を確保するための検証ループの実装方法","ko":"Spring Boot 프로젝트의 품질을 보장하기 위한 검증 루프 설정 방법","es":"Aprende a configurar springboot-verification para mejorar la calidad de tus proyectos Spring Boot con análisis estático, pruebas y escaneos de seguridad","fr":"Découvrez comment configurer springboot-verification pour améliorer la qualité de vos projets Spring Boot avec analyse statique, tests et scans de sécurité","de":"Erfahren Sie, wie Sie springboot-verification einrichten, um die Qualität Ihrer Spring-Boot-Projekte mit statischer Analyse, Tests und Sicherheitsscans zu ve...","pt":"Automatize a verificação de projetos Spring Boot com pipeline completo: build Maven/Gradle, análise estática, testes com cobertura, scans de segurança e revi...","ru":"Автоматизируйте проверку Spring Boot проектов: сборка Maven/Gradle, статический анализ, тесты с покрытием, security сканы и проверка изменений перед PR или р...","ar":"أتمتة التحقق من مشاريع Spring Boot: بناء Maven/Gradle، التحليل الثابت، الاختبارات مع التغطية، فحوصات الأمان ومراجعة الاختلافات قبل الطلبات السحابية أو النشر."},"definition":{"en":"springboot-verification is an AI Agent skill that runs an automated verification loop for Spring Boot projects. It orchestrates a pipeline including build commands (Maven/Gradle), static analysis, tests with coverage validation, security scans, and a diff review before a release or pull request.","zh":"Spring Boot 验证循环是一种用于验证 Spring Boot 项目代码质量的方法","ja":"Spring Boot プロジェクトのコード品質を検証するための手法","ko":"Spring Boot 프로젝트의 코드 품질을 검증하기 위한 방법","es":"springboot-verification es una herramienta de verificación para proyectos Spring Boot que automatiza el proceso de análisis y prueba","fr":"springboot-verification est un outil de vérification pour les projets Spring Boot qui automatise le processus d''analyse et de test","de":"springboot-verification ist ein Überprüfungstool für Spring-Boot-Projekte, das den Analyse- und Testprozess automatisiert","pt":"Spring Boot Verification Loop é um pipeline automatizado que executa verificação completa em projetos Spring Boot incluindo build com Maven/Gradle, análise estática, testes com cobertura, scans de segurança e revisão de diffs antes de pull requests ou deploy em produção.","ru":"Spring Boot Verification Loop - это автоматизированный pipeline проверки проектов Spring Boot, включающий сборку Maven/Gradle, статический анализ, тесты с покрытием, security сканы и проверку изменений перед pull requests или релизом.","ar":"Spring Boot Verification Loop هو خط أنابيب آلي للتحقق من مشاريع Spring Boot يتضمن البناء باستخدام Maven/Gradle، التحليل الثابت، الاختبارات مع التغطية، فحوصات الأمان ومراجعة الاختلافات قبل الطلبات السحابية أو النشر."},"features":{"en":["Executes Maven build commands (e.g., `mvn -T 4 clean verify -DskipTests`)","Runs Gradle build commands (e.g., `./gradlew clean assemble -x test`)","Performs static analysis and linting on the codebase","Runs tests and validates that coverage meets defined thresholds","Conducts security scans as part of the pipeline","Performs a diff review before final release or PR creation"],"zh":["构建和验证","静态分析和代码检查","测试和代码覆盖率分析","安全扫描和漏洞检测","diff 检查和代码复审"],"ja":["ビルドとバリデーション","静的分析とコードチェック","テストとコードカバレッジ分析","セキュリティスキャンと脆弱性検出","diff チェックとコードレビュー"],"ko":["빌드와 검증","정적 분석과 코드 체크","테스트와 코드 커버리지 분석","보안 스캔과 취약성 검색","diff 체크와 코드 리뷰"],"es":["Compilación y verificación de proyectos Spring Boot","Análisis estático de código","Pruebas con cobertura y validación de umbrales","Escaneos de seguridad y revisión de diferencias","Integración con herramientas de desarrollo como Maven y Gradle"],"fr":["Compilation et vérification de projets Spring Boot","Analyse statique de code","Tests avec couverture et validation de seuils","Scans de sécurité et révision de différences","Intégration avec des outils de développement tels que Maven et Gradle"],"de":["Kompilierung und Überprüfung von Spring-Boot-Projekten","Statische Code-Analyse","Tests mit Abdeckung und Validierung von Schwellenwerten","Sicherheitsscans und Überprüfung von Differenzen","Integration mit Entwicklungstools wie Maven und Gradle"],"pt":["Build otimizado com Maven (-T 4 clean verify) ou Gradle (clean assemble)","Análise estática e linting para qualidade de código","Execução de testes com verificação de cobertura","Scans de segurança automatizados","Revisão de diffs antes de PRs ou deploy","Validação de thresholds de cobertura de testes"],"ru":["Оптимизированная сборка с Maven (-T 4 clean verify) или Gradle (clean assemble)","Статический анализ и линтинг для качества кода","Запуск тестов с проверкой покрытия","Автоматические security сканы","Проверка изменений перед PR или релизом","Валидация порогов покрытия тестов"],"ar":["بناء مُحسّن باستخدام Maven (-T 4 clean verify) أو Gradle (clean assemble)","تحليل ثابت وفحص جودة الكود","تنفيذ الاختبارات مع التحقق من التغطية","فحوصات أمان تلقائية","مراجعة الاختلافات قبل الطلبات السحابية أو النشر","التحقق من حدود تغطية الاختبارات"]},"keywords":{"en":["how to use springboot-verification","what is springboot-verification","springboot-verification maven gradle commands","springboot-verification vs traditional ci","springboot-verification alternative","springboot-verification install guide","springboot-verification setup for ai agents","automate spring boot verification loop","spring boot test coverage validation ai agent"],"zh":["Spring Boot 验证循环","AIエージェント","代码质量保证","构建和验证","静态分析和代码检查","测试和代码覆盖率分析","安全扫描和漏洞检测"],"ja":["Spring Boot プロジェクトの検証ループ","AIエージェント","コード品質の保証","ビルドとバリデーション","静的分析とコードチェック","テストとコードカバレッジ分析","セキュリティスキャンと脆弱性検出"],"ko":["Spring Boot 프로젝트의 검증 루프","AI 에이전트","코드 품질 보장","빌드와 검증","정적 분석과 코드 체크","테스트와 코드 커버리지 분석","보안 스캔과 취약성 검색"],"es":["springboot-verification","herramientas de desarrollo","análisis estático","pruebas con cobertura","escaneos de seguridad","desarrollo de software","Agente de IA para desarrolladores","Herramientas de productividad para desarrolladores"],"fr":["springboot-verification","outils de développement","analyse statique","tests avec couverture","scans de sécurité","développement de logiciels","Agent IA pour les développeurs","Outils de productivité pour les développeurs"],"de":["springboot-verification","Entwicklungstools","statische Analyse","Tests mit Abdeckung","Sicherheitsscans","Software-Entwicklung","KI-Agent für Entwickler","Produktivitätstools für Entwickler"],"pt":["spring boot verification pipeline","maven verify skipTests","gradle assemble test coverage","pr verification spring boot","deploy verification java","test coverage thresholds","static analysis spring boot","ai agents desenvolvimento"],"ru":["spring boot verification pipeline","maven verify skipTests","gradle assemble test coverage","pr проверка spring boot","deploy верификация java","test coverage thresholds","статический анализ spring boot","ИИ Агенты разработки"],"ar":["spring boot verification pipeline","maven verify skipTests","gradle assemble test coverage","تحقق طلب سحابي spring boot","تحقق نشر java","حدود تغطية الاختبارات","تحليل ثابت spring boot","أدوات الذكاء الاصطناعي للمطورين"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Quality and DevOps Agents specializing in Java-based microservice validation pipelines.","zh":"非常适合专注于基于 Java 的微服务验证管道的代码质量和 DevOps 智能体。","ja":"Javaベースのマイクロサービス検証パイプラインを専門とするコード品質およびDevOpsエージェントに最適です。","ko":"Java 기반 마이크로서비스 검증 파이프라인을 전문으로 하는 코드 품질 및 DevOps 에이전트에 이상적입니다.","es":"Ideal para agentes de Calidad de Código y DevOps especializados en pipelines de validación de microservicios basados en Java.","fr":"Idéal pour les agents de Qualité de Code et DevOps spécialisés dans les pipelines de validation de microservices basés sur Java.","de":"Ideal für Code Quality und DevOps Agents, die sich auf Java-basierte Microservice-Validierungspipelines spezialisieren.","pt":"Ideal para Agentes de Qualidade de Código e DevOps especializados em pipelines de validação de microsserviços baseados em Java.","ru":"Идеально подходит для Агентов обеспечения качества кода и DevOps, специализирующихся на конвейерах проверки микросервисов на основе Java.","ar":"مثالي لوكلاء جودة الكود و DevOps المتخصصين في خطوط أنابيب التحقق من الخدمات المصغرة القائمة على Java."},"recommendation":{"en":"Enables automated execution of a comprehensive Spring Boot verification loop, including Maven/Gradle builds, static code analysis, test coverage validation with thresholds, and security scanning. Provides immediate feedback on build failures and code quality metrics before PR submission or deployment.","zh":"支持自动化执行全面的 Spring Boot 验证循环，包括 Maven/Gradle 构建、静态代码分析、带有阈值的测试覆盖率验证以及安全扫描。在 PR 提交或部署之前，提供关于构建失败和代码质量指标的即时反馈。","ja":"Maven/Gradleビルド、静的コード分析、しきい値付きテストカバレッジ検証、セキュリティスキャンを含む包括的なSpring Boot検証ループの自動実行を可能にします。PR提出またはデプロイ前に、ビルド失敗とコード品質メトリクスに関する即時のフィードバックを提供します。","ko":"Maven/Gradle 빌드, 정적 코드 분석, 임계값이 포함된 테스트 커버리지 검증, 보안 스캐닝을 포함한 포괄적인 Spring Boot 검증 루프의 자동화된 실행을 가능하게 합니다. PR 제출 또는 배포 전에 빌드 실패 및 코드 품질 메트릭에 대한 즉각적인 피드백을 제공합니다.","es":"Permite la ejecución automatizada de un ciclo completo de verificación de Spring Boot, incluyendo builds de Maven/Gradle, análisis estático de código, validación de cobertura de pruebas con umbrales y escaneo de seguridad. Proporciona retroalimentación inmediata sobre fallos de build y métricas de calidad de código antes de la entrega de un PR o el despliegue.","fr":"Permet l''exécution automatisée d''une boucle de vérification complète de Spring Boot, incluant les builds Maven/Gradle, l''analyse statique de code, la validation de la couverture de tests avec des seuils et l''analyse de sécurité. Fournit un retour immédiat sur les échecs de build et les métriques de qualité de code avant la soumission d''une PR ou le déploiement.","de":"Ermöglicht die automatisierte Ausführung eines umfassenden Spring Boot-Verifikationsloops, einschließlich Maven/Gradle-Builds, statischer Codeanalyse, Validierung der Testabdeckung mit Schwellenwerten und Security-Scanning. Bietet sofortiges Feedback zu Build-Fehlern und Code-Quality-Metriken vor der PR-Einreichung oder dem Deployment.","pt":"Permite a execução automatizada de um loop abrangente de verificação do Spring Boot, incluindo builds Maven/Gradle, análise estática de código, validação de cobertura de testes com limites e verificação de segurança. Fornece feedback imediato sobre falhas de build e métricas de qualidade de código antes do envio do PR ou da implantação.","ru":"Обеспечивает автоматизированное выполнение комплексного цикла проверки Spring Boot, включая сборки Maven/Gradle, статический анализ кода, проверку покрытия тестов с пороговыми значениями и сканирование безопасности. Предоставляет немедленную обратную связь о сбоях сборки и метриках качества кода до отправки пул-реквеста или развертывания.","ar":"يتيح التنفيذ الآتي لدورة التحقق الشاملة من Spring Boot، بما في ذلك بناء Maven/Gradle، وتحليل الكود الثابت، والتحقق من تغطية الاختبارات مع العتبات، والفحص الأمني. يوفر ملاحظات فورية حول فشل البناء ومقاييس جودة الكود قبل تقديم طلب السحب (PR) أو النشر."},"useCases":{"en":["Automating pre-PR validation for Spring Boot services","Running security scans after dependency upgrades","Validating test coverage thresholds pre-deployment","Executing static analysis during major refactoring"],"zh":["自动化 Spring Boot 服务的 PR 前验证","依赖项升级后运行安全扫描","部署前验证测试覆盖率阈值","在重大重构期间执行静态分析"],"ja":["Spring BootサービスのPR前検証の自動化","依存関係アップグレード後のセキュリティスキャンの実行","デプロイ前のテストカバレッジしきい値の検証","大規模なリファクタリング中の静的解析の実行"],"ko":["Spring Boot 서비스의 PR 전 검증 자동화","의존성 업그레이드 후 보안 스캔 실행","배포 전 테스트 커버리지 임계값 검증","주요 리팩토링 중 정적 분석 실행"],"es":["Automatización de la validación pre-PR para servicios de Spring Boot","Ejecución de escaneos de seguridad después de actualizaciones de dependencias","Validación de umbrales de cobertura de pruebas pre-despliegue","Ejecución de análisis estático durante una refactorización mayor"],"fr":["Automatisation de la validation pré-PR pour les services Spring Boot","Exécution d''analyses de sécurité après des mises à niveau de dépendances","Validation des seuils de couverture de tests pré-déploiement","Exécution d''analyse statique lors d''une refactorisation majeure"],"de":["Automatisierung der Pre-PR-Validierung für Spring Boot-Services","Durchführung von Security-Scans nach Dependency-Upgrades","Validierung von Testabdeckungsschwellenwerten vor dem Deployment","Durchführung von Static Analysis während größerer Refactorings"],"pt":["Automatização da validação pré-PR para serviços Spring Boot","Execução de verificações de segurança após atualizações de dependências","Validação de limites de cobertura de testes pré-implantação","Execução de análise estática durante grandes refatorações"],"ru":["Автоматизация предварительной проверки перед пул-реквестом для сервисов Spring Boot","Запуск проверок безопасности после обновлений зависимостей","Проверка пороговых значений покрытия тестов перед развертыванием","Выполнение статического анализа во время крупного рефакторинга"],"ar":["أتمتة التحقق قبل طلب السحب (PR) لخدمات Spring Boot","تشغيل فحوصات الأمان بعد ترقية التبعيات","التحقق من عتبات تغطية الاختبارات قبل النشر","تنفيذ التحليل الثابت خلال إعادة الهيكلة الكبرى"]},"limitations":{"en":["Spring Boot projects only","Requires Maven or Gradle build system","Dependent on project-specific test coverage thresholds","Build failure stops entire pipeline execution"],"zh":["仅限 Spring Boot 项目","需要 Maven 或 Gradle 构建系统","依赖于项目特定的测试覆盖率阈值","构建失败会停止整个管道的执行"],"ja":["Spring Bootプロジェクトのみ","MavenまたはGradleビルドシステムが必要","プロジェクト固有のテストカバレッジしきい値に依存","ビルド失敗はパイプライン全体の実行を停止します"],"ko":["Spring Boot 프로젝트만 해당","Maven 또는 Gradle 빌드 시스템 필요","프로젝트별 테스트 커버리지 임계값에 종속적","빌드 실패 시 전체 파이프라인 실행 중단"],"es":["Solo proyectos Spring Boot","Requiere un sistema de build Maven o Gradle","Dependiente de los umbrales de cobertura de pruebas específicos del proyecto","Un fallo de build detiene la ejecución completa de la pipeline"],"fr":["Projets Spring Boot uniquement","Nécessite un système de build Maven ou Gradle","Dépend des seuils de couverture de tests spécifiques au projet","Un échec de build arrête l''exécution complète de la pipeline"],"de":["Nur Spring Boot-Projekte","Erfordert ein Maven- oder Gradle-Buildsystem","Abhängig von projektspezifischen Testabdeckungsschwellenwerten","Build-Fehler stoppt die gesamte Pipeline-Ausführung"],"pt":["Apenas projetos Spring Boot","Requer sistema de build Maven ou Gradle","Dependente de limites de cobertura de testes específicos do projeto","Falha na build interrompe toda a execução do pipeline"],"ru":["Только проекты Spring Boot","Требуется система сборки Maven или Gradle","Зависит от специфичных для проекта пороговых значений покрытия тестов","Сбой сборки останавливает выполнение всего конвейера"],"ar":["مشاريع Spring Boot فقط","يتطلب نظام بناء Maven أو Gradle","يعتمد على عتبات تغطية اختبار محددة للمشروع","فشل البناء يوقف تنفيذ خط الأنابيب بالكامل"]},"version":4},"contentHash":"4895b880d86d5703f167f88ca376a55195b40c3b459ec228f5ec8f27bd1a704a","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":92}');
