INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/springboot-verification', 'springboot-verification', 'affaan-m', 'everything-claude-code', 'official', 'springboot-verification affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The springboot-verification skill automates a comprehensive verification pipeline for Spring Boot projects. It executes a sequence including build, linting, testing with coverage thresholds, and security scans, specifically designed for developers to run before PRs or deployments. Spring Boot 验证循环是一个用于确保 Spring Boot 项目代码质量的工具，包括构建、静态分析、测试和安全扫描 Spring Boot プロジェクトのコード品質を確保するための検証ループは、ビルド、静的分析、テスト、セキュリティスキャンを含みます Spring Boot 프로젝트의 코드 품질을 보장하기 위한 검증 루프는 빌드, 정적 분석, 테스트, 보안 스캔을 포함합니다 springboot-verification es un bucle de verificación para proyectos Spring Boot que incluye compilación, análisis estático, pruebas con cobertura y escaneos de seguridad springboot-verification est une boucle de vérification pour les projets Spring Boot qui inclut la compilation, l''analyse statique, les tests avec couverture et les scans de sécurité springboot-verification ist ein Überprüfungszyklus für Spring-Boot-Projekte, der die Kompilierung, die statische Analyse, die Tests mit Abdeckung und die Sicherheitsscans umfasst Loop de verificação automatizado para projetos Spring Boot que executa build, análise estática, testes com cobertura, scans de segurança e revisão de diffs antes de PRs ou deploy. Otimiza o fluxo de desenvolvimento com ferramentas de IA Agents. Автоматизированный цикл проверки Spring Boot проектов: сборка, статический анализ, тесты с покрытием, security сканы и проверка изменений перед PR или релизом. Интегрируется с ИИ Агентами для разработчиков. حلقة تحقق تلقائية لمشاريع Spring Boot تشمل البناء، التحليل الثابت، الاختبارات مع التغطية، فحوصات الأمان ومراجعة الاختلافات قبل الطلبات السحابية أو النشر. تعمل مع أدوات الذكاء الاصطناعي للمطورين. how to use springboot-verification what is springboot-verification springboot-verification maven gradle commands springboot-verification vs traditional ci springboot-verification alternative springboot-verification install guide springboot-verification setup for ai agents automate spring boot verification loop spring boot test coverage validation ai agent Spring Boot 验证循环 AIエージェント 代码质量保证 构建和验证 静态分析和代码检查 测试和代码覆盖率分析 安全扫描和漏洞检测 Executes Maven build commands (e.g., `mvn -T 4 clean verify -DskipTests`) Runs Gradle build commands (e.g., `./gradlew clean assemble -x test`) Performs static analysis and linting on the codebase Runs tests and validates that coverage meets defined thresholds Conducts security scans as part of the pipeline Performs a diff review before final release or PR creation springboot-verification is an AI Agent skill that runs an automated verification loop for Spring Boot projects. It orchestrates a pipeline including build commands (Maven/Gradle), static analysis, tests with coverage validation, security scans, and a diff review before a release or pull request.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/django-perf-review', 'official', 'getsentry', 'skills', 'getsentry/skills', 'django-perf-review', 360, 11, 92, '2026-03-06T00:20:36Z', '2026-03-06T05:05:58.318Z', 'd45298cb3c2b06777a28a2cadbcbb4eacc1e987ade230f4f94947ad927c92033', '{"id":"getsentry/skills/django-perf-review","name":"django-perf-review","description":{"en":"The django-perf-review skill reviews Django code for validated performance issues, optimizing database performance and ORM issues for developers.","zh":"django-perf-review是一种Django性能代码审查工具，用于找到N+1查询、优化Django ORM和数据库性能","ja":"django-perf-reviewは、Django パフォーマンス コード レビュー ツールで、N+1 クエリの検出、Django ORM とデータベースのパフォーマンス最適化に使用されます","ko":"django-perf-review는 Django 성능 코드 검토 도구로 N+1 쿼리를 찾고 Django ORM 및 데이터베이스 성능을 최적화하는 데 사용됩니다","es":"django-perf-review es una herramienta para revisar y optimizar el rendimiento de Django, detectando problemas como consultas N+1 y optimizando el ORM","fr":"django-perf-review est un outil pour examiner et optimiser les performances de Django, en détectant des problèmes tels que les requêtes N+1 et en optimisant l''ORM","de":"django-perf-review ist ein Tool zur Überprüfung und Optimierung der Leistung von Django, mit dem Probleme wie N+1-Abfragen und ORM-Optimierung erkannt werden","pt":"O django-perf-review é uma ferramenta para revisar e otimizar o desempenho de projetos Django, identificando problemas como consultas N+1 e issues de ORM.","ru":"django-perf-review - это инструмент для проверки и оптимизации производительности проектов Django, выявления проблем, таких как запросы N+1 и проблемы ORM.","ar":"أداة django-perf-review هي أداة لمراجعة وتحسين أداء مشاريع Django، وتحديد مشاكل مثل استفسارات N+1 ومشاكل ORM."},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"django-perf-review","description":"Django performance code review. Use when asked to review Django performance, find N+1 queries, optimize Django, check queryset performance, database performance, Django ORM issues, or audit Django code for performance problems.","bodyPreview":"# Django Performance Review\n\nReview Django code for **validated** performance issues. Research the codebase to confirm issues before reporting. Report only what you can prove.\n\n## Review Approach\n\n1. **Research first** - Trace data flow, check for existing optimizations, verify data volume\n2. **Validate before reporting** - Pattern matching is not validation\n3. **Zero findings is acceptable** - Don''t manufacture issues to appear thorough\n4. **Severity must match impact** - If you catch yourself","body":"# Django Performance Review\n\nReview Django code for **validated** performance issues. Research the codebase to confirm issues before reporting. Report only what you can prove.\n\n## Review Approach\n\n1. **Research first** - Trace data flow, check for existing optimizations, verify data volume\n2. **Validate before reporting** - Pattern matching is not validation\n3. **Zero findings is acceptable** - Don''t manufacture issues to appear thorough\n4. **Severity must match impact** - If you catch yourself writing \"minor\" in a CRITICAL finding, it''s not critical. Downgrade or skip it.\n\n## Impact Categories\n\nIssues are organized by impact. Focus on CRITICAL and HIGH - these cause real problems at scale.\n\n| Priority | Category | Impact |\n|----------|----------|--------|\n| 1 | N+1 Queries | **CRITICAL** - Multiplies with data, causes timeouts |\n| 2 | Unbounded Querysets | **CRITICAL** - Memory exhaustion, OOM kills |\n| 3 | Missing Indexes | **HIGH** - Full table scans on large tables |\n| 4 | Write Loops | **HIGH** - Lock contention, slow requests |\n| 5 | Inefficient Patterns | **LOW** - Rarely worth reporting |\n\n---\n\n## Priority 1: N+1 Queries (CRITICAL)\n\n**Impact:** Each N+1 adds `O(n)` database round trips. 100 rows = 100 extra queries. 10,000 rows = timeout.\n\n### Rule: Prefetch related data accessed in loops\n\nValidate by tracing: View → Queryset → Template/Serializer → Loop access\n\n```python\n# PROBLEM: N+1 - each iteration queries profile\ndef user_list(request):\n    users = User.objects.all()\n    return render(request, ''users.html'', {''users'': users})\n\n# Template:\n# {% for user in users %}\n#     {{ user.profile.bio }}  ← triggers query per user\n# {% endfor %}\n\n# SOLUTION: Prefetch in view\ndef user_list(request):\n    users = User.objects.select_related(''profile'')\n    return render(request, ''users.html'', {''users'': users})\n```\n\n### Rule: Prefetch in serializers, not just views\n\nDRF serializers accessing related fields cause N+1 if queryset isn''t optimized.\n\n```python\n# PROBLEM: SerializerMethodField queries per object\nclass UserSerializer(serializers.ModelSerializer):\n    order_count = serializers.SerializerMethodField()\n\n    def get_order_count(self, obj):\n        return obj.orders.count()  # ← query per user\n\n# SOLUTION: Annotate in viewset, access in serializer\nclass UserViewSet(viewsets.ModelViewSet):\n    def get_queryset(self):\n        return User.objects.annotate(order_count=Count(''orders''))\n\nclass UserSerializer(serializers.ModelSerializer):\n    order_count = serializers.IntegerField(read_only=True)\n```\n\n### Rule: Model properties that query are dangerous in loops\n\n```python\n# PROBLEM: Property triggers query when accessed\nclass User(models.Model):\n    @property\n    def recent_orders(self):\n        return self.orders.filter(created__gte=last_week)[:5]\n\n# Used in template loop = N+1\n\n# SOLUTION: Use Prefetch with custom queryset, or annotate\n```\n\n### Validation Checklist for N+1\n- [ ] Traced data flow from view to template/serializer\n- [ ] Confirmed related field is accessed inside a loop\n- [ ] Searched codebase for existing select_related/prefetch_related\n- [ ] Verified table has significant row count (1000+)\n- [ ] Confirmed this is a hot path (not admin, not rare action)\n\n---\n\n## Priority 2: Unbounded Querysets (CRITICAL)\n\n**Impact:** Loading entire tables exhausts memory. Large tables cause OOM kills and worker restarts.\n\n### Rule: Always paginate list endpoints\n\n```python\n# PROBLEM: No pagination - loads all rows\nclass UserListView(ListView):\n    model = User\n    template_name = ''users.html''\n\n# SOLUTION: Add pagination\nclass UserListView(ListView):\n    model = User\n    template_name = ''users.html''\n    paginate_by = 25\n```\n\n### Rule: Use iterator() for large batch processing\n\n```python\n# PROBLEM: Loads all objects into memory at once\nfor user in User.objects.all():\n    process(user)\n\n# SOLUTION: Stream with iterator()\nfor user in User.objects.iterator(chunk_size=1000):\n    process(user)\n```\n\n### Rule: Never call list() on unbounded querysets\n\n```python\n# PROBLEM: Forces full evaluation into memory\nall_users = list(User.objects.all())\n\n# SOLUTION: Keep as queryset, slice if needed\nusers = User.objects.all()[:100]\n```\n\n### Validation Checklist for Unbounded Querysets\n- [ ] Table is large (10k+ rows) or will grow unbounded\n- [ ] No pagination class, paginate_by, or slicing\n- [ ] This runs on user-facing request (not background job with chunking)\n\n---\n\n## Priority 3: Missing Indexes (HIGH)\n\n**Impact:** Full table scans. Negligible on small tables, catastrophic on large ones.\n\n### Rule: Index fields used in WHERE clauses on large tables\n\n```python\n# PROBLEM: Filtering on unindexed field\n# User.objects.filter(email=email)  # full scan if no index\n\nclass User(models.Model):\n    email = models.EmailField()  # ← no db_index\n\n# SOLUTION: Add index\nclass User(models.Model):\n    email = models.EmailField(db_index=True)\n```\n\n### Rule: Index fields used in ORDER BY on large tables\n\n```python\n# PROBLEM: Sorting requires full scan without index\nOrder.objects.order_by(''-created'')\n\n# SOLUTION: Index the sort field\nclass Order(models.Model):\n    created = models.DateTimeField(db_index=True)\n```\n\n### Rule: Use composite indexes for common query patterns\n\n```python\nclass Order(models.Model):\n    user = models.ForeignKey(User)\n    status = models.CharField(max_length=20)\n    created = models.DateTimeField()\n\n    class Meta:\n        indexes = [\n            models.Index(fields=[''user'', ''status'']),  # for filter(user=x, status=y)\n            models.Index(fields=[''status'', ''-created'']),  # for filter(status=x).order_by(''-created'')\n        ]\n```\n\n### Validation Checklist for Missing Indexes\n- [ ] Table has 10k+ rows\n- [ ] Field is used in filter() or order_by() on hot path\n- [ ] Checked model - no db_index=True or Meta.indexes entry\n- [ ] Not a foreign key (already indexed automatically)\n\n---\n\n## Priority 4: Write Loops (HIGH)\n\n**Impact:** N database writes instead of 1. Lock contention. Slow requests.\n\n### Rule: Use bulk_create instead of create() in loops\n\n```python\n# PROBLEM: N inserts, N round trips\nfor item in items:\n    Model.objects.create(name=item[''name''])\n\n# SOLUTION: Single bulk insert\nModel.objects.bulk_create([\n    Model(name=item[''name'']) for item in items\n])\n```\n\n### Rule: Use update() or bulk_update instead of save() in loops\n\n```python\n# PROBLEM: N updates\nfor obj in queryset:\n    obj.status = ''done''\n    obj.save()\n\n# SOLUTION A: Single UPDATE statement (same value for all)\nqueryset.update(status=''done'')\n\n# SOLUTION B: bulk_update (different values)\nfor obj in objects:\n    obj.status = compute_status(obj)\nModel.objects.bulk_update(objects, [''status''], batch_size=500)\n```\n\n### Rule: Use delete() on queryset, not in loops\n\n```python\n# PROBLEM: N deletes\nfor obj in queryset:\n    obj.delete()\n\n# SOLUTION: Single DELETE\nqueryset.delete()\n```\n\n### Validation Checklist for Write Loops\n- [ ] Loop iterates over 100+ items (or unbounded)\n- [ ] Each iteration calls create(), save(), or delete()\n- [ ] This runs on user-facing request (not one-time migration script)\n\n---\n\n## Priority 5: Inefficient Patterns (LOW)\n\n**Rarely worth reporting.** Include only as minor notes if you''re already reporting real issues.\n\n### Pattern: count() vs exists()\n\n```python\n# Slightly suboptimal\nif queryset.count() > 0:\n    do_thing()\n\n# Marginally better\nif queryset.exists():\n    do_thing()\n```\n\n**Usually skip** - difference is <1ms in most cases.\n\n### Pattern: len(queryset) vs count()\n\n```python\n# Fetches all rows to count\nif len(queryset) > 0:  # bad if queryset not yet evaluated\n\n# Single COUNT query\nif queryset.count() > 0:\n```\n\n**Only flag** if queryset is large and not already evaluated.\n\n### Pattern: get() in small loops\n\n```python\n# N queries, but if N is small (< 20), often fine\nfor id in ids:\n    obj = Model.objects.get(id=id)\n```\n\n**Only flag** if loop is large or this is in a very hot path.\n\n---\n\n## Validation Requirements\n\nBefore reporting ANY issue:\n\n1. **Trace the data flow** - Follow queryset from creation to consumption\n2. **Search for existing optimizations** - Grep for select_related, prefetch_related, pagination\n3. **Verify data volume** - Check if table is actually large\n4. **Confirm hot path** - Trace call sites, verify this runs frequently\n5. **Rule out mitigations** - Check for caching, rate limiting\n\n**If you cannot validate all steps, do not report.**\n\n---\n\n## Output Format\n\n```markdown\n## Django Performance Review: [File/Component Name]\n\n### Summary\nValidated issues: X (Y Critical, Z High)\n\n### Findings\n\n#### [PERF-001] N+1 Query in UserListView (CRITICAL)\n**Location:** `views.py:45`\n\n**Issue:** Related field `profile` accessed in template loop without prefetch.\n\n**Validation:**\n- Traced: UserListView → users queryset → user_list.html → `{{ user.profile.bio }}` in loop\n- Searched codebase: no select_related(''profile'') found\n- User table: 50k+ rows (verified in admin)\n- Hot path: linked from homepage navigation\n\n**Evidence:**\n```python\ndef get_queryset(self):\n    return User.objects.filter(active=True)  # no select_related\n```\n\n**Fix:**\n```python\ndef get_queryset(self):\n    return User.objects.filter(active=True).select_related(''profile'')\n```\n```\n\nIf no issues found: \"No performance issues identified after reviewing [files] and validating [what you checked].\"\n\n**Before submitting, sanity check each finding:**\n- Does the severity match the actual impact? (\"Minor inefficiency\" ≠ CRITICAL)\n- Is this a real performance issue or just a style preference?\n- Would fixing this measurably improve performance?\n\nIf the answer to any is \"no\" - remove the finding.\n\n---\n\n## What NOT to Report\n\n- Test files\n- Admin-only views\n- Management commands\n- Migration files\n- One-time scripts\n- Code behind disabled feature flags\n- Tables with <1000 rows that won''t grow\n- Patterns in cold paths (rarely executed code)\n- Micro-optimizations (exists vs count, only/defer without evidence)\n\n### False Positives to Avoid\n\n**Queryset variable assignment is not an issue:**\n```python\n# This is FINE - no performance difference\nprojects_qs = Project.objects.filter(org=org)\nprojects = list(projects_qs)\n\n# vs this - identical performance\nprojects = list(Project.objects.filter(org=org))\n```\nQuerysets are lazy. Assigning to a variable doesn''t execute anything.\n\n**Single query patterns are not N+1:**\n```python\n# This is ONE query, not N+1\nprojects = list(Project.objects.filter(org=org))\n```\nN+1 requires a loop that triggers additional queries. A single `list()` call is fine.\n\n**Missing select_related on single object fetch is not N+1:**\n```python\n# This is 2 queries, not N+1 - report as LOW at most\nstate = AutofixState.objects.filter(pr_id=pr_id).first()\nproject_id = state.request.project_id  # second query\n```\nN+1 requires a loop. A single object doing 2 queries instead of 1 can be reported as LOW if relevant, but never as CRITICAL/HIGH.\n\n**Style preferences are not performance issues:**\nIf your only suggestion is \"combine these two lines\" or \"rename this variable\" - that''s style, not performance. Don''t report it.\n"},"category":"official","lastSynced":"2026-03-06T05:05:58.318Z","seo":{"title":{"en":"django-perf-review: Django Performance Optimization Guide...","zh":"Django性能优化指南 - django-perf-review","ja":"Django パフォーマンス レビュー Setup Guide - django-perf-review","ko":"Django 성능 최적화 가이드 - django-perf-review","es":"Guía de configuración de django-perf-review para optimiza...","fr":"Guide de configuration de django-perf-review pour amélior...","de":"Einrichtungsleitfaden für django-perf-review zur Optimier...","pt":"Guia de Configuração do django-perf-review para Otimizaçã...","ru":"ИИ Агенты: Настройка django-perf-review для Производитель...","ar":"دليل إعداد أداة django-perf-review لتحسين الأداء"},"description":{"en":"Unlock Django performance issues with django-perf-review. Discover N+1 queries, optimize ORM, and audit code for production-ready efficiency. Get started now!","zh":"使用django-perf-review进行Django代码性能审查，找到N+1查询，优化Django ORM和数据库性能","ja":"Django パフォーマンス レビュー ツール django-perf-review を使用して、N+1 クエリを発見し、Django ORM とデータベースのパフォーマンスを最適化します","ko":"django-perf-review를 사용하여 Django 코드의 성능을 검토하고 N+1 쿼리를 찾고 Django ORM 및 데이터베이스 성능을 최적화합니다","es":"Aprenda a utilizar django-perf-review para identificar y solucionar problemas de rendimiento en Django, incluyendo consultas N+1 y optimización de ORM","fr":"Découvrez comment utiliser django-perf-review pour identifier et résoudre les problèmes de performances de Django, notamment les requêtes N+1 et l''optimisati...","de":"Erfahren Sie, wie Sie django-perf-review verwenden, um Leistungsprobleme in Django zu identifizieren und zu lösen, einschließlich N+1-Abfragen und ORM-Optimi...","pt":"Aprenda a configurar o django-perf-review para identificar e corrigir problemas de desempenho em projetos Django, incluindo consultas N+1 e otimização de ORM","ru":"Узнайте, как настроить django-perf-review для выявления и исправления проблем производительности в проектах Django, включая запросы N+1 и оптимизацию ORM","ar":"تعرف على كيفية إعداد أداة django-perf-review لتحديد ومعالجة مشاكل الأداء في مشاريع Django، بما في ذلك استفسارات N+1 وتحسين ORM"},"definition":{"en":"django-perf-review is a skill that analyzes Django code for performance problems, identifying N+1 queries and optimizing database performance.","zh":"django-perf-review是一种AIエージェント，用于审查Django代码的性能问题","ja":"django-perf-reviewは、Django コードのパフォーマンス問題をレビューするAIエージェントです","ko":"django-perf-review는 Django 코드의 성능 문제를 검토하는 인공지능 에이전트입니다","es":"django-perf-review es una herramienta de revisión de código para identificar problemas de rendimiento en aplicaciones Django","fr":"django-perf-review est un outil d''examen de code pour identifier les problèmes de performances dans les applications Django","de":"django-perf-review ist ein Code-Review-Tool zur Identifizierung von Leistungsproblemen in Django-Anwendungen","pt":"O django-perf-review é uma ferramenta de revisão de código para identificar problemas de desempenho em projetos Django.","ru":"django-perf-review - это инструмент для проверки кода, предназначенный для выявления проблем производительности в проектах Django.","ar":"أداة django-perf-review هي أداة مراجعة 코드 لتحديد مشاكل الأداء في مشاريع Django."},"features":{"en":["Researches codebase to confirm performance issues","Validates findings before reporting","Optimizes Django ORM for improved database performance","Identifies N+1 queries for optimization","Audits Django code for production-ready efficiency","Reports only proven performance issues"],"zh":["查找N+1查询","优化Django ORM","检查数据库性能","验证查询集性能","审查Django代码以发现性能问题"],"ja":["N+1 クエリの検出","Django ORM の最適化","データベース パフォーマンスの確認","クエリセット パフォーマンスの検証","Django コードのパフォーマンス問題のレビュー"],"ko":["N+1 쿼리 찾기","Django ORM 최적화","데이터베이스 성능 확인","쿼리셋 성능 검증","Django 코드의 성능 문제 검토"],"es":["Detección de consultas N+1","Optimización de ORM","Análisis de rendimiento de consultas","Revisión de código para problemas de rendimiento","Validación de problemas de rendimiento antes de informar","Compatibilidad con la auditoría de código de Django"],"fr":["Détection de requêtes N+1","Optimisation de l''ORM","Analyse des performances des requêtes","Examen de code pour les problèmes de performances","Validation des problèmes de performances avant de signaler","Compatibilité avec l''audit de code de Django"],"de":["Erkennung von N+1-Abfragen","Optimierung von ORM","Leistungsanalyse von Abfragen","Code-Review für Leistungsprobleme","Validierung von Leistungsproblemen vor dem Melden","Kompatibilität mit der Code-Audit von Django"],"pt":["Identificação de consultas N+1","Otimização de ORM","Verificação de desempenho de queryset","Análise de desempenho de banco de dados","Revisão de código para problemas de desempenho"],"ru":["Выявление запросов N+1","Оптимизация ORM","Проверка производительности queryset","Анализ производительности базы данных","Проверка кода на проблемы производительности"],"ar":["تحديد استفسارات N+1","تحسين ORM","فحص أداء queryset","تحليل أداء قاعدة البيانات","مراجعة الكود لتحديد مشاكل الأداء"]},"keywords":{"en":["django-perf-review setup guide","how to use django-perf-review","django performance optimization","django-perf-review vs django-debug-toolbar","what is django-perf-review","django-perf-review install","django performance issues","django orm optimization","django database performance"],"zh":["Django性能优化","django-perf-review","N+1查询","Django ORM","数据库性能","AIエージェント","Django代码审查"],"ja":["Django パフォーマンス レビュー","django-perf-review","N+1 クエリ","Django ORM","データベース パフォーマンス","AIエージェント","Django コード レビュー"],"ko":["Django 성능 최적화","django-perf-review","N+1 쿼리","Django ORM","데이터베이스 성능","인공지능 에이전트","Django 코드 검토"],"es":["django perf review","optimización de django","consultas n+1","orm optimización","rendimiento de django","herramientas de desarrollo de django","django ai agent","agentes de inteligencia artificial para django"],"fr":["django perf review","optimisation de django","requêtes n+1","orm optimisation","performances de django","outils de développement de django","django ai agent","agents d''intelligence artificielle pour django"],"de":["django perf review","optimierung von django","n+1-abfragen","orm optimierung","leistung von django","entwicklungstools für django","django ai agent","künstliche intelligenz agenten für django"],"pt":["django-perf-review","otimização de desempenho Django","consultas N+1","ORM Django","desempenho de queryset","produção Django","ferramentas de desenvolvimento Django"],"ru":["django-perf-review","Оптимизация производительности Django","Запросы N+1","ORM Django","Производительность queryset","Производство Django","Инструменты разработки Django"],"ar":["django-perf-review","تحسين أداء Django","استفسارات N+1","ORM Django","أداء queryset","إنتاج Django","أدوات تطوير Django"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Python Web Development Agents needing advanced Django performance optimization and code review capabilities.","zh":"适合需要高级 Django 性能优化和代码审查能力的 Python Web 开发 Agent。","ja":"Python Web 開発エージェントが高度な Django パフォーマンス最適化とコードレビュー機能を必要とする場合に適しています。","ko":"고급 Django 성능 최적화 및 코드 리뷰 기능이 필요한 Python Web 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo web de Python que necesitan una optimización de rendimiento avanzada de Django y capacidades de revisión de código.","fr":"Parfait pour les agents de développement Web Python nécessitant une optimisation de performances avancée de Django et des capacités de révision de code.","de":"Perfekt für Python-Web-Entwicklungsagenten, die eine erweiterte Leistungsoptimierung von Django und Code-Review-Funktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web em Python que necessitam de otimização de desempenho avançada do Django e capacidades de revisão de código.","ru":"Идеально подходит для агентов веб-разработки Python, которым необходима продвинутая оптимизация производительности Django и возможности проверки кода.","ar":"مثالي للوكلاء الذين يطورون ويب بايثون الذين يحتاجون إلى تحسين أداء متقدم لشركة Django وقدرات مراجعة الشفرة."},"recommendation":{"en":"Empowers agents to identify and resolve N+1 queries, optimize Django ORM issues, and audit Django code for performance problems using validated research and severity-matched reporting, all while ensuring database performance and queryset optimization.","zh":"赋予代理识别和解决 N+1 查询、优化 Django ORM 问题，并使用验证研究和严重性匹配报告审核 Django 代码以发现性能问题，同时确保数据库性能和查询集优化。","ja":"エージェントに N+1 クエリを識別して解決し、Django ORM の問題を最適化し、検証済みの研究と重大性に一致したレポートを使用して Django コードをパフォーマンスの問題について監査し、データベースのパフォーマンスとクエリセットの最適化を確保することを可能にします。","ko":"에이전트가 N+1 쿼리를 식별하고 해결하고 Django ORM 문제를 최적화하며 검증된 연구와 심각도에 맞는 보고서를 사용하여 성능 문제를 발견하기 위해 Django 코드를 감사하고 데이터베이스 성능 및 쿼리셋 최적화를 보장하는 것을 가능하게 합니다.","es":"Permite a los agentes identificar y resolver consultas N+1, optimizar problemas de Django ORM y auditar el código de Django para problemas de rendimiento utilizando investigaciones validadas y informes con gravedad coincidente, todo esto mientras se garantiza el rendimiento de la base de datos y la optimización de queryset.","fr":"Permet aux agents d''identifier et de résoudre des requêtes N+1, d''optimiser les problèmes de Django ORM et d''auditer le code Django pour des problèmes de performances en utilisant des recherches validées et des rapports avec une gravité correspondante, le tout en garantissant les performances de la base de données et l''optimisation de queryset.","de":"Ermöglicht es Agenten, N+1-Abfragen zu identifizieren und zu lösen, Django-ORM-Probleme zu optimieren und den Django-Code auf Leistungsprobleme zu überprüfen, indem validierte Forschung und Berichte mit übereinstimmender Schwere verwendet werden, während die Datenbankleistung und die Optimierung von QuerySets sichergestellt werden.","pt":"Habilita os agentes a identificar e resolver consultas N+1, otimizar problemas do Django ORM e auditar o código Django para problemas de desempenho usando pesquisas validadas e relatórios com gravidade correspondente, garantindo ao mesmo tempo o desempenho do banco de dados e a otimização da queryset.","ru":"Позволяет агентам выявлять и решать запросы N+1, оптимизировать проблемы Django ORM и проверять код Django на проблемы с производительностью с помощью проверенных исследований и отчетов, соответствующих степени тяжести, при этом обеспечивая производительность базы данных и оптимизацию queryset.","ar":"تمكين الوكلاء من تحديد ومعالجة استفسارات N+1 وتحسين مشاكل Django ORM ومراجعة رمز Django لمشاكل الأداء باستخدام أبحاث موثقة وتقارير متوافقة مع شدة الأثر، مع ضمان أداء قاعدة البيانات وتحسين queryset في نفس الوقت."},"useCases":{"en":["Debugging Django performance issues","Optimizing queryset performance","Auditing Django code for ORM issues and database performance problems"],"zh":["调试 Django 性能问题","优化查询集性能","审核 Django 代码以发现 ORM 问题和数据库性能问题"],"ja":["Django パフォーマンスの問題をデバッグする","クエリセットのパフォーマンスを最適化する","Django コードを ORM の問題とデータベースのパフォーマンスの問題について監査する"],"ko":["Django 성능 문제를 디버깅하는 것","쿼리셋 성능을 최적화하는 것","Django 코드를 ORM 문제 및 데이터베이스 성능 문제에 대해 감사하는 것"],"es":["Depuración de problemas de rendimiento de Django","Optimización del rendimiento de queryset","Auditoría del código de Django para problemas de ORM y rendimiento de la base de datos"],"fr":["Débogage des problèmes de performances de Django","Optimisation des performances de queryset","Audit du code Django pour les problèmes d''ORM et de performances de la base de données"],"de":["Debuggen von Django-Leistungsproblemen","Optimierung der Queryset-Leistung","Überprüfung des Django-Codes auf ORM-Probleme und Datenbankleistungsprobleme"],"pt":["Depuração de problemas de desempenho do Django","Otimização do desempenho da queryset","Auditoria do código Django para problemas de ORM e desempenho do banco de dados"],"ru":["Отладка проблем с производительностью Django","Оптимизация производительности queryset","Проверка кода Django на проблемы с ORM и производительностью базы данных"],"ar":["تصحيح أخطاء مشاكل الأداء في شركة Django","تحسين أداء queryset","مراجعة رمز Django لمشاكل ORM وأداء قاعدة البيانات"]},"limitations":{"en":["Requires access to Django codebase","Validation of issues before reporting is mandatory","Severity of reported issues must match impact"],"zh":["需要访问 Django 代码库","问题报告之前的验证是必需的","报告的问题的严重性必须与影响相匹配"],"ja":["Django コードベースへのアクセスが必要","報告前に問題の検証が必須","報告される問題の重大性は影響と一致する必要がある"],"ko":["Django 코드베이스에 접근할 수 있어야 함","报告하기 전에 문제를 검증해야 함","보고된 문제의 심각도는 영향과 일치해야 함"],"es":["Requiere acceso a la base de código de Django","La validación de los problemas antes de informar es obligatoria","La gravedad de los problemas informados debe coincidir con el impacto"],"fr":["Nécessite un accès à la base de code de Django","La validation des problèmes avant de signaler est obligatoire","La gravité des problèmes signalés doit correspondre à l''impact"],"de":["Erfordert Zugriff auf die Django-Codebasis","Die Validierung von Problemen vor der Meldung ist obligatorisch","Die Schwere der gemeldeten Probleme muss dem Auswirkung entsprechen"],"pt":["Requer acesso à base de código do Django","Validação de problemas antes do relatório é obrigatória","Gravidade dos problemas relatados deve corresponder ao impacto"],"ru":["Требуется доступ к базе кода Django","Проверка проблем перед отчетом обязательна","Степень тяжести отчетных проблем должна соответствовать воздействию"],"ar":["يتطلب الوصول إلى قاعدة الشفرة لشركة Django","التحقق من المشاكل قبل التقرير إلزامي","يجب أن تتوافق شدة الأثر للمشاكل المبلغ عنها مع التأثير"]},"version":4},"contentHash":"d45298cb3c2b06777a28a2cadbcbb4eacc1e987ade230f4f94947ad927c92033","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":92}');
