INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/django-perf-review', 'django-perf-review', 'getsentry', 'skills', 'official', 'django-perf-review getsentry skills official tag-production The django-perf-review skill reviews Django code for validated performance issues, optimizing database performance and ORM issues for developers. django-perf-review是一种Django性能代码审查工具，用于找到N+1查询、优化Django ORM和数据库性能 django-perf-reviewは、Django パフォーマンス コード レビュー ツールで、N+1 クエリの検出、Django ORM とデータベースのパフォーマンス最適化に使用されます django-perf-review는 Django 성능 코드 검토 도구로 N+1 쿼리를 찾고 Django ORM 및 데이터베이스 성능을 최적화하는 데 사용됩니다 django-perf-review es una herramienta para revisar y optimizar el rendimiento de Django, detectando problemas como consultas N+1 y optimizando el ORM django-perf-review est un outil pour examiner et optimiser les performances de Django, en détectant des problèmes tels que les requêtes N+1 et en optimisant l''ORM django-perf-review ist ein Tool zur Überprüfung und Optimierung der Leistung von Django, mit dem Probleme wie N+1-Abfragen und ORM-Optimierung erkannt werden O django-perf-review é uma ferramenta para revisar e otimizar o desempenho de projetos Django, identificando problemas como consultas N+1 e issues de ORM. django-perf-review - это инструмент для проверки и оптимизации производительности проектов Django, выявления проблем, таких как запросы N+1 и проблемы ORM. أداة django-perf-review هي أداة لمراجعة وتحسين أداء مشاريع Django، وتحديد مشاكل مثل استفسارات N+1 ومشاكل ORM. django-perf-review setup guide how to use django-perf-review django performance optimization django-perf-review vs django-debug-toolbar what is django-perf-review django-perf-review install django performance issues django orm optimization django database performance Django性能优化 django-perf-review N+1查询 Django ORM 数据库性能 AIエージェント Django代码审查 Researches codebase to confirm performance issues Validates findings before reporting Optimizes Django ORM for improved database performance Identifies N+1 queries for optimization Audits Django code for production-ready efficiency Reports only proven performance issues django-perf-review is a skill that analyzes Django code for performance problems, identifying N+1 queries and optimizing database performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/sandbox-sdk', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'sandbox-sdk', 535, 66, 92, '2026-03-06T05:33:24Z', '2026-03-06T05:56:39.417Z', '0f3501e6510921401be3f54bcb24d2a432a1b5c63af8f719eded3a087ad88ea9', '{"id":"cloudflare/skills/sandbox-sdk","name":"sandbox-sdk","description":{"en":"The sandbox-sdk skill enables developers to build sandboxed applications for secure code execution on Cloudflare Workers. It is essential for developers building AI code interpreters, CI/CD systems, or interactive development environments that need to execute untrusted code securely.","zh":"Cloudflare Sandbox SDK 允许开发者在 Workers 上构建隔离的代码执行环境，适用于AI代码解释器、CI/CD系统或运行不可信代码。它涵盖了完整的SDK生命周期、命令、文件和预览URL。","ja":"Cloudflare Sandbox SDK は、Workers上で安全なコード実行環境を構築するためのツールです。AIコードインタプリタ、CI/CDシステム、または信頼できないコードの実行に最適です。SDKライフサイクル、コマンド、ファイルを管理します。","ko":"Cloudflare Sandbox SDK는 Workers에서 격리된 코드 실행 환경을 구축하여 AI 코드 인터프리터, CI/CD 시스템 또는 신뢰할 수 없는 코드 실행에 사용됩니다. SDK 수명 주기, 명령, 파일 및 미리보기 URL을 다룹니다.","es":"El sandbox-sdk permite crear entornos de ejecución de código seguro y aislado en Cloudflare Workers. Utiliza npm y Docker para la instalación","fr":"Le sandbox-sdk permet de créer des environnements d''exécution de code sécurisés et isolés sur Cloudflare Workers. Il utilise npm et Docker pour l''installation","de":"Das sandbox-sdk ermöglicht die Erstellung von sicheren und isolierten Code-Ausführungsumgebungen in Cloudflare Workers. Es verwendet npm und Docker für die Installation","pt":"O Sandbox SDK permite construir aplicações em sandbox para execução de código seguro, utilizando Cloudflare Workers","ru":"Sandbox SDK позволяет создавать приложения в песочнице для безопасного выполнения кода, используя Cloudflare Workers","ar":"يسمح Sandbox SDK ببناء التطبيقات في حاوية رملية لتنفيذ الكود الآمن، باستخدام Cloudflare Workers"},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"sandbox-sdk","description":"Build sandboxed applications for secure code execution. Load when building AI code execution, code interpreters, CI/CD systems, interactive dev environments, or executing untrusted code. Covers Sandbox SDK lifecycle, commands, files, code interpreter, and preview URLs. Biases towards retrieval from Cloudflare docs over pre-trained knowledge.","bodyPreview":"# Cloudflare Sandbox SDK\n\nBuild secure, isolated code execution environments on Cloudflare Workers.\n\n## FIRST: Verify Installation\n\n```bash\nnpm install @cloudflare/sandbox\ndocker info  # Must succeed - Docker required for local dev\n```\n\n## Retrieval Sources\n\nYour knowledge of the Sandbox SDK may be outdated. **Prefer retrieval over pre-training** for any Sandbox SDK task.\n\n| Resource | URL |\n|----------|-----|\n| Docs | https://developers.cloudflare.com/sandbox/ |\n| API Reference | https://develo","body":"# Cloudflare Sandbox SDK\n\nBuild secure, isolated code execution environments on Cloudflare Workers.\n\n## FIRST: Verify Installation\n\n```bash\nnpm install @cloudflare/sandbox\ndocker info  # Must succeed - Docker required for local dev\n```\n\n## Retrieval Sources\n\nYour knowledge of the Sandbox SDK may be outdated. **Prefer retrieval over pre-training** for any Sandbox SDK task.\n\n| Resource | URL |\n|----------|-----|\n| Docs | https://developers.cloudflare.com/sandbox/ |\n| API Reference | https://developers.cloudflare.com/sandbox/api/ |\n| Examples | https://github.com/cloudflare/sandbox-sdk/tree/main/examples |\n| Get Started | https://developers.cloudflare.com/sandbox/get-started/ |\n\nWhen implementing features, fetch the relevant doc page or example first.\n\n## Required Configuration\n\n**wrangler.jsonc** (exact - do not modify structure):\n\n```jsonc\n{\n  \"containers\": [{\n    \"class_name\": \"Sandbox\",\n    \"image\": \"./Dockerfile\",\n    \"instance_type\": \"lite\",\n    \"max_instances\": 1\n  }],\n  \"durable_objects\": {\n    \"bindings\": [{ \"class_name\": \"Sandbox\", \"name\": \"Sandbox\" }]\n  },\n  \"migrations\": [{ \"new_sqlite_classes\": [\"Sandbox\"], \"tag\": \"v1\" }]\n}\n```\n\n**Worker entry** - must re-export Sandbox class:\n\n```typescript\nimport { getSandbox } from ''@cloudflare/sandbox'';\nexport { Sandbox } from ''@cloudflare/sandbox'';  // Required export\n```\n\n## Quick Reference\n\n| Task | Method |\n|------|--------|\n| Get sandbox | `getSandbox(env.Sandbox, ''user-123'')` |\n| Run command | `await sandbox.exec(''python script.py'')` |\n| Run code (interpreter) | `await sandbox.runCode(code, { language: ''python'' })` |\n| Write file | `await sandbox.writeFile(''/workspace/app.py'', content)` |\n| Read file | `await sandbox.readFile(''/workspace/app.py'')` |\n| Create directory | `await sandbox.mkdir(''/workspace/src'', { recursive: true })` |\n| List files | `await sandbox.listFiles(''/workspace'')` |\n| Expose port | `await sandbox.exposePort(8080)` |\n| Destroy | `await sandbox.destroy()` |\n\n## Core Patterns\n\n### Execute Commands\n\n```typescript\nconst sandbox = getSandbox(env.Sandbox, ''user-123'');\nconst result = await sandbox.exec(''python --version'');\n// result: { stdout, stderr, exitCode, success }\n```\n\n### Code Interpreter (Recommended for AI)\n\nUse `runCode()` for executing LLM-generated code with rich outputs:\n\n```typescript\nconst ctx = await sandbox.createCodeContext({ language: ''python'' });\n\nawait sandbox.runCode(''import pandas as pd; data = [1,2,3]'', { context: ctx });\nconst result = await sandbox.runCode(''sum(data)'', { context: ctx });\n// result.results[0].text = \"6\"\n```\n\n**Languages**: `python`, `javascript`, `typescript`\n\nState persists within context. Create explicit contexts for production.\n\n### File Operations\n\n```typescript\nawait sandbox.mkdir(''/workspace/project'', { recursive: true });\nawait sandbox.writeFile(''/workspace/project/main.py'', code);\nconst file = await sandbox.readFile(''/workspace/project/main.py'');\nconst files = await sandbox.listFiles(''/workspace/project'');\n```\n\n## When to Use What\n\n| Need | Use | Why |\n|------|-----|-----|\n| Shell commands, scripts | `exec()` | Direct control, streaming |\n| LLM-generated code | `runCode()` | Rich outputs, state persistence |\n| Build/test pipelines | `exec()` | Exit codes, stderr capture |\n| Data analysis | `runCode()` | Charts, tables, pandas |\n\n## Extending the Dockerfile\n\nBase image (`docker.io/cloudflare/sandbox:0.7.0`) includes Python 3.11, Node.js 20, and common tools.\n\nAdd dependencies by extending the Dockerfile:\n\n```dockerfile\nFROM docker.io/cloudflare/sandbox:0.7.0\n\n# Python packages\nRUN pip install requests beautifulsoup4\n\n# Node packages (global)\nRUN npm install -g typescript\n\n# System packages\nRUN apt-get update && apt-get install -y ffmpeg && rm -rf /var/lib/apt/lists/*\n\nEXPOSE 8080  # Required for local dev port exposure\n```\n\nKeep images lean - affects cold start time.\n\n## Preview URLs (Port Exposure)\n\nExpose HTTP services running in sandboxes:\n\n```typescript\nconst { url } = await sandbox.exposePort(8080);\n// Returns preview URL for the service\n```\n\n**Production requirement**: Preview URLs need a custom domain with wildcard DNS (`*.yourdomain.com`). The `.workers.dev` domain does not support preview URL subdomains.\n\nSee: https://developers.cloudflare.com/sandbox/guides/expose-services/\n\n## OpenAI Agents SDK Integration\n\nThe SDK provides helpers for OpenAI Agents at `@cloudflare/sandbox/openai`:\n\n```typescript\nimport { Shell, Editor } from ''@cloudflare/sandbox/openai'';\n```\n\nSee `examples/openai-agents` for complete integration pattern.\n\n## Sandbox Lifecycle\n\n- `getSandbox()` returns immediately - container starts lazily on first operation\n- Containers sleep after 10 minutes of inactivity (configurable via `sleepAfter`)\n- Use `destroy()` to immediately free resources\n- Same `sandboxId` always returns same sandbox instance\n\n## Anti-Patterns\n\n- **Don''t use internal clients** (`CommandClient`, `FileClient`) - use `sandbox.*` methods\n- **Don''t skip the Sandbox export** - Worker won''t deploy without `export { Sandbox }`\n- **Don''t hardcode sandbox IDs for multi-user** - use user/session identifiers\n- **Don''t forget cleanup** - call `destroy()` for temporary sandboxes\n\n## Detailed References\n\n- **[references/api-quick-ref.md](references/api-quick-ref.md)** - Full API with options and return types\n- **[references/examples.md](references/examples.md)** - Example index with use cases\n"},"category":"official","lastSynced":"2026-03-06T05:56:39.417Z","seo":{"title":{"en":"sandbox-sdk: Build Secure Code Execution Environments | A...","zh":"Cloudflare Sandbox SDK 设置指南：构建安全代码执行环境","ja":"Cloudflare Sandbox SDK セットアップガイド：AIエージェント向け安全なコード実行","ko":"Cloudflare Sandbox SDK 설정 가이드: 안전한 코드 실행 환경 구축","es":"Guía de configuración de sandbox-sdk para ejecución de có...","fr":"Guide d''installation de sandbox-sdk pour l''exécution de c...","de":"Einrichtungsleitfaden für sandbox-sdk zur sicheren Code-A...","pt":"Guia de Configuração do Sandbox SDK para Execução de Códi...","ru":"Настройка Sandbox SDK для Безопасного Выполнения Код","ar":"دليل إعداد Sandbox SDK لتنفيذ الكود الآمن"},"description":{"en":"Learn how to use the Cloudflare Sandbox SDK to build secure, isolated environments for AI code interpreters & CI/CD systems. Includes setup guide, Docker req...","zh":"学习如何使用Cloudflare Sandbox SDK在Workers上构建安全的沙盒环境，用于AI代码执行、CI/CD系统和执行不可信代码。包含安装、Docker设置和API参考。","ja":"Cloudflare Sandbox SDKを使用して、AIエージェントやCI/CDシステムのための安全なコード実行環境を構築する方法。DockerのインストールとAPIリファレンスを含む。","ko":"Cloudflare Sandbox SDK를 사용하여 AI 코드 실행, CI/CD 시스템 및 신뢰할 수 없는 코드 실행을 위한 안전한 샌드박스 환경을 구축하는 방법을 알아보세요. Docker 설치 및 API 참조 포함.","es":"Aprende a utilizar sandbox-sdk para crear entornos de ejecución de código aislados y seguros en Cloudflare Workers","fr":"Découvrez comment utiliser sandbox-sdk pour créer des environnements d''exécution de code isolés et sécurisés sur Cloudflare Workers","de":"Erfahren Sie, wie Sie sandbox-sdk verwenden, um isolierte und sichere Code-Ausführungsumgebungen in Cloudflare Workers zu erstellen","pt":"Aprenda a configurar o Sandbox SDK para criar ambientes de execução de código isolados e seguros com Cloudflare Workers","ru":"Узнайте, как настроить Sandbox SDK для создания изолированных и безопасных сред выполнения кода с Cloudflare Workers","ar":"تعلم كيفية إعداد Sandbox SDK لإنشاء بيئات تنفيذ الكود المعزولة والأمنة مع Cloudflare Workers"},"definition":{"en":"sandbox-sdk is an AI agent skill for building secure, isolated code execution environments on Cloudflare Workers. It covers the SDK lifecycle, commands, file management, and code interpretation, with a bias towards retrieving the latest information from Cloudflare''s official documentation.","zh":"Cloudflare Sandbox SDK 是一个用于在 Cloudflare Workers 上创建安全、隔离的代码执行环境的开发工具。它专为构建AI代码执行器、代码解释器、CI/CD系统、交互式开发环境或执行不可信代码而设计，需要本地Docker支持进行开发。","ja":"Cloudflare Sandbox SDK は、Cloudflare Workers上で安全に分離されたコード実行環境を作成する開発ツールです。AIエージェントのコード実行、コードインタプリタ、CI/CDシステム、対話型開発環境、または信頼できないコードの実行に使用され、ローカル開発にはDockerが必要です。","ko":"Cloudflare Sandbox SDK는 Cloudflare Workers에서 안전하고 격리된 코드 실행 환경을 생성하기 위한 개발 도구입니다. AI 코드 실행, 코드 인터프리터, CI/CD 시스템, 대화형 개발 환경 또는 신뢰할 수 없는 코드 실행을 구축하는 데 사용되며 로컬 개발을 위해 Docker가 필요합니다.","es":"El sandbox-sdk es un kit de desarrollo de software que permite crear entornos de ejecución de código seguro y aislado","fr":"Le sandbox-sdk est un kit de développement de logiciel qui permet de créer des environnements d''exécution de code sécurisés et isolés","de":"Das sandbox-sdk ist ein Software-Development-Kit, das die Erstellung von sicheren und isolierten Code-Ausführungsumgebungen ermöglicht","pt":"O Sandbox SDK é uma ferramenta para criar ambientes de execução de código isolados e seguros com Cloudflare Workers","ru":"Sandbox SDK - это инструмент для создания изолированных и безопасных сред выполнения кода с Cloudflare Workers","ar":"Sandbox SDK هو أداة لإنشاء بيئات تنفيذ الكود المعزولة والأمنة مع Cloudflare Workers"},"features":{"en":["Manages the full Sandbox SDK lifecycle for application development","Executes commands within a secure, isolated execution environment","Handles file operations within the sandboxed application","Integrates code interpreter functionality for dynamic execution","Generates and manages preview URLs for testing applications","Requires Docker for local development (via `docker info` command)"],"zh":["使用 npm 安装 @cloudflare/sandbox 包","本地开发需要 Docker 环境支持","管理沙盒的完整生命周期","支持执行文件和代码解释器命令","生成安全的预览 URL 用于测试","优先从Cloudflare官方文档检索最新API信息"],"ja":["npm を使用した @cloudflare/sandbox パッケージのインストール","ローカル開発にはDocker環境が必須","サンドボックスの完全なライフサイクル管理","ファイルとコードインタプリタコマンドの実行をサポート","テスト用の安全なプレビューURLを生成","Cloudflare公式ドキュメントからのAPI情報取得を優先"],"ko":["npm을 통한 @cloudflare/sandbox 패키지 설치","로컬 개발을 위한 Docker 환경 필요","샌드박스의 전체 수명 주기 관리","파일 및 코드 인터프리터 명령 실행 지원","테스트를 위한 안전한 미리보기 URL 생성","Cloudflare 공식 문서에서 최신 API 정보 검색 우선"],"es":["Instalación utilizando npm y Docker","Creación de entornos de ejecución de código aislados y seguros","Compatibilidad con Cloudflare Workers","Acceso a la documentación y referencias de la API","Soporte para la ejecución de código de confianza y no confianza"],"fr":["Installation utilisant npm et Docker","Création d''environnements d''exécution de code isolés et sécurisés","Compatibilité avec Cloudflare Workers","Accès à la documentation et aux références de l''API","Support pour l''exécution de code de confiance et non de confiance"],"de":["Installation mit npm und Docker","Erstellung von isolierten und sicheren Code-Ausführungsumgebungen","Kompatibilität mit Cloudflare Workers","Zugriff auf die Dokumentation und API-Referenzen","Unterstützung für die Ausführung von vertrauenswürdigem und nicht vertrauenswürdigem Code"],"pt":["Criação de ambientes de execução de código isolados com Cloudflare Workers","Suporte à execução de código em sandbox para garantir a segurança","Integração com Docker para desenvolvimento local","Acesso à documentação oficial da Cloudflare para atualizações e referências","Suporte à execução de código em diferentes linguagens de programação","Preferência por recuperação de informações em vez de pré-treinamento"],"ru":["Создание изолированных сред выполнения кода с Cloudflare Workers","Поддержка выполнения кода в песочнице для обеспечения безопасности","Интеграция с Docker для локальной разработки","Доступ к официальной документации Cloudflare для обновлений и справок","Поддержка выполнения кода на разных языках программирования","Предпочтение извлечения информации над предварительным обучением"],"ar":["إنشاء بيئات تنفيذ الكود المعزولة مع Cloudflare Workers","دعم تنفيذ الكود في حاوية رملية لضمان الأمان","التكامل مع Docker لتطوير المحلي","الوصول إلى الوثائق الرسمية للشركة Cloudflare للحصول على التحديثات والمراجع","دعم تنفيذ الكود بلغات برمجة مختلفة","التفضيل لاسترجاع المعلومات على التدريب المسبق"]},"keywords":{"en":["how to use sandbox-sdk","sandbox-sdk vs code-sandbox","sandbox-sdk install guide","Cloudflare Workers sandbox environment","secure code execution SDK","sandbox-sdk setup docker","what is sandbox-sdk","sandbox-sdk API reference","AI code interpreter sandbox","untrusted code execution Cloudflare"],"zh":["Cloudflare Sandbox SDK","AI代码执行","代码解释器","CI/CD系统"," Workers 沙盒","不可信代码执行","Docker安装","Cloudflare文档","预览URL","安全代码环境"],"ja":["Cloudflare Sandbox SDK","AIエージェント コード実行","コードインタプリタ","CI/CDシステム","Workers サンドボックス","信頼できないコード実行","Dockerインストール","Cloudflareドキュメント","プレビューURL","安全なコード環境"],"ko":["Cloudflare Sandbox SDK","AI 코드 실행","코드 인터프리터","CI/CD 시스템","Workers 샌드박스","신뢰할 수 없는 코드 실행","Docker 설치","Cloudflare 문서","미리보기 URL","안전한 코드 환경"],"es":["sandbox-sdk","ejecución de código seguro","Cloudflare Workers","npm","Docker","entornos de ejecución d