INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/sandbox-sdk', 'sandbox-sdk', 'cloudflare', 'skills', 'official', 'sandbox-sdk cloudflare skills official agents cloudflare skills workers The sandbox-sdk skill enables developers to build sandboxed applications for secure code execution on Cloudflare Workers. It is essential for developers building AI code interpreters, CI/CD systems, or interactive development environments that need to execute untrusted code securely. Cloudflare Sandbox SDK 允许开发者在 Workers 上构建隔离的代码执行环境，适用于AI代码解释器、CI/CD系统或运行不可信代码。它涵盖了完整的SDK生命周期、命令、文件和预览URL。 Cloudflare Sandbox SDK は、Workers上で安全なコード実行環境を構築するためのツールです。AIコードインタプリタ、CI/CDシステム、または信頼できないコードの実行に最適です。SDKライフサイクル、コマンド、ファイルを管理します。 Cloudflare Sandbox SDK는 Workers에서 격리된 코드 실행 환경을 구축하여 AI 코드 인터프리터, CI/CD 시스템 또는 신뢰할 수 없는 코드 실행에 사용됩니다. SDK 수명 주기, 명령, 파일 및 미리보기 URL을 다룹니다. El sandbox-sdk permite crear entornos de ejecución de código seguro y aislado en Cloudflare Workers. Utiliza npm y Docker para la instalación Le sandbox-sdk permet de créer des environnements d''exécution de code sécurisés et isolés sur Cloudflare Workers. Il utilise npm et Docker pour l''installation Das sandbox-sdk ermöglicht die Erstellung von sicheren und isolierten Code-Ausführungsumgebungen in Cloudflare Workers. Es verwendet npm und Docker für die Installation O Sandbox SDK permite construir aplicações em sandbox para execução de código seguro, utilizando Cloudflare Workers Sandbox SDK позволяет создавать приложения в песочнице для безопасного выполнения кода, используя Cloudflare Workers يسمح Sandbox SDK ببناء التطبيقات في حاوية رملية لتنفيذ الكود الآمن، باستخدام Cloudflare Workers how to use sandbox-sdk sandbox-sdk vs code-sandbox sandbox-sdk install guide Cloudflare Workers sandbox environment secure code execution SDK sandbox-sdk setup docker what is sandbox-sdk sandbox-sdk API reference AI code interpreter sandbox untrusted code execution Cloudflare Cloudflare Sandbox SDK AI代码执行 代码解释器 CI/CD系统 Workers 沙盒 不可信代码执行 Docker安装 Cloudflare文档 预览URL 安全代码环境 Manages the full Sandbox SDK lifecycle for application development Executes commands within a secure, isolated execution environment Handles file operations within the sandboxed application Integrates code interpreter functionality for dynamic execution Generates and manages preview URLs for testing applications Requires Docker for local development (via `docker info` command) sandbox-sdk is an AI agent skill for building secure, isolated code execution environments on Cloudflare Workers. It covers the SDK lifecycle, commands, file management, and code interpretation, with a bias towards retrieving the latest information from Cloudflare''s official documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('n8n-io/n8n/loom-transcript', 'official', 'n8n-io', 'n8n', 'n8n-io/n8n', 'loom-transcript', 177792, 55472, 92, '2026-03-06T06:12:37Z', '2026-03-06T06:20:48.997Z', 'f9a0e0f8348bf0c2cf509916c84a3a00ab06f91b3230015620f11e3a530ecdca', '{"id":"n8n-io/n8n/loom-transcript","name":"loom-transcript","description":{"en":"The loom-transcript skill fetches and displays full transcripts from Loom video URLs, benefiting developers who need to access video content. It uses Loom''s GraphQL API to extract video metadata.","zh":"Loom Transcript Fetcher 是一个使用 Loom 的 GraphQL API 从 Loom 视频 URL 中获取和显示全文转录的工具。它支持多种 URL 格式，并可以提取 32 个字符的 hex 视频 ID。","ja":"Loom トランスクリプト フェッチャーは、Loom の GraphQL API を使用して Loom ビデオ URL から全文のトランスクリプトを取得して表示するツールです。複数の URL フォーマットをサポートし、32 文字の hex ビデオ ID を抽出できます。","ko":"Loom Transcript Fetcher는 Loom의 GraphQL API를 사용하여 Loom 비디오 URL에서 전체 전사본을 가져와 표시하는 툴입니다. 여러 URL 형식을 지원하며 32개의 문자 hex 비디오 ID를 추출할 수 있습니다.","es":"Loom Transcript es una herramienta que permite recuperar transcripciones de video de Loom mediante la API de GraphQL","fr":"Loom Transcript est un outil qui permet de récupérer des transcriptions de vidéo Loom via l''API GraphQL","de":"Loom Transcript ist ein Tool, das die Wiedergabe von Loom-Videotranskripten über die GraphQL-API ermöglicht","pt":"A ferramenta Loom Transcript é uma solução para extrair transcrições de vídeos Loom usando a API GraphQL do Loom.","ru":"Инструмент Loom Transcript является решением для извлечения транскрипций видео Loom с помощью GraphQL API Loom.","ar":"أداة نص لوم هي حل لاستخراج النصوص من مقاطع الفيديو لوم باستخدام واجهة برمجة التطبيقات الرسومية لوم."},"owner":"n8n-io","repo":"n8n","repoPath":"n8n-io/n8n","stars":177792,"forks":55472,"updatedAt":"2026-03-06T06:12:37Z","topics":["ai","apis","automation","cli","data-flow","development","integration-framework","integrations","ipaas","low-code","low-code-platform","mcp","mcp-client","mcp-server","n8n","no-code","self-hosted","typescript","workflow","workflow-automation"],"skillMd":{"name":"loom-transcript","description":"Fetch and display the full transcript from a Loom video URL. Use when the user wants to get or read a Loom transcript.","bodyPreview":"# Loom Transcript Fetcher\n\nFetch the transcript from a Loom video using Loom''s GraphQL API.\n\n## Instructions\n\nGiven the Loom URL: $ARGUMENTS\n\n### 1. Extract the Video ID\n\nParse the Loom URL to extract the 32-character hex video ID. Supported URL formats:\n- `https://www.loom.com/share/<video-id>`\n- `https://www.loom.com/embed/<video-id>`\n- `https://www.loom.com/share/<video-id>?sid=<session-id>`\n\nThe video ID is the 32-character hex string after `/share/` or `/embed/`.\n\n### 2. Fetch Video Metadat","body":"# Loom Transcript Fetcher\n\nFetch the transcript from a Loom video using Loom''s GraphQL API.\n\n## Instructions\n\nGiven the Loom URL: $ARGUMENTS\n\n### 1. Extract the Video ID\n\nParse the Loom URL to extract the 32-character hex video ID. Supported URL formats:\n- `https://www.loom.com/share/<video-id>`\n- `https://www.loom.com/embed/<video-id>`\n- `https://www.loom.com/share/<video-id>?sid=<session-id>`\n\nThe video ID is the 32-character hex string after `/share/` or `/embed/`.\n\n### 2. Fetch Video Metadata\n\nUse the `WebFetch` tool to POST to `https://www.loom.com/graphql` to get the video title and details.\n\nUse this curl command via Bash:\n\n```bash\ncurl -s ''https://www.loom.com/graphql'' \\\n  -H ''Content-Type: application/json'' \\\n  -H ''Accept: application/json'' \\\n  -H ''x-loom-request-source: loom_web_45a5bd4'' \\\n  -H ''apollographql-client-name: web'' \\\n  -H ''apollographql-client-version: 45a5bd4'' \\\n  -d ''{\n    \"operationName\": \"GetVideoSSR\",\n    \"variables\": {\"id\": \"<VIDEO_ID>\", \"password\": null},\n    \"query\": \"query GetVideoSSR($id: ID!, $password: String) { getVideo(id: $id, password: $password) { ... on RegularUserVideo { id name description createdAt owner { display_name } } } }\"\n  }''\n```\n\n### 3. Fetch the Transcript URLs\n\nUse curl via Bash to call the GraphQL API:\n\n```bash\ncurl -s ''https://www.loom.com/graphql'' \\\n  -H ''Content-Type: application/json'' \\\n  -H ''Accept: application/json'' \\\n  -H ''x-loom-request-source: loom_web_45a5bd4'' \\\n  -H ''apollographql-client-name: web'' \\\n  -H ''apollographql-client-version: 45a5bd4'' \\\n  -d ''{\n    \"operationName\": \"FetchVideoTranscript\",\n    \"variables\": {\"videoId\": \"<VIDEO_ID>\", \"password\": null},\n    \"query\": \"query FetchVideoTranscript($videoId: ID!, $password: String) { fetchVideoTranscript(videoId: $videoId, password: $password) { ... on VideoTranscriptDetails { id video_id source_url captions_source_url } ... on GenericError { message } } }\"\n  }''\n```\n\nReplace `<VIDEO_ID>` with the actual video ID extracted in step 1.\n\nThe response contains:\n- `source_url` — JSON transcript URL\n- `captions_source_url` — VTT (WebVTT) captions URL\n\n### 4. Download and Parse the Transcript\n\nFetch **both** URLs returned from step 3 (if available):\n\n1. **VTT captions** (`captions_source_url`): Download with `curl -sL \"<url>\"`. This is a WebVTT file with timestamps and text.\n2. **JSON transcript** (`source_url`): Download with `curl -sL \"<url>\"`. This is a JSON file with transcript segments.\n\nPrefer the VTT captions as the primary source since they include proper timestamps. Fall back to the JSON transcript if VTT is unavailable.\n\n### 5. Present the Transcript\n\nFormat and present the full transcript to the user:\n\n**Video:** [Title from metadata]\n**Author:** [Owner name]\n**Date:** [Created date]\n\n---\n\n**0:00** - First transcript segment text...\n\n**0:14** - Second transcript segment text...\n\n(continue for all segments)\n\n---\n\n## Error Handling\n\n- If the GraphQL response contains a `GenericError`, report the error message to the user.\n- If both `source_url` and `captions_source_url` are null/missing, tell the user that no transcript is available for this video.\n- If the video URL is invalid or the ID cannot be extracted, ask the user for a valid Loom URL.\n\n## Notes\n\n- No authentication or cookies are required — Loom''s transcript API is publicly accessible.\n- Only English transcripts are available through this API.\n- Transcripts are auto-generated and may contain minor errors."},"category":"official","lastSynced":"2026-03-06T06:20:48.997Z","seo":{"title":{"en":"loom-transcript: GraphQL API Transcript Fetcher | AI Agen...","zh":"Loom Transcript Fetcher 设置指南 - 使用 GraphQL API","ja":"Loom トランスクリプト フェッチャー設定ガイド - GraphQL API を使用","ko":"Loom Transcript Fetcher 설정 가이드 - GraphQL API 사용","es":"Guía de configuración de Loom Transcript: Extracción de t...","fr":"Guide de configuration de Loom Transcript: Récupération d...","de":"Loom-Transkript-Konfigurationsleitfaden: Videotranskripte...","pt":"Guia de Configuração do Loom Transcript: Ferramenta de Ex...","ru":"ИИ Агент Loom Transcript: Руководство по Настройке и Испо...","ar":"دليل إعداد أداة نص لوم: استخراج نص من مقاطع الفيديو"},"description":{"en":"Unlock Loom video transcripts with our AI agent skill. Learn how to fetch and display transcripts using Loom''s GraphQL API. Get started now!","zh":"使用 Loom Transcript Fetcher 从 Loom 视频 URL 中获取和显示全文转录。了解如何使用 GraphQL API 提取视频 ID 和元数据。","ja":"Loom トランスクリプト フェッチャーを使用して Loom ビデオ URL から全文のトランスクリプトを取得して表示します。GraphQL API を使用してビデオ ID とメタデータを抽出する方法について説明します。","ko":"Loom Transcript Fetcher를 사용하여 Loom 비디오 URL에서 전체 전사본을 가져와 표시합니다. GraphQL API를 사용하여 비디오 ID와 메타데이터를 추출하는 방법에 대해 알아보세요.","es":"Aprende a configurar Loom Transcript para recuperar transcripciones de video con nuestra guía paso a paso","fr":"Découvrez comment configurer Loom Transcript pour récupérer des transcriptions vidéo avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Loom Transcript konfigurieren, um Videotranskripte abzurufen, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a usar a ferramenta de transcrição de vídeo Loom Transcript para extrair texto de vídeos Loom. Veja como configurar e usar essa ferramenta poderosa.","ru":"Узнайте, как использовать инструмент транскрипции видео Loom Transcript для извлечения текста из видео Loom. См. руководство по настройке и использованию.","ar":"تعرف على كيفية استخدام أداة نص لوم لاستخراج النص من مقاطع الفيديو لوم. انظر دليل الإعداد والاستخدام."},"definition":{"en":"loom-transcript is a skill that fetches and displays the full transcript from a Loom video URL using Loom''s GraphQL API.","zh":"Loom Transcript Fetcher 是一个 AI 工具，用于从 Loom 视频 URL 中获取和显示全文转录。","ja":"Loom トランスクリプト フェッチャーは、Loom ビデオ URL から全文のトランスクリプトを取得して表示する AI エージェントです。","ko":"Loom Transcript Fetcher는 Loom 비디오 URL에서 전체 전사본을 가져와 표시하는 AI 에이전트입니다.","es":"Loom Transcript es un agente de inteligencia artificial que extrae transcripciones de video de Loom","fr":"Loom Transcript est un agent d''intelligence artificielle qui extrait des transcriptions de vidéo Loom","de":"Loom Transcript ist ein KI-Tool, das Videotranskripte von Loom extrahiert","pt":"O Loom Transcript é uma ferramenta que extrai transcrições de vídeos Loom usando a API GraphQL do Loom.","ru":"Loom Transcript - это инструмент, который извлекает транскрипции видео Loom с помощью GraphQL API Loom.","ar":"أداة نص لوم هي أداة تستخرج النصوص من مقاطع الفيديو لوم باستخدام واجهة برمجة التطبيقات الرسومية لوم."},"features":{"en":["Extracts 32-character hex video ID from Loom URL","Supports multiple URL formats, including https://www.loom.com/share/<video-id> and https://www.loom.com/embed/<video-id>","Fetches video metadata using Loom''s GraphQL API","Displays full transcript from Loom video","Compatible with low-code and no-code platforms, including n8n and TypeScript","Enables workflow automation using MCP and IPAAS integrations"],"zh":["使用 Loom 的 GraphQL API 获取全文转录","支持多种 URL 格式，包括 https://www.loom.com/share/<video-id> 和 https://www.loom.com/embed/<video-id>","可以提取 32 个字符的 hex 视频 ID","支持 TypeScript 和 n8n 等低代码平台","可以与其他工具和服务集成，实现自动化工作流"],"ja":["Loom の GraphQL API を使用して全文のトランスクリプトを取得","複数の URL フォーマットをサポートし、https://www.loom.com/share/<video-id> と https://www.loom.com/embed/<video-id> を含む","32 文字の hex ビデオ ID を抽出","TypeScript と n8n などの低コードプラットフォームをサポート","他のツールやサービスと統合して自動化されたワークフローを実現"],"ko":["Loom의 GraphQL API를 사용하여 전체 전사본을 가져옵니다","여러 URL 형식을 지원하며 https://www.loom.com/share/<video-id> 와 https://www.loom.com/embed/<video-id> 를 포함합니다","32개의 문자 hex 비디오 ID를 추출합니다","TypeScript와 n8n 등의 저코드 플랫폼을 지원합니다","다른 툴과 서비스와 통합하여 자동화된 워크플로우를 구현할 수 있습니다"],"es":["Soporte para formatos de URL de Loom","Extracción de ID de video de 32 caracteres","Uso de la API de GraphQL de Loom","Recuperación de metadatos de video","Compatibilidad con TypeScript y n8n"],"fr":["Prise en charge des formats d''URL Loom","Extraction de l''ID de vidéo de 32 caractères","Utilisation de l''API GraphQL Loom","Récupération de métadonnées de vidéo","Compatibilité avec TypeScript et n8n"],"de":["Unterstützung für Loom-URL-Formate","Extraktion der 32-zeichen Video-ID","Verwendung der Loom GraphQL-API","Abruf von Videometadaten","Kompatibilität mit TypeScript und n8n"],"pt":["Extração de transcrições de vídeos Loom usando a API GraphQL do Loom","Suporte a URLs de vídeo Loom no formato https://www.loom.com/share/<video-id>","Suporte a URLs de vídeo Loom no formato https://www.loom.com/embed/<video-id>","Extração do ID de vídeo de 32 caracteres a partir da URL do vídeo Loom","Uso da CLI para executar a ferramenta","Desenvolvido em TypeScript"],"ru":["Извлечение транскрипций видео Loom с помощью GraphQL API Loom","Поддержка URL видео Loom в формате https://www.loom.com/share/<video-id>","Поддержка URL видео Loom в формате https://www.loom.com/embed/<video-id>","Извлечение идентификатора видео из 32 символов из URL видео Loom","Использование CLI для выполнения инструмента","Разработано на TypeScript"],"ar":["استخراج النصوص من مقاطع الفيديو لوم باستخدام واجهة برمجة التطبيقات الرسومية لوم","دعم عناوين_URL لمقاطع الفيديو لوم بالتنسيق https://www.loom.com/share/<video-id>","دعم عناوين_URL لمقاطع الفيديو لوم بالتنسيق https://www.loom.com/embed/<video-id>","استخراج معرف الفيديو من 32 حرفا من عنوان_URL الفيديو لوم","استخدام واجهة سطر الأوامر لتشغيل الأداة","تم تطويره باستخدام TypeScript"]},"keywords":{"en":["how to use loom-transcript","loom-transcript setup guide","what is loom-transcript","loom-transcript alternative","loom-transcript vs n8n","loom-transcript install","graphql api transcript fetcher","loom video transcript fetcher","ai agent skill for loom transcript"],"zh":["Loom Transcript Fetcher","GraphQL API","低代码平台","n8n","TypeScript","视频转录","AI 工具","自动化工作流"],"ja":["Loom トランスクリプト フェッチャー","GraphQL API","低コードプラットフォーム","n8n","TypeScript","ビデオトランスクリプト","AI エージェント","自動化されたワークフロー"],"ko":["Loom Transcript Fetcher","GraphQL API","저코드 플랫폼","n8n","TypeScript","비디오 전사","AI 에이전트","자동화된 워크플로우"],"es":["Loom Transcript","agente de inteligencia artificial","extracción de transcripciones de video","API de GraphQL","TypeScript","n8n","automatización de flujo de trabajo","Herramientas de desarrollo"],"fr":["Loom Transcript","agent d''intelligence artificielle","extraction de transcriptions de vidéo","API GraphQL","TypeScript","n8n","automatisation de flux de travail","Outils de développement"],"de":["Loom Transcript","KI-Tool","Videotranskript-Extraktion","GraphQL-API","TypeScript","n8n","Workflow-Automatisierung","Entwicklungstools"],"pt":["Loom Transcript","Extração de transcrições de vídeo","API GraphQL do Loom","CLI","TypeScript","Desenvolvimento de software","Ferramentas de desenvolvimento","Integração de APIs","Automatização de fluxo de dados"],"ru":["Loom Transcript","Извлечение транскрипций видео","GraphQL API Loom","CLI","TypeScript","Разработка программного обеспечения","Инструменты разработки","Интеграция API","Автоматизация потока данных"],"ar":["أداة نص لوم","استخراج النصوص من مقاطع الفيديو","واجهة برمجة التطبيقات الرسومية لوم","واجهة سطر الأوامر","TypeScript","تطوير البرمجيات","أدوات التطوير","تكامل واجهات برمجة التطبيقات","أتمتة تدفق البيانات"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Content Analysis Agents that need to extract and process spoken content from Loom videos.","zh":"适用于需要从 Loom 视频中提取和处理语音内容的内容分析代理。","ja":"Loom ビデオからの音声コンテンツを抽出および処理する必要があるコンテンツ分析エージェントに最適。","ko":"Loom 비디오의 음성 콘텐츠를 추출하고 처리해야 하는 콘텐츠 분석 에이전트에 적합합니다.","es":"Ideal para Content Analysis Agents que necesitan extraer y procesar contenido hablado de videos de Loom.","fr":"Idéal pour les Content Analysis Agents qui doivent extraire et traiter le contenu parlé des vidéos Loom.","de":"Ideal für Content Analysis Agents, die gesprochene Inhalte aus Loom-Videos extrahieren und verarbeiten müssen.","pt":"Ideal para Agentes de Análise de Conteúdo que precisam extrair e processar conteúdo falado de vídeos do Loom.","ru":"Идеально подходит для агентов анализа контента, которым необходимо извлекать и обрабатывать устный контент из видео Loom.","ar":"مثالي لوكلاء تحليل المحتوى الذين يحتاجون إلى استخراج ومعالجة المحتوى المنطوق من مقاطع فيديو Loom."},"recommendation":{"en":"Enables agents to programmatically retrieve full video transcripts through Loom''s GraphQL API, extracting the 32-character hex video ID from various URL formats including share and embed patterns. This provides structured text data from video content for downstream processing and analysis.","zh":"使代理能够通过 Loom 的 GraphQL API 编程方式检索完整的视频转录，提取来自各种 URL 格式（包括共享和嵌入模式）的 32 个字符的十六进制视频 ID。这为视频内容的下游处理和分析提供了结构化的文本数据。","ja":"Loom の GraphQL API を使用して、エージェントがプログラムでフルビデオのトランスクリプトを取得できるようにします。共有および埋め込みパターンを含むさまざまな URL フォーマットからの 32 文字の 16 進数ビデオ ID を抽出します。これにより、ビデオ コンテンツの下流処理および分析のための構造化テキスト データが提供されます。","ko":"에이전트가 Loom의 GraphQL API를 통해 전체 비디오 자막을 프로그래밍 방식으로检索할 수 있도록 합니다. 공유 및 임베드 패턴을 포함한 다양한 URL 형식에서 32자리 16진수 비디오 ID를 추출합니다. 이는 비디오 콘텐츠의 하위 처리 및 분석을 위한 구조화된 텍스트 데이터를 제공합니다.","es":"Permite a los agentes recuperar mediante programación transcripciones completas de video a través de la GraphQL API de Loom, extrayendo el ID de video hexadecimal de 32 caracteres de varios formatos de URL, incluidos los patrones share y embed. Esto proporciona datos de texto estructurados del contenido de video para su posterior procesamiento y análisis.","fr":"Permet aux agents de récupérer programmatiquement des transcriptions vidéo complètes via la GraphQL API de Loom, en extrayant l''ID vidéo hexadécimal de 32 caractères à partir de divers formats d''URL, y compris les modèles de partage (share) et d''intégration (embed). Cela fournit des données textuelles structurées à partir du contenu vidéo pour un traitement et une analyse en aval.","de":"Ermöglicht es Agents, programmgesteuert vollständige Videotranskripte über die GraphQL API von Loom abzurufen, indem die 32-stellige hexadezimale Video-ID aus verschiedenen URL-Formaten extrahiert wird, einschließlich Share- und Embed-Muster. Dies liefert strukturierte Textdaten aus Videoinhalten für die nachgelagerte Verarbeitung und Analyse.","pt":"Permite que os agentes recuperem programaticamente transcrições completas de vídeo através da API GraphQL do Loom, extraindo o ID de vídeo hexadecimal de 32 caracteres de vários formatos de URL, incluindo padrões de compartilhamento e incorporação. Isso fornece dados de texto estruturados a partir do conteúdo de vídeo para processamento e análise downstream.","ru":"Позволяет агентам программно извлекать полные расшифровки видео через GraphQL API Loom, извлекая 32-символьный шестнадцатеричный идентификатор видео из различных форматов URL, включая шаблоны общего доступа и встраивания. Это предоставляет структурированные текстовые данные из видеоконтента для последующей обработки и анализа.","ar":"يمكن الوكلاء من استرداد نصوص الفيديو الكاملة برمجيًا من خلال GraphQL API الخاص بـ Loom، واستخراج معرف الفيديو السداسي العشري المكون من 32 حرفًا من تنسيقات URL المختلفة بما في ذلك أنماط المشاركة والتضمين. وهذا يوفر بيانات نصية منظمة من محتوى الفيديو للمعالجة والتحليل اللاحقين."},"useCases":{"en":["Extracting meeting notes from recorded Loom presentations","Analyzing customer feedback from video testimonials","Generating text summaries from training videos","Creating searchable archives of video content"],"zh":["从记录的 Loom 演示中提取会议记录","从视频推荐中分析客户反馈","从培训视频生成文本摘要","创建可搜索的视频内容存档"],"ja":["記録された Loom プレゼンテーションからミーティング ノートを抽出","ビデオ テストから顧客 フィードバックを分析","トレーニング ビデオからテキスト サマリーを生成","検索可能なビデオ コンテンツ アーカイブを作成"],"ko":["녹화된 Loomプレゼンテ이션에서 회의록 추출","비디오 추천에서 고객 피드백 분석","교육 비디오에서 텍스트 요약 생성","검색 가능한 비디오 콘텐츠 아카이브 생성"],"es":["Extraer notas de reuniones de presentaciones grabadas en Loom","Analizar comentarios de clientes de testimonios en video","Generar resúmenes de texto a partir de videos de capacitación","Crear archivos buscables de contenido de video"],"fr":["Extraire les notes de réunion à partir de présentations Loom enregistrées","Analyser les retours clients à partir de témoignages vidéo","Générer des résumés textuels à partir de vidéos de formation","Créer des archives consultables de contenu vidéo"],"de":["Extrahieren von Besprechungsnotizen aus aufgezeichneten Loom-Präsentationen","Analysieren von Kundenfeedback aus Video-Testimonials","Erstellen von Textzusammenfassungen aus Schulungsvideos","Erstellen durchsuchbarer Archive von Videoinhalten"],"pt":["Extrair notas de reuniões de apresentações Loom gravadas","Analisar feedback de clientes de depoimentos em vídeo","Gerar resumos em texto de vídeos de treinamento","Criar arquivos pesquisáveis de conteúdo de vídeo"],"ru":["Извлечение заметок встреч из записанных презентаций Loom","Анализ отзывов клиентов из видео-отзывов","Создание текстовых сводок из обучающих видео","Создание доступных для поиска архивов видеоконтента"],"ar":["استخراج ملاحظات الاجتماع من العروض التقديمية المسجلة في Loom","تحليل ملاحظات العملاء من شهادات الفيديو","إنشاء ملخصات نصية من مقاطع الفيديو التدريبية","إنشاء أرشيفات قابلة للبحث لمحتوى الفيديو"]},"limitations":{"en":["Requires valid Loom video URL with accessible transcript","Depends on Loom''s GraphQL API stability","Only supports specific URL formats (/share/ and /embed/)"],"zh":["需要有效的 Loom 视频 URL 和可访问的转录","依赖 Loom 的 GraphQL API 的稳定性","仅支持特定的 URL 格式 (/share/ 和 /embed/)"],"ja":["有効な Loom ビデオ URL およびアクセス可能なトランスクリプトが必要","Loom の GraphQL API の安定性に依存","特定の URL フォーマット (/share/ および /embed/) のみをサポート"],"ko":["유효한 Loom 비디오 URL 및 접근 가능한 자막이 필요함","Loom의 GraphQL API 안정성에 의존함","특정 URL 형식(/share/ 및 /embed/)만 지원"],"es":["Requiere una URL de video de Loom válida con transcripción accesible","Depende de la estabilidad de la GraphQL API de Loom","Solo admite formatos de URL específicos (/share/ y /embed/)"],"fr":["Nécessite une URL de vidéo Loom valide avec une transcription accessible","Dépend de la stabilité de la GraphQL API de Loom","Prend uniquement en charge des formats d''URL spécifiques (/share/ et /embed/)"],"de":["Erfordert eine gültige Loom-Video-URL mit zugänglichem Transkript","Hängt von der Stabilität der GraphQL API von Loom ab","Unterstützt nur bestimmte URL-Formate (/share/ und /embed/)"],"pt":["Requer um URL de vídeo do Loom válido com transcrição acessível","Depende da estabilidade da API GraphQL do Loom","Suporta apenas formatos de URL específicos (/share/ e /embed/)"],"ru":["Требуется действительный URL-адрес видео Loom с доступной расшифровкой","Зависит от стабильности GraphQL API Loom","Поддерживает только определенные форматы URL (/share/ и /embed/)"],"ar":["يتطلب عنوان URL صالح لفيديو Loom مع نص مترجم يمكن الوصول إليه","يعتمد على استقرار GraphQL API الخاص بـ Loom","يدعم فقط تنسيقات URL محددة (/share/ و /embed/)"]},"version":4},"contentHash":"f9a0e0f8348bf0c2cf509916c84a3a00ab06f91b3230015620f11e3a530ecdca","repoEtag":"W/\"3826f18d1894df306122a172f629759ce7b1aa3bff04dbe05feba05281ded220\"","qualityScore":92}');
