INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/building-mcp-server-on-cloudflare', 'building-mcp-server-on-cloudflare', 'cloudflare', 'skills', 'official', 'building-mcp-server-on-cloudflare cloudflare skills official agents cloudflare skills workers The building-mcp-server-on-cloudflare skill enables developers to set up MCP servers on Cloudflare using Workers integration. It provides retrieval sources for server setup, auth, and deployment. 本指南介绍如何在 Cloudflare 上搭建 MCP 服务器，包括设置、认证和部署 このガイドでは、Cloudflare 上の MCP サーバーの設定、認証、デプロイについて説明します 이 튜토리얼에서는 Cloudflare에서 MCP 서버를 설정하는 방법, 인증, 배포에 대해 설명합니다 Configura un servidor MCP en Cloudflare utilizando Workers y MCP SDK. Aprende a utilizar las fuentes de recuperación para tareas de servidor MCP. Configurez un serveur MCP sur Cloudflare en utilisant Workers et MCP SDK. Découvrez comment utiliser les sources de récupération pour les tâches de serveur MCP. Richten Sie einen MCP-Server auf Cloudflare mit Workers und MCP SDK ein. Erfahren Sie, wie Sie die Retrieval-Quellen für MCP-Server-Aufgaben verwenden. Configurar um servidor MCP na Cloudflare é mais fácil com nossa guia. Aprenda a integrar com Workers e MCP SDK para uma solução personalizada Настройка сервера MCP на Cloudflare стала проще с нашей инструкцией. Узнайте, как интегрировать с Workers и MCP SDK для индивидуального решения إعداد خادم MCP على Cloudflare أصبح أسهل مع دليلنا. تعلم كيفية التكامل مع Workers و MCP SDK للحصول على حل مخصص how to build MCP server on Cloudflare building-mcp-server-on-cloudflare setup guide Cloudflare Workers MCP SDK integration what is building-mcp-server-on-cloudflare building-mcp-server-on-cloudflare vs traditional MCP servers building-mcp-server-on-cloudflare install and configure Cloudflare MCP 服务器 MCP SDK Cloudflare Workers 服务器设置 认证 部署 MCP 文档 Workers 文档 Retrieves MCP server setup information from https://developers.cloudflare.com/agents/mcp/ Utilizes Cloudflare Workers for MCP server deployment Follows the Model Context Protocol (MCP) spec from https://modelcontextprotocol.io/ Supports authentication and deployment using MCP SDK Provides integration with Workers docs for further customization building-mcp-server-on-cloudflare is a skill that integrates Cloudflare Workers with the MCP SDK for building MCP servers on Cloudflare');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/building-ai-agent-on-cloudflare', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'building-ai-agent-on-cloudflare', 535, 66, 92, '2026-03-06T05:33:24Z', '2026-03-06T05:52:49.079Z', '31554ff30e2edb8c2dc9bd5fba15438691fb07f3541f0a0cc843b6a13cdaa573', '{"id":"cloudflare/skills/building-ai-agent-on-cloudflare","name":"building-ai-agent-on-cloudflare","description":{"en":"This skill enables developers to build and deploy AI agents on Cloudflare''s global network using the Agents SDK. It provides tools for creating, managing, and scaling AI agents with serverless architecture.","zh":"本文介绍了在Cloudflare上构建AI代理的技术细节，包括使用Agents SDK和Workers实现平台集成和部署","ja":"本文では、CloudflareでAIエージェントを構築する技術的な詳細について説明し、Agents SDKとWorkersを使用したプラットフォームの統合とデプロイについて紹介する","ko":"본 문서에서는 클라우드플레어에서 AI 에이전트를 구축하는 기술적인 세부 사항을介绍하며 Agents SDK와 Workers를 사용한 플랫폼 통합과 배포에 대해 설명한다","es":"Construye agentes de inteligencia artificial en Cloudflare utilizando el SDK de Agents y Workers. Aprende a integrar plataformas y desplegar soluciones.","fr":"Créez des agents d''intelligence artificielle sur Cloudflare en utilisant le SDK Agents et Workers. Apprenez à intégrer des plateformes et à déployer des solutions.","de":"Erstellen Sie KI-Agents auf Cloudflare mit dem Agents-SDK und Workers. Lernen Sie, Plattformen zu integrieren und Lösungen bereitzustellen.","pt":"Crie um agente de IA personalizado na Cloudflare utilizando o Agents SDK e Workers. Aprenda a integrar e implantar com sucesso.","ru":"Создайте собственного ИИ Агента на Cloudflare, используя Agents SDK и Workers. Узнайте, как интегрировать и развертывать.","ar":"أنشئ وكيل ذكاء اصطناعي مخصص على كلاودفلير باستخدام Agents SDK وووركرز. تعلم كيفية التكامل والنشر بنجاح"},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"building-ai-agent-on-cloudflare","description":"|","bodyPreview":"# Building Cloudflare Agents\n\nYour knowledge of the Agents SDK may be outdated. **Prefer retrieval over pre-training** for any agent-building task.\n\n## Retrieval Sources\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| Agents SDK docs | `https://github.com/cloudflare/agents/tree/main/docs` | SDK API, state, routing, scheduling |\n| Cloudflare Agents docs | `https://developers.cloudflare.com/agents/` | Platform integration, deployment |\n| Workers docs | Search tool o","body":"# Building Cloudflare Agents\n\nYour knowledge of the Agents SDK may be outdated. **Prefer retrieval over pre-training** for any agent-building task.\n\n## Retrieval Sources\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| Agents SDK docs | `https://github.com/cloudflare/agents/tree/main/docs` | SDK API, state, routing, scheduling |\n| Cloudflare Agents docs | `https://developers.cloudflare.com/agents/` | Platform integration, deployment |\n| Workers docs | Search tool or `https://developers.cloudflare.com/workers/` | Runtime APIs, bindings, config |\n\n## When to Use\n\n- User wants to build an AI agent or chatbot\n- User needs stateful, real-time AI interactions\n- User asks about the Cloudflare Agents SDK\n- User wants scheduled tasks or background AI work\n- User needs WebSocket-based AI communication\n\n## Prerequisites\n\n- Cloudflare account with Workers enabled\n- Node.js 18+ and npm/pnpm/yarn\n- Wrangler CLI (`npm install -g wrangler`)\n\n## Quick Start\n\n```bash\nnpm create cloudflare@latest -- my-agent --template=cloudflare/agents-starter\ncd my-agent\nnpm start\n```\n\nAgent runs at `http://localhost:8787`\n\n## Core Concepts\n\n### What is an Agent?\n\nAn Agent is a stateful, persistent AI service that:\n- Maintains state across requests and reconnections\n- Communicates via WebSockets or HTTP\n- Runs on Cloudflare''s edge via Durable Objects\n- Can schedule tasks and call tools\n- Scales horizontally (each user/session gets own instance)\n\n### Agent Lifecycle\n\n```\nClient connects → Agent.onConnect() → Agent processes messages\n                                    → Agent.onMessage()\n                                    → Agent.setState() (persists + syncs)\nClient disconnects → State persists → Client reconnects → State restored\n```\n\n## Basic Agent Structure\n\n```typescript\nimport { Agent, Connection } from \"agents\";\n\ninterface Env {\n  AI: Ai;  // Workers AI binding\n}\n\ninterface State {\n  messages: Array<{ role: string; content: string }>;\n  preferences: Record<string, string>;\n}\n\nexport class MyAgent extends Agent<Env, State> {\n  // Initial state for new instances\n  initialState: State = {\n    messages: [],\n    preferences: {},\n  };\n\n  // Called when agent starts or resumes\n  async onStart() {\n    console.log(\"Agent started with state:\", this.state);\n  }\n\n  // Handle WebSocket connections\n  async onConnect(connection: Connection) {\n    connection.send(JSON.stringify({\n      type: \"welcome\",\n      history: this.state.messages,\n    }));\n  }\n\n  // Handle incoming messages\n  async onMessage(connection: Connection, message: string) {\n    const data = JSON.parse(message);\n\n    if (data.type === \"chat\") {\n      await this.handleChat(connection, data.content);\n    }\n  }\n\n  // Handle disconnections\n  async onClose(connection: Connection) {\n    console.log(\"Client disconnected\");\n  }\n\n  // React to state changes\n  onStateUpdate(state: State, source: string) {\n    console.log(\"State updated by:\", source);\n  }\n\n  private async handleChat(connection: Connection, userMessage: string) {\n    // Add user message to history\n    const messages = [\n      ...this.state.messages,\n      { role: \"user\", content: userMessage },\n    ];\n\n    // Call AI\n    const response = await this.env.AI.run(\"@cf/meta/llama-3-8b-instruct\", {\n      messages,\n    });\n\n    // Update state (persists and syncs to all clients)\n    this.setState({\n      ...this.state,\n      messages: [\n        ...messages,\n        { role: \"assistant\", content: response.response },\n      ],\n    });\n\n    // Send response\n    connection.send(JSON.stringify({\n      type: \"response\",\n      content: response.response,\n    }));\n  }\n}\n```\n\n## Entry Point Configuration\n\n```typescript\n// src/index.ts\nimport { routeAgentRequest } from \"agents\";\nimport { MyAgent } from \"./agent\";\n\nexport default {\n  async fetch(request: Request, env: Env) {\n    // routeAgentRequest handles routing to /agents/:class/:name\n    return (\n      (await routeAgentRequest(request, env)) ||\n      new Response(\"Not found\", { status: 404 })\n    );\n  },\n};\n\nexport { MyAgent };\n```\n\nClients connect via: `wss://my-agent.workers.dev/agents/MyAgent/session-id`\n\n## Wrangler Configuration\n\n```toml\nname = \"my-agent\"\nmain = \"src/index.ts\"\ncompatibility_date = \"2024-12-01\"\n\n[ai]\nbinding = \"AI\"\n\n[durable_objects]\nbindings = [{ name = \"AGENT\", class_name = \"MyAgent\" }]\n\n[[migrations]]\ntag = \"v1\"\nnew_classes = [\"MyAgent\"]\n```\n\n## State Management\n\n### Reading State\n\n```typescript\n// Current state is always available\nconst currentMessages = this.state.messages;\nconst userPrefs = this.state.preferences;\n```\n\n### Updating State\n\n```typescript\n// setState persists AND syncs to all connected clients\nthis.setState({\n  ...this.state,\n  messages: [...this.state.messages, newMessage],\n});\n\n// Partial updates work too\nthis.setState({\n  preferences: { ...this.state.preferences, theme: \"dark\" },\n});\n```\n\n### SQL Storage\n\nFor complex queries, use the embedded SQLite database:\n\n```typescript\n// Create tables\nawait this.sql`\n  CREATE TABLE IF NOT EXISTS documents (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    title TEXT NOT NULL,\n    content TEXT,\n    created_at DATETIME DEFAULT CURRENT_TIMESTAMP\n  )\n`;\n\n// Insert\nawait this.sql`\n  INSERT INTO documents (title, content)\n  VALUES (${title}, ${content})\n`;\n\n// Query\nconst docs = await this.sql`\n  SELECT * FROM documents WHERE title LIKE ${`%${search}%`}\n`;\n```\n\n## Scheduled Tasks\n\nAgents can schedule future work:\n\n```typescript\nasync onMessage(connection: Connection, message: string) {\n  const data = JSON.parse(message);\n\n  if (data.type === \"schedule_reminder\") {\n    // Schedule task for 1 hour from now\n    const { id } = await this.schedule(3600, \"sendReminder\", {\n      message: data.reminderText,\n      userId: data.userId,\n    });\n\n    connection.send(JSON.stringify({ type: \"scheduled\", taskId: id }));\n  }\n}\n\n// Called when scheduled task fires\nasync sendReminder(data: { message: string; userId: string }) {\n  // Send notification, email, etc.\n  console.log(`Reminder for ${data.userId}: ${data.message}`);\n\n  // Can also update state\n  this.setState({\n    ...this.state,\n    lastReminder: new Date().toISOString(),\n  });\n}\n```\n\n### Schedule Options\n\n```typescript\n// Delay in seconds\nawait this.schedule(60, \"taskMethod\", { data });\n\n// Specific date\nawait this.schedule(new Date(\"2025-01-01T00:00:00Z\"), \"taskMethod\", { data });\n\n// Cron expression (recurring)\nawait this.schedule(\"0 9 * * *\", \"dailyTask\", {});  // 9 AM daily\nawait this.schedule(\"*/5 * * * *\", \"everyFiveMinutes\", {});  // Every 5 min\n\n// Manage schedules\nconst schedules = await this.getSchedules();\nawait this.cancelSchedule(taskId);\n```\n\n## Chat Agent (AI-Powered)\n\nFor chat-focused agents, extend `AIChatAgent`:\n\n```typescript\nimport { AIChatAgent } from \"agents/ai-chat-agent\";\n\nexport class ChatBot extends AIChatAgent<Env> {\n  // Called for each user message\n  async onChatMessage(message: string) {\n    const response = await this.env.AI.run(\"@cf/meta/llama-3-8b-instruct\", {\n      messages: [\n        { role: \"system\", content: \"You are a helpful assistant.\" },\n        ...this.messages,  // Automatic history management\n        { role: \"user\", content: message },\n      ],\n      stream: true,\n    });\n\n    // Stream response back to client\n    return response;\n  }\n}\n```\n\nFeatures included:\n- Automatic message history\n- Resumable streaming (survives disconnects)\n- Built-in `saveMessages()` for persistence\n\n## Client Integration\n\n### React Hook\n\n```tsx\nimport { useAgent } from \"agents/react\";\n\nfunction Chat() {\n  const { state, send, connected } = useAgent({\n    agent: \"my-agent\",\n    name: userId,  // Agent instance ID\n  });\n\n  const sendMessage = (text: string) => {\n    send(JSON.stringify({ type: \"chat\", content: text }));\n  };\n\n  return (\n    <div>\n      {state.messages.map((msg, i) => (\n        <div key={i}>{msg.role}: {msg.content}</div>\n      ))}\n      <input onKeyDown={(e) => e.key === \"Enter\" && sendMessage(e.target.value)} />\n    </div>\n  );\n}\n```\n\n### Vanilla JavaScript\n\n```javascript\nconst ws = new WebSocket(\"wss://my-agent.workers.dev/agents/MyAgent/user123\");\n\nws.onopen = () => {\n  console.log(\"Connected to agent\");\n};\n\nws.onmessage = (event) => {\n  const data = JSON.parse(event.data);\n  console.log(\"Received:\", data);\n};\n\nws.send(JSON.stringify({ type: \"chat\", content: \"Hello!\" }));\n```\n\n## Common Patterns\n\nSee [references/agent-patterns.md](references/agent-patterns.md) for:\n- Tool calling and function execution\n- Multi-agent orchestration\n- RAG (Retrieval Augmented Generation)\n- Human-in-the-loop workflows\n\n## Deployment\n\n```bash\n# Deploy\nnpx wrangler deploy\n\n# View logs\nwrangler tail\n\n# Test endpoint\ncurl https://my-agent.workers.dev/agents/MyAgent/test-user\n```\n\n## Troubleshooting\n\nSee [references/troubleshooting.md](references/troubleshooting.md) for common issues.\n\n## References\n\n- [references/examples.md](references/examples.md) — Official templates and production examples\n- [references/agent-patterns.md](references/agent-patterns.md) — Advanced patterns\n- [references/state-patterns.md](references/state-patterns.md) — State management strategies\n- [references/troubleshooting.md](references/troubleshooting.md) — Error solutions\n"},"category":"official","lastSynced":"2026-03-06T05:52:49.079Z","seo":{"title":{"en":"Building AI Agents on Cloudflare: Developer Setup Guide |...","zh":"Cloudflare AI代理构建设置指南","ja":"Cloudflare AIエージェント構築ベストプラクティス","ko":"클라우드플레어 AI 에이전트 구축 가이드","es":"Guía de configuración de agentes de inteligencia artifici...","fr":"Guide de mise en place d''agents d''intelligence artificiel...","de":"Einrichtungsleitfaden für KI-Agents auf Cloudflare","pt":"Guia de Configuração de Agente de IA na Cloudflare","ru":"Руководство по настройке ИИ Агентов на Cloudflare","ar":"دليل إعداد وإنشاء وكيل ذكاء اصطناعي على كلاودفلير"},"description":{"en":"Learn how to deploy AI agents on Cloudflare Workers using the Agents SDK. Includes setup steps, API endpoints, and code examples for developers.","zh":"了解如何在Cloudflare上构建AI代理，使用Agents SDK和Workers，实现高效的平台集成和部署","ja":"CloudflareでAIエージェントを構築する方法を学び、Agents SDKとWorkersを使用してプラットフォームの統合とデプロイを効率化する","ko":"클라우드플레어에서 AI 에이전트를 구축하는 방법을 알아보고 Agents SDK와 Workers를 사용하여 플랫폼 통합과 배포를 효율화하는 방법","es":"Aprende a construir agentes de inteligencia artificial en Cloudflare con nuestra guía paso a paso. Descubre cómo aprovechar el SDK de Agents y Workers.","fr":"Découvrez comment créer des agents d''intelligence artificielle sur Cloudflare avec notre guide étape par étape. Apprenez à utiliser le SDK Agents et Workers.","de":"Erfahren Sie, wie Sie KI-Agents auf Cloudflare erstellen, mit unserer Schritt-für-Schritt-Anleitung. Entdecken Sie, wie Sie das Agents-SDK und Workers nutzen...","pt":"Aprenda a criar agente de IA na Cloudflare com nossa guia passo a passo, incluindo integração com Workers e SDK","ru":"Узнайте, как создать ИИ Агента на Cloudflare с нашей пошаговой инструкцией, включая интеграцию с Workers и SDK","ar":"تعرف على كيفية إنشاء وكيل ذكاء اصطناعي على كلاودفلير بخطوات بسيطة، بما في ذلك التكامل مع ووركرز و SDK"},"definition":{"en":"Building AI Agents on Cloudflare is a developer skill that uses the Agents SDK to create and deploy AI agents on Cloudflare Workers. It includes tools for routing, state management, and integration with Cloudflare''s serverless platform.","zh":"Cloudflare AI代理是使用Agents SDK和Workers构建的智能代理，实现高效的平台集成和部署","ja":"Cloudflare AIエージェントは、Agents SDKとWorkersを使用して構築されたスマートエージェントであり、プラットフォームの統合とデプロイを効率化する","ko":"클라우드플레어 AI 에이전트는 Agents SDK와 Workers를 사용하여 구축된 스마트 에이전트로 플랫폼 통합과 배포를 효율화한다","es":"Un agente de inteligencia artificial en Cloudflare es un software que utiliza el SDK de Agents para automatizar tareas y procesos.","fr":"Un agent d''intelligence artificielle sur Cloudflare est un logiciel qui utilise le SDK Agents pour automatiser des tâches et des processus.","de":"Ein KI-Agents auf Cloudflare ist eine Software, die das Agents-SDK nutzt, um Aufgaben und Prozesse zu automatisieren.","pt":"Um agente de IA na Cloudflare é um software que utiliza o Agents SDK para automatizar tarefas e processos na plataforma","ru":"ИИ Агент на Cloudflare - это программное обеспечение, использующее Agents SDK для автоматизации задач и процессов на платформе","ar":"وكيل ذكاء اصطناعي على كلاودفلير هو برنامج يستخدم Agents SDK لتنفيذ العمليات والأتمتة على المنصة"},"features":{"en":["Agents SDK integration for AI agent development","Cloudflare Workers deployment for serverless execution","State management and routing capabilities","Integration with Cloudflare''s developer platform","Support for multiple AI models and frameworks"],"zh":["使用Agents SDK实现代理构建","使用Workers实现平台集成和部署","支持SDK API、状态、路由和调度","提供文档和搜索工具以便于开发"],"ja":["Agents SDKを使用してエージェントを構築する","Workersを使用してプラットフォームの統合とデプロイを実現する","SDK API、状態、ルーティング、スケジューリングをサポートする","文書と検索ツールを提供して開発を容易にする"],"ko":["Agents SDK를 사용하여 에이전트를 구