INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/building-ai-agent-on-cloudflare', 'building-ai-agent-on-cloudflare', 'cloudflare', 'skills', 'official', 'building-ai-agent-on-cloudflare cloudflare skills official agents cloudflare skills workers This skill enables developers to build and deploy AI agents on Cloudflare''s global network using the Agents SDK. It provides tools for creating, managing, and scaling AI agents with serverless architecture. 本文介绍了在Cloudflare上构建AI代理的技术细节，包括使用Agents SDK和Workers实现平台集成和部署 本文では、CloudflareでAIエージェントを構築する技術的な詳細について説明し、Agents SDKとWorkersを使用したプラットフォームの統合とデプロイについて紹介する 본 문서에서는 클라우드플레어에서 AI 에이전트를 구축하는 기술적인 세부 사항을介绍하며 Agents SDK와 Workers를 사용한 플랫폼 통합과 배포에 대해 설명한다 Construye agentes de inteligencia artificial en Cloudflare utilizando el SDK de Agents y Workers. Aprende a integrar plataformas y desplegar soluciones. Créez des agents d''intelligence artificielle sur Cloudflare en utilisant le SDK Agents et Workers. Apprenez à intégrer des plateformes et à déployer des solutions. Erstellen Sie KI-Agents auf Cloudflare mit dem Agents-SDK und Workers. Lernen Sie, Plattformen zu integrieren und Lösungen bereitzustellen. Crie um agente de IA personalizado na Cloudflare utilizando o Agents SDK e Workers. Aprenda a integrar e implantar com sucesso. Создайте собственного ИИ Агента на Cloudflare, используя Agents SDK и Workers. Узнайте, как интегрировать и развертывать. أنشئ وكيل ذكاء اصطناعي مخصص على كلاودفلير باستخدام Agents SDK وووركرز. تعلم كيفية التكامل والنشر بنجاح Cloudflare AI agents Agents SDK setup Cloudflare Workers AI serverless AI deployment AI agent development Cloudflare developer tools AI routing on Cloudflare state management AI Cloudflare AI代理 Agents SDK Workers 平台集成 部署 智能代理 云计算 开发指南 Agents SDK integration for AI agent development Cloudflare Workers deployment for serverless execution State management and routing capabilities Integration with Cloudflare''s developer platform Support for multiple AI models and frameworks Building AI Agents on Cloudflare is a developer skill that uses the Agents SDK to create and deploy AI agents on Cloudflare Workers. It includes tools for routing, state management, and integration with Cloudflare''s serverless platform.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/pr-writer', 'official', 'getsentry', 'skills', 'getsentry/skills', 'pr-writer', 360, 11, 92, '2026-03-06T00:20:36Z', '2026-03-06T05:12:37.990Z', 'b18903219ba2881a6f0fa609abd7fc61779757b61a7223e9b0a8f3720deeeaac', '{"id":"getsentry/skills/pr-writer","name":"pr-writer","description":{"en":"The pr-writer skill automates pull request creation and editing for developers, following Sentry''s engineering practices and utilizing GitHub CLI. It ensures consistent PR titles, descriptions, and issue references.","zh":"PR Writer 是一个 AIエージェント，用于创建和更新 Pull Request，遵循 Sentry 的工程实践","ja":"PR Writer は、GitHub CLI を使用して Pull Request を作成および更新する AIエージェントです","ko":"PR Writer는 Sentry 규약을 준수하는 Pull Request를 생성하고 업데이트 하는 AI 에이전트입니다","es":"El skill pr-writer crea solicitudes de extracción en GitHub siguiendo las convenciones de Sentry. Requiere GitHub CLI autenticado","fr":"Le skill pr-writer crée des demandes d''extraction sur GitHub en suivant les conventions Sentry. Nécessite GitHub CLI authentifié","de":"Der pr-writer-Skill erstellt Pull-Requests auf GitHub nach Sentry-Konventionen. Benötigt authentifizierten GitHub CLI","pt":"O pr-writer é uma ferramenta que ajuda a criar solicitações de pull seguindo as convenções do Sentry, melhorando a colaboração em equipe e reduzindo erros","ru":"ИИ Агент pr-writer помогает создавать запросы на принятие изменений в соответствии с соглашениями Sentry, улучшая командную работу и снижая ошибки","ar":"أداة الذكاء الاصطناعي pr-writer تساعد في إنشاء طلبات السحب وفقًا لاتفاقيات Sentry، وتحسين التعاون الفريق وتقليل الأخطاء"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"pr-writer","description":"ALWAYS use this skill when creating or updating pull requests — never create or edit a PR directly without it. Follows Sentry conventions for PR titles, descriptions, and issue references. Trigger on any create PR, open PR, submit PR, make PR, update PR title, update PR description, edit PR, push and create PR, prepare changes for review task, or request for a PR writer.","bodyPreview":"# PR Writer\n\nCreate pull requests following Sentry''s engineering practices.\n\n**Requires**: GitHub CLI (`gh`) authenticated and available.\n\n## Prerequisites\n\nBefore creating a PR, ensure all changes are committed. If there are uncommitted changes, run the `sentry-skills:commit` skill first to commit them properly.\n\n```bash\n# Check for uncommitted changes\ngit status --porcelain\n```\n\nIf the output shows any uncommitted changes (modified, added, or untracked files that should be included), invoke th","body":"# PR Writer\n\nCreate pull requests following Sentry''s engineering practices.\n\n**Requires**: GitHub CLI (`gh`) authenticated and available.\n\n## Prerequisites\n\nBefore creating a PR, ensure all changes are committed. If there are uncommitted changes, run the `sentry-skills:commit` skill first to commit them properly.\n\n```bash\n# Check for uncommitted changes\ngit status --porcelain\n```\n\nIf the output shows any uncommitted changes (modified, added, or untracked files that should be included), invoke the `sentry-skills:commit` skill before proceeding.\n\n## Process\n\n### Step 1: Verify Branch State\n\n```bash\n# Detect the default branch — note the output for use in subsequent commands\ngh repo view --json defaultBranchRef --jq ''.defaultBranchRef.name''\n```\n\n```bash\n# Check current branch and status (substitute the detected branch name above for BASE)\ngit status\ngit log BASE..HEAD --oneline\n```\n\nEnsure:\n- All changes are committed\n- Branch is up to date with remote\n- Changes are rebased on the base branch if needed\n\n### Step 2: Analyze Changes\n\nReview what will be included in the PR:\n\n```bash\n# See all commits that will be in the PR (substitute detected branch name for BASE)\ngit log BASE..HEAD\n\n# See the full diff\ngit diff BASE...HEAD\n```\n\nUnderstand the scope and purpose of all changes before writing the description.\n\n### Step 3: Write the PR Description\n\nUse this structure for PR descriptions (ignoring any repository PR templates):\n\n```markdown\n<brief description of what the PR does>\n\n<why these changes are being made - the motivation>\n\n<alternative approaches considered, if any>\n\n<any additional context reviewers need>\n```\n\n**Do NOT include:**\n- \"Test plan\" sections\n- Checkbox lists of testing steps\n- Redundant summaries of the diff\n\n**Do include:**\n- Clear explanation of what and why\n- Links to relevant issues or tickets\n- Context that isn''t obvious from the code\n- Notes on specific areas that need careful review\n\n### Step 4: Create the PR\n\n```bash\ngh pr create --draft --title \"<type>(<scope>): <description>\" --body \"$(cat <<''EOF''\n<description body here>\nEOF\n)\"\n```\n\n**Title format** follows commit conventions:\n- `feat(scope): Add new feature`\n- `fix(scope): Fix the bug`\n- `ref: Refactor something`\n\n## PR Description Examples\n\n### Feature PR\n\n```markdown\nAdd Slack thread replies for alert notifications\n\nWhen an alert is updated or resolved, we now post a reply to the original\nSlack thread instead of creating a new message. This keeps related\nnotifications grouped and reduces channel noise.\n\nPreviously considered posting edits to the original message, but threading\nbetter preserves the timeline of events and works when the original message\nis older than Slack''s edit window.\n\nRefs SENTRY-1234\n```\n\n### Bug Fix PR\n\n```markdown\nHandle null response in user API endpoint\n\nThe user endpoint could return null for soft-deleted accounts, causing\ndashboard crashes when accessing user properties. This adds a null check\nand returns a proper 404 response.\n\nFound while investigating SENTRY-5678.\n\nFixes SENTRY-5678\n```\n\n### Refactor PR\n\n```markdown\nExtract validation logic to shared module\n\nMoves duplicate validation code from the alerts, issues, and projects\nendpoints into a shared validator class. No behavior change.\n\nThis prepares for adding new validation rules in SENTRY-9999 without\nduplicating logic across endpoints.\n```\n\n## Issue References\n\nReference issues in the PR body:\n\n| Syntax | Effect |\n|--------|--------|\n| `Fixes #1234` | Closes GitHub issue on merge |\n| `Fixes SENTRY-1234` | Closes Sentry issue |\n| `Refs GH-1234` | Links without closing |\n| `Refs LINEAR-ABC-123` | Links Linear issue |\n\n## Guidelines\n\n- **One PR per feature/fix** - Don''t bundle unrelated changes\n- **Keep PRs reviewable** - Smaller PRs get faster, better reviews\n- **Explain the why** - Code shows what; description explains why\n- **Mark WIP early** - Use draft PRs for early feedback\n\n## Editing Existing PRs\n\nIf you need to update a PR after creation, use `gh api` instead of `gh pr edit`:\n\n```bash\n# Update PR description\ngh api -X PATCH repos/{owner}/{repo}/pulls/PR_NUMBER -f body=\"$(cat <<''EOF''\nUpdated description here\nEOF\n)\"\n\n# Update PR title\ngh api -X PATCH repos/{owner}/{repo}/pulls/PR_NUMBER -f title=''new: Title here''\n\n# Update both\ngh api -X PATCH repos/{owner}/{repo}/pulls/PR_NUMBER \\\n  -f title=''new: Title'' \\\n  -f body=''New description''\n```\n\nNote: `gh pr edit` is currently broken due to GitHub''s Projects (classic) deprecation.\n\n## References\n\n- [Sentry Code Review Guidelines](https://develop.sentry.dev/engineering-practices/code-review/)\n- [Sentry Commit Messages](https://develop.sentry.dev/engineering-practices/commit-messages/)\n"},"category":"official","lastSynced":"2026-03-06T05:12:37.990Z","seo":{"title":{"en":"pr-writer: Automated Pull Request Management for AI Agent...","zh":"PR Writer Setup Guide - AIエージェント for Sentry Conventions","ja":"PR Writer ベストプラクティス - GitHub CLI を使用した AIエージェント","ko":"PR Writer 설정 가이드 - Sentry 규약을 위한 AI 에이전트","es":"Guía de configuración de pr-writer para GitHub CLI","fr":"Configurer pr-writer pour GitHub CLI - Meilleures pratiques","de":"Einrichtungsleitfaden für pr-writer mit GitHub CLI","pt":"Guia de Configuração do pr-writer para Desenvolvedores","ru":"Настройка ИИ Агента pr-writer: Руководство для Разработчиков","ar":"إعداد أداة الذكاء الاصطناعي pr-writer: دليل للمطورين"},"description":{"en":"Streamline your pull request workflow with pr-writer. Learn how to automate PR creation and editing with GitHub CLI and Sentry conventions.","zh":"使用 PR Writer AIエージェント自动化您的 Pull Request 流程，遵循 Sentry 的工程实践","ja":"PR Writer AIエージェントを使用して、GitHub CLI を活用した Pull Request の作成と更新を自動化する","ko":"PR Writer AI 에이전트를 사용하여 Sentry 규약을 준수하는 Pull Request를 자동화합니다","es":"Aprende a utilizar pr-writer para crear solicitudes de extracción en GitHub siguiendo las convenciones de Sentry","fr":"Découvrez comment configurer pr-writer pour créer des demandes d''extraction sur GitHub en suivant les conventions Sentry","de":"Erfahren Sie, wie Sie pr-writer einrichten, um Pull-Requests auf GitHub nach Sentry-Konventionen zu erstellen","pt":"Aprenda a configurar o pr-writer para criar solicitações de pull seguindo as convenções do Sentry e melhorar a colaboração em equipe","ru":"Узнайте, как настроить ИИ Агент pr-writer для создания запросов на принятие изменений в соответствии с соглашениями Sentry и улучшения командной работы","ar":"تعرف على كيفية إعداد أداة الذكاء الاصطناعي pr-writer لإنشاء طلبات السحبตาม اتفاقيات Sentry وتحسين التعاون الفريق"},"definition":{"en":"pr-writer is a skill that automates the creation and editing of pull requests according to Sentry conventions, using GitHub CLI for authentication and management.","zh":"PR Writer 是一种自动化 Pull Request 创建和更新的 AIエージェント","ja":"PR Writer は Pull Request の作成と更新を自動化する AIエージェントの一種です","ko":"PR Writer는 Pull Request를 자동으로 생성하고 업데이트하는 AI 에이전트입니다","es":"pr-writer es un skill que crea solicitudes de extracción en GitHub siguiendo las convenciones de Sentry","fr":"pr-writer est un skill qui crée des demandes d''extraction sur GitHub en suivant les conventions Sentry","de":"pr-writer ist ein Skill, der Pull-Requests auf GitHub nach Sentry-Konventionen erstellt","pt":"O pr-writer é uma ferramenta de automação que ajuda a criar solicitações de pull seguindo as convenções do Sentry","ru":"ИИ Агент pr-writer - это инструмент автоматизации, который помогает создавать запросы на принятие изменений в соответствии с соглашениями Sentry","ar":"أداة الذكاء الاصطناعي pr-writer هي أداة أتمتة تساعد في إنشاء طلبات السحب وفقًا لاتفاقيات Sentry"},"features":{"en":["Triggers on create PR, open PR, submit PR, make PR, update PR title, and update PR description events","Follows Sentry conventions for PR titles, descriptions, and issue references","Requires GitHub CLI (gh) authenticated and available","Checks for uncommitted changes using git status --porcelain command","Invokes sentry-skills:commit skill to commit changes properly if needed"],"zh":["遵循 Sentry 的工程实践","使用 GitHub CLI 进行认证","自动创建和更新 Pull Request","支持 PR 标题、描述和问题引用","触发创建、打开、提交和更新 Pull Request"],"ja":["Sentry のエンジニアリング実践に従う","GitHub CLI を使用した認証","Pull Request の自動作成と更新","PR タイトル、説明、問題参照のサポート","Pull Request の作成、開催、提出、更新のトリガー"],"ko":["Sentry 규약을 준수","GitHub CLI를 사용한 인증","Pull Request의 자동 생성 및 업데이트","PR 제목, 설명, 문제 참조 지원","Pull Request 생성, 열기, 제출, 업데이트 트리거"],"es":["Sigue las convenciones de Sentry para títulos y descripciones de PR","Requiere GitHub CLI autenticado","Soporta la creación y actualización de solicitudes de extracción","Verifica cambios no comprometidos con `git status --porcelain`","Invoca el skill `sentry-skills:commit` para comprometer cambios","Funciona con tareas de preparación de cambios para revisión"],"fr":["Suit les conventions Sentry pour les titres et les descriptions de PR","Nécessite GitHub CLI authentifié","Prend en charge la création et la mise à jour des demandes d''extraction","Vérifie les changements non validés avec `git status --porcelain`","Appelle le skill `sentry-skills:commit` pour valider les changements","Fonctionne avec les tâches de préparation des changements pour la révision"],"de":["Folgt den Sentry-Konventionen für PR-Titel und -Beschreibungen","Benötigt authentifizierten GitHub CLI","Unterstützt die Erstellung und Aktualisierung von Pull-Requests","Überprüft nicht committete Änderungen mit `git status --porcelain`","Ruft den Skill `sentry-skills:commit` auf, um Änderungen zu committen","Funktioniert mit Aufgaben zur Vorbereitung von Änderungen für die Überprüfung"],"pt":["Criação de solicitações de pull seguindo as convenções do Sentry","Utilização do GitHub CLI (gh) autenticado e disponível","Verificação de alterações não commitadas antes de criar uma solicitação de pull","Suporte à atualização de títulos e descrições de solicitações de pull","Integração com a ferramenta sentry-skills:commit para commitar alterações"],"ru":["Создание запросов на принятие изменений в соответствии с соглашениями Sentry","Использование GitHub CLI (gh) аутентифицированного и доступного","Проверка незафиксированных изменений перед созданием запроса на принятие изменений","Поддержка обновления названий и описаний запросов на принятие изменений","Интеграция с инструментом sentry-skills:commit для фиксации изменений"],"ar":["إنشاء طلبات السحب وفقًا لاتفاقيات Sentry","استخدام واجهة سطر الأوامر GitHub (gh) المُصادق عليها والمتاحة","فحص التغييرات غير الملتزمة قبل إنشاء طلب السحب","دعم تحديث عناوين ووصفات طلبات السحب","التكامل مع أداة sentry-skills:commit لتغييرات الالتزام"]},"keywords":{"en":["pr-writer setup guide","how to use pr-writer with GitHub CLI","pr-writer vs manual PR creation","what is pr-writer skill","pr-writer install for AI agents","automated pull request management with pr-writer","pr-writer and Sentry conventions","pr-writer alternative for developers","pr-writer tutorial for AI agents"],"zh":["PR Writer","AIエージェント","Sentry","GitHub CLI","Pull Request","自动化","工程实践","认证"],"ja":["PR Writer","AIエージェント","Sentry","GitHub CLI","Pull Request","自動化","エンジニアリング実践","認証"],"ko":["PR Writer","AI 에이전트","Sentry","GitHub CLI","Pull Request","자동화","규약","인증"],"es":["pr-writer","GitHub CLI","Sentry","solicitudes de extracción","convenciones de Sentry","Herramientas de desarrollo","Skills de desarrollo","Agentes de IA para desarrollo"],"fr":["pr-writer","GitHub CLI","Sentry","demandes d''extraction","conventions Sentry","Outils de développement","Compétences de développement","Agents d''IA pour le développement"],"de":["pr-writer","GitHub CLI","Sentry","Pull-Requests","Sentry-Konventionen","Entwicklungstools","Entwicklungs-Skills","KI-Agents für die Entwicklung"],"pt":["pr-writer","sentry","github cli","solicitação de pull","convenções de solicitação de pull","ferramenta de automação","desenvolvimento de software","colaboração em equipe"],"ru":["pr-writer","sentry","github cli","запрос на принятие изменений","соглашения о запросах на принятие изменений","инструмент автоматизации","разработка программного обеспечения","командная работа"],"ar":["pr-writer","sentry","github cli","طلب السحب","اتفاقيات طلب السحب","أداة أتمتة","تطوير البرمجيات","التعاون الفريق"]}},"agentAnalysis":{"suitability":{"en":"Perfect for GitHub-integrated Agents needing standardized pull request management and automation.","zh":"适合需要标准化拉取请求管理和自动化的GitHub集成代理。","ja":"GitHubに統合されたエージェントが標準化されたプルリクエスト管理と自動化を必要とする場合に最適です。","ko":"표준화된 풀 리퀘스트 관리 및 자동화가 필요한 GitHub 통합 에이전트에 적합합니다.","es":"Perfecto para Agentes integrados con GitHub que necesitan una gestión y automatización de solicitudes de extracción estandarizadas.","fr":"Parfait pour les agents intégrés à GitHub ayant besoin d''une gestion et d''une automatisation de demandes de tirage standardisées.","de":"Perfekt für GitHub-integrierte Agenten, die eine standardisierte Pull-Request-Verwaltung und -Automatisierung benötigen.","pt":"Perfeito para Agentes integrados ao GitHub que necessitam de gerenciamento e automação de pull requests padronizados.","ru":"Идеально подходит для агентов, интегрированных с GitHub, которым необходима стандартизированная автоматизация и управление запросами на включение.","ar":"مثالي للوكلاء المتكاملين مع GitHub الذين بحاجة إلى إدارة طلبات السحب ومؤشراتها المعيارية"},"recommendation":{"en":"Empowers agents to create and update pull requests following Sentry''s engineering practices, utilizing GitHub CLI for seamless integration and authentication, and adhering to specific conventions for PR titles, descriptions, and issue references.","zh":"赋予代理创建和更新拉取请求的能力，遵循Sentry的工程实践，利用GitHub CLI实现无缝集成和认证，并遵守特定的PR标题、描述和问题引用的约定。","ja":"エージェントがプルリクエストを作成および更新できるようにし、Sentryのエンジニアリングプラクティスに従い、GitHub CLIを使用してシームレスな統合と認証を行い、PRタイトル、説明、問題参照に関する特定の規約に従う。","ko":"에이전트가 풀 리퀘스트를 생성 및 업데이트할 수 있도록 하여 Sentry의 엔지니어링 관행을 따르고 GitHub CLI를 사용하여 무결점 통합 및 인증을 수행하며 PR 제목, 설명 및 문제 참조에 대한 특정 규칙을 따릅니다.","es":"Habilita a los agentes a crear y actualizar solicitudes de extracción siguiendo las prácticas de ingeniería de Sentry, utilizando GitHub CLI para una integración y autenticación sin problemas y ajustándose a convenciones específicas para títulos de PR, descripciones y referencias de problemas.","fr":"Autonomise les agents pour créer et mettre à jour des demandes de tirage en suivant les pratiques d''ingénierie de Sentry, en utilisant GitHub CLI pour une intégration et une authentification sans discontinuité et en respectant des conventions spécifiques pour les titres de PR, les descriptions et les références de problèmes.","de":"Ermächtigt Agenten, Pull-Requests zu erstellen und zu aktualisieren, indem sie Sentrys Ingenieurpraktiken befolgen, GitHub CLI für eine nahtlose Integration und Authentifizierung nutzen und bestimmte Konventionen für PR-Titel, Beschreibungen und Issues-Referenzen einhalten.","pt":"Habilita os agentes a criar e atualizar pull requests seguindo as práticas de engenharia do Sentry, utilizando o GitHub CLI para integração e autenticação sem problemas, e seguindo convenções específicas para títulos de PR, descrições e referências de problemas.","ru":"Наделяет агентов возможностью создавать и обновлять запросы на включение в соответствии с инженерными практиками Sentry, используя GitHub CLI для бесшовной интеграции и аутентификации, и придерживаясь определенных конвенций для названий PR, описаний и ссылок на проблемы.","ar":"تمكّن الوكلاء من إنشاء وتحديث طلبات السحب اتباعًا لممارسات الهندسة في Sentry، مستخدمين واجهة سطر الأوامر في GitHub من أجل التكامل والتأكيد بدون مشاكل، والتزامًا بالاتفاقيات المحددة لأسماء PR والوصف والإحالات إلى القضايا"},"useCases":{"en":["Automating pull request creation with standardized titles and descriptions","Updating pull request details to reflect changes in the codebase","Triggering PR creation or updates based on specific Git events, such as push or commit","Ensuring compliance with Sentry conventions for issue references in pull requests"],"zh":["使用标准化标题和描述自动创建拉取请求","更新拉取请求详细信息以反映代码库中的更改","基于特定Git事件（如推送或提交）触发PR创建或更新","确保拉取请求中的问题引用符合Sentry约定"],"ja":["標準化されたタイトルと説明を使用してプルリクエストを自動的に作成する","コードベースの変更を反映するためにプルリクエストの詳細を更新する","特定のGitイベント（プッシュまたはコミットなど）に基づいてPRの作成または更新をトリガーする","プルリクエスト内の問題参照がSentryの規約に準拠することを保証する"],"ko":["표준화된 제목 및 설명을 사용하여 풀 리퀘스트를 자동으로 생성합니다.","코드베이스의 변경 사항을 반영하기 위해 풀 리퀘스트의 세부 정보를 업데이트합니다.","특정 Git 이벤트(푸시 또는 커밋 등)에 따라 PR 생성 또는 업데이트를 트리거합니다.","풀 리퀘스트 내의 문제 참조가 Sentry 규약을 준수하도록 보장합니다."],"es":["Automatización de la creación de solicitudes de extracción con títulos y descripciones estandarizados","Actualización de los detalles de la solicitud de extracción para reflejar los cambios en la base de código","Desencadenamiento de la creación o actualización de PR en función de eventos Git específicos, como push o commit","Garantía del cumplimiento de las convenciones de Sentry para referencias de problemas en solicitudes de extracción"],"fr":["Automatisation de la création de demandes de tirage avec des titres et des descriptions standardisés","Mise à jour des détails de la demande de tirage pour refléter les changements dans la base de code","Déclenchement de la création ou de la mise à jour de PR en fonction d''événements Git spécifiques, tels que push ou commit","Assurance du respect des conventions de Sentry pour les références de problèmes dans les demandes de tirage"],"de":["Automatisierung der Erstellung von Pull-Requests mit standardisierten Titeln und Beschreibungen","Aktualisierung der Pull-Request-Details, um Änderungen im Codebase widerzuspiegeln","Auslösen der Pull-Request-Erstellung oder -Aktualisierung basierend auf bestimmten Git-Ereignissen, wie Push oder Commit","Sicherstellung der Einhaltung der Sentry-Konventionen für Issue-Referenzen in Pull-Requests"],"pt":["Automatizar a criação de pull requests com títulos e descrições padronizados","Atualizar detalhes de pull requests para refletir alterações na base de código","Acionar a criação ou atualização de PR com base em eventos Git específicos, como push ou commit","Garantir conformidade com as convenções do Sentry para referências de problemas em pull requests"],"ru":["Автоматизировать создание запросов на включение с стандартизированными названиями и описаниями","Обновлять детали запросов на включение, чтобы отразить изменения в кодовой базе","Запускать создание или обновление PR на основе определенных событий Git, таких как push или commit","Обеспечивать соблюдение конвенций Sentry для ссылок на проблемы в запросах на включение"],"ar":["توفير آلي لإنشاء طلبات السحب مع أسماء ووصف معياري","تحديث تفاصيل طلبات السحب لتجسيد التغييرات في قاعدة الشفرة","تشغيل إنشاء أو تحديث طلبات السحب استنادًا إلى أحداث Git محددة، مثل الدفع أو الالتزام","ضمان الامتثال لاتفاقيات Sentry للإحالات إلى القضايا في طلبات السحب"]},"limitations":{"en":["Requires GitHub CLI (`gh`) authenticated and available","Needs all changes to be committed before creating a pull request","Dependent on Git status for determining uncommitted changes"],"zh":["需要GitHub CLI（`gh`）进行认证和可用性","需要在创建拉取请求之前提交所有更改","依赖于Git状态来确定未提交的更改"],"ja":["GitHub CLI（`gh`）の認証と可用性が必要","プルリクエストを作成する前にすべての変更をコミットする必要がある","未コミットの変更を決定するためにGitの状態に依存する"],"ko":["GitHub CLI(`gh`)의 인증 및 가용성이 필요합니다.","풀 리퀘스트를 생성하기 전에 모든 변경 사항을 커밋해야 합니다.","커밋되지 않은 변경 사항을 결정하기 위해 Git 상태에 의존합니다."],"es":["Requiere GitHub CLI (`gh`) autenticado y disponible","Necesita que todos los cambios estén comprometidos antes de crear una solicitud de extracción","Dependiente del estado de Git para determinar los cambios no comprometidos"],"fr":["Nécessite GitHub CLI (`gh`) authentifié et disponible","Nécessite que tous les changements soient validés avant de créer une demande de tirage","Dépendant de l''état de Git pour déterminer les changements non validés"],"de":["Benötigt GitHub CLI (`gh`) authentifiziert und verfügbar","Benötigt, dass alle Änderungen committet werden, bevor ein Pull-Request erstellt wird","Abhängig vom Git-Status, um nicht committete Änderungen zu bestimmen"],"pt":["Exige que o GitHub CLI (`gh`) esteja autenticado e disponível","Necessita que todas as alterações sejam commitadas antes de criar um pull request","Depende do status do Git para determinar alterações não commitadas"],"ru":["Требует аутентификации и доступности GitHub CLI (`gh`)","Требует, чтобы все изменения были зафиксированы перед созданием запроса на включение","Зависит от статуса Git для определения незафиксированных изменений"],"ar":["يتطلب تأكيد واجهة سطر الأوامر في GitHub (`gh`) وتوفرها","يحتاج إلى تأكيد جميع التغييرات قبل إنشاء طلب سحب","يعتمد على حالة Git لتحديد التغييرات غير الملتزمة"]},"version":4},"contentHash":"b18903219ba2881a6f0fa609abd7fc61779757b61a7223e9b0a8f3720deeeaac","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":92}');
