INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/pr-writer', 'pr-writer', 'getsentry', 'skills', 'official', 'pr-writer getsentry skills official tag-production The pr-writer skill automates pull request creation and editing for developers, following Sentry''s engineering practices and utilizing GitHub CLI. It ensures consistent PR titles, descriptions, and issue references. PR Writer 是一个 AIエージェント，用于创建和更新 Pull Request，遵循 Sentry 的工程实践 PR Writer は、GitHub CLI を使用して Pull Request を作成および更新する AIエージェントです PR Writer는 Sentry 규약을 준수하는 Pull Request를 생성하고 업데이트 하는 AI 에이전트입니다 El skill pr-writer crea solicitudes de extracción en GitHub siguiendo las convenciones de Sentry. Requiere GitHub CLI autenticado Le skill pr-writer crée des demandes d''extraction sur GitHub en suivant les conventions Sentry. Nécessite GitHub CLI authentifié Der pr-writer-Skill erstellt Pull-Requests auf GitHub nach Sentry-Konventionen. Benötigt authentifizierten GitHub CLI O pr-writer é uma ferramenta que ajuda a criar solicitações de pull seguindo as convenções do Sentry, melhorando a colaboração em equipe e reduzindo erros ИИ Агент pr-writer помогает создавать запросы на принятие изменений в соответствии с соглашениями Sentry, улучшая командную работу и снижая ошибки أداة الذكاء الاصطناعي pr-writer تساعد في إنشاء طلبات السحب وفقًا لاتفاقيات Sentry، وتحسين التعاون الفريق وتقليل الأخطاء pr-writer setup guide how to use pr-writer with GitHub CLI pr-writer vs manual PR creation what is pr-writer skill pr-writer install for AI agents automated pull request management with pr-writer pr-writer and Sentry conventions pr-writer alternative for developers pr-writer tutorial for AI agents PR Writer AIエージェント Sentry GitHub CLI Pull Request 自动化 工程实践 认证 Triggers on create PR, open PR, submit PR, make PR, update PR title, and update PR description events Follows Sentry conventions for PR titles, descriptions, and issue references Requires GitHub CLI (gh) authenticated and available Checks for uncommitted changes using git status --porcelain command Invokes sentry-skills:commit skill to commit changes properly if needed pr-writer is a skill that automates the creation and editing of pull requests according to Sentry conventions, using GitHub CLI for authentication and management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/expo-api-routes', 'official', 'expo', 'skills', 'expo/skills', 'expo-api-routes', 1349, 59, 91, '2026-03-06T04:04:30Z', '2026-03-06T05:21:32.392Z', 'db4d2cd6fbce04d9a7914db6e37513c218d5fb678e962c034ebfc122c7406fd3', '{"id":"expo/skills/expo-api-routes","name":"expo-api-routes","description":{"en":"expo-api-routes provides guidelines for creating secure API routes in Expo Router with EAS Hosting, benefiting developers who need to protect server-side secrets and validate data.","zh":"Expo API 路由提供了一种保护服务器端秘密和数据库操作的方式，使用 EAS Hosting 实现安全的 API 路由","ja":"Expo API ルーティングは、EAS Hosting を使用してサーバーサイドのシークレットとデータベース操作を保護する方法を提供します","ko":"Expo API 라우트는 EAS Hosting을 사용하여 서버측 비밀과 데이터베이스 작업을 보호하는 방법을 제공합니다","es":"Guía técnica para crear rutas API en Expo Router con EAS Hosting, protegiendo secretos del servidor y operaciones de base de datos","fr":"Guide technique pour créer des routes API dans Expo Router avec EAS Hosting, protégeant les secrets serveur et les opérations de base de données","de":"Technische Anleitung zur Erstellung von API-Routen in Expo Router mit EAS Hosting, um Server-Geheimnisse und Datenbankoperationen zu schützen","pt":"O expo-api-routes fornece diretrizes para criar rotas de API em Expo Router com EAS Hosting, garantindo a segurança de segredos do servidor e operações de banco de dados.","ru":"Expo-api-routes предоставляет руководство по созданию маршрутов API в Expo Router с EAS Hosting, обеспечивая безопасность серверных секретов и операций с базой данных.","ar":"يوفر expo-api-routes إرشادات لإنشاء مسارات واجهة برمجة التطبيقات في Expo Router مع EAS Hosting، مما يضمن أمان الأسرار الخادمة وعمليات قاعدة البيانات."},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"expo-api-routes","description":"Guidelines for creating API routes in Expo Router with EAS Hosting","version":"1.0.0","bodyPreview":"## When to Use API Routes\n\nUse API routes when you need:\n\n- **Server-side secrets** — API keys, database credentials, or tokens that must never reach the client\n- **Database operations** — Direct database queries that shouldn''t be exposed\n- **Third-party API proxies** — Hide API keys when calling external services (OpenAI, Stripe, etc.)\n- **Server-side validation** — Validate data before database writes\n- **Webhook endpoints** — Receive callbacks from services like Stripe or GitHub\n- **Rate limi","body":"## When to Use API Routes\n\nUse API routes when you need:\n\n- **Server-side secrets** — API keys, database credentials, or tokens that must never reach the client\n- **Database operations** — Direct database queries that shouldn''t be exposed\n- **Third-party API proxies** — Hide API keys when calling external services (OpenAI, Stripe, etc.)\n- **Server-side validation** — Validate data before database writes\n- **Webhook endpoints** — Receive callbacks from services like Stripe or GitHub\n- **Rate limiting** — Control access at the server level\n- **Heavy computation** — Offload processing that would be slow on mobile\n\n## When NOT to Use API Routes\n\nAvoid API routes when:\n\n- **Data is already public** — Use direct fetch to public APIs instead\n- **No secrets required** — Static data or client-safe operations\n- **Real-time updates needed** — Use WebSockets or services like Supabase Realtime\n- **Simple CRUD** — Consider Firebase, Supabase, or Convex for managed backends\n- **File uploads** — Use direct-to-storage uploads (S3 presigned URLs, Cloudflare R2)\n- **Authentication only** — Use Clerk, Auth0, or Firebase Auth instead\n\n## File Structure\n\nAPI routes live in the `app` directory with `+api.ts` suffix:\n\n```\napp/\n  api/\n    hello+api.ts          → GET /api/hello\n    users+api.ts          → /api/users\n    users/[id]+api.ts     → /api/users/:id\n  (tabs)/\n    index.tsx\n```\n\n## Basic API Route\n\n```ts\n// app/api/hello+api.ts\nexport function GET(request: Request) {\n  return Response.json({ message: \"Hello from Expo!\" });\n}\n```\n\n## HTTP Methods\n\nExport named functions for each HTTP method:\n\n```ts\n// app/api/items+api.ts\nexport function GET(request: Request) {\n  return Response.json({ items: [] });\n}\n\nexport async function POST(request: Request) {\n  const body = await request.json();\n  return Response.json({ created: body }, { status: 201 });\n}\n\nexport async function PUT(request: Request) {\n  const body = await request.json();\n  return Response.json({ updated: body });\n}\n\nexport async function DELETE(request: Request) {\n  return new Response(null, { status: 204 });\n}\n```\n\n## Dynamic Routes\n\n```ts\n// app/api/users/[id]+api.ts\nexport function GET(request: Request, { id }: { id: string }) {\n  return Response.json({ userId: id });\n}\n```\n\n## Request Handling\n\n### Query Parameters\n\n```ts\nexport function GET(request: Request) {\n  const url = new URL(request.url);\n  const page = url.searchParams.get(\"page\") ?? \"1\";\n  const limit = url.searchParams.get(\"limit\") ?? \"10\";\n\n  return Response.json({ page, limit });\n}\n```\n\n### Headers\n\n```ts\nexport function GET(request: Request) {\n  const auth = request.headers.get(\"Authorization\");\n\n  if (!auth) {\n    return Response.json({ error: \"Unauthorized\" }, { status: 401 });\n  }\n\n  return Response.json({ authenticated: true });\n}\n```\n\n### JSON Body\n\n```ts\nexport async function POST(request: Request) {\n  const { email, password } = await request.json();\n\n  if (!email || !password) {\n    return Response.json({ error: \"Missing fields\" }, { status: 400 });\n  }\n\n  return Response.json({ success: true });\n}\n```\n\n## Environment Variables\n\nUse `process.env` for server-side secrets:\n\n```ts\n// app/api/ai+api.ts\nexport async function POST(request: Request) {\n  const { prompt } = await request.json();\n\n  const response = await fetch(\"https://api.openai.com/v1/chat/completions\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,\n    },\n    body: JSON.stringify({\n      model: \"gpt-4\",\n      messages: [{ role: \"user\", content: prompt }],\n    }),\n  });\n\n  const data = await response.json();\n  return Response.json(data);\n}\n```\n\nSet environment variables:\n\n- **Local**: Create `.env` file (never commit)\n- **EAS Hosting**: Use `eas env:create` or Expo dashboard\n\n## CORS Headers\n\nAdd CORS for web clients:\n\n```ts\nconst corsHeaders = {\n  \"Access-Control-Allow-Origin\": \"*\",\n  \"Access-Control-Allow-Methods\": \"GET, POST, PUT, DELETE, OPTIONS\",\n  \"Access-Control-Allow-Headers\": \"Content-Type, Authorization\",\n};\n\nexport function OPTIONS() {\n  return new Response(null, { headers: corsHeaders });\n}\n\nexport function GET() {\n  return Response.json({ data: \"value\" }, { headers: corsHeaders });\n}\n```\n\n## Error Handling\n\n```ts\nexport async function POST(request: Request) {\n  try {\n    const body = await request.json();\n    // Process...\n    return Response.json({ success: true });\n  } catch (error) {\n    console.error(\"API error:\", error);\n    return Response.json({ error: \"Internal server error\" }, { status: 500 });\n  }\n}\n```\n\n## Testing Locally\n\nStart the development server with API routes:\n\n```bash\nnpx expo serve\n```\n\nThis starts a local server at `http://localhost:8081` with full API route support.\n\nTest with curl:\n\n```bash\ncurl http://localhost:8081/api/hello\ncurl -X POST http://localhost:8081/api/users -H \"Content-Type: application/json\" -d ''{\"name\":\"Test\"}''\n```\n\n## Deployment to EAS Hosting\n\n### Prerequisites\n\n```bash\nnpm install -g eas-cli\neas login\n```\n\n### Deploy\n\n```bash\neas deploy\n```\n\nThis builds and deploys your API routes to EAS Hosting (Cloudflare Workers).\n\n### Environment Variables for Production\n\n```bash\n# Create a secret\neas env:create --name OPENAI_API_KEY --value sk-xxx --environment production\n\n# Or use the Expo dashboard\n```\n\n### Custom Domain\n\nConfigure in `eas.json` or Expo dashboard.\n\n## EAS Hosting Runtime (Cloudflare Workers)\n\nAPI routes run on Cloudflare Workers. Key limitations:\n\n### Missing/Limited APIs\n\n- **No Node.js filesystem** — `fs` module unavailable\n- **No native Node modules** — Use Web APIs or polyfills\n- **Limited execution time** — 30 second timeout for CPU-intensive tasks\n- **No persistent connections** — WebSockets require Durable Objects\n- **fetch is available** — Use standard fetch for HTTP requests\n\n### Use Web APIs Instead\n\n```ts\n// Use Web Crypto instead of Node crypto\nconst hash = await crypto.subtle.digest(\n  \"SHA-256\",\n  new TextEncoder().encode(\"data\")\n);\n\n// Use fetch instead of node-fetch\nconst response = await fetch(\"https://api.example.com\");\n\n// Use Response/Request (already available)\nreturn new Response(JSON.stringify(data), {\n  headers: { \"Content-Type\": \"application/json\" },\n});\n```\n\n### Database Options\n\nSince filesystem is unavailable, use cloud databases:\n\n- **Cloudflare D1** — SQLite at the edge\n- **Turso** — Distributed SQLite\n- **PlanetScale** — Serverless MySQL\n- **Supabase** — Postgres with REST API\n- **Neon** — Serverless Postgres\n\nExample with Turso:\n\n```ts\n// app/api/users+api.ts\nimport { createClient } from \"@libsql/client/web\";\n\nconst db = createClient({\n  url: process.env.TURSO_URL!,\n  authToken: process.env.TURSO_AUTH_TOKEN!,\n});\n\nexport async function GET() {\n  const result = await db.execute(\"SELECT * FROM users\");\n  return Response.json(result.rows);\n}\n```\n\n## Calling API Routes from Client\n\n```ts\n// From React Native components\nconst response = await fetch(\"/api/hello\");\nconst data = await response.json();\n\n// With body\nconst response = await fetch(\"/api/users\", {\n  method: \"POST\",\n  headers: { \"Content-Type\": \"application/json\" },\n  body: JSON.stringify({ name: \"John\" }),\n});\n```\n\n## Common Patterns\n\n### Authentication Middleware\n\n```ts\n// utils/auth.ts\nexport async function requireAuth(request: Request) {\n  const token = request.headers.get(\"Authorization\")?.replace(\"Bearer \", \"\");\n\n  if (!token) {\n    throw new Response(JSON.stringify({ error: \"Unauthorized\" }), {\n      status: 401,\n      headers: { \"Content-Type\": \"application/json\" },\n    });\n  }\n\n  // Verify token...\n  return { userId: \"123\" };\n}\n\n// app/api/protected+api.ts\nimport { requireAuth } from \"../../utils/auth\";\n\nexport async function GET(request: Request) {\n  const { userId } = await requireAuth(request);\n  return Response.json({ userId });\n}\n```\n\n### Proxy External API\n\n```ts\n// app/api/weather+api.ts\nexport async function GET(request: Request) {\n  const url = new URL(request.url);\n  const city = url.searchParams.get(\"city\");\n\n  const response = await fetch(\n    `https://api.weather.com/v1/current?city=${city}&key=${process.env.WEATHER_API_KEY}`\n  );\n\n  return Response.json(await response.json());\n}\n```\n\n## Rules\n\n- NEVER expose API keys or secrets in client code\n- ALWAYS validate and sanitize user input\n- Use proper HTTP status codes (200, 201, 400, 401, 404, 500)\n- Handle errors gracefully with try/catch\n- Keep API routes focused — one responsibility per endpoint\n- Use TypeScript for type safety\n- Log errors server-side for debugging\n"},"category":"official","lastSynced":"2026-03-06T05:21:32.392Z","seo":{"title":{"en":"expo-api-routes: Setup Guide for Secure API Routing | AI ...","zh":"Expo API 路由设置指南","ja":"Expo API ルーティングのベストプラクティス","ko":"Expo API 라우트 설정 가이드","es":"Guía de configuración para expo-api-routes con EAS Hosting","fr":"Configurer les routes API Expo avec EAS Hosting - Meilleu...","de":"Einrichtungsleitfaden für expo-api-routes mit EAS Hosting","pt":"Guia de Configuração de Rotas de API com Expo Router e EA...","ru":"Настройка маршрутов API с Expo Router и EAS Hosting: Руко...","ar":"دليل إعداد مسارات واجهة برمجة التطبيقات مع Expo Router و ..."},"description":{"en":"Unlock secure API routing with expo-api-routes! Learn how to protect server-side secrets, validate data, and create webhook endpoints with our expert guide.","zh":"了解如何在 Expo Router 中创建 API 路由，使用 EAS Hosting 保护服务器端秘密和数据库操作","ja":"Expo Router で API ルーティングを作成する方法を学び、EAS Hosting を使用してサーバーサイドのシークレットとデータベース操作を保護する","ko":"Expo Router에서 API 라우트를 생성하고 EAS Hosting을 사용하여 서버측 비밀과 데이터베이스 작업을 보호하는 방법을 알아보세요","es":"Aprende a crear rutas API en Expo Router con EAS Hosting para proteger secretos del servidor y operaciones de base de datos","fr":"Découvrez comment créer des routes API dans Expo Router avec EAS Hosting pour protéger les secrets serveur et les opérations de base de données","de":"Erfahren Sie, wie Sie API-Routen in Expo Router mit EAS Hosting erstellen, um Server-Geheimnisse und Datenbankoperationen zu schützen","pt":"Aprenda a criar rotas de API seguras com Expo Router e EAS Hosting para proteger segredos do servidor e operações de banco de dados","ru":"Узнайте, как создавать защищенные маршруты API с помощью Expo Router и EAS Hosting для защиты серверных секретов и операций с базой данных","ar":"تعرف على كيفية إنشاء مسارات واجهة برمجة التطبيقات الآمنة مع Expo Router و EAS Hosting لحماية الأسرار الخادمة وعمليات قاعدة البيانات"},"definition":{"en":"expo-api-routes is a set of guidelines for creating API routes in Expo Router with EAS Hosting, enabling secure server-side operations and data validation.","zh":"Expo API 路由是 Expo Router 中的一种功能，允许开发者创建安全的 API 路由","ja":"Expo API ルーティングは、Expo Router の機能で、開発者がセキュアな API ルーティングを作成できるようにします","ko":"Expo API 라우트는 Expo Router의 기능으로 개발자가 보안 API 라우트를 생성할 수 있게 해줍니다","es":"expo-api-routes es una guía para crear rutas API en Expo Router con EAS Hosting","fr":"expo-api-routes est un guide 