INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('expo/skills/expo-api-routes', 'expo-api-routes', 'expo', 'skills', 'official', 'expo-api-routes expo skills official expo-api-routes provides guidelines for creating secure API routes in Expo Router with EAS Hosting, benefiting developers who need to protect server-side secrets and validate data. Expo API 路由提供了一种保护服务器端秘密和数据库操作的方式，使用 EAS Hosting 实现安全的 API 路由 Expo API ルーティングは、EAS Hosting を使用してサーバーサイドのシークレットとデータベース操作を保護する方法を提供します Expo API 라우트는 EAS Hosting을 사용하여 서버측 비밀과 데이터베이스 작업을 보호하는 방법을 제공합니다 Guía técnica para crear rutas API en Expo Router con EAS Hosting, protegiendo secretos del servidor y operaciones de base de datos Guide technique pour créer des routes API dans Expo Router avec EAS Hosting, protégeant les secrets serveur et les opérations de base de données Technische Anleitung zur Erstellung von API-Routen in Expo Router mit EAS Hosting, um Server-Geheimnisse und Datenbankoperationen zu schützen O expo-api-routes fornece diretrizes para criar rotas de API em Expo Router com EAS Hosting, garantindo a segurança de segredos do servidor e operações de banco de dados. Expo-api-routes предоставляет руководство по созданию маршрутов API в Expo Router с EAS Hosting, обеспечивая безопасность серверных секретов и операций с базой данных. يوفر expo-api-routes إرشادات لإنشاء مسارات واجهة برمجة التطبيقات في Expo Router مع EAS Hosting، مما يضمن أمان الأسرار الخادمة وعمليات قاعدة البيانات. how to use expo-api-routes expo-api-routes setup guide expo-api-routes vs react-router expo-api-routes install what is expo-api-routes expo-api-routes alternative expo-api-routes documentation expo-api-routes tutorial expo-api-routes eas hosting Expo API 路由 Expo Router EAS Hosting 服务器端秘密 数据库操作 第三方 API 代理 服务器端验证 Webhook 端点 Protects server-side secrets, such as API keys and database credentials Enables direct database operations without exposing queries to clients Supports third-party API proxies for services like OpenAI and Stripe Provides server-side validation for data before database writes Allows creation of webhook endpoints for services like Stripe and GitHub Implements rate limiting for secure API routing expo-api-routes is a set of guidelines for creating API routes in Expo Router with EAS Hosting, enabling secure server-side operations and data validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/MCP Builder', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'MCP Builder', 0, 0, 90, '2026-02-20T04:13:19.570Z', '2026-02-20T04:20:40.319Z', '1654144e43465e6548305572bd5f12ca508f6050b1f40d02de6706e0e856c89b', '{"id":"majiayu000/claude-skill-registry/MCP Builder","name":"MCP Builder","description":{"zh":"MCP Builder是一种生产就绪服务器开发框架，提供了MCP基础、工具设计原则、实现模式等功能","ja":"MCP Builderは本番環境用サーバー開発フレームワークであり、MCPの基礎、ツール設計原則、実装パターンなどの機能を提供する","ko":"MCP Builder는 프로덕션 레디 서버 개발 프레임워크로서 MCP 기초, 도구 설계 원칙, 구현 패턴 등의 기능을 제공합니다","es":"La guía más completa para desarrollar servidores MCP de producción, cubriendo fundamentos, principios de diseño y patrones de implementación","fr":"Le guide le plus complet pour développer des serveurs MCP de production, couvrant les fondamentaux, les principes de conception et les modèles de mise en œuvre","de":"Die umfassendste Anleitung für die Entwicklung von MCP-Servern für die Produktion, einschließlich Grundlagen, Designprinzipien und Implementierungsmustern","pt":"Aprenda a desenvolver servidores MCP de produção com nossa guia abrangente. Este guia inclui fundamentos, padrões de implementação e melhores práticas de segurança.","ru":"Узнайте, как создать сервер MCP для производства с нашей всесторонней инструкцией. Этот гид включает основы, шаблоны реализации и лучшие практики безопасности.","ar":"تعلم كيفية تطوير خوادم MCP جاهزة للانتاج مع دليلنا الشامل. هذا الدليل يتضمن الأساسيات ونماذج التنفيذ وأفضل الممارسات الأمنية.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"MCP Builder指南：生产就绪服务器开发","ja":"MCP Builderガイド：本番環境用サーバー開発","ko":"MCP Builder 가이드: 프로덕션 레디 서버 개발","es":"Guía de Desarrollo de Servidores MCP","fr":"Guide de Développement d