INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/MCP Builder', 'MCP Builder', 'majiayu000', 'claude-skill-registry', 'community', 'MCP Builder majiayu000 claude-skill-registry community MCP Builder是一种生产就绪服务器开发框架，提供了MCP基础、工具设计原则、实现模式等功能 MCP Builderは本番環境用サーバー開発フレームワークであり、MCPの基礎、ツール設計原則、実装パターンなどの機能を提供する MCP Builder는 프로덕션 레디 서버 개발 프레임워크로서 MCP 기초, 도구 설계 원칙, 구현 패턴 등의 기능을 제공합니다 La guía más completa para desarrollar servidores MCP de producción, cubriendo fundamentos, principios de diseño y patrones de implementación Le guide le plus complet pour développer des serveurs MCP de production, couvrant les fondamentaux, les principes de conception et les modèles de mise en œuvre Die umfassendste Anleitung für die Entwicklung von MCP-Servern für die Produktion, einschließlich Grundlagen, Designprinzipien und Implementierungsmustern Aprenda a desenvolver servidores MCP de produção com nossa guia abrangente. Este guia inclui fundamentos, padrões de implementação e melhores práticas de segurança. Узнайте, как создать сервер MCP для производства с нашей всесторонней инструкцией. Этот гид включает основы, шаблоны реализации и лучшие практики безопасности. تعلم كيفية تطوير خوادم MCP جاهزة للانتاج مع دليلنا الشامل. هذا الدليل يتضمن الأساسيات ونماذج التنفيذ وأفضل الممارسات الأمنية. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app MCP Builder 生产就绪服务器开发 MCP基础 工具设计原则 实现模式 错误处理 测试策略 安全最佳实践 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/using-git-worktrees', 'official', 'obra', 'superpowers', 'obra/superpowers', 'using-git-worktrees', 71924, 5546, 89, '2026-03-06T03:26:30Z', '2026-03-06T03:36:13.009Z', 'de9dcde34840eee074047ec327d4ea6ca4954c5a73a6d874dc48f25fe46c9e7c', '{"id":"obra/superpowers/using-git-worktrees","name":"using-git-worktrees","description":{"en":"The using-git-worktrees skill creates isolated workspaces for simultaneous branch work, benefiting developers who need to manage multiple features. It ensures reliable isolation through systematic directory selection and safety verification.","zh":"Git Worktrees允许您创建隔离的工作空间，实现多分支同时开发","ja":"Git Worktreesを使用すると、複数のブランチを同時に開発できます","ko":"Git Worktrees를 사용하여 여러 브랜치를 동시에 개발할 수 있습니다","es":"Git Worktrees permite crear espacios de trabajo aislados para desarrollar características de manera independiente. Esta habilidad utiliza la selección de directorios y verificación de seguridad para garantizar la isolación","fr":"Git Worktrees permet de créer des espaces de travail isolés pour développer des fonctionnalités de manière indépendante. Cette compétence utilise la sélection de répertoires et la vérification de sécurité pour assurer l''isolation","de":"Git Worktrees ermöglicht die Erstellung von isolierten Arbeitsbereichen, um Funktionen unabhängig zu entwickeln. Diese Fähigkeit nutzt die Verzeichnisauswahl und Sicherheitsprüfung, um die Isolation zu gewährleisten","pt":"O using-git-worktrees permite criar espaços de trabalho isolados para desenvolvedores trabalharem em múltiplos branches simultaneamente","ru":"ИИ Агенты: using-git-worktrees позволяет создавать изолированные рабочие пространства для работы над несколькими ветками одновременно","ar":"أداة using-git-worktrees تمكن المطورين من إنشاء مساحات عمل معزولة للعمل على عدة فروع في نفس الوقت"},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"using-git-worktrees","description":"Use when starting feature work that needs isolation from current workspace or before executing implementation plans - creates isolated git worktrees with smart directory selection and safety verification","bodyPreview":"# Using Git Worktrees\n\n## Overview\n\nGit worktrees create isolated workspaces sharing the same repository, allowing work on multiple branches simultaneously without switching.\n\n**Core principle:** Systematic directory selection + safety verification = reliable isolation.\n\n**Announce at start:** \"I''m using the using-git-worktrees skill to set up an isolated workspace.\"\n\n## Directory Selection Process\n\nFollow this priority order:\n\n### 1. Check Existing Directories\n\n```bash\n# Check in priority order","body":"# Using Git Worktrees\n\n## Overview\n\nGit worktrees create isolated workspaces sharing the same repository, allowing work on multiple branches simultaneously without switching.\n\n**Core principle:** Systematic directory selection + safety verification = reliable isolation.\n\n**Announce at start:** \"I''m using the using-git-worktrees skill to set up an isolated workspace.\"\n\n## Directory Selection Process\n\nFollow this priority order:\n\n### 1. Check Existing Directories\n\n```bash\n# Check in priority order\nls -d .worktrees 2>/dev/null     # Preferred (hidden)\nls -d worktrees 2>/dev/null      # Alternative\n```\n\n**If found:** Use that directory. If both exist, `.worktrees` wins.\n\n### 2. Check CLAUDE.md\n\n```bash\ngrep -i \"worktree.*director\" CLAUDE.md 2>/dev/null\n```\n\n**If preference specified:** Use it without asking.\n\n### 3. Ask User\n\nIf no directory exists and no CLAUDE.md preference:\n\n```\nNo worktree directory found. Where should I create worktrees?\n\n1. .worktrees/ (project-local, hidden)\n2. ~/.config/superpowers/worktrees/<project-name>/ (global location)\n\nWhich would you prefer?\n```\n\n## Safety Verification\n\n### For Project-Local Directories (.worktrees or worktrees)\n\n**MUST verify directory is ignored before creating worktree:**\n\n```bash\n# Check if directory is ignored (respects local, global, and system gitignore)\ngit check-ignore -q .worktrees 2>/dev/null || git check-ignore -q worktrees 2>/dev/null\n```\n\n**If NOT ignored:**\n\nPer Jesse''s rule \"Fix broken things immediately\":\n1. Add appropriate line to .gitignore\n2. Commit the change\n3. Proceed with worktree creation\n\n**Why critical:** Prevents accidentally committing worktree contents to repository.\n\n### For Global Directory (~/.config/superpowers/worktrees)\n\nNo .gitignore verification needed - outside project entirely.\n\n## Creation Steps\n\n### 1. Detect Project Name\n\n```bash\nproject=$(basename \"$(git rev-parse --show-toplevel)\")\n```\n\n### 2. Create Worktree\n\n```bash\n# Determine full path\ncase $LOCATION in\n  .worktrees|worktrees)\n    path=\"$LOCATION/$BRANCH_NAME\"\n    ;;\n  ~/.config/superpowers/worktrees/*)\n    path=\"~/.config/superpowers/worktrees/$project/$BRANCH_NAME\"\n    ;;\nesac\n\n# Create worktree with new branch\ngit worktree add \"$path\" -b \"$BRANCH_NAME\"\ncd \"$path\"\n```\n\n### 3. Run Project Setup\n\nAuto-detect and run appropriate setup:\n\n```bash\n# Node.js\nif [ -f package.json ]; then npm install; fi\n\n# Rust\nif [ -f Cargo.toml ]; then cargo build; fi\n\n# Python\nif [ -f requirements.txt ]; then pip install -r requirements.txt; fi\nif [ -f pyproject.toml ]; then poetry install; fi\n\n# Go\nif [ -f go.mod ]; then go mod download; fi\n```\n\n### 4. Verify Clean Baseline\n\nRun tests to ensure worktree starts clean:\n\n```bash\n# Examples - use project-appropriate command\nnpm test\ncargo test\npytest\ngo test ./...\n```\n\n**If tests fail:** Report failures, ask whether to proceed or investigate.\n\n**If tests pass:** Report ready.\n\n### 5. Report Location\n\n```\nWorktree ready at <full-path>\nTests passing (<N> tests, 0 failures)\nReady to implement <feature-name>\n```\n\n## Quick Reference\n\n| Situation | Action |\n|-----------|--------|\n| `.worktrees/` exists | Use it (verify ignored) |\n| `worktrees/` exists | Use it (verify ignored) |\n| Both exist | Use `.worktrees/` |\n| Neither exists | Check CLAUDE.md → Ask user |\n| Directory not ignored | Add to .gitignore + commit |\n| Tests fail during baseline | Report failures + ask |\n| No package.json/Cargo.toml | Skip dependency install |\n\n## Common Mistakes\n\n### Skipping ignore verification\n\n- **Problem:** Worktree contents get tracked, pollute git status\n- **Fix:** Always use `git check-ignore` before creating project-local worktree\n\n### Assuming directory location\n\n- **Problem:** Creates inconsistency, violates project conventions\n- **Fix:** Follow priority: existing > CLAUDE.md > ask\n\n### Proceeding with failing tests\n\n- **Problem:** Can''t distinguish new bugs from pre-existing issues\n- **Fix:** Report failures, get explicit permission to proceed\n\n### Hardcoding setup commands\n\n- **Problem:** Breaks on projects using different tools\n- **Fix:** Auto-detect from project files (package.json, etc.)\n\n## Example Workflow\n\n```\nYou: I''m using the using-git-worktrees skill to set up an isolated workspace.\n\n[Check .worktrees/ - exists]\n[Verify ignored - git check-ignore confirms .worktrees/ is ignored]\n[Create worktree: git worktree add .worktrees/auth -b feature/auth]\n[Run npm install]\n[Run npm test - 47 passing]\n\nWorktree ready at /Users/jesse/myproject/.worktrees/auth\nTests passing (47 tests, 0 failures)\nReady to implement auth feature\n```\n\n## Red Flags\n\n**Never:**\n- Create worktree without verifying it''s ignored (project-local)\n- Skip baseline test verification\n- Proceed with failing tests without asking\n- Assume directory location when ambiguous\n- Skip CLAUDE.md check\n\n**Always:**\n- Follow directory priority: existing > CLAUDE.md > ask\n- Verify directory is ignored for project-local\n- Auto-detect and run project setup\n- Verify clean test baseline\n\n## Integration\n\n**Called by:**\n- **brainstorming** (Phase 4) - REQUIRED when design is approved and implementation follows\n- **subagent-driven-development** - REQUIRED before executing any tasks\n- **executing-plans** - REQUIRED before executing any tasks\n- Any skill needing isolated workspace\n\n**Pairs with:**\n- **finishing-a-development-branch** - REQUIRED for cleanup after work complete\n"},"category":"official","lastSynced":"2026-03-06T03:36:13.009Z","seo":{"title":{"en":"using-git-worktrees: Isolated Workspace Setup Guide | AI ...","zh":"使用Git Worktrees的设置指南","ja":"Git Worktreesのベストプラクティス - AIエージェント","ko":"Git Worktrees 설정 가이드 - AI 툴","es":"Guía de configuración de Git Worktrees para un desarrollo...","fr":"Guide de mise en place de Git Worktrees pour un développe...","de":"Einrichtungsleitfaden für Git Worktrees zur isolierten En...","pt":"Guia de Configuração do using-git-worktrees para Desenvol...","ru":"ИИ Агенты: Настройка using-git-worktrees для Изолированно...","ar":"إعداد أداة using-git-worktrees للعمل المزدوج مع غيت"},"description":{"en":"Discover how to create isolated Git workspaces with smart directory selection and safety verification. Learn to use using-git-worktrees for efficient feature...","zh":"了解如何使用Git Worktrees创建隔离的工作空间，实现多分支同时开发","ja":"Git Worktreesを使用して複数のブランチを同時に開発する方法を学ぶ - AIエージェント","ko":"Git Worktrees를 사용하여 분기된 작업 공간을 생성하고 여러 브랜치를 동시에 개발하는 방법","es":"Aprende a utilizar Git Worktrees para crear espacios de trabajo aislados y mejorar tu flujo de desarrollo con esta guía paso a paso","fr":"Découvrez comment utiliser Git Worktrees pour créer des espaces de travail isolés et améliorer votre flux de développement avec ce guide étape par étape","de":"Erfahren Sie, wie Sie Git Worktrees verwenden, um isolierte Arbeitsbereiche zu erstellen und Ihren Entwicklungsprozess zu verbessern, mit diesem Schritt-für-...","pt":"Aprenda a usar o using-git-worktrees para criar espaços de trabalho isolados com seleção de diretório inteligente e verificação de segurança","ru":"Узнайте, как использовать using-git-worktrees для создания изолированных рабочих пространств с умной выборкой директорий и проверкой безопасности","ar":"تعرف على كيفية استخدام أداة using-git-worktrees لإنشاء مساحات عمل معزولة مع اختيار دليل ذكي وتحقق من الأمان"},"definition":{"en":"using-git-worktrees is a skill that creates isolated Git workspaces, allowing for simultaneous work on multiple branches without switching, using systematic directory selection and safety verification.","zh":"Git Worktrees是一种创建隔离工作空间的方法，允许同时开发多个分支","ja":"Git Worktreesは、複数のブランチを同時に開発できるようにするための方法です","ko":"Git Worktrees는 여러 브랜치를 동시에 개발할 수 있게 해주는 방법입니다","es":"Git Worktrees es una característica que permite crear espacios de trabajo aislados en un mismo repositorio","fr":"Git Worktrees est une fonctionnalité qui permet de créer des espaces de travail isolés dans un même référentiel","de":"Git Worktrees ist eine Funktion, die die Erstellung von isolierten Arbeitsbereichen in einem gleichen Repository ermöglicht","pt":"O using-git-worktrees é uma habilidade que cria espaços de trabalho isolados com seleção de diretório inteligente e verificação de segurança","ru":"ИИ Агенты: using-git-worktrees - это способность создавать изолированные рабочие пространства с умной выборкой директорий и проверкой безопасности","ar":"أداة using-git-worktrees هي قدرة لإنشاء مساحات عمل معزولة مع اختيار دليل ذكي وتحقق من الأمان"},"features":{"en":["Creates isolated Git workspaces for simultaneous branch work","Utilizes systematic directory selection for efficient workspace setup","Performs safety verification to ensure reliable isolation","Follows a priority order for directory selection, including checking existing directories","Enables work on multiple branches without switching between them"],"zh":["创建隔离的工作空间","实现多分支同时开发","系统化的目录选择","安全性验证"],"ja":["複数のブランチを同時に開発","隔離されたワークスペースの作成","システム化されたディレクトリ選択","セキュリティ検証"],"ko":["여러 브랜치를 동시에 개발","분리된 작업 공간 생성","시스템화된 디렉토리 선택","안전성 검증"],"es":["Creación de espacios de trabajo aislados","Selección de directorios inteligente","Verificación de seguridad para garantizar la isolación","Permite el trabajo en múltiples ramas simultáneamente","Compatibilidad con la línea de comandos (CLI)"],"fr":["Création d''espaces de travail isolés","Sélection de répertoires intelligente","Vérification de sécurité pour assurer l''isolation","Permet de travailler sur plusieurs branches simultanément","Compatibilité avec la ligne de commande (CLI)"],"de":["Erstellung von isolierten Arbeitsbereichen","Intelligente Verzeichnisauswahl","Sicherheitsprüfung, um die Isolation zu gewährleisten","Ermöglicht die Arbeit an mehreren Zweigen gleichzeitig","Kompatibilität mit der Kommandozeile (CLI)"],"pt":["Criação de espaços de trabalho isolados","Seleção de diretório inteligente","Verificação de segurança","Trabalho em múltiplos branches simultaneamente","Integração com Git","Prioridade de seleção de diretórios"],"ru":["Создание изолированных рабочих пространств","Умная выборка директорий","Проверка безопасности","Работа над несколькими ветками одновременно","Интеграция с Git","Приоритет выбора директорий"],"ar":["إنشاء مساحات عمل معزولة","اختيار دليل ذكي","تحقق من الأمان","العمل على عدة فروع في نفس الوقت","التكامل مع غيت","أولوية اختيار الدلائل"]},"keywords":{"en":["how to use using-git-worktrees","using-git-worktrees alternative","using-git-worktrees setup guide","what is using-git-worktrees","using-git-worktrees vs git checkout","using-git-worktrees install","git worktrees tutorial","isolated workspace setup","git branch management"],"zh":["Git Worktrees","隔离工作空间","多分支开发","AI工具","Git工作流","代码管理"],"ja":["Git Worktrees","AIエージェント","複数ブランチ開発","隔離ワークスペース","Gitワークフロー","コード管理"],"ko":["Git Worktrees","AI 툴","분기된 작업 공간","여러 브랜치 개발","Git 작업 흐름","코드 관리"],"es":["Git Worktrees","desarrollo aislado","espacios de trabajo","selección de directorios","verificación de seguridad","línea de comandos","CLI","desarrollo de software","herramientas de desarrollo"],"fr":["Git Worktrees","développement isolé","espaces de travail","sélection de répertoires","vérification de sécurité","ligne de commande","CLI","développement de logiciels","outils de développement"],"de":["Git Worktrees","isolierte Entwicklung","Arbeitsbereiche","Verzeichnisauswahl","Sicherheitsprüfung","Kommandozeile","CLI","Software-Entwicklung","Entwicklungstools"],"pt":["using-git-worktrees","Git worktrees","espaços de trabalho isolados","seleção de diretório inteligente","verificação de segurança","desenvolvimento de software","ferramentas de desenvolvimento","git para desenvolvedores"],"ru":["using-git-worktrees","ИИ Агенты","Git worktrees","изолированные рабочие пространства","умная выборка директорий","проверка безопасности","разработка программного обеспечения","инструменты разработки","git для разработчиков"],"ar":["using-git-worktrees","أدوات الذكاء الاصطناعي","غيت ووركتريس","مساحات عمل معزولة","اختيار دليل ذكي","تحقق من الأمان","تطوير البرمجيات","أدوات التطوير","غيت للمطورين"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing isolated workspace management and simultaneous branch development.","zh":"非常适合需要隔离工作空间管理和同时分支开发的版本控制代理。","ja":"バージョン管理エージェントが分離されたワークスペース管理と同時ブランチ開発を必要とする場合に最適です。","ko":"분리된 작업 공간 관리 및 동시 분기 개발이 필요한 버전 제어 에이전트에 적합합니다.","es":"Perfecto para agentes de control de versiones que necesitan gestión de espacio de trabajo aislado y desarrollo de ramas simultáneo.","fr":"Parfait pour les agents de contrôle de version nécessitant une gestion d''espace de travail isolé et un développement de branches simultané.","de":"Perfekt für Version Control Agents, die eine isolierte Arbeitsbereichsverwaltung und eine simultane Branch-Entwicklung benötigen.","pt":"Perfeito para Agentes de Controle de Versão que necessitam de gerenciamento de espaço de trabalho isolado e desenvolvimento de branch simultâneo.","ru":"Идеально для агентов контроля версий, которым необходимы изолированное управление рабочим пространством и одновременное развитие веток.","ar":"مثالي لعميل إدارة الإصدارات الذي يحتاج إلى إدارة مساحة عمل معزولة وتطوير فرع متزامن."},"recommendation":{"en":"Empowers agents to create isolated git worktrees with systematic directory selection and safety verification, enabling reliable isolation and simultaneous work on multiple branches without switching, utilizing git commands and repository sharing.","zh":"赋予代理创建带有系统目录选择和安全性验证的隔离git工作树的能力，从而可以在不切换的情况下可靠地隔离并同时处理多个分支，利用git命令和仓库共享。","ja":"エージェントがシステムディレクトリ選択と安全性の検証を備えた分離されたgitワークツリーを作成する能力を付与し、gitコマンドとリポジトリの共有を利用して、スイッチングせずに複数のブランチを同時に信頼性よく分離および処理できるようにします。","ko":"에이전트가 시스템 디렉토리 선택 및 보안 검증을 갖춘 분리된 git 작업 트리를 생성할 수 있는 능력을 부여하여 git 명령 및 리포지토리 공유를 사용하여 스위치하지 않고도 여러 분기를 동시에 신뢰할 수 있게 분리 및 처리할 수 있습니다.","es":"Habilita a los agentes a crear worktrees de git aislados con selección de directorio sistemática y verificación de seguridad, lo que permite un aislamiento confiable y un trabajo simultáneo en varias ramas sin conmutación, utilizando comandos de git y compartición de repositorio.","fr":"Permet aux agents de créer des worktrees git isolés avec une sélection de répertoire systématique et une vérification de sécurité, permettant ainsi un isolement fiable et un travail simultané sur plusieurs branches sans basculement, en utilisant des commandes git et un partage de référentiel.","de":"Ermächtigt die Agenten, isolierte git-Arbeitsbereiche mit systematischer Verzeichnisauswahl und Sicherheitsüberprüfung zu erstellen, wodurch ein zuverlässiges Isolieren und eine simultane Arbeit an mehreren Branches ohne Umschalten ermöglicht wird, unter Verwendung von git-Befehlen und Repository-Freigabe.","pt":"Habilita os agentes a criar worktrees git isolados com seleção de diretório sistemática e verificação de segurança, permitindo isolamento confiável e trabalho simultâneo em várias branches sem troca, utilizando comandos git e compartilhamento de repositório.","ru":"Наделяет агентов возможностью создавать изолированные рабочие деревья git с системным выбором директории и проверкой безопасности, что обеспечивает надежную изоляцию и одновременную работу над несколькими ветками без переключения, используя команды git и обмен репозиторием.","ar":"يمنح الوكلاء khảية إنشاء أشجار عمل جيت معزولة مع اختيار دليلي منهجي وتحقق من السلامة، مما يتيح العزل الموثوق به والعمل المتزامن على عدة فروع بدون تبديل، باستخدام أوامر جيت ومشاركة المستودع."},"useCases":{"en":["Initializing isolated workspaces for feature development","Managing multiple branches simultaneously without switching","Verifying safety and directory selection for worktree creation"],"zh":["为功能开发初始化隔离工作空间","同时处理多个分支而无需切换","验证工作树创建的安全性和目录选择"],"ja":["機能開発のために分離されたワークスペースを初期化する","スイッチングせずに複数のブランチを同時に処理する","ワークツリー作成の安全性とディレクトリ選択を検証する"],"ko":["기능 개발을 위한 분리된 작업 공간 초기화","스위치하지 않고 동시에 여러 분기를 처리","작업 트리 생성의 보안 및 디렉토리 선택을 검증"],"es":["Inicialización de espacios de trabajo aislados para el desarrollo de características","Gestión de varias ramas simultáneamente sin conmutación","Verificación de seguridad y selección de directorio para la creación de worktree"],"fr":["Initialisation d''espaces de travail isolés pour le développement de fonctionnalités","Gestion de plusieurs branches simultanément sans basculement","Vérification de sécurité et sélection de répertoire pour la création de worktree"],"de":["Initialisierung isolierter Arbeitsbereiche für die Entwicklung von Funktionen","Verwaltung mehrerer Branches simultan ohne Umschalten","Überprüfung der Sicherheit und Auswahl des Verzeichnisses für die Erstellung von Worktrees"],"pt":["Inicializar espaços de trabalho isolados para desenvolvimento de recursos","Gerenciar várias branches simultaneamente sem troca","Verificar segurança e seleção de diretório para criação de worktree"],"ru":["Инициализация изолированных рабочих пространств для развития функций","Управление несколькими ветками одновременно без переключения","Проверка безопасности и выбора директории для создания рабочего дерева"],"ar":["تinitialized مساحات عمل معزولة لتطوير الميزات","إدارة عدة فروع في نفس الوقت بدون تبديل","التحقق من السلامة واختيار الدليل لإنشاء شجرة العمل"]},"limitations":{"en":["Requires git installation and repository access","Limited to git version control system"],"zh":["需要git安装和仓库访问","仅限git版本控制系统"],"ja":["gitのインストールとリポジトリへのアクセスが必要","gitバージョン管理システムのみに限定"],"ko":["git 설치 및 리포지토리 액세스가 필요","git 버전 제어 시스템에만 제한"],"es":["Requiere instalación de git y acceso al repositorio","Limitado al sistema de control de versiones git"],"fr":["Nécessite l''installation de git et l''accès au référentiel","Limité au système de contrôle de version git"],"de":["Erfordert die Installation von git und den Zugriff auf das Repository","Begrenzt auf das git-Versionssystem"],"pt":["Requer instalação do git e acesso ao repositório","Limitado ao sistema de controle de versão git"],"ru":["Требуется установка git и доступ к репозиторию","Ограничен системой контроля версий git"],"ar":["يتطلب تثبيت جيت ووصول إلى المستودع","محدود بنظام إدارة الإصدارات جيت"]},"version":4},"contentHash":"de9dcde34840eee074047ec327d4ea6ca4954c5a73a6d874dc48f25fe46c9e7c","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":89}');
