INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/using-git-worktrees', 'using-git-worktrees', 'obra', 'superpowers', 'official', 'using-git-worktrees obra superpowers official The using-git-worktrees skill creates isolated workspaces for simultaneous branch work, benefiting developers who need to manage multiple features. It ensures reliable isolation through systematic directory selection and safety verification. Git Worktrees允许您创建隔离的工作空间，实现多分支同时开发 Git Worktreesを使用すると、複数のブランチを同時に開発できます Git Worktrees를 사용하여 여러 브랜치를 동시에 개발할 수 있습니다 Git Worktrees permite crear espacios de trabajo aislados para desarrollar características de manera independiente. Esta habilidad utiliza la selección de directorios y verificación de seguridad para garantizar la isolación Git Worktrees permet de créer des espaces de travail isolés pour développer des fonctionnalités de manière indépendante. Cette compétence utilise la sélection de répertoires et la vérification de sécurité pour assurer l''isolation Git Worktrees ermöglicht die Erstellung von isolierten Arbeitsbereichen, um Funktionen unabhängig zu entwickeln. Diese Fähigkeit nutzt die Verzeichnisauswahl und Sicherheitsprüfung, um die Isolation zu gewährleisten O using-git-worktrees permite criar espaços de trabalho isolados para desenvolvedores trabalharem em múltiplos branches simultaneamente ИИ Агенты: using-git-worktrees позволяет создавать изолированные рабочие пространства для работы над несколькими ветками одновременно أداة using-git-worktrees تمكن المطورين من إنشاء مساحات عمل معزولة للعمل على عدة فروع في نفس الوقت how to use using-git-worktrees using-git-worktrees alternative using-git-worktrees setup guide what is using-git-worktrees using-git-worktrees vs git checkout using-git-worktrees install git worktrees tutorial isolated workspace setup git branch management Git Worktrees 隔离工作空间 多分支开发 AI工具 Git工作流 代码管理 Creates isolated Git workspaces for simultaneous branch work Utilizes systematic directory selection for efficient workspace setup Performs safety verification to ensure reliable isolation Follows a priority order for directory selection, including checking existing directories Enables work on multiple branches without switching between them using-git-worktrees is a skill that creates isolated Git workspaces, allowing for simultaneous work on multiple branches without switching, using systematic directory selection and safety verification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/coding-standards', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'coding-standards', 61988, 7678, 89, '2026-03-06T03:39:20Z', '2026-03-06T03:49:21.589Z', 'be0b5f2063e9b4b1c6514889b0dc408316f7b0c7892832d10b69ec28e1389b7c', '{"id":"affaan-m/everything-claude-code/coding-standards","name":"coding-standards","description":{"en":"The coding-standards skill provides universal conventions and patterns for TypeScript, JavaScript, React, and Node.js development. It assists developers in establishing and enforcing code quality principles, naming conventions, and structural consistency across projects.","zh":"coding-standards AI代理提供适用于TypeScript、JavaScript、React和Node.js开发的通用编码标准。帮助开发者建立项目规范、执行代码质量审查、设置linting和格式化规则，确保代码可读性和一致性。","ja":"coding-standards AIエージェントは、TypeScript、JavaScript、React、Node.js開発のための汎用コーディング規約を提供します。プロジェクト規範の確立、コード品質レビュー、linting/フォーマット規則の設定を支援し、コードの可読性と一貫性を確保します。","ko":"coding-standards AI 에이전트는 TypeScript, JavaScript, React, Node.js 개발을 위한 범용 코딩 표준을 제공합니다. 프로젝트 규범 수립, 코드 품질 검토, linting/포맷팅 규칙 설정을 지원하여 코드 가독성과 일관성을 보장합니다.","es":"Estándares de codificación universales para proyectos de TypeScript, JavaScript, React y Node.js","fr":"Normes de codage universelles pour les projets TypeScript, JavaScript, React et Node.js","de":"Universelle Codierungsstandards für TypeScript-, JavaScript-, React- und Node.js-Projekte","pt":"Skill de AI Agent que fornece padrões universais de codificação para TypeScript, JavaScript, React e Node.js. Ideal para iniciar projetos, revisar código e configurar regras de linting e formatação.","ru":"Навык ИИ Агента, предоставляющий универсальные стандарты кодирования для TypeScript, JavaScript, React и Node.js. Идеален для начала проектов, проверки кода и настройки линтинга и форматирования.","ar":"مهارة أدوات الذكاء الاصطناعي التي توفر معايير ترميز عالمية لـ TypeScript وJavaScript وReact وNode.js. مثالية لبدء المشاريع، مراجعة الكود وإعداد قواعد linting والتنسيق."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"coding-standards","description":"Universal coding standards, best practices, and patterns for TypeScript, JavaScript, React, and Node.js development.","bodyPreview":"# Coding Standards & Best Practices\n\nUniversal coding standards applicable across all projects.\n\n## When to Activate\n\n- Starting a new project or module\n- Reviewing code for quality and maintainability\n- Refactoring existing code to follow conventions\n- Enforcing naming, formatting, or structural consistency\n- Setting up linting, formatting, or type-checking rules\n- Onboarding new contributors to coding conventions\n\n## Code Quality Principles\n\n### 1. Readability First\n- Code is read more than wr","body":"# Coding Standards & Best Practices\n\nUniversal coding standards applicable across all projects.\n\n## When to Activate\n\n- Starting a new project or module\n- Reviewing code for quality and maintainability\n- Refactoring existing code to follow conventions\n- Enforcing naming, formatting, or structural consistency\n- Setting up linting, formatting, or type-checking rules\n- Onboarding new contributors to coding conventions\n\n## Code Quality Principles\n\n### 1. Readability First\n- Code is read more than written\n- Clear variable and function names\n- Self-documenting code preferred over comments\n- Consistent formatting\n\n### 2. KISS (Keep It Simple, Stupid)\n- Simplest solution that works\n- Avoid over-engineering\n- No premature optimization\n- Easy to understand > clever code\n\n### 3. DRY (Don''t Repeat Yourself)\n- Extract common logic into functions\n- Create reusable components\n- Share utilities across modules\n- Avoid copy-paste programming\n\n### 4. YAGNI (You Aren''t Gonna Need It)\n- Don''t build features before they''re needed\n- Avoid speculative generality\n- Add complexity only when required\n- Start simple, refactor when needed\n\n## TypeScript/JavaScript Standards\n\n### Variable Naming\n\n```typescript\n// ✅ GOOD: Descriptive names\nconst marketSearchQuery = ''election''\nconst isUserAuthenticated = true\nconst totalRevenue = 1000\n\n// ❌ BAD: Unclear names\nconst q = ''election''\nconst flag = true\nconst x = 1000\n```\n\n### Function Naming\n\n```typescript\n// ✅ GOOD: Verb-noun pattern\nasync function fetchMarketData(marketId: string) { }\nfunction calculateSimilarity(a: number[], b: number[]) { }\nfunction isValidEmail(email: string): boolean { }\n\n// ❌ BAD: Unclear or noun-only\nasync function market(id: string) { }\nfunction similarity(a, b) { }\nfunction email(e) { }\n```\n\n### Immutability Pattern (CRITICAL)\n\n```typescript\n// ✅ ALWAYS use spread operator\nconst updatedUser = {\n  ...user,\n  name: ''New Name''\n}\n\nconst updatedArray = [...items, newItem]\n\n// ❌ NEVER mutate directly\nuser.name = ''New Name''  // BAD\nitems.push(newItem)     // BAD\n```\n\n### Error Handling\n\n```typescript\n// ✅ GOOD: Comprehensive error handling\nasync function fetchData(url: string) {\n  try {\n    const response = await fetch(url)\n\n    if (!response.ok) {\n      throw new Error(`HTTP ${response.status}: ${response.statusText}`)\n    }\n\n    return await response.json()\n  } catch (error) {\n    console.error(''Fetch failed:'', error)\n    throw new Error(''Failed to fetch data'')\n  }\n}\n\n// ❌ BAD: No error handling\nasync function fetchData(url) {\n  const response = await fetch(url)\n  return response.json()\n}\n```\n\n### Async/Await Best Practices\n\n```typescript\n// ✅ GOOD: Parallel execution when possible\nconst [users, markets, stats] = await Promise.all([\n  fetchUsers(),\n  fetchMarkets(),\n  fetchStats()\n])\n\n// ❌ BAD: Sequential when unnecessary\nconst users = await fetchUsers()\nconst markets = await fetchMarkets()\nconst stats = await fetchStats()\n```\n\n### Type Safety\n\n```typescript\n// ✅ GOOD: Proper types\ninterface Market {\n  id: string\n  name: string\n  status: ''active'' | ''resolved'' | ''closed''\n  created_at: Date\n}\n\nfunction getMarket(id: string): Promise<Market> {\n  // Implementation\n}\n\n// ❌ BAD: Using ''any''\nfunction getMarket(id: any): Promise<any> {\n  // Implementation\n}\n```\n\n## React Best Practices\n\n### Component Structure\n\n```typescript\n// ✅ GOOD: Functional component with types\ninterface ButtonProps {\n  children: React.ReactNode\n  onClick: () => void\n  disabled?: boolean\n  variant?: ''primary'' | ''secondary''\n}\n\nexport function Button({\n  children,\n  onClick,\n  disabled = false,\n  variant = ''primary''\n}: ButtonProps) {\n  return (\n    <button\n      onClick={onClick}\n      disabled={disabled}\n      className={`btn btn-${variant}`}\n    >\n      {children}\n    </button>\n  )\n}\n\n// ❌ BAD: No types, unclear structure\nexport function Button(props) {\n  return <button onClick={props.onClick}>{props.children}</button>\n}\n```\n\n### Custom Hooks\n\n```typescript\n// ✅ GOOD: Reusable custom hook\nexport function useDebounce<T>(value: T, delay: number): T {\n  const [debouncedValue, setDebouncedValue] = useState<T>(value)\n\n  useEffect(() => {\n    const handler = setTimeout(() => {\n      setDebouncedValue(value)\n    }, delay)\n\n    return () => clearTimeout(handler)\n  }, [value, delay])\n\n  return debouncedValue\n}\n\n// Usage\nconst debouncedQuery = useDebounce(searchQuery, 500)\n```\n\n### State Management\n\n```typescript\n// ✅ GOOD: Proper state updates\nconst [count, setCount] = useState(0)\n\n// Functional update for state based on previous state\nsetCount(prev => prev + 1)\n\n// ❌ BAD: Direct state reference\nsetCount(count + 1)  // Can be stale in async scenarios\n```\n\n### Conditional Rendering\n\n```typescript\n// ✅ GOOD: Clear conditional rendering\n{isLoading && <Spinner />}\n{error && <ErrorMessage error={error} />}\n{data && <DataDisplay data={data} />}\n\n// ❌ BAD: Ternary hell\n{isLoading ? <Spinner /> : error ? <ErrorMessage error={error} /> : data ? <DataDisplay data={data} /> : null}\n```\n\n## API Design Standards\n\n### REST API Conventions\n\n```\nGET    /api/markets              # List all markets\nGET    /api/markets/:id          # Get specific market\nPOST   /api/markets              # Create new market\nPUT    /api/markets/:id          # Update market (full)\nPATCH  /api/markets/:id          # Update market (partial)\nDELETE /api/markets/:id          # Delete market\n\n# Query parameters for filtering\nGET /api/markets?status=active&limit=10&offset=0\n```\n\n### Response Format\n\n```typescript\n// ✅ GOOD: Consistent response structure\ninterface ApiResponse<T> {\n  success: boolean\n  data?: T\n  error?: string\n  meta?: {\n    total: number\n    page: number\n    limit: number\n  }\n}\n\n// Success response\nreturn NextResponse.json({\n  success: true,\n  data: markets,\n  meta: { total: 100, page: 1, limit: 10 }\n})\n\n// Error response\nreturn NextResponse.json({\n  success: false,\n  error: ''Invalid request''\n}, { status: 400 })\n```\n\n### Input Validation\n\n```typescript\nimport { z } from ''zod''\n\n// ✅ GOOD: Schema validation\nconst CreateMarketSchema = z.object({\n  name: z.string().min(1).max(200),\n  description: z.string().min(1).max(2000),\n  endDate: z.string().datetime(),\n  categories: z.array(z.string()).min(1)\n})\n\nexport async function POST(request: Request) {\n  const body = await request.json()\n\n  try {\n    const validated = CreateMarketSchema.parse(body)\n    // Proceed with validated data\n  } catch (error) {\n    if (error instanceof z.ZodError) {\n      return NextResponse.json({\n        success: false,\n        error: ''Validation failed'',\n        details: error.errors\n      }, { status: 400 })\n    }\n  }\n}\n```\n\n## File Organization\n\n### Project Structure\n\n```\nsrc/\n├── app/                    # Next.js App Router\n│   ├── api/               # API routes\n│   ├── markets/           # Market pages\n│   └── (auth)/           # Auth pages (route groups)\n├── components/            # React components\n│   ├── ui/               # Generic UI components\n│   ├── forms/            # Form components\n│   └── layouts/          # Layout components\n├── hooks/                # Custom React hooks\n├── lib/                  # Utilities and configs\n│   ├── api/             # API clients\n│   ├── utils/           # Helper functions\n│   └── constants/       # Constants\n├── types/                # TypeScript types\n└── styles/              # Global styles\n```\n\n### File Naming\n\n```\ncomponents/Button.tsx          # PascalCase for components\nhooks/useAuth.ts              # camelCase with ''use'' prefix\nlib/formatDate.ts             # camelCase for utilities\ntypes/market.types.ts         # camelCase with .types suffix\n```\n\n## Comments & Documentation\n\n### When to Comment\n\n```typescript\n// ✅ GOOD: Explain WHY, not WHAT\n// Use exponential backoff to avoid overwhelming the API during outages\nconst delay = Math.min(1000 * Math.pow(2, retryCount), 30000)\n\n// Deliberately using mutation here for performance with large arrays\nitems.push(newItem)\n\n// ❌ BAD: Stating the obvious\n// Increment counter by 1\ncount++\n\n// Set name to user''s name\nname = user.name\n```\n\n### JSDoc for Public APIs\n\n```typescript\n/**\n * Searches markets using semantic similarity.\n *\n * @param query - Natural language search query\n * @param limit - Maximum number of results (default: 10)\n * @returns Array of markets sorted by similarity score\n * @throws {Error} If OpenAI API fails or Redis unavailable\n *\n * @example\n * ```typescript\n * const results = await searchMarkets(''election'', 5)\n * console.log(results[0].name) // \"Trump vs Biden\"\n * ```\n */\nexport async function searchMarkets(\n  query: string,\n  limit: number = 10\n): Promise<Market[]> {\n  // Implementation\n}\n```\n\n## Performance Best Practices\n\n### Memoization\n\n```typescript\nimport { useMemo, useCallback } from ''react''\n\n// ✅ GOOD: Memoize expensive computations\nconst sortedMarkets = useMemo(() => {\n  return markets.sort((a, b) => b.volume - a.volume)\n}, [markets])\n\n// ✅ GOOD: Memoize callbacks\nconst handleSearch = useCallback((query: string) => {\n  setSearchQuery(query)\n}, [])\n```\n\n### Lazy Loading\n\n```typescript\nimport { lazy, Suspense } from ''react''\n\n// ✅ GOOD: Lazy load heavy components\nconst HeavyChart = lazy(() => import(''./HeavyChart''))\n\nexport function Dashboard() {\n  return (\n    <Suspense fallback={<Spinner />}>\n      <HeavyChart />\n    </Suspense>\n  )\n}\n```\n\n### Database Queries\n\n```typescript\n// ✅ GOOD: Select only needed columns\nconst { data } = await supabase\n  .from(''markets'')\n  .select(''id, name, status'')\n  .limit(10)\n\n// ❌ BAD: Select everything\nconst { data } = await supabase\n  .from(''markets'')\n  .select(''*'')\n```\n\n## Testing Standards\n\n### Test Structure (AAA Pattern)\n\n```typescript\ntest(''calculates similarity correctly'', () => {\n  // Arrange\n  const vector1 = [1, 0, 0]\n  const vector2 = [0, 1, 0]\n\n  // Act\n  const similarity = calculateCosineSimilarity(vector1, vector2)\n\n  // Assert\n  expect(similarity).toBe(0)\n})\n```\n\n### Test Naming\n\n```typescript\n// ✅ GOOD: Descriptive test names\ntest(''returns empty array when no markets match query'', () => { })\ntest(''throws error when OpenAI API key is missing'', () => { })\ntest(''falls back to substring search when Redis unavailable'', () => { })\n\n// ❌ BAD: Vague test names\ntest(''works'', () => { })\ntest(''test search'', () => { })\n```\n\n## Code Smell Detection\n\nWatch for these anti-patterns:\n\n### 1. Long Functions\n```typescript\n// ❌ BAD: Function > 50 lines\nfunction processMarketData() {\n  // 100 lines of code\n}\n\n// ✅ GOOD: Split into smaller functions\nfunction processMarketData() {\n  const validated = validateData()\n  const transformed = transformData(validated)\n  return saveData(transformed)\n}\n```\n\n### 2. Deep Nesting\n```typescript\n// ❌ BAD: 5+ levels of nesting\nif (user) {\n  if (user.isAdmin) {\n    if (market) {\n      if (market.isActive) {\n        if (hasPermission) {\n          // Do something\n        }\n      }\n    }\n  }\n}\n\n// ✅ GOOD: Early returns\nif (!user) return\nif (!user.isAdmin) return\nif (!market) return\nif (!market.isActive) return\nif (!hasPermission) return\n\n// Do something\n```\n\n### 3. Magic Numbers\n```typescript\n// ❌ BAD: Unexplained numbers\nif (retryCount > 3) { }\nsetTimeout(callback, 500)\n\n// ✅ GOOD: Named constants\nconst MAX_RETRIES = 3\nconst DEBOUNCE_DELAY_MS = 500\n\nif (retryCount > MAX_RETRIES) { }\nsetTimeout(callback, DEBOUNCE_DELAY_MS)\n```\n\n**Remember**: Code quality is not negotiable. Clear, maintainable code enables rapid development and confident refactoring.\n"},"category":"official","lastSynced":"2026-03-06T03:49:21.589Z","seo":{"title":{"en":"coding-standards: Universal Best Practices Setup Guide | ...","zh":"coding-standards AI代理：TypeScript和JavaScript代码规范最佳实践指南","ja":"coding-standards AIエージェント：TypeScript/JavaScriptコーディング規約設定ガイド","ko":"coding-standards AI 에이전트: TypeScript/JavaScript 코딩 표준 설정 가이드","es":"Guía de configuración de estándares de codificación para ...","fr":"Guide de mise en place des normes de codage pour TypeScri...","de":"Einrichtungsleitfaden für Codierungsstandards in TypeScri...","pt":"Padrões de Codificação: Guia de Melhores Práticas para Ty...","ru":"Стандарты кодирования: Лучшие практики для TypeScript, Ja...","ar":"معايير الترميز: أفضل الممارسات لـ TypeScript وJavaScript ..."},"description":{"en":"Implement TypeScript, JavaScript, React & Node.js coding standards. This AI Agent skill enforces linting, formatting, and type-checking rules for new project...","zh":"专为TypeScript、JavaScript、React和Node.js开发设计的AI代理工具，提供统一的代码规范、最佳实践和模式。适用于新项目启动、代码审查、重构和团队协作场景。","ja":"TypeScript、JavaScript、React、Node.js開発向けAIエージェント。統一されたコーディング規約、ベストプラクティス、パターンを提供。新規プロジェクト開始、コードレビュー、リファクタリングに最適。","ko":"TypeScript, JavaScript, React, Node.js 개발을 위한 AI 에이전트. 통합 코딩 표준, 베스트 프랙티스, 패턴 제공. 새 프로젝트 시작, 코드 리뷰, 리팩토링에 최적화.","es":"Mejora la calidad de tu código con estándares universales para TypeScript, JavaScript, React y Node.js","fr":"Améliorez la qualité de votre code avec des normes universelles pour TypeScript, JavaScript, React et Node.js","de":"Verbessern Sie die Code-Qualität mit universellen Standards für TypeScript, JavaScript, React und Node.js","pt":"Use AI Agents para aplicar padrões universais de código em TypeScript, JavaScript, React e Node.js. Melhore legibilidade, mantenha consistência e configure f...","ru":"Используйте ИИ Агенты для применения универсальных стандартов кода в TypeScript, JavaScript, React и Node.js. Улучшите читаемость, обеспечьте согласованность...","ar":"استخدم أدوات الذكاء الاصطناعي لتطبيق معايير الترميز العالمية في TypeScript وJavaScript وReact وNode.js. عزز قابلية القراءة، حافظ على الاتساق وقم بإعداد أدوات..."},"definition":{"en":"coding-standards is an AI Agent skill that delivers universal coding standards, best practices, and patterns for TypeScript, JavaScript, React, and Node.js development to ensure code quality and maintainability.","zh":"coding-standards是一款AI代理工具，专门为TypeScript、JavaScript、React和Node.js开发提供统一的编码标准、最佳实践和模式。它帮助开发者在项目启动、代码审查和重构过程中维护代码质量和一致性。","ja":"coding-standardsは、TypeScript、JavaScript、React、Node.js開発向けの統一コーディング規約、ベストプラクティス、パターンを提供するAIエージェントツールです。プロジェクト開始、コードレビュー、リファクタリング時のコード品質と一貫性を維持します。","ko":"coding-standards는 TypeScript, JavaScript, React, Node.js 개발을 위한 통합 코딩 표준, 베스트 프랙티스, 패턴을 제공하는 AI 에이전트 도구입니다. 프로젝트 시작, 코드 리뷰, 리팩토링 과정에서 코드 품질과 일관성을 유지합니다.","es":"Estándares de codificación son reglas y patrones para escribir código de alta calidad","fr":"Les n