INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/cost-aware-llm-pipeline', 'cost-aware-llm-pipeline', 'affaan-m', 'everything-claude-code', 'official', 'cost-aware-llm-pipeline affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The cost-aware-llm-pipeline skill provides composable patterns for optimizing LLM API usage. It is designed for developers building applications that call Claude, GPT, or other LLM APIs and need to maintain quality while controlling budget. Cost-Aware LLM Pipeline是一种优化LLM API成本的模式，结合模型路由、预算跟踪、重试逻辑和提示缓存 Cost-Aware LLM Pipelineは、AIエージェントのコスト削減を実現するためのパターンで、モデルルーティング、予算追跡、リトライロジック、プロンプトキャッシングを組み合わせたもの Cost-Aware LLM Pipeline는 LLM API 비용을 최적화하는 패턴으로 모델 라우팅, 예산 추적, 재시도 로직, 프롬프트 캐싱을 결합한 구성 가능한 파이프라인 Cost-aware-llm-pipeline es un patrón de optimización de costos para el uso de API de LLM, que combina enrutamiento de modelos, seguimiento de presupuesto, lógica de reintento y caché de solicitudes Cost-aware-llm-pipeline est un modèle d''optimisation des coûts pour l''utilisation d''API de LLM, qui combine le routage de modèles, la gestion budgétaire, la logique de réessai et le cache de requêtes Cost-aware-llm-pipeline ist ein Muster für die Kostenoptimierung von LLM-APIs, das Modellrouting, Budgetverfolgung, Wiederholungslogik und Promptcaching kombiniert O Cost-Aware LLM Pipeline é um padrão de otimização de custo para uso de APIs de LLM, combinando roteamento de modelo e rastreamento de orçamento. Cost-Aware LLM Pipeline — это шаблон оптимизации затрат для использования API LLM, который объединяет маршрутизацию модели и отслеживание бюджета для ИИ Агентов Cost-Aware LLM Pipeline نمط لتحسين التكلفة لاستخدام واجهات برمجة التطبيقات LLM، يدمج مسارات النموذج وتتبع الميزانية لأدوات الذكاء الاصطناعي cost-aware-llm-pipeline setup guide how to use cost-aware-llm-pipeline what is cost-aware-llm-pipeline cost-aware-llm-pipeline vs langchain llm api budget tracking model routing by task complexity claude api cost optimization install cost-aware-llm-pipeline mcp cost optimization patterns prompt caching for llm apis LLM API成本优化 AIエージェント 模型路由 预算跟踪 重试逻辑 提示缓存 Cost-Aware LLM Pipeline Model routing by task complexity for optimal LLM selection Budget tracking to monitor and control API spend Retry logic for handling API failures gracefully Prompt caching to reduce redundant API calls Composable pipeline architecture for flexible integration Support for processing batches of items with varying complexity cost-aware-llm-pipeline is an AI Agent Skill that provides cost optimization patterns for LLM API usage. It combines model routing by task complexity, budget tracking, retry logic, and prompt caching into a composable pipeline for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/django-security', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'django-security', 61988, 7678, 89, '2026-03-06T03:39:20Z', '2026-03-06T04:03:10.547Z', 'd5d174690a16dca99798693f47b5df17478bfc5ff0f91684caf56dc1e9bef8b5', '{"id":"affaan-m/everything-claude-code/django-security","name":"django-security","description":{"en":"This AI agent skill provides comprehensive security guidelines for Django applications, covering authentication, authorization, and secure deployment configurations. It assists developers in protecting against common vulnerabilities like CSRF, SQL injection, and XSS.","zh":"Django 安全配置最佳实践指南，涵盖身份验证、授权、CSRF 保护和 SQL 注入防御","ja":"Django セキュリティ設定のベストプラクティスを提供するガイド、認証、認可、CSRF 保護、SQL インジェクション防止を含む","ko":"Django 보안 설정 가이드, 인증, 권한, CSRF 보호, SQL 인젝션 방지 등","es":"La seguridad de Django es crucial para proteger tus aplicaciones contra vulnerabilidades comunes. Aprende a implementar las mejores prácticas de seguridad en tus proyectos Django","fr":"La sécurité de Django est cruciale pour protéger vos applications contre les vulnérabilités courantes. Apprenez à mettre en œuvre les meilleures pratiques de sécurité dans vos projets Django","de":"Die Sicherheit von Django ist entscheidend, um Ihre Anwendungen vor gängigen Schwachstellen zu schützen. Erfahren Sie, wie Sie die Sicherheitsbest-Practices in Ihren Django-Projekten umsetzen können","pt":"Um AI Agent especializado em segurança Django, oferecendo diretrizes para autenticação, autorização, proteção CSRF, prevenção de SQL injection e configurações seguras de deploy em produção.","ru":"Специализированный ИИ Агент по безопасности Django, предоставляющий руководства по аутентификации, авторизации, защите от CSRF, предотвращению SQL инъекций и безопасным настройкам развертывания.","ar":"أداة ذكاء اصطناعي متخصصة في أمان Django، تقدم إرشادات للمصادقة، التفويض، الحماية من CSRF، منع حقن SQL وإعدادات النشر الآمنة."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"django-security","description":"Django security best practices, authentication, authorization, CSRF protection, SQL injection prevention, XSS prevention, and secure deployment configurations.","bodyPreview":"# Django Security Best Practices\n\nComprehensive security guidelines for Django applications to protect against common vulnerabilities.\n\n## When to Activate\n\n- Setting up Django authentication and authorization\n- Implementing user permissions and roles\n- Configuring production security settings\n- Reviewing Django application for security issues\n- Deploying Django applications to production\n\n## Core Security Settings\n\n### Production Settings Configuration\n\n```python\n# settings/production.py\nimport","body":"# Django Security Best Practices\n\nComprehensive security guidelines for Django applications to protect against common vulnerabilities.\n\n## When to Activate\n\n- Setting up Django authentication and authorization\n- Implementing user permissions and roles\n- Configuring production security settings\n- Reviewing Django application for security issues\n- Deploying Django applications to production\n\n## Core Security Settings\n\n### Production Settings Configuration\n\n```python\n# settings/production.py\nimport os\n\nDEBUG = False  # CRITICAL: Never use True in production\n\nALLOWED_HOSTS = os.environ.get(''ALLOWED_HOSTS'', '''').split('','')\n\n# Security headers\nSECURE_SSL_REDIRECT = True\nSESSION_COOKIE_SECURE = True\nCSRF_COOKIE_SECURE = True\nSECURE_HSTS_SECONDS = 31536000  # 1 year\nSECURE_HSTS_INCLUDE_SUBDOMAINS = True\nSECURE_HSTS_PRELOAD = True\nSECURE_CONTENT_TYPE_NOSNIFF = True\nSECURE_BROWSER_XSS_FILTER = True\nX_FRAME_OPTIONS = ''DENY''\n\n# HTTPS and Cookies\nSESSION_COOKIE_HTTPONLY = True\nCSRF_COOKIE_HTTPONLY = True\nSESSION_COOKIE_SAMESITE = ''Lax''\nCSRF_COOKIE_SAMESITE = ''Lax''\n\n# Secret key (must be set via environment variable)\nSECRET_KEY = os.environ.get(''DJANGO_SECRET_KEY'')\nif not SECRET_KEY:\n    raise ImproperlyConfigured(''DJANGO_SECRET_KEY environment variable is required'')\n\n# Password validation\nAUTH_PASSWORD_VALIDATORS = [\n    {\n        ''NAME'': ''django.contrib.auth.password_validation.UserAttributeSimilarityValidator'',\n    },\n    {\n        ''NAME'': ''django.contrib.auth.password_validation.MinimumLengthValidator'',\n        ''OPTIONS'': {\n            ''min_length'': 12,\n        }\n    },\n    {\n        ''NAME'': ''django.contrib.auth.password_validation.CommonPasswordValidator'',\n    },\n    {\n        ''NAME'': ''django.contrib.auth.password_validation.NumericPasswordValidator'',\n    },\n]\n```\n\n## Authentication\n\n### Custom User Model\n\n```python\n# apps/users/models.py\nfrom django.contrib.auth.models import AbstractUser\nfrom django.db import models\n\nclass User(AbstractUser):\n    \"\"\"Custom user model for better security.\"\"\"\n\n    email = models.EmailField(unique=True)\n    phone = models.CharField(max_length=20, blank=True)\n\n    USERNAME_FIELD = ''email''  # Use email as username\n    REQUIRED_FIELDS = [''username'']\n\n    class Meta:\n        db_table = ''users''\n        verbose_name = ''User''\n        verbose_name_plural = ''Users''\n\n    def __str__(self):\n        return self.email\n\n# settings/base.py\nAUTH_USER_MODEL = ''users.User''\n```\n\n### Password Hashing\n\n```python\n# Django uses PBKDF2 by default. For stronger security:\nPASSWORD_HASHERS = [\n    ''django.contrib.auth.hashers.Argon2PasswordHasher'',\n    ''django.contrib.auth.hashers.PBKDF2PasswordHasher'',\n    ''django.contrib.auth.hashers.PBKDF2SHA1PasswordHasher'',\n    ''django.contrib.auth.hashers.BCryptSHA256PasswordHasher'',\n]\n```\n\n### Session Management\n\n```python\n# Session configuration\nSESSION_ENGINE = ''django.contrib.sessions.backends.cache''  # Or ''db''\nSESSION_CACHE_ALIAS = ''default''\nSESSION_COOKIE_AGE = 3600 * 24 * 7  # 1 week\nSESSION_SAVE_EVERY_REQUEST = False\nSESSION_EXPIRE_AT_BROWSER_CLOSE = False  # Better UX, but less secure\n```\n\n## Authorization\n\n### Permissions\n\n```python\n# models.py\nfrom django.db import models\nfrom django.contrib.auth.models import Permission\n\nclass Post(models.Model):\n    title = models.CharField(max_length=200)\n    content = models.TextField()\n    author = models.ForeignKey(User, on_delete=models.CASCADE)\n\n    class Meta:\n        permissions = [\n            (''can_publish'', ''Can publish posts''),\n            (''can_edit_others'', ''Can edit posts of others''),\n        ]\n\n    def user_can_edit(self, user):\n        \"\"\"Check if user can edit this post.\"\"\"\n        return self.author == user or user.has_perm(''app.can_edit_others'')\n\n# views.py\nfrom django.contrib.auth.mixins import LoginRequiredMixin, PermissionRequiredMixin\nfrom django.views.generic import UpdateView\n\nclass PostUpdateView(LoginRequiredMixin, PermissionRequiredMixin, UpdateView):\n    model = Post\n    permission_required = ''app.can_edit_others''\n    raise_exception = True  # Return 403 instead of redirect\n\n    def get_queryset(self):\n        \"\"\"Only allow users to edit their own posts.\"\"\"\n        return Post.objects.filter(author=self.request.user)\n```\n\n### Custom Permissions\n\n```python\n# permissions.py\nfrom rest_framework import permissions\n\nclass IsOwnerOrReadOnly(permissions.BasePermission):\n    \"\"\"Allow only owners to edit objects.\"\"\"\n\n    def has_object_permission(self, request, view, obj):\n        # Read permissions allowed for any request\n        if request.method in permissions.SAFE_METHODS:\n            return True\n\n        # Write permissions only for owner\n        return obj.author == request.user\n\nclass IsAdminOrReadOnly(permissions.BasePermission):\n    \"\"\"Allow admins to do anything, others read-only.\"\"\"\n\n    def has_permission(self, request, view):\n        if request.method in permissions.SAFE_METHODS:\n            return True\n        return request.user and request.user.is_staff\n\nclass IsVerifiedUser(permissions.BasePermission):\n    \"\"\"Allow only verified users.\"\"\"\n\n    def has_permission(self, request, view):\n        return request.user and request.user.is_authenticated and request.user.is_verified\n```\n\n### Role-Based Access Control (RBAC)\n\n```python\n# models.py\nfrom django.contrib.auth.models import AbstractUser, Group\n\nclass User(AbstractUser):\n    ROLE_CHOICES = [\n        (''admin'', ''Administrator''),\n        (''moderator'', ''Moderator''),\n        (''user'', ''Regular User''),\n    ]\n    role = models.CharField(max_length=20, choices=ROLE_CHOICES, default=''user'')\n\n    def is_admin(self):\n        return self.role == ''admin'' or self.is_superuser\n\n    def is_moderator(self):\n        return self.role in [''admin'', ''moderator'']\n\n# Mixins\nclass AdminRequiredMixin:\n    \"\"\"Mixin to require admin role.\"\"\"\n\n    def dispatch(self, request, *args, **kwargs):\n        if not request.user.is_authenticated or not request.user.is_admin():\n            from django.core.exceptions import PermissionDenied\n            raise PermissionDenied\n        return super().dispatch(request, *args, **kwargs)\n```\n\n## SQL Injection Prevention\n\n### Django ORM Protection\n\n```python\n# GOOD: Django ORM automatically escapes parameters\ndef get_user(username):\n    return User.objects.get(username=username)  # Safe\n\n# GOOD: Using parameters with raw()\ndef search_users(query):\n    return User.objects.raw(''SELECT * FROM users WHERE username = %s'', [query])\n\n# BAD: Never directly interpolate user input\ndef get_user_bad(username):\n    return User.objects.raw(f''SELECT * FROM users WHERE username = {username}'')  # VULNERABLE!\n\n# GOOD: Using filter with proper escaping\ndef get_users_by_email(email):\n    return User.objects.filter(email__iexact=email)  # Safe\n\n# GOOD: Using Q objects for complex queries\nfrom django.db.models import Q\ndef search_users_complex(query):\n    return User.objects.filter(\n        Q(username__icontains=query) |\n        Q(email__icontains=query)\n    )  # Safe\n```\n\n### Extra Security with raw()\n\n```python\n# If you must use raw SQL, always use parameters\nUser.objects.raw(\n    ''SELECT * FROM users WHERE email = %s AND status = %s'',\n    [user_input_email, status]\n)\n```\n\n## XSS Prevention\n\n### Template Escaping\n\n```django\n{# Django auto-escapes variables by default - SAFE #}\n{{ user_input }}  {# Escaped HTML #}\n\n{# Explicitly mark safe only for trusted content #}\n{{ trusted_html|safe }}  {# Not escaped #}\n\n{# Use template filters for safe HTML #}\n{{ user_input|escape }}  {# Same as default #}\n{{ user_input|striptags }}  {# Remove all HTML tags #}\n\n{# JavaScript escaping #}\n<script>\n    var username = {{ username|escapejs }};\n</script>\n```\n\n### Safe String Handling\n\n```python\nfrom django.utils.safestring import mark_safe\nfrom django.utils.html import escape\n\n# BAD: Never mark user input as safe without escaping\ndef render_bad(user_input):\n    return mark_safe(user_input)  # VULNERABLE!\n\n# GOOD: Escape first, then mark safe\ndef render_good(user_input):\n    return mark_safe(escape(user_input))\n\n# GOOD: Use format_html for HTML with variables\nfrom django.utils.html import format_html\n\ndef greet_user(username):\n    return format_html(''<span class=\"user\">{}</span>'', escape(username))\n```\n\n### HTTP Headers\n\n```python\n# settings.py\nSECURE_CONTENT_TYPE_NOSNIFF = True  # Prevent MIME sniffing\nSECURE_BROWSER_XSS_FILTER = True  # Enable XSS filter\nX_FRAME_OPTIONS = ''DENY''  # Prevent clickjacking\n\n# Custom middleware\nfrom django.conf import settings\n\nclass SecurityHeaderMiddleware:\n    def __init__(self, get_response):\n        self.get_response = get_response\n\n    def __call__(self, request):\n        response = self.get_response(request)\n        response[''X-Content-Type-Options''] = ''nosniff''\n        response[''X-Frame-Options''] = ''DENY''\n        response[''X-XSS-Protection''] = ''1; mode=block''\n        response[''Content-Security-Policy''] = \"default-src ''self''\"\n        return response\n```\n\n## CSRF Protection\n\n### Default CSRF Protection\n\n```python\n# settings.py - CSRF is enabled by default\nCSRF_COOKIE_SECURE = True  # Only send over HTTPS\nCSRF_COOKIE_HTTPONLY = True  # Prevent JavaScript access\nCSRF_COOKIE_SAMESITE = ''Lax''  # Prevent CSRF in some cases\nCSRF_TRUSTED_ORIGINS = [''https://example.com'']  # Trusted domains\n\n# Template usage\n<form method=\"post\">\n    {% csrf_token %}\n    {{ form.as_p }}\n    <button type=\"submit\">Submit</button>\n</form>\n\n# AJAX requests\nfunction getCookie(name) {\n    let cookieValue = null;\n    if (document.cookie && document.cookie !== '''') {\n        const cookies = document.cookie.split('';'');\n        for (let i = 0; i < cookies.length; i++) {\n            const cookie = cookies[i].trim();\n            if (cookie.substring(0, name.length + 1) === (name + ''='')) {\n                cookieValue = decodeURIComponent(cookie.substring(name.length + 1));\n                break;\n            }\n        }\n    }\n    return cookieValue;\n}\n\nfetch(''/api/endpoint/'', {\n    method: ''POST'',\n    headers: {\n        ''X-CSRFToken'': getCookie(''csrftoken''),\n        ''Content-Type'': ''application/json'',\n    },\n    body: JSON.stringify(data)\n});\n```\n\n### Exempting Views (Use Carefully)\n\n```python\nfrom django.views.decorators.csrf import csrf_exempt\n\n@csrf_exempt  # Only use when absolutely necessary!\ndef webhook_view(request):\n    # Webhook from external service\n    pass\n```\n\n## File Upload Security\n\n### File Validation\n\n```python\nimport os\nfrom django.core.exceptions import ValidationError\n\ndef validate_file_extension(value):\n    \"\"\"Validate file extension.\"\"\"\n    ext = os.path.splitext(value.name)[1]\n    valid_extensions = [''.jpg'', ''.jpeg'', ''.png'', ''.gif'', ''.pdf'']\n    if not ext.lower() in valid_extensions:\n        raise ValidationError(''Unsupported file extension.'')\n\ndef validate_file_size(value):\n    \"\"\"Validate file size (max 5MB).\"\"\"\n    filesize = value.size\n    if filesize > 5 * 1024 * 1024:\n        raise ValidationError(''File too large. Max size is 5MB.'')\n\n# models.py\nclass Document(models.Model):\n    file = models.FileField(\n        upload_to=''documents/'',\n        validators=[validate_file_extension, validate_file_size]\n    )\n```\n\n### Secure File Storage\n\n```python\n# settings.py\nMEDIA_ROOT = ''/var/www/media/''\nMEDIA_URL = ''/media/''\n\n# Use a separate domain for media in production\nMEDIA_DOMAIN = ''https://media.example.com''\n\n# Don''t serve user uploads directly\n# Use whitenoise or a CDN for static files\n# Use a separate server or S3 for media files\n```\n\n## API Security\n\n### Rate Limiting\n\n```python\n# settings.py\nREST_FRAMEWORK = {\n    ''DEFAULT_THROTTLE_CLASSES'': [\n        ''rest_framework.throttling.AnonRateThrottle'',\n        ''rest_framework.throttling.UserRateThrottle''\n    ],\n    ''DEFAULT_THROTTLE_RATES'': {\n        ''anon'': ''100/day'',\n        ''user'': ''1000/day'',\n        ''upload'': ''10/hour'',\n    }\n}\n\n# Custom throttle\nfrom rest_framework.throttling import UserRateThrottle\n\nclass BurstRateThrottle(UserRateThrottle):\n    scope = ''burst''\n    rate = ''60/min''\n\nclass SustainedRateThrottle(UserRateThrottle):\n    scope = ''sustained''\n    rate = ''1000/day''\n```\n\n### Authentication for APIs\n\n```python\n# settings.py\nREST_FRAMEWORK = {\n    ''DEFAULT_AUTHENTICATION_CLASSES'': [\n        ''rest_framework.authentication.TokenAuthentication'',\n        ''rest_framework.authentication.SessionAuthentication'',\n        ''rest_framework_simplejwt.authentication.JWTAuthentication'',\n    ],\n    ''DEFAULT_PERMISSION_CLASSES'': [\n        ''rest_framework.permissions.IsAuthenticated'',\n    ],\n}\n\n# views.py\nfrom rest_framework.decorators import api_view, permission_classes\nfrom rest_framework.permissions import IsAuthenticated\n\n@api_view([''GET'', ''POST''])\n@permission_classes([IsAuthenticated])\ndef protected_view(request):\n    return Response({''message'': ''You are authenticated''})\n```\n\n## Security Headers\n\n### Content Security Policy\n\n```python\n# settings.py\nCSP_DEFAULT_SRC = \"''self''\"\nCSP_SCRIPT_SRC = \"''self'' https://cdn.example.com\"\nCSP_STYLE_SRC = \"''self'' ''unsafe-inline''\"\nCSP_IMG_SRC = \"''self'' data: https:\"\nCSP_CONNECT_SRC = \"''self'' https://api.example.com\"\n\n# Middleware\nclass CSPMiddleware:\n    def __init__(self, get_response):\n        self.get_response = get_response\n\n    def __call__(self, request):\n        response = self.get_response(request)\n        response[''Content-Security-Policy''] = (\n            f\"default-src {CSP_DEFAULT_SRC}; \"\n            f\"script-src {CSP_SCRIPT_SRC}; \"\n            f\"style-src {CSP_STYLE_SRC}; \"\n            f\"img-src {CSP_IMG_SRC}; \"\n            f\"connect-src {CSP_CONNECT_SRC}\"\n        )\n        return response\n```\n\n## Environment Variables\n\n### Managing Secrets\n\n```python\n# Use python-decouple or django-environ\nimport environ\n\nenv = environ.Env(\n    # set casting, default value\n    DEBUG=(bool, False)\n)\n\n# reading .env file\nenviron.Env.read_env()\n\nSECRET_KEY = env(''DJANGO_SECRET_KEY'')\nDATABASE_URL = env(''DATABASE_URL'')\nALLOWED_HOSTS = env.list(''ALLOWED_HOSTS'')\n\n# .env file (never commit this)\nDEBUG=False\nSECRET_KEY=your-secret-key-here\nDATABASE_URL=postgresql://user:password@localhost:5432/dbname\nALLOWED_HOSTS=example.com,www.example.com\n```\n\n## Logging Security Events\n\n```python\n# settings.py\nLOGGING = {\n    ''version'': 1,\n    ''disable_existing_loggers'': False,\n    ''handlers'': {\n        ''file'': {\n            ''level'': ''WARNING'',\n            ''class'': ''logging.FileHandler'',\n            ''filename'': ''/var/log/django/security.log'',\n        },\n        ''console'': {\n            ''level'': ''INFO'',\n            ''class'': ''logging.StreamHandler'',\n        },\n    },\n    ''loggers'': {\n        ''django.security'': {\n            ''handlers'': [''file'', ''console''],\n            ''level'': ''WARNING'',\n            ''propagate'': True,\n        },\n        ''django.request'': {\n            ''handlers'': [''file''],\n            ''level'': ''ERROR'',\n            ''propagate'': False,\n        },\n    },\n}\n```\n\n## Quick Security Checklist\n\n| Check | Description |\n|-------|-------------|\n| `DEBUG = False` | Never run with DEBUG in production |\n| HTTPS only | Force SSL, secure cookies |\n| Strong secrets | Use environment variables for SECRET_KEY |\n| Password validation | Enable all password validators |\n| CSRF protection | Enabled by default, don''t disable |\n| XSS prevention | Django auto-escapes, don''t use `&#124;safe` with user input |\n| SQL injection | Use ORM, never concatenate strings in queries |\n| File uploads | Validate file type and size |\n| Rate limiting | Throttle API endpoints |\n| Security headers | CSP, X-Frame-Options, HSTS |\n| Logging | Log security events |\n| Updates | Keep Django and dependencies updated |\n\nRemember: Security is a process, not a product. Regularly review and update your security practices.\n"},"category":"official","lastSynced":"2026-03-06T04:03:10.547Z","seo":{"title":{"en":"django-security: Secure Deployment & CSRF Protection Guid...","zh":"Django 安全配置最佳实践","ja":"Django セキュリティ設定ガイド","ko":"Django 보안 설정 가이드","es":"Guía de Seguridad Django: Mejores Prácticas para Desarrol...","fr":"Guide de Sécurité Django: Bonnes Pratiques pour les Dével...","de":"Django-Sicherheitsleitfaden: Best Practices für Entwickler","pt":"Django Security: Melhores Práticas para Autenticação e Pr...","ru":"Безопасность Django: Лучшие Практики для Аутентификации и...","ar":"أفضل ممارسات أمان Django: الحماية من الثغرات الشائعة"},"description":{"en":"Implement Django security best practices with this AI agent skill. Get expert guidance on authentication, authorization, SQL injection prevention, and config...","zh":"了解 Django 安全配置的最佳实践，包括身份验证、授权、CSRF 保护和 SQL 注入防御","ja":"Django セキュリティ設定のベストプラクティスを学び、認証、認可、CSRF 保護、SQL インジェクション防止を実現する","ko":"Django 보안 설정의最佳实践을 알아보세요. 인증, 권한, CSRF 보호, SQL 인젝션 방지 등","es":"Aprende a proteger tus aplicaciones Django con nuestras mejores prácticas de seguridad, incluyendo autenticación, autorización y protección contra ataques de...","fr":"Apprenez à protéger vos applications Django avec nos meilleures pratiques de sécurité, y compris l''authentification, l''autorisation et la protection contre l...","de":"Erfahren Sie, wie Sie Ihre Django-Anwendungen mit unseren Sicherheitsbest-Practices schützen können, einschließlich Authentifizierung, Autorisierung und Schu...","pt":"AI Agent com melhores práticas de segurança Django: configuração de produção, prevenção de CSRF, SQL injection, XSS e autenticação segura para deploy.","ru":"ИИ Агент с лучшими практиками безопасности Django: производственные настройки, защита от CSRF, SQL инъекций, XSS и безопасная аутентификация для развертывания.","ar":"أداة الذكاء الاصطناعي لأفضل ممارسات أمان Django: إعدادات الإنتاج، الحماية من CSRF، حقن SQL، XSS والمصادقة الآمنة للنشر."},"definition":{"en":"django-security is an AI agent skill that delivers expert guidance on Django security best practices. It helps developers implement authentication, authorization, CSRF protection, SQL injection prevention, XSS prevention, and configure production security settings.","zh":"Django 安全配置是指保护 Django 应用程序免受常见漏洞的安全措施","ja":"Django セキュリティ設